INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (1, 1, 'pousada-vale-do-cafe', 'Pousada Vale do Café', '3300308', 'Rua Vereador José Alves Pegas, 212', 'Localizada na Vila Histórica de Ipiabas, em um conjunto arquitetônico construído no século XIX, cercada de natureza, e com amplo jardim, a Pousada Vale do Café oferece dias de descanso no ritmo suave do interior rural, onde o tempo anda sem pressa. O café da manhã é servido com itens selecionados de produção local e caseiro.', '24h', '(21) 97040-3433', '', 'www.pousadavaledocafe.rio.br', 'SIM', 'SIM', '', -22.3787794, -43.8802862, 'referencia', 'https://www.google.com/maps/search/?api=1&query=Pousada%20Vale%20do%20Caf%C3%A9%2C%20Barra%20do%20Pira%C3%AD%2C%20RJ', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.4');
