INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (2, 1, 'rvc-turismo', 'RVC Turismo', '3300308', 'Rua Cel. Cristiano Rocha, 100', 'Realiza parcerias e faz com que o turista se encante com nosso destino. Oferece a possibilidade de novas experiências, principalmente no meio rural.', '08h às 18h', '(24) 99955-0302 / (24) 98155-0903', '@receptivovaledocafe', 'www.receptivovaledocafe.com.br', 'NÃO', 'SIM', '', -22.3768485, -43.8725918, 'referencia', 'https://www.google.com/maps/search/?api=1&query=RVC%20Turismo%2C%20Barra%20do%20Pira%C3%AD%2C%20RJ', 9, 'publicado', 'guia', 'Vale do Café · pdf 1 p.4');
INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (3, 1, 'hotel-fazenda-sao-sebastiao', 'Hotel Fazenda São Sebastião', '3300308', 'Rua Cel. Christiano Rocha', 'Buscamos que nossos hóspedes desfrutem da vida no campo em um ambiente rústico e acolhedor. Amplo espaço para caminhadas por trilhas e estradas rurais, lagos para pesca, piscina com água constantemente renovada.', 'Seg a Sab 08h30min às 18h - Dom 09h às 16h', '(24) 2437-1426 - (24) 99263-7731 (Whatsapp)', '@hotelfazendasaosebastiao', 'www.hotelfazendasaosebastiao.com.br', 'SIM', 'SIM', 'SIM', -22.3668626, -43.9087054, 'endereco', 'https://www.google.com/maps/place/Hotel+Fazenda+S%C3%A3o+Sebasti%C3%A3o/@-22.3668626,-43.9087054,15z/data=!4m10!3m9!1s0x0:0xcca049ca24eff619!5m4!1s2021-12-05!2i10!4m1!1i2!8m2!3d-22.3668626!4d-43.9087054?sa=X&ved=2ahUKEwiNorWnvq_0AhWCB9QKHX_RAuoQ_BJ6BAhBEAU&shorturl=1', 5, 'publicado', 'guia', 'Vale do Café · pdf 1 p.5');
