INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (4, 1, 'casarao-cultural-vale-do-cafe', 'Casarão Cultural Vale do Café', '3300308', 'Rua Vereador José Alves Pegas, s/n', 'Espaço único no Vale do Café, localizado na Vila Histórica da Piedade em Ipiabas - RJ, foi construído em 1874. Por intermédio do Projeto de Artesanato do qual participam artesãos do Vale do Café, oferece produtos relacionados à Arquitetura Neoclássica e aos temas históricos e culturais da região.Disponibiliza roteiros turísticos e city tour e promove eventos culturais, feiras de produtos orgânicos e de artesanato.Por intermédio do Espaço Vida e Arte valoriza o artista da região que deseja expor seus trabalhos. Dispõe de cafeteria na qual são priorizados os produtos da região e de espaço com peças de antiquário e colecionáveis.', 'Qui a Dom - 10h às 18h', '(24) 98877-0115', '@casaraoculturalvaledocafe / @casaraoipiabas', '', 'NÃO', 'SIM', 'SIM', -22.3946184, -43.905789, 'endereco', 'https://www.google.com/maps/place/Casarao+Cultural+do+Vale+do+Caf%C3%A9/@-22.3946184,-43.905789,15z/data=!4m5!3m4!1s0x0:0x4c1f1be795c68c6f!8m2!3d-22.3946184!4d-43.905789?sa=X&ved=2ahUKEwiWpbrmuK_0AhWdIrkGHX2XAisQ_BJ6BAhEEAM&shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.5');
