INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (6, 1, 'rota-393', 'Rota 393', '3300308', 'Rua José Tavares Filho, 111', 'Turismo receptivo em todo o Vale do Café, associando o turismo rural às experiências ligadas ao ecoturismo, aventura, histórico cultural e gastronômico. Valorizamos as particularidades e potencial do distrito de Ipiabas e como este se relaciona com o meio ambiente e a sustentabilidade.', '09h às 19h / Finais de semana 07h às 21h', '(24) 99934-6077', '@rota_393', '', 'SIM', 'SIM', 'SIM', -22.4781239, -43.8185609, 'endereco', 'https://www.google.com/maps/place/R.+Jos%C3%A9+Tav%C3%A1res+Filho,+111+-+S%C3%A3o+Jo%C3%A3o,+Barra+do+Pira%C3%AD+-+RJ,+27140-410/@-22.4781239,-43.8207496,17z/data=!3m1!4b1!4m5!3m4!1s0x9eb51cdf163e5f:0xcef745b8f026ce47!8m2!3d-22.4781239!4d-43.8185609?shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.6');
