INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (10, 1, 'fazenda-da-taquara', 'Fazenda da Taquara', '3300308', 'RJ 145, 2 Estrada Barra do Piraí', 'Com quase dois séculos de existência, a sede, ainda em perfeito estado de conservação, preserva sua história com móveis e retratos originais. A propriedade recebe visitantes do mundo inteiro, e oferece um delicioso almoço ou café colonial com produtos da própria fazenda. Há também visitação no cafezal , mostrando todo o processo do café até o seu beneficiamento.', '', '(24) 99919-8567', '', 'www.portalvaledocafe.com.br/fazendadataquara', 'NÃO', 'SIM', '', -22.4519265, -43.8381958, 'endereco', 'https://www.google.com/maps/place/RJ-145,+2+-+Barra+do+Pira%C3%AD,+RJ/@-22.4519215,-43.8403845,17z/data=!3m1!4b1!4m6!3m5!1s0x9eb597e639def9:0x7a4e51be8019eb6b!8m2!3d-22.4519265!4d-43.8381958!15sCiFSSiAxNDUsIDIgRXN0cmFkYSBCYXJyYSBkbyBQaXJhw62SARBnZW9jb2RlZF9hZGRyZXNz?shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.8');
