INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (11, 1, 'haras-fire-notes', 'Haras Fire Notes', '3300308', 'Estrada Fazenda da Abundância, 252', 'Desde 1988 o Haras Fire Notes oferece várias atividades, como aulas de equitação, salto, tambor, treinamento funcional, cursos e cavalgadas onde o lazer alia-se à educação ambiental e ao desenvolvimento sustentável da região. Os turistas que visitarem o local poderão interagir com o ambiente natural de Ipiabas e seus diversos atrativos por meio de diferentes roteiros de cavalgadas. (Pedra do Gavião, Cachoeira e diversas trilhas).', 'Ter a Sáb - 08h às 17h / Dom - 08h às 12h', '(24) 99921-2639', '@paulinholavinas', '', 'NÃO', 'SIM', 'SIM', -22.3648681, -43.8761507, 'endereco', 'https://www.google.com/maps/place/Haras+Fire+Notes/@-22.3648681,-43.8761507,15z/data=!4m5!3m4!1s0x0:0xb387dad2c8faaa6e!8m2!3d-22.3648681!4d-43.8761507?shorturl=1', 6, 'publicado', 'guia', 'Vale do Café · pdf 1 p.8');
