INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (12, 1, 'fazenda-da-posse', 'Fazenda da Posse', '3300407', 'Rua Doutor Dario Aragão, 2', 'Café Colonial com agendamento e guiamento contando a História da Fazenda.  Primeira Construção de Barra Mansa, datada de 1768, hoje a Fazenda da Posse abriga um Centro de Documentação e Memória, regido nos termos do Plano Municipal de Cultura e pelo Programa de Ocupação Artística dos Equipamentos Públicos de Cultura. Administrado pela Fundação de Cultura, o CEDOC é um espaço direcionado para pesquisas, produção e armazenamento de documentos relacionados ao universo histórico, social, político e cultural de Barra Mansa e região. Apresenta grande valor histórico-cultural para toda Região. Atualmente é um Centro de Cultura.', '08h à 12h', '(24) 3029-9365', '@culturabarramansa', '', 'SIM', 'NÃO', 'SIM', -22.5474578, -44.1572456, 'endereco', 'https://www.google.com/maps/place/Fazenda+da+Posse+-+Barra+Mansa+RJ/@-22.5474578,-44.1594343,17z/data=!3m1!4b1!4m5!3m4!1s0x9e99492f761bc9:0x18f20c82ef272d39!8m2!3d-22.5474578!4d-44.1572456?shorturl=1', 7, 'publicado', 'guia', 'Vale do Café · pdf 1 p.10');
