INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (14, 1, 'palacio-barao-de-guapy-1857', 'Palácio Barão de Guapy (1857)', '3300407', 'Praça da Bandeira, s/n', 'De arquitetura neoclássica, o prédio teve sua construção iniciada no ano de 1857, na administração do Comandante Lucas Antônio Monteiro de Barros, e concluída em 1865, na gestão do Comendador Joaquim José Ferraz de Oliveira, o Barão de Guapi. Foi tombado em 1979 pelo Instituto Estadual do Patrimônio Cultural (Inepac). Em 1914, a Câmara Municipal cedeu a parte térrea para que nela fosse instalada a Prefeitura de Barra Mansa, que durante 70 anos funcionou no local. No plenário do Legislativo, chamam atenção as cadeiras em couro trabalhado, lustres de cristal e uma pinacoteca de valor histórico relevante. Atualmente abriga a Biblioteca Municipal. Mantém o salão do plenário e pinturas preservadas.', '08h às 17h', '(24) 3029-9365', '@culturabarramansa', 'www.cultura.patrimonio@barramansa.rj.gov.br', 'NÃO', 'NÃO', 'SIM', -22.5426711, -44.1718512, 'endereco', 'https://www.google.com/maps/place/Pal%C3%A1cio+Bar%C3%A3o+De+Guapi/@-22.5426749,-44.1740406,17z/data=!3m1!4b1!4m5!3m4!1s0x9e995626492c61:0x7c7a2ef510333e56!8m2!3d-22.5426711!4d-44.1718512?shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.11');
