INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (15, 1, 'destilaria-amazzoni', 'Destilaria Amázzoni', '3300407', 'Rodovia Presidente Dutra S/N – KM 291', 'Tour pela destilaria com explicação do processo produtivo e história + shot de degustação dos 3 produtos. O Amázzoni Gin foi eleito pelo World Gin Awards como o melhor gin do mundo em 2021.', '09h às 17h', '(24) 99901-8319', '@amazzonigin', 'www.amazzonigin.com', 'SIM', 'SIM', '', -22.4534357, -44.3102739, 'endereco', 'https://www.google.com/maps/place/Destilaria+Am%C3%A1zzoni/@-22.4534377,-44.3125064,17z/data=!4m5!3m4!1s0x9e85a3eadc0fb5:0x483ad8b4eb426015!8m2!3d-22.4534357!4d-44.3102739?q=Destilaria+Gin+Amazzoni&um=1&ie=UTF-8&sa=X&ved=2ahUKEwjz9qa4y6_0AhUFrHIEHeI3ADEQ_AUoA3oECAEQBQ&shorturl=1', 9, 'publicado', 'guia', 'Vale do Café · pdf 1 p.11');
