INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (16, 1, 'parque-centenario-jardim-das-preguica', 'Parque Centenário Jardim das Preguiça', '3300407', 'R. Custódio Ferreira Leite', 'Neste Parque encontram-se 25 bichos preguiças que vivem soltas por entre as árvores e Caminhos em pleno centro da cidade. O Parque Centenário, também conhecido como Praça da Bandeira, é um parque urbano projetado pelo engenheiro e paisagista francês Auguste François Marie Glaziou, a pedido de Joaquim José Ferraz de Oliveira, o Barão de Guapy, primeiro presidente da Câmara Municipal de Barra Mansa. Criado na década de 1870, o Parque já foi reorganizado pelo paisagista Burle Marx, em 1991. O parque já foi chamado de “Jardim de Baixo”, já que havia o “Jardim de Cima” no Largo da Matriz, mas o nome “Parque Centenário” foi dado em 1922, como uma homenagem ao centenário da Independência do Brasil. Algum tempo depois, levou o nome de Praça Feliciano Sodré, em homenagem ao então governador do Estado. Em 1932, no ano do centenário de Barra Mansa, o prefeito Izimbardo Peixoto, por meio de uma lei municipal, devolveu a denominação de ‘Parque Centenário’. Conhecido como Jardim das Preguiças, ganhou o pseudônimo por hospedar o bicho preguiça, que passeia nas árvores, antigas e altas.', '08h às 20h', '', '', '', 'NÃO', 'NÃO', '', -22.5435045, -44.1721749, 'endereco', 'https://www.google.com/maps/place/Jardim+das+Pregui%C3%A7as+-+Centro,+Barra+Mansa+-+RJ/@-22.5434518,-44.1742497,17z/data=!3m1!4b1!4m6!3m5!1s0x9e9bfdf61a2223:0x6fe0a0a0e4bf9d6!8m2!3d-22.5435045!4d-44.1721749!15sCidQYXJxdWUgQ2VudGVuw6FyaW8gSmFyZGltIGRhcyBQcmVndWnDp2GSAQt0b3duX3NxdWFyZQ?shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.12');
INSERT INTO atrativo_termos (atrativo_id, termo_id) VALUES (16, 1);
