INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (17, 1, 'fazenda-cachoeira', 'Fazenda Cachoeira', '3300407', 'Alambique Cachaça Rochinha', 'Cuidadosamente reconstruída, mantém as características da arquitetura do final do século XVIII, tendo sido erguida por volta de 1717. A fazenda Cachoeira, dedicou-se inicialmente ao plantio da cana para a produção de açúcar e aguardente, tendo adotado mais tarde o cultivo do café, que era o grande produto da cidade durante o período imperial. A Cachaçaria Rochinha está aberta à visitação, incluindo degustação de produtos e conhecimento de fases do processo produtivo, uma verdadeira viagem ao Brasil Império, com os sabores e aromas do campo.', '10h às 17h', '(24) 3353-2920', '', 'www.rochinha.com.br/site/index.asp', 'SIM', 'SIM', '', -22.4537504, -44.310079, 'endereco', 'https://www.google.com/maps/place/Fazenda+Cachoeira+-+Alambique+Cacha%C3%A7a+Rochinha/@-22.4537504,-44.3122677,17z/data=!3m1!4b1!4m5!3m4!1s0x9e85cdb3116113:0x7105548f4039cd50!8m2!3d-22.4537504!4d-44.310079?shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.12');
