INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (21, 1, 'artesanato-stella-carvalho', 'Artesanato Stella Carvalho', '3300407', 'Rua Ary Kerner Thomas da Costa, 74 - Amparo', 'É no próprio local que os artesãos fabricam suas peças e dão aula de artesanato para o moradores do Distrito. Construído pela Associação das Damas de Caridade de Amparo, em 1981. Entre seus objetivos estão o incentivo às habilidades artesanais e a facilitação do acesso ao mercado de vendas, cujos resultados revertem para as artesãs, como uma espécie de cooperativa. O projeto foi do Engenheiro Luiz Roberto Correia Reche e mostra uma fachada com esquadria em estilo colonial, mantendo o clima do cenário histórico de Amparo. As colchas de retalhos produzidas pelo artesanato são famosas, conhecidas inclusive em outros países, tornando-se um referencial de Amparo.', '', '', '@artesanato.stelladecarvalho', '', 'NÃO', 'NÃO', 'SIM', -22.5418152, -44.177568, 'endereco', 'https://www.google.com/maps/place/Banca+Do+Amparo/@-22.5418152,-44.177568,15z/data=!4m5!3m4!1s0x0:0xdce63c526da16fc8!8m2!3d-22.5418152!4d-44.177568?shorturl=1', 8, 'publicado', 'guia', 'Vale do Café · pdf 1 p.14');
