INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (42, 1, 'parque-equestre-felipe-azevedo', 'Parque Equestre Felipe Azevedo', '3302908', 'Est. Dr. Audifaz Gonçalves de Azevedo Filho, 945', 'O local possui instalações de qualidade, dispondo de ampla área, com diversos piquetes, 50 cocheiras e cinco pistas espaçosas (duas de areia e três de grama), todas em excelente condições, além de picadeiro e trilhas destinadas a passeios ecológicos.  Luiz Felipe de Azevedo, é detentor de diversos títulos, possuindo, inclusive, duas medalhas olímpicas de bronze (Atlanta e Sidnei) e uma medalha de ouro obtida no pan-americano de Havana (Cuba), além do título de Campeão Americano e do recorde de potência, alcançado em Roma (Itália), em 2001, quando saltou 2.32 metros.', '08h às 18h', '(24) 9987-07832', '', '', 'SIM', 'NÃO', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Parque%20Equestre%20Felipe%20Azevedo%2C%20Miguel%20Pereira%2C%20RJ', 6, 'publicado', 'guia', 'Vale do Café · pdf 1 p.27');
