INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (62, 1, 'museu-da-cachaca', 'Museu da Cachaça', '3303856', 'Rua General Cintra, 447', 'Museu da Cachaça é o primeiro no gênero no país. Seus idealizadores, Íris e Iale Renan (hoje falecido), inauguraram o Museu em 1991 e foram necessários anos de pesquisas em bibliotecas e colecionando algumas centenas de garrafas compradas em todos os cantos do Brasil, para montar este acervo vasto e peculiar, que é apresentado aos seus visitantes junto com quadros, coleções de crônicas e artigos, livros especializados, trovas populares, um antigo mini alambique, dentre muitos outras atrações, que compõem a importante história da cachaça. No Museu da Cachaça também estão instaladas uma indústria artesanal de aguardente, duas adegas e um bar para degustação gratuita.', 'Ter e Sex 09h às 18h Sab 09h às 19h a Dom 09h às 17h', '(24) 2485.1475', '', '', 'NÃO', 'NÃO', '', -22.4197537, -43.428882, 'endereco', 'https://www.google.com/maps/place/Museu+da+Cacha%C3%A7a+-+Paty+do+Alferes/@-22.4197538,-43.428886,15z/data=!4m5!3m4!1s0x0:0x717ca9f7deb89e65!8m2!3d-22.4197537!4d-43.428882?shorturl=1', 3, 'publicado', 'guia', 'Vale do Café · pdf 1 p.39');
