INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (72, 1, 'hotel-fazenda-sao-joao-de-pirai', 'Hotel Fazenda São João de Piraí', '3304003', 'Est. Municipal Piraí Santanézia - Enseada da Garças, Piraí', 'Possui uma vasta área rural com mais de 1 milhão de metros quadrados. Composta por pastos, criação de animais, lagos, muito verde e ar puro, produção de laticínios e doces caseiros, sem falar do visual indescritível do nascer e do pôr do sol. Há também um lago, que é ideal para pesca esportiva e atividades aquáticas, criando experiências únicas com verdadeiro contato da vida no campo e assim um ambiente ideal para exercícios, caminhadas, corridas, passeios de bicicletas, cavalgadas, trilhas off-road, mountain bike e qualquer atividade ao ar livre.', '', '(24) 99966-7287', '@hotelfazendasaojoaodepirai', 'www.hotelsaojoao.com.br', 'NÃO', 'SIM', '', -22.5689163, -43.8414459, 'endereco', 'https://www.google.com/maps/place/Hotel+Fazenda+S%C3%A3o+Jo%C3%A3o+de+Pira%C3%AD/@-22.5689113,-43.8436346,17z/data=!3m1!4b1!4m8!3m7!1s0x9eb269b68e6cc7:0x3937cc94cef23834!5m2!4m1!1i2!8m2!3d-22.5689163!4d-43.8414459?shorturl=1', 2, 'publicado', 'guia', 'Vale do Café · pdf 1 p.46');
