INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (73, 1, 'clube-de-pesca-pirai', 'Clube de Pesca Piraí', '3304003', 'RJ – 139 Km 85, s/n , Piraí - RJ', 'Criado em 1966 por pescadores amadores e funcionários da Light, o Clube de Pesca de Piraí teve grande importância para a preservação ambiental na Represa de Ribeirão das Lajes e seu entorno. Com ações em parceria com a Light realizou campanhas de repeixamento e tem servido de base de apoio para diversas atividades da Marinha e do Exército.', '', '(24) 99316-9286 / (24) 99316-9121', '@clubedepescapirai', '', 'NÃO', 'NÃO', '', -22.6971638, -43.9064728, 'endereco', 'https://www.google.com/maps/place/Clube+de+Pesca+de+Pira%C3%AD/@-22.6971862,-43.9086294,17z/data=!3m1!4b1!4m5!3m4!1s0x9ea919dd421ec5:0xc96bf9426c23cd01!8m2!3d-22.6971638!4d-43.9064728?shorturl=1', 5, 'publicado', 'guia', 'Vale do Café · pdf 1 p.46');
