INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (74, 1, 'hotel-fazenda-st-robert', 'Hotel Fazenda St Robert', '3304003', 'Est. Sanatório da Serra Paracambi, 6440', 'Toda roça que se preze tem muitos animais. Na Mini Fazendinha seus filhos vão poder ficar bem perto do nossos bichinhos e interagir com eles de um jeito impossível de se fazer hoje em dia nas grandes cidades do país. Conhecer a Mini Fazendinha também é um momento para permitir que seu filho tenha algumas experiências únicas. As crianças poderão ordenhar as vaquinhas ou alimentar os muitos coelhos da Coelhândia. Os pequenos também terão a oportunidade de interagir com galinhas, patinhos e muito mais. Por fim, a Mini Fazendinha também conta com outros moradores muito nobres, como Os Três Porquinhos e os búfalos Bull e Bill.  As duas estrelas da fazenda são os mascotes Bob Panga e a Vaquinha Lili. Eles são os favoritos da criançada. Outra parada obrigatória desse passeio, que agrada desde os pequenos até os mais velhos, é acerca do Boi Bandido. Ali, o objetivo é bater uma foto do bicho mais invocado da fazendinha.', '', '(21) 3597-7299 / (21) 3597-7281 / (21) 97291-5650', '@hotelfazendastrobert', 'hotelfazendastrobert.com.br', 'NÃO', 'SIM', '', -22.592339, -43.7910695, 'endereco', 'https://www.google.com/maps/place/Estr.+Sanat%C3%B3rio+da+Serra+Paracambi,+6440+-+Sanat%C3%B3rio+da+Serra,+Pira%C3%AD+-+RJ,+27175-000/@-22.592334,-43.7932582,17z/data=!3m1!4b1!4m5!3m4!1s0x9eb2b2d20ee97f:0xb86f7277d47c25f4!8m2!3d-22.592339!4d-43.7910695?shorturl=1', 7, 'publicado', 'guia', 'Vale do Café · pdf 1 p.47');
