INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (77, 1, 'hotel-fazenda-cascatinha', 'Hotel Fazenda Cascatinha', '3304003', 'Estrada Sanatorio da Serra, 6200', 'O Hotel Fazenda Cascatinha situa-se em um belíssimo cenário cercado de verde e muito espaço, numa verdadeira e acolhedora fazenda planejada com confortável infraestrutura para receber você e sua família. Ambiente ideal para quem procura hospitalidade, lazer, diversão e relaxamento; além da tranquilidade e segurança que um bucólico ambiente rural proporciona. Local propício para você colocar sua saúde mental em dia.', 'Segunda à Sexta - 09h às 17h', '(21) 2221-1714 / (21) 2221-1905 / (21) 2262-7831', '@hotelfazendacascatinha', 'hotelfazendacascatinha.com.br', 'NÃO', 'SIM', '', -22.5902446, -43.7717924, 'endereco', 'https://www.google.com/maps/place/Estr.+Sanat%C3%B3rio+da+Serra+Paracambi,+6200+-+Pira%C3%AD,+RJ,+27175-000/@-22.5902396,-43.7739811,17z/data=!3m1!4b1!4m5!3m4!1s0x994d3f38857ed5:0xf0f4d96473f5212e!8m2!3d-22.5902446!4d-43.7717924?shorturl=1', 7, 'publicado', 'guia', 'Vale do Café · pdf 1 p.48');
