INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (84, 1, 'parque-arqueologico-e-ambiental-de-sao-joao-marcos', 'Parque Arqueológico e Ambiental de São João Marcos', '3304409', 'Estrada RJ 149, Km 20', 'No Parque, os visitantes têm conforto e segurança para desfrutar de uma experiência para todos os sentidos: admirar as paisagens da Mata Atlântica e de Ribeirão das Lajes, ouvir o canto dos pássaros e experimentar no Quiosque quitutes resgatados do livro de receitas da Dona Cidinha, ex-moradora. A admissão é gratuita, assim como todas as atividades. No Circuito de Visitação, o destaque são as ruínas da Igreja Matriz e da Casa do Capitão-mor, Centro de Memória com maquete e exposição, anfiteatro e campo de futebol. Há ainda o observatório de pássaros, Sala de Energia Criativa, horta orgânica, viveiro de mudas, mirante, Espaço de Leitura Fagundes Varela, jardim sensorial, estacionamento e banheiro com acessibilidade.', 'Qua a Sex 10h às 16h / Sáb a Dom 9h às 17h', '', '@parquesaojoaomarcos', 'saojoaomarcos.com.br', 'NÃO', 'NÃO', 'SIM', -22.8422798, -44.0535744, 'endereco', 'https://www.google.com/maps/place/S%C3%A3o+Jo%C3%A3o+Marcos,+Rio+Claro+-+RJ,+27460-000/@-22.8422792,-44.0623292,15z/data=!3m1!4b1!4m6!3m5!1s0x9c17050a7c2091:0xbf95a8dd497c36ad!8m2!3d-22.8422798!4d-44.0535744!15sCj9QYXJxdWUgQXJxdWVvbMOzZ2ljbyBlIEFtYmllbnRhbCBkZSBTw6NvIEpvw6NvIE1hcmNvcyByaW8gY2xhcm-SAQhsb2NhbGl0eQ?shorturl=1', 4, 'publicado', 'guia', 'Vale do Café · pdf 1 p.53');
