INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (92, 1, 'fazenda-uniao', 'Fazenda União', '3304508', 'Estrada do Abarracamento RJ 135 km 25', 'São mais de cento e quarenta hectares de natureza onde se forma um vale único repleto de história. Paisagens incríveis podem ser apreciadas enquanto respira-se o perfume das flores que crescem nos jardins da propriedade levando os visitantes a uma renovação de energia. Passeios a cavalo ou de quadriciclo, ordenha na mini-vaca, cavalgada na baia de areia, tirar uma fotografia com as simpáticas e fotogênicas ovelhinhas, ou com os pavões Custódio e Bernardino, sem esquecer da mascote, a jumentinha Ana-Bella, e ainda alimentar as galinhas e pescar no lago. Aos que apenas gostam de curtir a natureza, admirar os cantos dos pássaros, fazer uma caminhada pelas trilhas da fazenda ou até um cochilinho nos redários.', '08h às 10h', '(24) 99915-1210 (Whatsapp)', '@fazenda_uniao', 'www.fazendauniao.com.br', 'SIM', 'SIM', 'SIM', -22.1762943, -43.5628396, 'endereco', 'https://www.google.com/maps/place/Hotel+Fazenda+Uni%C3%A3o/@-22.1763862,-43.5627514,15z/data=!4m10!3m9!1s0x0:0x148cec111f05793d!5m4!1s2021-12-05!2i10!4m1!1i2!8m2!3d-22.1762943!4d-43.5628396?shorturl=1', 4, 'publicado', 'guia', 'Vale do Café · pdf 1 p.58');
