INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (96, 1, 'cachaca-werneck', 'Cachaça Werneck', '3304508', 'Estrada Rio das Flores x Barreado , 9001', 'Uma cachaça artesanal com padrões de qualidade equivalentes aos utilizados na produção dos melhores destilados do mundo, produzida pelo casal Cilene e Eli Werneck. O visitante pode conhecer detalhadamente cada fase do processo, pois Eli possui planilhas para todas as fases do processo de produção, com rastreabilidade total. Olhando uma garrafa, pela etiqueta de lote, é possível dizer de que área do canavial saiu a cana e em que dia ou período ela foi cortada e moída.  Isso trouxe como consequência ser o primeiro produtor do estado do Rio de Janeiro a receber a Certificação INMETRO de Qualidade e Sustentabilidade.', '', '(24) 99298-9998 - (24) 99298-9900', '@cachacawerneck', 'www.cachacawerneck.com.br', 'SIM', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Cacha%C3%A7a%20Werneck%2C%20Rio%20das%20Flores%2C%20RJ', 3, 'publicado', 'guia', 'Vale do Café · pdf 1 p.60');
