INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (100, 1, 'hotel-fazenda-vilarejo', 'Hotel Fazenda Vilarejo', '3306107', 'Rodovia Canção do Amor, 13685', 'Hotel Fazenda Vilarejo conta com Fazendinha com animais de verdade, horta orgânica, pedalinho no lago, pesqueiro, passeio a cavalo e de bicicleta, ampla área verde com recreação para todas as idades, festas temáticas o ano inteiro e o Vilarejo Radical, com 2 mega tirolesas, arvorismo, parede de escalada e rapel. Temos Piscina aberta com toboágua e parque aquático infantil e piscina coberta. Cinema, Espaço Kids e Espaço Zen. Além de usufruir de toda estrutura do hotel, os hóspedes podem viver uma experiência única em visita à produção da Cachaçaria Vilarejo, onde são feitos artesanalmente os rótulos de cachaças e licores Vilarejo. Nosso all inclusive oferece café, lanche, almoço, petiscos, jantar e comidas temáticas de acordo com o calendário de festas anual do Hotel. Bebidas alcoólicas e não alcoólicas durante todo o período de hospedagem nos três bares disponíveis no hotel.', '10h às 20h', '(24) 2438-9000 - (24) 99981-6803 (Whatsapp)', '@hotelvilarejo', 'www.hotelfazendavilarejo.com.br', 'SIM', 'SIM', '', -22.294727, -43.925755, 'endereco', 'https://www.google.com/maps/place/Hotel+Fazenda+Vilarejo/@-22.2919127,-43.9193499,15z/data=!4m10!3m9!1s0x9ec58c475c2875:0xb0a6ef9483c9650e!5m4!1s2021-12-05!2i10!4m1!1i2!8m2!3d-22.294727!4d-43.925755?shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.63');
