INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (102, 1, 'parque-natural-municipal-do-acude-da-concordia', 'Parque Natural Municipal do Açude da Concórdia', '3306107', 'Rodovia RJ 145, Km 45', 'O Açude da Concórdia com certeza é um lindo lugar onde se mantém contato com a natureza quase intocada e um ótimo lugar para fazer um daqueles piqueniques com a família no final de semana. Suas águas transparentes e frias têm 4.170 metros de contorno. Inserido em área florestal com resquícios da Mata Atlântica. É contornado por vegetação de pastagem e um caminho gramado propício à caminhada. Durante o percurso pode-se ouvir animais como o inhambu, juriti, e o jacu', 'QUI a DOM - 09h às 17h', '(24) 99215-0962', '', '', 'NÃO', 'SIM', 'SIM', -22.3479976, -43.7627041, 'endereco', 'https://www.google.com/maps/place/Parque+Natural+Municipal+do+A%C3%A7ude+da+Conc%C3%B3rdia/@-22.3479926,-43.7648928,17z/data=!3m1!4b1!4m5!3m4!1s0x993365539445d7:0xf77de39fddbea2cf!8m2!3d-22.3479976!4d-43.7627041?shorturl=1', 6, 'publicado', 'guia', 'Vale do Café · pdf 1 p.64');
