INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (104, 1, 'capril-do-lago', 'Capril do Lago', '3306107', 'Rua Boa Ventura, Canteiro, Valença', 'O tour guiado consiste no passeio pelo capril com participação do trato de nossas cabras e retirada do leite. Há também tour com degustação de produtos feitos com o leite das cabras do Lago, como diversos queijos, doces e tortas. Inclui um lanche com bolos, broas, biscoitos e suco. E um brinde com sabonete de leite de cabra e um doce de leite artesanal. Além de todo o passeio guiado e o lanche, as crianças que acompanham os pais neste guia com a degustação, têm direito a dar uma mamadeira para a cabra sem custo adicional', 'Sáb de 09h às 11h e 14h às 16h', '(24) 98145-4441', '@caprildolago', '', 'NÃO', 'SIM', '', -22.2692738, -43.7328808, 'endereco', 'https://www.google.com.br/maps/place/R.+Boa+Ventura+-+Varginha,+Valen%C3%A7a+-+RJ,+27600-000/@-22.2692688,-43.7350695,17z/data=!3m1!4b1!4m5!3m4!1s0x992c3884ce7375:0x556193c791c984bc!8m2!3d-22.2692738!4d-43.7328808?shorturl=1', 2, 'publicado', 'guia', 'Vale do Café · pdf 1 p.65');
