INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (105, 1, 'fazenda-cachoeira-grande', 'Fazenda Cachoeira Grande', '3306206', 'Estrada Fazenda Cachoeira, 1639', 'Datada de 1820, O programa consiste em visita à sede, onde será contada a história da fazenda, sua recuperação, além de informações sobre o mobiliário existente e objetos, os jardins e lago bem como museu de carros antigos e as ruínas de petrechos usados para secar e beneficiar arroz são experiências únicas que a fazenda proporciona aos seus visitantes. Ao final do tour é servido um delicioso café com comidas típicas.', 'Seg. a seg. 10h às 19h', '(24) 2471-1264 - (21) 999114339 whatsapp', '@fazendacachoeiragranderj', 'fazendacachoeiragrande.com.br', 'SIM', 'SIM', 'SIM', -22.4466214, -43.6981404, 'endereco', 'https://www.google.com/maps/place/Fazenda+Cachoeira+Grande/@-22.4466214,-43.7003291,17z/data=!3m1!4b1!4m5!3m4!1s0x9930c3f7f357c7:0x19324f850f011217!8m2!3d-22.4466214!4d-43.6981404?shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.67');
