INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (108, 1, 'fazenda-sao-luiz-da-boa-sorte-museu-do-cafe', 'Fazenda São Luiz da Boa Sorte / Museu do Café', '3306206', 'Rodovia BR 393, Km 210', 'Recebe para visitas guiadas, hospedagens, atividades pedagógicas e eventos turístico-culturais. Uma verdadeira viagem de volta ao passado. A visita à fazenda inclui também o único Museu do Café do estado do Rio.  Uma experiência única e muito especial. O museu foi concebido para que a história dos escravos na época dos Barões do Café fique preservada e seja contada por muitas gerações. Uma visita enriquecedora de cultura e conhecimento, proporcionando uma experiência única ao visitante.', '02h às 03h', '(24) 99298-7204', '', 'www.fazendasaoluizdaboasorte.com.br', 'SIM', 'SIM', 'SIM', -22.3931726, -43.6529209, 'referencia', 'https://www.google.com/maps/search/?api=1&query=Fazenda%20S%C3%A3o%20Luiz%20da%20Boa%20Sorte%20/%20Museu%20do%20Caf%C3%A9%2C%20Vassouras%2C%20RJ', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.69');
