INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (109, 1, 'fazenda-uniao-carvalheira', 'Fazenda União Carvalheira', '3306206', 'Via Ipiranga RJ137, n˚ 8676', 'Visita Guiada pelo Alambique desde o processamento do Caldo de Cana até a estocagem em Toneis. Degustação das cachaças e licores, Caldo de cana com os deliciosos pastéis e bolos da Luiza. Passeio de Trenzinho da Estrada de Ferro União Carvalheira. Circuito de aproximadamente 1 km passando por túnel, pontes e lagos. Tem restaurante, e ainda passeio de pedalinho pelo lago.', '', '(24) 99819-8200', '', '', 'NÃO', 'SIM', 'SIM', -22.4084352, -43.6602673, 'endereco', 'https://www.google.com/maps/place/R.+Bar%C3%A3o+de+Vassouras,+33+-+Centro,+Vassouras+-+RJ,+27700-000/@-22.4084302,-43.662456,17z/data=!3m1!4b1!4m5!3m4!1s0x9930c65fe36cd9:0x58a0914be8a6a3fb!8m2!3d-22.4084352!4d-43.6602673?shorturl=1', 3, 'publicado', 'guia', 'Vale do Café · pdf 1 p.70');
