INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (110, 1, 'fazenda-santa-eufrasia', 'Fazenda Santa Eufrásia', '3306206', 'Rodovia BR 393, Km 242', 'Construída por cerca de 1830, a única fazenda particular tombada pelo Instituto de Patrimônio Histórico e Artístico Nacional (IPAM) em Vassouras, é uma das construções históricas mais importantes da área. visitas guiadas com turistas pelas edificações com pessoal vestida com roupas da época. O passeio passa por três quartos mobiliados com artefatos da época e pela sala de música. Ao final, os visitantes podem degustar do café produzido na fazenda, é possível agendar um piquenique também.', 'Sob consulta', '(24) 99994-9494', '', 'www.fazendasantaeufrasia.com.br', 'NÃO', 'SIM', 'SIM', -22.3128776, -43.5138001, 'referencia', 'https://www.google.com/maps/search/?api=1&query=Fazenda%20Santa%20Eufr%C3%A1sia%2C%20Vassouras%2C%20RJ', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.70');
