INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (115, 1, 'vassouras-eco-resort', 'Vassouras Eco Resort', '3306206', 'Estrada Aliança, 665, Bairro Aliança', 'Com uma grande variedade de pacotes o Vassouras Eco Resort está localizado no Vale do Café, uma área repleta de belezas naturais de tirarem o fôlego. Por aqui, respeitamos e nos preocupamos com a natureza e adotamos diversas práticas sustentáveis. Em reconhecimento a esses esforços, e por cumprirmos as resoluções de proteção ambiental, conquistamos o Certificado Ambiental do Ibama. Afinal, acreditamos que é possível oferecer o melhor para você, sem prejudicar os nossos recursos naturais, por meio de um turismo sustentável de qualidade.', '24h', '(24) 2491-9100 - (24) 99252-5780', '@vassourasecoresort', 'www.vassourasecoresort.com.br/', 'SIM', 'SIM', '', -22.3075508, -43.5546675, 'endereco', 'https://www.google.com/maps/place/Vassouras+Eco+Resort/@-22.3073394,-43.554736,19z/data=!4m9!3m8!1s0x0:0x10cad4f9e260072!5m2!4m1!1i2!8m2!3d-22.3075508!4d-43.5546675!15sChRWYXNzb3VyYXMgRWNvIFJlc29ydJIBDHJlc29ydF9ob3RlbA?shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.72');
