INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (116, 1, 'fazenda-sao-roque', 'Fazenda São Roque', '3306206', 'Rodovia Lúcio Meira, km 245', 'Um lindo casarão em “L” disposto sobre um platô ladeado por um muro de arrimo em pedra seca que delimita o antigo terreiro de café da propriedade. Um vasto campo gramado e antigas ruínas formam cenários perfeitos para cerimônias ao ar livre, trazendo todo o charme dos casamentos no campo, com a bela fazenda histórica de fundo. Realiza um teatro histórico com mais de 10 atores e um grupo de jongo e maculelê. A composição entre o casarão, grandes árvores dispostas em torno dele e o muro feito de pedras que cerca ambos, dão a dimensão da beleza do lugar. a propriedade dedica-se a hotelaria e ao passeio histórico.', '', '(21) 97977-7555', '', 'www.fazendasaoroque.com.br/', 'NÃO', 'SIM', '', -22.4265918, -43.7580375, 'endereco', 'https://www.google.com/maps/place/Fazenda+S%C3%A3o+Roque/@-22.4265868,-43.7602262,17z/data=!3m1!4b1!4m5!3m4!1s0x993501f0fa0af7:0x2570fc788f7b69e5!8m2!3d-22.4265918!4d-43.7580375?shorturl=1', 1, 'publicado', 'guia', 'Vale do Café · pdf 1 p.73');
