INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (117, 1, 'hotel-fazenda-galo-vermelho', 'Hotel Fazenda Galo Vermelho', '3306206', 'Rodovia RJ - 121, 681', 'No Hotel Fazenda Galo Vermelho você encontra aconchego, carinho e uma completa estrutura de lazer. Além de fazendinha, horta orgânica, ordenha e passeio de charrete, possui toda estrutura de lazer para toda a família: recreação, canoagem, piscina, piscina aquecida, arco e flecha e parede de escalada entre outros. Tudo isso cercado por belíssimas sedes de fazendas históricas.', '', '(24) 2491-9501 | (24) 2491-9502 - (24) 9 8855-7031', '@hfgvermelho', 'www.hotelfazendagalovermelho.com.br', 'NÃO', 'SIM', '', -22.455307, -43.652624, 'endereco', 'https://www.google.com/maps/place/Hotel+Fazenda+Galo+Vermelho/@-22.455307,-43.652624,15z/data=!4m10!3m9!1s0x0:0x1c63e6d138ccaa8!5m4!1s2021-12-05!2i10!4m1!1i2!8m2!3d-22.455307!4d-43.652624?sa=X&ved=2ahUKEwjO5Leoycb0AhWaILkGHTyIBd0Q_BJ6BAhMEAU&shorturl=1', 4, 'publicado', 'guia', 'Vale do Café · pdf 1 p.73');
