INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (121, 1, 'cooperativa-de-mulheres-nativas-de-arraial-do-cabo', 'Cooperativa de Mulheres Nativas de Arraial do Cabo', '3300258', 'Rua Epitácio Pessoa, 14 - Fundos', 'As mulheres nativas são mulheres idosas, que pescam, beneficiam, preparam e comercializam seus produtos. Além de serem responsáveis por todo o processo, elas são atuantes na luta pela pesca artesanal dentro da ResexMar de Arraial do Cabo (que é uma Unidade de Conservação Federal), promovem o resgate das tradições cabistas e ensinam outras mulheres a pescar. Na sede da Cooperativa de Mulheres Nativas, acontece a degustação de pratos com referência ao mar e a cultura da pesca tradicional, e também preparam cachaças com camboi - conhecido como "úisque cabista" - e outros frutos e sementes da Restinga de Massambaba, resgatando parte da história e da cultura popular cabista. Tudo acompanhado de muita prosa e histórias incríveis das "MULHERES MARAVILHAS DA PESCA".', 'Não informado.', '22 98174-2795', '@mulheresnativas.cooperativa', '', 'NÃO', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Cooperativa%20de%20Mulheres%20Nativas%20de%20Arraial%20do%20Cabo%2C%20Arraial%20do%20Cabo%2C%20RJ', 3, 'publicado', 'guia', 'Costa do Sol · pdf 2 p.8');
