INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (129, 1, 'pousada-fazenda-sao-joao', 'Pousada Fazenda São João', '3301306', 'Estrada Velha Rio Dourado - Barra de São João', 'Local onde o hóspede pode vivenciar experiências de um dia na fazenda: ordenha, passeios a cavalo, de charrete, contato com os animais, e também a famosa caminhada contornando o Morro São João, ou a caminhada do Vulcão.. O imóvel do século XVIII, construído em estilo colonial português, mantém suas características históricas e naturais preservadas. A área de 200 alqueires fica a 50 metros do nível do mar, no Morro São João.', '24 horas.', '22 2777-4625 / 22 99990-3444', '@pousadafazendasaojoao', 'www.pousadadafazenda.com', 'SIM', 'NÃO', 'SIM', -22.5427197, -42.0117833, 'endereco', 'https://www.google.com.br/maps/place/Pousada+Fazenda+S%C3%A3o+Jo%C3%A3o/@-22.5427145,-42.0139708,17z/data=!3m1!4b1!4m8!3m7!1s0x97b177a6f5ff3f:0xa30b7112d2b82389!5m2!4m1!1i2!8m2!3d-22.5427197!4d-42.0117833?shorturl=1', 6, 'publicado', 'guia', 'Costa do Sol · pdf 2 p.16');
