INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (132, 1, 'arrastao-da-cultura', 'Arrastão da Cultura', '3301876', '', 'O roteiro Arrastão da Cultura remonta a história, trazendo curiosidades da cultura local. Passando por lugares históricos, como o Bairro Estação, é possível ver o espaço onde existia a Antiga Estação Ferroviária. O passeio segue pela antiga rota dos tropeiros, por antigos armazéns e sítios arqueológicos. Localizado às margens da Lagoa de Araruama, é possível embarcar no Coração de Iguaba Grande. No Sítio Palinha é servido um típico café da roça. No Sítio Angino, o destaque é para a antiga rota dos tropeiros e suas nascentes. A recepção é feita pelos proprietários do local, onde são comercializados produtos agroecológicos. Paradas no Sítio dos Dias, no Sítio da Dona Vilma e no Espaço Ecológico Celia Barbosa da Silva (Lagoa do Bulcão), onde é possível realizar uma pequena trilha e apreciar algumas espécies de Aroeira, Ipê, Flamboyant, Saguis, Galo da Serra, Canário da Terra e outras espécies da fauna e flora presentes, também fazem parte do roteiro. O roteiro é finalizado com um delicioso almoço no Restaurante Mineiro.', 'O percurso é feito de jardineira ou micro-ônibus, com duração de 7 horas e os sítios visitados são agendados previamente', '22 99282 5930 (apenas Whatsapp)', '', '', 'NÃO', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Arrast%C3%A3o%20da%20Cultura%2C%20Iguaba%20Grande%2C%20RJ', 1, 'publicado', 'guia', 'Costa do Sol · pdf 2 p.19');
