INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (134, 1, 'lagoa-do-bulcao', 'Lagoa do Bulcão', '3301876', 'Estrada Da Capivara S/N - Coqueiros', 'Um espaço ecológico criado em 2020, com intuito de preservar e promover espaço de lazer e educação ambiental,composto por uma quadra, uma trilha que dá acesso ao monte de oração, espaço para exposição de artesanato local, área para recreação infantil e um lago. Nessa localidade é possível realizar uma pequena trilha e apreciar algumas espécies de Aroeira, Ipê, Flamboyant e saguis, galo da serra, canário da terra e outras espécies da fauna e flora presentes em nossa cidade.', 'Livre.', '', '', '', 'NÃO', 'NÃO', 'NÃO', -22.8218841, -42.2061915, 'referencia', 'https://www.google.com/maps/search/?api=1&query=Lagoa%20do%20Bulc%C3%A3o%2C%20Iguaba%20Grande%2C%20RJ', 6, 'publicado', 'guia', 'Costa do Sol · pdf 2 p.20');
