INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (144, 1, 'caminhos-de-sapeatiba', 'Caminhos de Sapeatiba', '3301876', '', 'Embarque no Coração de Iguaba Grande, localizado às margens da lagoa de Araruama e seguimos para o Parque Ecológico Célia Barbosa Da Silva - Lagoa Do Bulcão, um espaço ecológico criado em 2020, com intuito de preservar e promover educação ambiental. Nessa localidade é possível realizar uma pequena trilha e apreciar algumas espécies de Aroeira, Ipê, Pau Brasil, Pau Ferro, Saguis, Galo da Serra, Canário da Terra, Tiê sangue, Tiziu e outras espécies da fauna e flora presentes em nossa cidade. A próxima parada é no Sítio Ivonilda, onde é oferecido o café da manhã rural e pode-se degustar bolos, frutas e sucos naturais preparados com produtos colhidos na propriedade. Após o café, a visita é no Sítio Faisão Dourado onde é comercializado produtos do sítio e é oferecido a experiência e vivência no meio rural com a criação de peixe e camarões em tanques de cativeiro, algumas aves como faisão, patos, gansos, galinhas, suínos, ovelhas, entre outros. A seguir, a visita é ao Sítio dos Chaves, propriedade com algumas espécies de bananeiras e canteiros com hortaliças agroecológicas onde é possível adquirir direto do produtor. Na sequência a parada é no Rancho Gratidão lindo lugar com aspecto de fazenda onde pode se viver experiências interação e contato direto com animais como bezerros e cavalos, alimentar peixes no lago, recreação, jogos de sinuca e totó, campo de futebol, cozinha a lenha, churrasqueira, e um espaço convidativo e apropriado para ser oferecido e servido refeições como café, lanches e almoço.', 'O percurso é feito de jardineira ou micro-ônibus, com duração de 7 horas e os sítios visitados são agendados previamente.', '22 99282 5930 (apenas Whatsapp)', '', '', 'NÃO', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Caminhos%20de%20Sapeatiba%2C%20Iguaba%20Grande%2C%20RJ', 1, 'publicado', 'guia', 'Costa do Sol · pdf 2 p.26');
