INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (145, 1, 'sitio-organicos-monte-alto', 'Sítio Orgânicos Monte Alto', '3302403', 'Sítio Monte Alto s/n - Centro do Sana', 'Experiência de integração para toda a família. Caminhadas agroecológicas, oficinas com enfoque na alimentação orgânica e nas práticas agroecológicas. O principal projeto é o "da horta à mesa" com oficinas de plantio, colheita e feitura da comida no fogão a lenha, visando a vivência no meio rural. Observação de pássaros livres em seus ambientes naturais, pesque e pague, trilhas ao Peito do Pombo com guia, caminhadas com reconhecimento de plantas, árvores e horta medicinal, e para as crianças, o projeto " Pé no Chão ", com subida de árvores, escalagem, e outras brincadeiras  no campo com o contato direto com a natureza.', 'Das 6h às 17h.', '22 98182-0263', '@organicosmontealto', '', 'SIM', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=S%C3%ADtio%20Org%C3%A2nicos%20Monte%20Alto%2C%20Maca%C3%A9%2C%20RJ', 4, 'publicado', 'guia', 'Costa do Sol · pdf 2 p.28');
