INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (189, 1, 'casa-da-ponte-arte-e-jardim', 'Casa da Ponte Arte e Jardim', '3302254', 'Rua Wanderbilt Duarte de Barros, 2461, Vila Benfica (1a casa após ponte, próximo Hotel Conora)', 'Enquanto desfruta de um local único, próximo à natureza e a cachoeira, o visitante pode apreciar o artesanato e plantas. Artesanato feitos no local, contato direto com o Mestre Artesão, arte com feltro, telhas de barro, em espelhos, peças de gesso decoradas e pintadas, arte sacra, confecção de peças de decoração com diversos elementos, jogos lúdicos, arte em madeira (pinus, eucalipto ou madeira de demolição), pintura em tecido, imãs de geladeira entre outros artesanatos. Plantas: variedades de suculentas, cactos, rosas, terrários, mini-mundos e diversidades de outras plantas. Em desenvolvimento a arte com kokedama.', 'Não informado.', '24 99826-2021 / 24 98838-8153 (Wagner Barros) 24 99822-7151, / 24 98838-8154 (Verluze Barros)', '@casadaponteitatiaiarj_', '', 'SIM', 'SIM', 'NÃO', -22.4742142, -44.5798954, 'endereco', 'https://www.google.com.br/maps/place/Rua+Wanderbilt+Duarte+de+Barros,+2461+-+Vila+Pinheiro,+Itatiaia+-+RJ,+27580-000/@-22.4742142,-44.5798954,17z/data=!3m1!4b1!4m6!3m5!1s0x9e77d0237fb137:0x628fb7d8ac49b120!8m2!3d-22.4742142!4d-44.5798954!16s%2Fg%2F11jyyl94qn?hl=pt-BR&entry=ttu', 4, 'publicado', 'guia', 'Agulhas Negras · pdf 3 p.6');
