INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (192, 1, 'cachaca-adelina', 'Cachaça Adelina', '3304110', 'Av. Fernando Bernardelli, s/n° - Centro', 'Agradável experiência com a bebida que faz parte da história do Brasil e de Porto Real. Visita guiada pelo proprietário do Alambique Cachaça Adelina, explicando todo o processo da produção da cachaça, desde o plantio da cana até o engarrafamento da bebida. Degustação e venda no final do tour.', 'Das 9h às 17h.', '24 99908-6381', '@cachacaadelina', 'www.adelinabrasil.com.br', 'SIM', 'SIM', 'NÃO', -22.4149503, -44.2992843, 'endereco', 'https://www.google.com.br/maps/place/Cacha%C3%A7a+Adelina+-+Artesanal/@-22.4149453,-44.3018592,17z/data=!4m6!3m5!1s0x9e8f2f9d983b81:0x707bb43e98870b35!8m2!3d-22.4149503!4d-44.2992843!16s%2Fg%2F11fb34qxf3?hl=pt-BR&entry=ttu', 3, 'publicado', 'guia', 'Agulhas Negras · pdf 3 p.9');
