INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (196, 1, 'sitio-sao-roque', 'Sítio São Roque', '3304110', 'Av. Dom Pedro II, 2900 – Village', 'O visitante vai experimentar o clima típico das antigas propriedades dos primeiros colonos de Porto Real, e ainda pode adquirir tilápias criadas no local e também patos vivos ou abatidos. O sítio oferece almoço para grupos, por agendamento.', 'Das 9h às 17h.', '24 99998-9802', '', '', 'SIM', 'SIM', 'NÃO', -22.4104527, -44.3082224, 'endereco', 'https://www.google.com.br/maps/place/Av.+Dom+Pedro+II,+2900+-+Village,+Porto+Real+-+RJ,+27570-000/@-22.410718,-44.3090324,18z/data=!4m6!3m5!1s0x9e8f411f419a81:0x4da61625b1fdabcc!8m2!3d-22.4104527!4d-44.3082224!16s%2Fg%2F11tdjx4xqb?hl=pt-BR&entry=ttu', 7, 'publicado', 'guia', 'Agulhas Negras · pdf 3 p.12');
