INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (198, 1, 'feira-da-roca', 'Feira da Roça', '3304128', 'Rua Carlos Haasis, n° 59 - Centro.', 'A Feira da Roça é um lugar típico de Quatis, fundada em 1985, muitas pessoas procuram o lugar atrás de produtos rurais artesanais e artesanatos; existe também um bom restaurante self-service com comidas típicas e um forró animado.', 'Das 11h às 18h, todo segundo e quarto domingo do mês.', '24 99915-1858', '', '', 'SIM', 'NÃO', 'SIM', -22.4107563, -44.2638203, 'endereco', 'https://www.google.com.br/maps/place/Feira+da+Ro%C3%A7a+-+Associa%C3%A7%C3%A3o/@-22.4107774,-44.2638999,16.79z/data=!4m15!1m8!3m7!1s0x9e8fc91aa0f1b1:0x52e87566745da0ca!2sR.+Carlos+Haasis,+59+-+Jardim+Polastri,+Quatis+-+RJ,+27420-070!3b1!8m2!3d-22.4107563!4d-44.2638203!16s%2Fg%2F11h2d4h7wc!3m5!1s0x9e8f5bac63d645:0x9bed75511e89a412!8m2!3d-22.411362!4d-44.2632059!16s%2Fg%2F11t5bbn07p?hl=pt-BR&entry=ttu', 7, 'publicado', 'guia', 'Agulhas Negras · pdf 3 p.14');
