INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (200, 1, 'hotel-fazenda-bom-retiro', 'Hotel Fazenda Bom Retiro', '3304128', 'Estrada Silvio César Sampaio Km 7- CEP 27410- 970', 'Tonico Sampaio, proprietário da Fazenda Bom Retiro, idealizou nos primeiros anos do século passado (1912) , a produção da mais pura aguardente da região: a Cachaça Quatis, uma tradição que foi mantida pelo seu filho Silvio Sampaio e seguida hoje,por seus netos.', 'Das 8h às 22h.', '24 99834-2604/ 99975-0763', '@hotelfazendabomretiro, @cachacaquatis', '', 'SIM', 'SIM', 'SIM', -22.3985419, -44.3202896, 'endereco', 'https://www.google.com.br/maps/place/Hotel+Fazenda+Bom+Retiro/@-22.3984379,-44.3222664,16z/data=!4m6!3m5!1s0x9e8f34eb52cf79:0x5228de5ab0895172!8m2!3d-22.3985419!4d-44.3202896!16s%2Fg%2F11d_dk69vh?hl=pt-BR&entry=ttu', 3, 'publicado', 'guia', 'Agulhas Negras · pdf 3 p.15');
