INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (206, 1, 'rotas-de-pedal', 'Rotas de Pedal', '3304128', 'Praça Dr Teixeira Brandão - Centro', 'O projeto Rotas de Pedal é um turismo de aventura para quem deseja respirar ar puro e ter liberdade junto à natureza. Contamos com aproximadamente 75 rotas, passando por várias paisagem rurais.', 'Não informado.', 'Não informado.', '', 'https://quatis.rj.gov.br/projeto-rotas-de-pedal/', 'NÃO', 'SIM', 'SIM', -22.4095683, -44.2608426, 'endereco', 'https://www.google.com.br/maps/place/Pra%C3%A7a+Teixeira+Brand%C3%A3o+-+ou+a+do+Quati/@-22.4096415,-44.261163,19.25z/data=!4m6!3m5!1s0x9e8fcc23ac0aa1:0xa4451e31f53c91d7!8m2!3d-22.4095683!4d-44.2608426!16s%2Fg%2F11cs5vbr71?hl=pt-BR&entry=ttu', 9, 'publicado', 'guia', 'Agulhas Negras · pdf 3 p.18');
INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (207, 1, 'pesqueiro-recanto-do-tambaqui', 'Pesqueiro Recanto do Tambaqui', '3304201', 'Estrada Resende-Mauá (RJ-163) Km 12,5', 'Com vista privilegiada da região da Capelinha e da Serra da Mantiqueira, em meio ao verde envolvente num cenário com marcas típicas da área rural, o Recanto do Tambaqui oferece ao visitante um acolhedor e amplo espaço ao ar livre, com um restaurante arejado e simpático. A comida é digna de elogios dos mais exigentes frequentadores. Sem falar na produção própria de geleias artesanais 100% naturais e doces caseiros. Delícias da roça.', 'O pesqueiro funciona de Quarta à Segunda-feira das 8h às 18h. O restaurante funciona de quinta-feira a domingo e feriados das 11h30min às 15h45min.', '24 99998-5361/ 24 99966-2489', '@recanto_do_tambaqui_oficial', '', 'NÃO', 'NÃO', 'SIM', -22.368102, -44.4975254, 'endereco', 'https://www.google.com.br/maps/place/Recanto+Do+Tambaqui/@-22.3675431,-44.5099815,15z/data=!4m10!1m2!2m1!1spesqueiro+recanto+do+tambaqui!3m6!1s0x9e7b35fd01a88f:0xc8d6e3ee8c32ea33!8m2!3d-22.368102!4d-44.4975254!15sCh1wZXNxdWVpcm8gcmVjYW50byBkbyB0YW1iYXF1aVofIh1wZXNxdWVpcm8gcmVjYW50byBkbyB0YW1iYXF1aZIBCnJlc3RhdXJhbnTgAQA!16s%2Fg%2F11dxb13ltf?hl=pt-BR&entry=ttu', 3, 'publicado', 'guia', 'Agulhas Negras · pdf 3 p.20');
