INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (208, 1, 'trutas-da-serrinha-trutario', 'Trutas da Serrinha - Trutário', '3304201', 'Alameda dos Oitis s/n°. (em frente a Cervejaria Elbers) Serrinha do Alambari', 'Trutas da Serrinha é um recanto aprazível e uma das marcas da Serrinha do Alambari. Ele se acomoda entre os braços verdes da mata, com seus tanques de água muito fria, próprio para a proliferação da truta, peixe que é também uma tradição regional. O Trutário produz e vende várias delícias manufaturadas à base da truta, como o filé, o filé defumado, o patê e a casquinha', 'De terça-feira a domingo de 9h às 16h.', '24 99915-5084', '@trutasdaserrinha', 'www.trutasdaserrinha.com.br', 'SIM', 'SIM', 'SIM', -22.3953565, -44.5535685, 'endereco', 'https://www.google.com/maps/place/Trutas+da+Serrinha/@-22.3953565,-44.5535685,17z/data=!3m1!4b1!4m6!3m5!1s0x9e709ee8f51d39:0x6e6da833f53019a4!8m2!3d-22.3953565!4d-44.5535685!16s%2Fg%2F11bwyvhpbl?hl=pt-BR&entry=ttu', 9, 'publicado', 'guia', 'Agulhas Negras · pdf 3 p.21');
