INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (209, 1, 'elbers-bier-cervejaria-artesanal', 'Elbers Bier - Cervejaria Artesanal', '3304201', 'Estrada Top Club, lote 112 – Serrinha do Alambari', 'Na Área de Proteção Ambiental da Serrinha do Alambari, em Resende, é possível encontrar em meio à Mata Atlântica, uma cervejaria artesanal com a tradição cervejeira belga: a Elbers Bier. A água cristalina e pura que vem de nascentes da Serra da Mantiqueira se junta ao mais tradicionais maltes e demais ingredientes belgas para produzir uma variedade de cervejas que vai das Ales, passando pelas clássicas Blonde, Trippel, Witbier, Dubbel e até uma à base de pinhão, a semente da Araucária, o pinheiro típico da região.', 'A fábrica está em atividade de Segunda à Sexta-feira, das 7h às 15h. O bar da fábrica recebe visitantes aos sábados, domingos e feriados, de 11h às 18h.', '21 98627-3567', '@Elbersbier', 'https://www.elbers.com.br/', 'SIM', 'NÃO', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Elbers%20Bier%20-%20Cervejaria%20Artesanal%2C%20Resende%2C%20RJ', 3, 'publicado', 'guia', 'Agulhas Negras · pdf 3 p.22');
