INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (213, 1, 'reserva-ecologica-de-guapiacu-regua', 'Reserva Ecológica de Guapiaçu (REGUA)', '3300803', 'Estrada do Matumbo s/n', 'A REGUA possui trilhas criadas ao redor dos alagados próximos ao Centro de Visitantes e outras trilhas que aproximam os visitantes da floresta e as áreas restauradas pela reserva. Uma experiência que almeja sensibilizar os visitantes para a relevância e beleza ímpar da Mata Atlântica e toda a sua biodiversidade. A REGUA se especializa em receber o público de observadores de aves. Ofertamos um espaço bem próximo ao Rio de Janeiro com uma infraestrutura adequada para receber visitantes amantes da natureza numa região ainda muito preservada. Para melhor atender o público de observadores de aves, contamos com trilhas e 3 torres de observação e um abrigo, todas na sede da REGUA.', '07h às 16h30min', '(22) 3835-1557 e (22) 99934-4220', '@reservaecologicadeguapiacu', 'www.regua.org.br', 'SIM', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Reserva%20Ecol%C3%B3gica%20de%20Guapia%C3%A7u%20%28REGUA%29%2C%20Cachoeiras%20de%20Macacu%2C%20RJ', 6, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.6');
