INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (233, 1, 'sitio-castelo-das-trutas', 'Sítio Castelo das Trutas', '3303401', 'Rua Dez de outubro, 10 - Amparo', 'O sítio possui produção de Trutas.', '8h às 16h', '(21) 98277-6858', '@emporio_mio_di_bao', '', 'SIM', 'SIM', 'SIM', -22.2436799, -42.4902843, 'endereco', 'https://www.google.com/maps/place/Estr.+Morro+das+Contas+-+Ch%C3%A1cara+Para%C3%ADso,+Nova+Friburgo+-+RJ/@-22.2436749,-42.492473,17z/data=!4m5!3m4!1s0x97f493210ad063:0x96a3d33e15377c6!8m2!3d-22.2436799!4d-42.4902843?shorturl=1', 9, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.18');
INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (234, 1, 'za-tur', 'Za Tur', '3303401', 'Rua Celestina, 187 - casa 3', 'Agência de receptivo. Um turismo de experiência com diversos atrativos desde laticínios naturais e sem aditivos químicos, goiabada cascão no tacho de cobre e fogão a lenha, cachaçaria artesanal, restaurantes fogão a lenha, queijos trufados, criação de trutas, experiência em um castelo de pedra, sítio com produção 100% orgânicos com colhe e pague, plantação de morangos, plantação de lúpulos, experiência com realizações de bouquet de flores, sítio com day use e experiência de realização de eco jóias, horto com uma gama diferenciada de produtos, artesanato e decoração para jardim e vários locais com geleias diferenciadas com destaque de produtos com lúpulo. Pesque e pague, uma granja com ovos caipiras de ótima qualidade, camping, galpão com antiguidades revivendo o passado, um armazém centenário com especialidade de comidas orgânicas e tradicional carne na lata. Experiências com café da manhã ou da tarde a escolher. O principal diferencial do atendimento é a exclusividade para grupos nos atrativos individualizados. O grupo é atendido como uma família.', '9h às 18h', '(22) 99961-9999', '@zaianefernandes', 'www.altosdaserramar.com.br', 'SIM', 'SIM', '', -22.2508622, -42.4675614, 'endereco', 'https://www.google.com.br/maps/place/R.+Celestina+-+Amparo+-+Ch%C3%A1cara+Para%C3%ADso,+Nova+Friburgo+-+RJ/@-22.2508572,-42.4697501,17z/data=!3m1!4b1!4m5!3m4!1s0x97f3648079c32f:0x7085aeb3b0a4156d!8m2!3d-22.2508622!4d-42.4675614?shorturl=1', 2, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.19');
