INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (248, 1, 'sawabona-eco-pousada-cafe-bistro', 'Sawabona Eco Pousada, Café & Bistrô', '3303401', 'Rua Doralice Merecci, 735 - Campo do Coelho', 'Pousada sustentável construída em container com a experiência de Sawabona, além de um charmoso café e bistrô com produtos artesanais, tais como, bolos, chá, crepes, sorvetes e bombons. Experiência de hospedagem em container, aliada a meditação e contemplação de uma vista panorâmica com total privacidade, além de práticas sustentáveis como horta em pneus reutilizados, dentre outros exemplos.', '12h às 16h', '(22) 2543-1247 e (22) 99848-5606', '@sawabonaeco e @sawabonacafeebistro', 'www.ecosawa.com.br', 'SIM', 'SIM', '', -22.259675, -42.61985, 'endereco', 'https://www.google.com.br/maps/place/Sawabona+Caf%C3%A9+%26+Bistr%C3%B4/@-22.25967,-42.6220387,17z/data=!3m1!4b1!4m8!3m7!1s0x982184d57665fd:0x4cb3942b3d14d92!5m2!4m1!1i2!8m2!3d-22.259675!4d-42.61985?shorturl=1', 1, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.26');
