INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (249, 1, 'altos-da-serramar', 'Altos da Serramar', '3303401', 'Estrada de Boa Esperança, km 7,5', 'A rede Altos da Serramar é formada por produtores rurais que desenvolvem incríveis iniciativas com práticas sustentáveis para a agricultura e o turismo nos distritos de Mury, Lumiar e São Pedro da Serra (Nova Friburgo) e Barra Alegre (Bom Jardim), situados na região serrana do estado do Rio de Janeiro. As propriedades, caracterizadas por excelente conservação ambiental, localizam-se no território da APA de Macaé de Cima ou em seus arredores. O agroturismo concilia as potencialidades da região, integrando a conservação ambiental à agricultura e ao turismo, sendo um grande estímulo à agroecologia', 'Somente com agendamento', '(22) 99838-5102', '@altosdaserramar', 'www.altosdaserramar.com.br', 'SIM', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Altos%20da%20Serramar%2C%20Nova%20Friburgo%2C%20RJ', 4, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.27');
