INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (251, 1, 'docuras-da-suely', 'Doçuras da Suely', '3303401', 'Av Antônio Mario de Azevedo 11000', 'Visitação da estufa de plantação de morango, com mais 10 mil pés da fruta, onde o visitante pode tirar a sua foto, e em alguns períodos pode também colher o seu morango. Sobre a colheita do morango, é preciso fazer contato e se informar antes, pois há períodos para colheita por conta da produção. Além disso, há uma grande e confortável loja, com amplo estacionamento, e muitos doces feitos com a fruta, suco de fruta natural, pastel da casa com massa caseira, e além de muitos outros produtos de pequenos produtores da nossa região, e do nosso estado.', '09h às 17h', '(22) 999322387 whatsapp / (22) 2543-2469', '', '', 'SIM', 'SIM', 'SIM', -22.2755175, -42.6016817, 'endereco', 'https://www.google.com/maps/place/Do%C3%A7uras+Da+Suely+%2F+Morangos/@-22.2755175,-42.6016817,15z/data=!4m5!3m4!1s0x0:0xd00aae33c8387744!8m2!3d-22.2755175!4d-42.6016817?sa=X&ved=2ahUKEwiE1MLTsYT2AhXETd8KHTX6DRcQ_BJ6BAgiEAU&shorturl=1', 3, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.28');
