INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (258, 1, 'fazenda-pedras-altas-organicos', 'Fazenda Pedras Altas Orgânicos', '3303906', 'Estrada dos Albertos, Brejal', 'Uma visita entre a plantação de orgânicos podendo o próprio turista colher, se quiser. Uma experiência incrível! O proprietário ensina os visitantes como usar as verduras e legumes, e alguns chás com ervas medicinais. Há 40 anos trabalhando com produtos orgânicos.', '9h às 14h', '(24) 99865-5324', 'Orgânicos Edinho', '', 'SIM', 'SIM', 'SIM', -22.2622601, -43.0265909, 'endereco', 'https://www.google.com.br/maps/place/Estr.+dos+Albertos+%26+Estr.+Brejal+-+Posse,+Petr%C3%B3polis+-+RJ/@-22.2622551,-43.0287796,17z/data=!3m1!4b1!4m5!3m4!1s0x98501a135fb5dd:0x3e383078f902fdfc!8m2!3d-22.2622601!4d-43.0265909?shorturl=1', 4, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.32');
