INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (266, 1, 'sitio-vaca-do-brejo', 'Sítio Vaca do Brejo', '3303906', 'Estrada do Sossego n 11', 'Uma casa maravilhosa cujo nome é " Sítio Vaca do Brejo". Sem modéstia, um "cinco estrelas" dentro do Brejal! Incomparável em termos de infraestrutura e conforto! Desde piscina aquecida com borda infinita até Playgrounds para crianças e adultos, salão de jogos, suítes mega confortáveis com vistas panorâmicas! Além da tradicional lareira, toda a casa é composta por aquecedores e refrigeradores! Além de tudo isso, uma excelente e irresistível área gourmet.', '', '(24) 99911-7422 e (24) 99833-2646', '@sitiovacadobrejo', '', 'SIM', 'SIM', '', -22.3807535, -42.9893906, 'endereco', 'https://www.google.com.br/maps/place/Estr.+Rinc%C3%A3o+do+Sossego+-+Posse,+Teres%C3%B3polis+-+RJ/@-22.3807485,-42.9915793,17z/data=!3m1!4b1!4m5!3m4!1s0x984d06052b027d:0x35946c7494188352!8m2!3d-22.3807535!4d-42.9893906?shorturl=1', 9, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.37');
