INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (270, 1, 'sitio-alto-taquaril', 'Sítio Alto Taquaril', '3303906', 'Vale do Taquaril km 5,5', 'Criação de cabras leiteiras e de lã e venda de reprodutores. Avicultura com diversos tipos de aves. Apicultura. Venda de produtos do sítio (ovos, mel, queijos, geleias, alcaparras, alguns tipos de plantas). Produtos da horta e do pomar dependendo da estação. Coleção de bromélias. Visita guiada aos diversos tipos de criações e caminhada com vista panorâmica da pedra do Elefante e Maria Antônia. Atrativos de tipos variados e atendimento em inglês, italiano e espanhol, além do português.', '09h às 12h e 14h às 17h', '(21) 2521-2209 e (21) 99616-5151', '', '', 'SIM', 'SIM', '', -22.3271763, -43.064823, 'endereco', 'https://www.google.com/maps/place/Pedra+do+Taquaril/@-22.3271763,-43.0670117,17z/data=!3m1!4b1!4m5!3m4!1s0x9853cecf6feeff:0x4676aff5c3892fb9!8m2!3d-22.3271763!4d-43.064823?q=Pedra+do+Taquaril+%E2%80%93+Petr%C3%B3polis/RJ&rlz=1C1GCEU_enBR973BR973&um=1&ie=UTF-8&sa=X&ved=2ahUKEwjCgteC3vL1AhW1GLkGHanSDzYQ_AUoAXoECAIQAw&shorturl=1', 2, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.39');
