INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (295, 1, 'cachacaria-imbauba', 'Cachaçaria Imbaúba', '3305802', 'Estrada da Cachoeira - Bengala', 'A proposta é de experiência sensorial, harmonizando os diferentes blends com a paisagem local. Em diferentes versões, sendo uma Reserva e outra Reserva Especial, propondo uma diversificação de sabores, com cachaças armazenadas em diferentes madeiras brasileiras. A Cachaça Imbaúba é produzida de forma totalmente artesanal. Nosso desejo consiste em levar aos consumidores um produto de alta qualidade, mas cercado pelo conceito do aconchego, do trabalho em família, da sustentabilidade, do amor à cidade de Teresópolis. Estamos localizados em uma das áreas mais belas da região serrana do Rio de Janeiro.', '09h às 17h', '(21) 99187-7159', '@cachacariaimbauba', 'cachacaimbauba.com.br', 'NÃO', 'SIM', 'SIM', -22.2884541, -42.7755729, 'endereco', 'https://www.google.com/maps/place/Cacha%C3%A7aria+Imba%C3%BAba/@-22.2884341,-42.7779136,17z/data=!3m1!4b1!4m5!3m4!1s0x983b18feb8e889:0x313f5bc480967c6e!8m2!3d-22.2884541!4d-42.7755729?shorturl=1', 3, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.53');
