INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (296, 1, 'fazenda-geneve', 'Fazenda Geneve', '3305802', 'Estrada Teresópolis-Friburgo, km 16', 'Um tour mostra as cabras, a produção de queijos, visita à loja e restaurante, degustação de queijos diversos e venda de produtos feitos com leite de cabra, como xampus, sabonetes e cremes. No local fica o restaurante Cremerie Genève, que serve os queijos frescos acompanhados por pratos com ingredientes da propriedade e cerveja feita no local. Produção de alimentos, fabricação de queijo, loja, degustação e restaurante', '09h às 18h', '(21) 3643-5168, (21) 3643-6391, (21) 99495-3502', '@queijosdecabrageneve', 'fazendageneve.com.br', 'NÃO', 'SIM', 'SIM', -22.3450662, -42.8503125, 'endereco', 'https://www.google.com/maps/place/Fazenda+Gen%C3%A8ve/@-22.3450558,-42.8524425,17z/data=!3m1!4b1!4m5!3m4!1s0x9837ccb664d111:0xb90386f57bdfb1e1!8m2!3d-22.3450662!4d-42.8503125?shorturl=1', 2, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.53');
