INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (297, 1, 'fazenda-vale-das-palmeiras', 'Fazenda Vale das Palmeiras', '3305802', 'Estrada Teresópolis, km 15', 'Visitação à produção de Leite 100% orgânico para seus derivados como queijo minas frescal, ricota, coalhada, queijo cottage e iogurte. A Vale das Palmeiras possui a Certificação Orgânica desde 1997. Reserva Particular do Patrimônio Natural - RPPN Rildo de Oliveira Gomes II. Em uma área de 200 hectares, a fazenda foi recuperada através de um plano simples e viável de recuperação que cercou as nascentes, a reserva legal, as áreas de preservação permanente e deixou a vegetação nativa se reconstituir naturalmente', '09h às 17h', '(21) 3641-9671', '@valedaspalmeirasorganicos', 'www.valedaspalmeiras.com.br', 'NÃO', 'SIM', '', -22.3947009, -42.9893734, 'referencia', 'https://www.google.com/maps/search/?api=1&query=Fazenda%20Vale%20das%20Palmeiras%2C%20Teres%C3%B3polis%2C%20RJ', 2, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.54');
