INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (299, 1, 'museu-do-futuro', 'Museu do Futuro', '3305802', 'Estrada Teresópolis–Friburgo, km 21', 'Museu de conhecimento interativo, com imagens e aromas; sob agendamento. Hostel. Com um banco de sementes disponíveis para reflorestamento, o Museu do Futuro busca ensinar e promover a preservação da Mata Atlântica. A iniciativa partiu da ONG Museu do Futuro, que investe em educação ecológica e comprou 20.000 m² de mata nativa dentro da reserva do Parque dos Três Picos. O espaço fica em meio à mata atlântica, junto à Cachoeira dos Frades. Na sede do museu, que possui arquitetura ecológica, são realizados cursos, pesquisas e atividades culturais. Há seminários voltados para ecologia, pedagogia, arte, arquitetura e sustentabilidade. O Museu promove também terapias ecológicas, com alimentação equilibrada, massagens energéticas, técnicas respiratórias etc., para integrar o homem à natureza. Visita sob agendamento. As mais atualizadas atividades sendo realizadas no local são: Meditação; Técnicas de auto ajuda; Coach; Biodança; Terapia vibracional em hertz; Cosmobiologia para pessoas e empresas; entre outras, seguindo uma nova tendência mundial com este segmento turístico', '08h às 13h', '(21) 3641-9856 e (21) 99724-5467', '@museudofuturo', 'museudelfuturo.com', 'NÃO', 'SIM', '', -22.338164, -42.8029302, 'endereco', 'https://www.google.com/maps/place/Museu+do+Futuro/@-22.338159,-42.8051189,17z/data=!3m1!4b1!4m5!3m4!1s0x98374136b74d61:0xfb0011867d9467c4!8m2!3d-22.338164!4d-42.8029302?shorturl=1', 6, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.55');
