INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (300, 1, 'rancho-g', 'Rancho G', '3305802', 'Estr. Dr. Rogério de Moura Estevão, km 31,5 , Vieira', 'Unidade de produção orgânica associada à AAT - Associação Agroecológica de Teresópolis. Produção vegetal orgânica (frutas, legumes, verduras e grãos), produção animal caipira (galinhas, patos, coelhos, tilápias, ovos de galinha e pato). Tour guiado de vivência rural, semeando, plantando e colhendo produtos orgânicos (colha e pague), mais de 400 mil m² de Mata Atlântica para desfrutar de trilhas para caminhadas, além das alamedas internas nas áreas de plantio ladeadas por frutíferas diversas. Espaço Brincarte para a criançada, com diversas alternativas (balanços na árvore, circuito de pneus passando por dentro da árvore dos balanços, pula-pula de pneu, escorregrama, mini golfe na grama, quadra gramada). Espaço Bicharada com laguinho, patos, galinhas e coelhos). Redário, com diversas redes para descanso. Espaço Gastronomia com varandão gourmet dotado de fogão à lenha e churrasqueira onde são servidas as refeições tradicionalmente rurais (café da manhã, almoço e lanche da tarde). Hospedagem rural para grupos na casa de sede (suite+quarto+mezanino habitável) e em um conjunto anexo de duas suítes com quartos duplos, podendo acomodar grupos de até 24 pessoas. Área para camping.', '09h às 18h', '(21) 2641-2222 e (21) 97960-8480', '@museudofuturo', 'ranchogtere.wixsite.com/ranchog', 'SIM', 'SIM', '', -22.3806889, -42.9258369, 'endereco', 'https://www.google.com/maps/place/Rodovia+Dr.+Rog%C3%A9rio+Moura+Estev%C3%A3o+-+Albuquerque,+Teres%C3%B3polis+-+RJ/@-22.3806839,-42.9280256,17z/data=!3m1!4b1!4m5!3m4!1s0x98379089d40d63:0x2c6c56ace3f5c670!8m2!3d-22.3806889!4d-42.9258369?shorturl=1', 4, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.56');
