INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (301, 1, 'rancho-sabor-da-roca', 'Rancho Sabor da Roça', '3305802', 'Rua José Manoel Rodrigues – Vale dos Lúcios', 'Proporciona ao visitante, vivenciar a rotina do campo e do agricultor, manusear verduras e legumes direto na horta; plantar mudas de plantas e hortaliças diversas; colhendo seu próprio alimento in natura e podendo comprar alguns produtos produzidos no local, como geleias e cervejas artesanais. O local dispõe de uma cozinha em conceito aberto onde é servido um almoço caseiro preparado no fogão a lenha com ingredientes cultivados no sítio. Rúcula, espinafre e brócolis. As geleias são feitas com frutas do sítio, nossas cervejas ainda não são comercializadas para fora, podendo ser consumidas dentro do sítio, são feitas geralmente usando nossos próprios produtos, nosso lúpulo, e fazemos as witbier de rúcula, laranja, limão Siciliano e capim limão.', '09h às 18h', '(21) 99422-7725', '', '', 'NÃO', 'SIM', 'SIM', -22.2759738, -42.7900054, 'endereco', 'https://www.google.com/maps/place/R.+Jos%C3%A9+Manoel+Rodrigues+-+Vale+de+Bonsucesso,+Teres%C3%B3polis+-+RJ/@-22.2759688,-42.7921941,17z/data=!3m1!4b1!4m5!3m4!1s0x9839667d7798b3:0x50a22ffd73e6e59a!8m2!3d-22.2759738!4d-42.7900054?shorturl=1', 3, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.57');
