INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (304, 1, 'sitio-do-ser', 'Sítio do Ser', '3305802', 'Estrada Olha Bicho, 701 - Boqueirão', 'Hospedagem; café da manhã; restaurante; trilhas com condutores; lago para pesca; decoração indígena; não é aconselhável para crianças; ideal para grupos; Centro de referência de aquicultura e hidroponia. Oferece sauna; campo de futebol / vôlei; piscina e wifi nas áreas comuns. Espaços para promover workshops e eventos: Sala rústica de reunião, ambiente descontraído e simples, com capacidade para abrigar até 40 pessoas. Recursos: tv, vídeo, projetor de slides, anfiteatro ao ar livre, capacidade para 80 pessoas. Ideal para vivências, dramatizações e representações teatrais', '09h às 18h', '(21) 2641-1103 e (21) 98895-4134', '@ceu_consultoria', '', 'SIM', 'SIM', 'SIM', -22.3585493, -42.8638265, 'referencia', 'https://www.google.com/maps/search/?api=1&query=S%C3%ADtio%20do%20Ser%2C%20Teres%C3%B3polis%2C%20RJ', 5, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.58');
