INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (306, 1, 'sitio-voze', 'Sítio VôZé', '3305802', 'Estrada Teresópolis - Friburgo, km 15', 'Exposição e oficina de criação de brinquedos populares; oficina de bonecos gigantes. Oferecem espaço para pequenos eventos, visita mediada para grupos turísticos e escolares com venda de produtos locais e exposição de brinquedos populares. Horta pequena. Um lugar de salvaguarda da mata, dos animais silvestres, de brinquedos e brincadeiras e das culturas populares tradicionais. Trabalham para retomar os valores da família, do tempo livre, do encontro e das boas práticas ligadas à vida rural.', '09h às 18h', '(21) 3641-9806 e (21) 99196-7567', '', '', 'NÃO', 'SIM', '', -22.3461109, -42.8661951, 'endereco', 'https://www.google.com/maps/place/S%C3%ADtio+V%C3%B4Z%C3%A9/@-22.3461059,-42.8683838,17z/data=!3m1!4b1!4m5!3m4!1s0x9849ce31916ab5:0xc0e2f606744d4a68!8m2!3d-22.3461109!4d-42.8661951?shorturl=1', 4, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.59');
