INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (307, 1, 'sobrado-jose-francisco-lippi', 'Sobrado José Francisco Lippi', '3305802', 'Estrada Teresópolis-Friburgo, km 15', 'O sobrado abriga e divulga parte da História de Teresópolis: trajetória da vida do imigrante italiano José Francisco Lippi e o início do vilarejo Venda Nova. Além dos documentos, fotos, móveis e ambientes do final do século XIX, o espaço inclui jardins para passeios entre flores, frutas e pássaros. São 5 mil metros quadrados preparados com cantos, recantos e encantos para receber visitantes e tocar o coração das crianças. Visitas escolares, agendadas para grupos e pesquisas, Geleia e licor de jabuticaba, entre outras frutas e doces.', 'Sáb, Dom e feriados, das 13h30min às 17h30min', '(21) 2644-7076 e (21) 97236-7271', '@sobradohistorico', 'www.sobradohistorico.com.br', 'NÃO', 'SIM', '', -22.3461109, -42.8661951, 'endereco', 'https://www.google.com/maps/place/S%C3%ADtio+V%C3%B4Z%C3%A9/@-22.3461059,-42.8683838,17z/data=!3m1!4b1!4m5!3m4!1s0x9849ce31916ab5:0xc0e2f606744d4a68!8m2!3d-22.3461109!4d-42.8661951?shorturl=1', 1, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.60');
