INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (316, 1, 'hotel-fazenda-rio-dos-frades', 'Hotel Fazenda Rio dos Frades', '3305802', 'Estrada Teresópolis-Friburgo, km 19', 'O Hotel Fazenda está em uma propriedade de 960.000 m², sendo destes 600.000 m² de área preservada de mata Atlântica, cortada por uma trilha que termina em um mirante com vista panorâmica de 360°. Possui pedalinho, tirolesa (condicionado a peso e idade), salão de jogos, salão de sinuca (para adultos), toboágua, pesca ecológica, piscinas térmicas – adulto e infantil, piscinas ao ar livre – adulto e infantil, sauna seca e a vapor, videokê, "bicholândia", quadra de vôlei, campo de futebol, quadra de bocha, cavalos (para crianças), quadra de tênis (para o tênis tem que levar equipamento), toboágua e outras opções de lazer.', '09h às 18h', '(21) 2742-3597, (21) 2742-2647 e (21) 99613-8309', '', 'hotelfazendariodosfrades.com.br', 'SIM', 'SIM', '', -22.3297178, -42.8316923, 'endereco', 'https://www.google.com/maps/place/Hotel+Fazenda+Rio+dos+Frades/@-22.3297128,-42.833881,17z/data=!3m1!4b1!4m8!3m7!1s0x9837993c148d79:0x5ccd2099f31c74db!5m2!4m1!1i2!8m2!3d-22.3297178!4d-42.8316923?shorturl=1', 5, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.64');
