INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (317, 1, 'hotel-rosa-dos-ventos', 'Hotel Rosa dos Ventos', '3305802', 'Estrada Teresópolis - Friburgo, Km 22,5', 'O Hotel está no centro de um parque privativo de 100 hectares a 1.250 m de altitude e dispõe de três opções de restaurantes. Entre as opções de lazer há 10 quilômetros de trilhas internas para passeios ecológicos, picadeiro para equitação, cocheiras, cavalos, quadras de tênis, vôlei e futebol society, duas piscinas climatizadas com energia solar e jacuzzi externa com hidromassagem, barco e caiaques, pesca esportiva em um lago de montanha abastecido por nascentes e águas pluviais não poluídas.', '09h às 18h', '(21) 2644-7253, (21) 2644-6191', '@hotelrosadosventos', 'hotelrosadosventos.com.br', 'SIM', 'SIM', '', -22.3296247, -42.866712, 'endereco', 'https://www.google.com/maps/place/Hotel+Rosa+dos+Ventos/@-22.3296247,-42.866712,13z/data=!4m6!3m5!1s0x9839922d38c46d:0x2709e36c8bf7a649!5m2!4m1!1i2!15sCihFc3RyYWRhIFRlcmVzw7Nwb2xpcyAtIEZyaWJ1cmdvLCBLbSAyMiw1WiciJWVzdHJhZGEgdGVyZXPDs3BvbGlzIGZyaWJ1cmdvIGttIDIyIDWSAQVob3RlbJoBI0NoWkRTVWhOTUc5blMwVkpRMEZuU1VObmJ6UTJZVXBSRUFF?shorturl=1', 5, 'publicado', 'guia', 'Serra Verde Imperial · pdf 4 p.64');
