INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (369, 1, 'sertao-do-vale-mambucaba', 'Sertão do Vale Mambucaba', '3300100', 'Av. Francisco Magalhães de Castro, 1103', 'Conhecer os locais de beneficiamento da produção agrícola em uma associação, podendo fazer visita no campo de onde vem a produção. Vivenciar a realidade do produtor rural, sempre guiada por um produtor.', 'De segunda-feira a sábado das 08h às 17h.', '24 3362-6978 / 24 99828-0935', '', '', 'NÃO', 'SIM', '', -22.949434, -44.573919, 'endereco', 'https://www.google.com.br/maps/place/22%C2%B056''58.0%22S+44%C2%B034''26.1%22W/@-22.949429,-44.5761077,17z/data=!3m1!4b1!4m4!3m3!8m2!3d-22.949434!4d-44.573919', 9, 'publicado', 'guia', 'Costa Verde · pdf 6 p.6');
INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (370, 1, 'sertao-de-mambucaba', 'Sertão de Mambucaba', '3300100', 'Estrada do Sertão de Mambucaba', 'Integração com a natureza e visita a pontos históricos da região, que foi palco para a passagem do café do Vale do Paraíba, no período do império no Brasil, e também o ciclo da Banana, no século XX. Saída do Sítio São João e caminhada até a Cachoeira das Três Quedas, para banho e contemplação.', 'Das 06h às 17h.', '24 99961-5800', '@emanuele_calago', '', 'NÃO', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Sert%C3%A3o%20de%20Mambucaba%2C%20Angra%20dos%20Reis%2C%20RJ', 1, 'publicado', 'guia', 'Costa Verde · pdf 6 p.6');
