INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (371, 1, 'aldeia-sapukai', 'Aldeia Sapukai', '3300100', 'Bairro do Bracuí', 'Os Guaranis conservam suas tradições ancestrais, como danças e cantos e a maioria é bilingue, já que além do Tupi Guarani, falam Português. Lá os moradores mantêm uma vida simples cultivando para seu sustento alimentos como mandioca, banana e palmito, além de plantas medicinais. Seu colorido trabalho de cestaria, colares, pulseiras e artesanato em madeira são muito apreciados por turistas. Ao visitar a aldeia você será apresentado à cultura Guarani por meio de atividades como canto cultural, pintura corporal, roda de conversas, comidas típicas, passeio guiado e apresentações. Para os adeptos de aventuras são oferecidas ainda atividades como trilha guiada até a linda Cachoeira da Aldeia, tiro ao alvo com zarabatana, arco e flecha.', 'Não informado.', '24 99866-5466 (Júlio Karai) | 24 99965-1495 (Lucas Xunu Mirim)', '@aldeiasapukaii', '', 'NÃO', 'SIM', '', -22.905381, -44.38512, 'endereco', 'https://www.google.com.br/maps/place/22%C2%B054''19.4%22S+44%C2%B023''06.4%22W/@-22.905376,-44.3873087,17z/data=!3m1!4b1!4m4!3m3!8m2!3d-22.905381!4d-44.38512', 6, 'publicado', 'guia', 'Costa Verde · pdf 6 p.7');
