INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (373, 1, 'aie-eletuloju', 'Aiê Eletuloju', '3300100', 'Estrada da Fazenda Santa Rita 1, Bairro Bracuí', 'Aiê Eletuloju: uma porta para o sagrado no Quilombo Santa Rita do Bracuí. Agroecossistema, vivências, trilhas, Palestras, oficinas, produtos da roça, atividades culturais, ensinamento sobre etnobotânica e etnoecologia, manejos sustentáveis. Um polo agroecológico que tem como foco a educação trabalhando eixos centrais como: Quilombo, Candomblé e o grande leque da permacultura.', 'Das 07h às 18h.', '24 98107-3330', '@eletuloju.aie', '', 'NÃO', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Ai%C3%AA%20Eletuloju%2C%20Angra%20dos%20Reis%2C%20RJ', 4, 'publicado', 'guia', 'Costa Verde · pdf 6 p.8');
