INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (374, 1, 'bee-point-meliponario-saco-do-ceu', 'BEE POINT - Meliponário Saco do Céu', '3300100', 'Rua da Praia, casa 10, Enseada das Estrelas, Saco do Céu - Ilha Grande', 'Local para conhecer abelhas nativas sem ferrão, experimentar o mel produzido na Mata Atlântica e aprender sobre a importância dos polinizadores para a saúde das florestas. Tour guiado por profissional com formação superior em apicultura e meliponicultura, abertura de caixas, degustação de meles e frutas do pomar. Meliponário legalizado junto aos órgãos ambientais e aberto à visitação, aptos a receber turistas e proporcionar uma experiência ímpar na degustação de meles das abelhas nativas da costa verde.', 'Das 08h às 17h.', '24 99815-4802', '@meliponariobeepoint', '', 'SIM', 'SIM', 'SIM', -23.1393871, -44.1684391, 'endereco', 'https://www.google.com.br/maps/place/R.+da+Praia,+10+-+Vila+do+Abra%C3%A3o,+Angra+dos+Reis+-+RJ/@-23.1393822,-44.1706278,17z/data=!3m1!4b1!4m6!3m5!1s0x9c5c0bea1ba9bf:0x26c31631a7ba46dd!8m2!3d-23.1393871!4d-44.1684391!16s%2Fg%2F11h3qdx_t8', 3, 'publicado', 'guia', 'Costa Verde · pdf 6 p.9');
