INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (377, 1, 'alho-poro-restaurante', 'Alho Poró Restaurante', '3300100', 'Rua João Gomes Ribeiro, 18 - Alto Cantagalo', 'Gastronomia contemporânea à base de frutos do mar e de opções de proteínas bovina e suína, além de uma variedade de risotos. Clima de montanha, ambiente familiar,  decoração rústica, onde os clientes podem desfrutar de cachoeiras e de uma piscina natural com águas cristalinas, contemplando a natureza e o canto dos pássaros.', 'De quinta-feira a domingo, das 12h às 17h.', '21 97237-3578', '@alhoporooficial', 'www.alhopororestaurante.com.br', 'SIM', 'SIM', 'SIM', -23.0171761, -44.1840861, 'endereco', 'https://www.google.com.br/maps/place/Alho+Por%C3%B3+Restaurante(+Cantagalo-+Angra+dos+Reis)/@-23.0171711,-44.1862748,17z/data=!3m1!4b1!4m6!3m5!1s0x9c0992c76e7429:0x315d120baebf5382!8m2!3d-23.0171761!4d-44.1840861!16s%2Fg%2F11jjq91xmq', 4, 'publicado', 'guia', 'Costa Verde · pdf 6 p.11');
