INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (378, 1, 'turismo-de-base-comunitaria-do-quilombo-santa-rita', 'Turismo de Base Comunitária do Quilombo Santa Rita do Bracuí', '3300100', 'Estrada Santa Rita do Bracuí', 'O Quilombo Santa Rita do Bracuí tem uma bonita história de luta e tradição. O Turismo de Base Comunitária foi o meio usado pelos quilombolas para passar sua história e receberem uma renda. Opções para o turista: passar um belo dia na comunidade, café quilombola, trilha, hospedagem casual, refeições tradicionais, oficinas, contação de histórias entre outros atrativos. Todas as atividades são feitas pelos quilombolas.', 'Das 08h às 17h.', '24 99946-7591', '', '', 'NÃO', 'SIM', 'SIM', -22.921803, -44.402109, 'endereco', 'https://www.google.com.br/maps/place/22%C2%B055''18.5%22S+44%C2%B024''07.6%22W/@-22.921798,-44.4042977,17z/data=!3m1!4b1!4m4!3m3!8m2!3d-22.921803!4d-44.402109', 1, 'publicado', 'guia', 'Costa Verde · pdf 6 p.12');
