INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (379, 1, 'republica-educacao-solidaria', 'República Educação Solidária', '3300100', 'Av. Beira Mar s/n - Abraão - Ilha Grande', 'Localizada em frente ao Terminal Turístico Janete Dias de Aguiar, porta de entrada da Vila do Abraão, capital da Ilha Grande, a área da Republica Educação Solidária abriga um conjunto de imóveis simbólicos para conectar-se a comunidade e a reconhecer-se na espacialidade, ressignificando a noção de pertencimento e territorialidade do visitante. Nosso diferencial é o Circuito Curto de Comercialização, no qual apresentamos a possibilidade de conhecer o morador e poder comprar direto do produtor, conhecendo o seu espaço e ajudando a escoar suas versáteis produções e serviços. Tempo de visitação: Para manter os princípios da República Educação Solidária, não há um tempo médio definido para a visitação, pois o circuito pode durar de algumas horas a uma vida inteira.', 'Não informado.', '24 99825-5732', '@educacao.solidaria', 'http://vitrineculturalcostaverde.com.br/catalogo.php', 'NÃO', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Rep%C3%BAblica%20Educa%C3%A7%C3%A3o%20Solid%C3%A1ria%2C%20Angra%20dos%20Reis%2C%20RJ', 9, 'publicado', 'guia', 'Costa Verde · pdf 6 p.12');
INSERT INTO atrativo_termos (atrativo_id, termo_id) VALUES (379, 13);
