INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (380, 1, 'nativa-da-ilha-tours-concierge', 'Nativa da Ilha Tours & Concierge', '3300100', 'Rua da Assembleia, 243 - Vila do Abraão - Ilha Grande', 'Nativa da Ilha é um micro-empreendimento criado para ser ferramenta de impacto social na região da Baía da Ilha Grande. Sua missão é servir de apoio não só às comunidades tradicionais, mas também contribuir para a criação de uma consciência de respeito e valorização da cultura popular oferecendo produtos e serviços que contribuam para o alcance de uma nova perspectiva e consciência que ajude a evitar que identidades tradicionais sejam diluídas. Nossos roteiros de turismo de base comunitária visam promover um turismo mais justo e inclusivo, pois colocam a população local no protagonismo para responder às demandas dos ecossistemas locais e contribuir para gerar renda e autonomia para essas populações rurais.', 'Das 09h às 18h.', '24 99825-5732', '@alexandra.campos.ilha', '', 'SIM', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Nativa%20da%20Ilha%20Tours%20%26%20Concierge%2C%20Angra%20dos%20Reis%2C%20RJ', 8, 'publicado', 'guia', 'Costa Verde · pdf 6 p.13');
