INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (387, 1, 'agroindustria', 'Agroindústria', '3302601', 'Estrada São João Marcos, s/n -  Parque das Ruínas do Saco de Cima.', 'A Agroindústria de Mangaratiba trabalha com processamento, como a banana passa, farinha de banana e doces diversos de acordo com a safra local. No prédio funciona uma Associação de Agricultores do Município, que é responsável pelo processamento e vendas dos produtos. Há também a importância histórico-cultural do local, devido o prédio estar localizado bem próximo às Ruínas do Saco de Cima.', 'Das 08h às 16h.', '21 97138-1277', '', '', 'SIM', 'NÃO', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Agroind%C3%BAstria%2C%20Mangaratiba%2C%20RJ', 3, 'publicado', 'guia', 'Costa Verde · pdf 6 p.19');
