INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (388, 1, 'fazenda-da-lapa', 'Fazenda da Lapa', '3302601', 'Estrada imperial de São João Marcos, 126', 'Fazenda histórica do período do café da antiga cidade de São João Marcos ou São João do Príncipe. Localizada na Serra do Piloto, Estrada Imperial de São João Marcus, primeira estrada de rodagem do Brasil. A Fazenda está aberta a visitação, hospedagem, restaurante e brechó. Possui cavalos, galinheiro, criação de gado leiteiro, produz queijo artesanal, banana orgânica, horta. O casarão está conservado e possui um pátio de secagem de café da época. Possui trilhas junto a mata atlântica, nascentes e piscina natural.', 'Finais de semana, das 11h às 16h.', '21 99274-6740', '@fazendadalapa', '', 'SIM', 'SIM', '', -22.869981, -44.006556, 'endereco', 'https://www.google.com.br/maps/place/FAZENDA+da+LAPA/@-22.869976,-44.0087447,17z/data=!3m1!4b1!4m6!3m5!1s0x9c113f18f049ed:0xe6b24b98a0caa6dc!8m2!3d-22.869981!4d-44.006556!16s%2Fg%2F11h_w4724z', 1, 'publicado', 'guia', 'Costa Verde · pdf 6 p.20');
