INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (390, 1, 'circuito-imperial-da-serra-do-piloto', 'Circuito Imperial da Serra do Piloto', '3302601', 'Estrada Real da Serra do Piloto', 'O roteiro dá direito a passeio em carro 4x4, guiamento (guia credenciado Cadastur e especializado em atrativos naturais) histórico nos pontos turísticos durante o trajeto, caminhada ecológica até o Mirante da Represa de Ribeirão das Lajes e Ponte Bela, kit lanche, banho de cachoeira, almoço com comida feita à lenha (não incluso), e seguro assistência médica e hospitalar.', 'Das 08h às 17h.', '21 96476-5439', '@calangostour', '', 'SIM', 'SIM', 'SIM', -22.8600285, -43.9996766, 'endereco', 'https://www.google.com.br/maps/place/Serra+do+Piloto,+Mangaratiba+-+RJ/@-22.8620288,-44.0094282,16z/data=!3m1!4b1!4m10!1m2!2m1!1sEstrada+Real+da+Serra+do+Piloto!3m6!1s0x9c10e81634664d:0x109126ee6a3decae!8m2!3d-22.8600285!4d-43.9996766!15sCh9Fc3RyYWRhIFJlYWwgZGEgU2VycmEgZG8gUGlsb3RvkgEMc3VibG9jYWxpdHkx4AEA!16s%2Fg%2F120s_6n5', 1, 'publicado', 'guia', 'Costa Verde · pdf 6 p.21');
