INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (394, 1, 'cachaca-coqueiro', 'Cachaça Coqueiro', '3303807', 'Fazenda Cabral 2º Distrito - Cabral', 'É o Alambique artesanal mais antigo em funcionamento no município, desde 1803 e conta com loja de produtos locais em sua sede. Tour guiado nas dependências do alambique com explicação sobre o processo de fabricação e contando a história da cachaça mais antiga em atividade no município.', 'Das 08h às 18h.', '24 3371-0016', '@cachacacoqueiro', 'https://www.cachacacoqueiro.com.br/', 'SIM', 'NÃO', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Cacha%C3%A7a%20Coqueiro%2C%20Paraty%2C%20RJ', 3, 'publicado', 'guia', 'Costa Verde · pdf 6 p.24');
