INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (395, 1, 'cachaca-maria-izabel', 'Cachaça Maria Izabel', '3303807', 'Sítio Santo Antônio, s/n, Corumbê', 'É o único alambique do município fundado e gerido por uma mulher e tem todas suas etapas de produção supervisionada por ela, que dá o nome a cachaça. Vivência com roda de conversa com a proprietária, onde ela conta as etapas do processo de fabricação e até a história da cachaça no município de Paraty.', 'Das 10h às 16h.', '24 99999-9908', '@cachacamariaizabel', 'https://mariaizabel.com.br/', 'SIM', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Cacha%C3%A7a%20Maria%20Izabel%2C%20Paraty%2C%20RJ', 3, 'publicado', 'guia', 'Costa Verde · pdf 6 p.25');
