INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (400, 1, 'akura-outdoor-experience', 'AKURA - Outdoor Experience', '3303807', 'Flat 02 - Rua Peroba Rosa, Alameda Princesa Isabel, 140', 'Agência de turismo voltada ao ecoturismo e conta com roteiros personalizados.', 'Das 06h às 18h.', '34 99944-4581', '@akuraparaty', '', 'SIM', 'SIM', 'SIM', -23.2153814, -44.7138604, 'endereco', 'https://www.google.com.br/maps/place/Alameda+Princesa+Isabel,+140+-+Pontal,+Paraty+-+RJ,+23970-000/@-23.2153765,-44.7160491,777m/data=!3m2!1e3!4b1!4m5!3m4!1s0x9d6d3b5266c98b:0xd58ff374a459455a!8m2!3d-23.2153814!4d-44.7138604', 6, 'publicado', 'guia', 'Costa Verde · pdf 6 p.28');
