INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (401, 1, 'quilombo-campinho-da-independencia', 'Quilombo Campinho da Independência', '3303807', 'Br 101 Km 584 - Quilombo Campinho da Independência', 'As famílias que vivem no Quilombo antêm vivas as tradições como o Jongo, a Capoeira, histórias e saberes que remetem ao continente Africano. O turismo que ocorre lá é o de Base Comunitária e um dos principais atrativos do local é uma belíssima cachoeira, trilhas, ruínas do tempo da escravidão, além de rodas de conversa e a culinária típica, que o visitante degusta em um espaço construído junto a casa de moradores.', 'Das 09h às 17h.', '(Raísa) 24 99946-7591 / (Marilda) 24 988172696 ou pelo e-mail marildaquilombo@gmail.com', '@quilombo_do_campinho', 'www.quilombodocampinho.org', 'SIM', 'SIM', 'SIM', -23.2960578, -44.7007608, 'endereco', 'https://www.google.com.br/maps/place/Quilombo+do+Campinho+da+Independ%C3%AAncia/@-23.2960528,-44.7052455,777m/data=!3m2!1e3!4b1!4m6!3m5!1s0x9d6b2d359d62ed:0x4e06fd15c4706ae6!8m2!3d-23.2960578!4d-44.7007608!16s%2Fg%2F11cnz42lns', 6, 'publicado', 'guia', 'Costa Verde · pdf 6 p.28');
