INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (405, 1, 'fazenda-bananal', 'Fazenda Bananal', '3303807', 'Estrada da Pedra Branca – Paraty, Rio de janeiro, Brasil', 'A Fazenda Bananal é um destino imperdível para os amantes de turismo rural, com 187 hectares abertos à visitação. O destaque é a sustentabilidade, presente em todos os ângulos: ambiental, histórico-cultural e social. A visita à Fazenda Bananal é personalizada, permitindo que o visitante monte o próprio roteiro. A primeira parada recomendada é o Casarão Histórico, tombado pelo IPHAN, com sua estrutura original preservada. Atualmente, o espaço é utilizado para exposições temporárias que contam a história e as tradições de Paraty. A segunda parada é um roteiro que apresenta modelos e tecnologias que utilizam a força e a inteligência da natureza para criar sistemas produtivos mais limpos e sustentáveis. Durante o passeio, é possível conhecer a agrofloresta, a horta orgânica, a fossa verde, o biodigestor e outras boas práticas na relação com a natureza. A dica final é uma visita ao restaurante, onde são servidos pratos deliciosos que variam de acordo com a sazonalidade dos alimentos e priorizam ingredientes locais. A Agrofloresta e a Horta da Fazenda abastecem o restaurante com mais de 60 produtos diferentes por ano, cultivados sem o uso de agrotóxicos ou adubos químicos. Em resumo, a Fazenda Bananal é um lugar incrível que combina desenvolvimento e sustentabilidade, preservando o patrimônio histórico e cultural, e promovendo o turismo consciente. Se você quer aprender mais sobre práticas sustentáveis, saborear deliciosas refeições orgânicas e desfrutar de um passeio personalizado, não deixe de visitar a Fazenda Bananal!', 'De segunda-feira a domingo, das 10h às 17h. O Restaurante pede reservas antecipada e fica aberto das 12h às 17h.', '24 3371-1666 (WhatsApp)', '@fazendabananal', 'FazendaBananal.com.br', 'SIM', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Fazenda%20Bananal%2C%20Paraty%2C%20RJ', 4, 'publicado', 'guia', 'Costa Verde · pdf 6 p.31');
