INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (406, 1, 'cachaca-tellura', 'Cachaça Tellura', '3301009', 'Estrada RJ 194 Campos p/ Gargaú', 'Produzida na Fazenda Abadia, que tem tradição no cultivo da cana de açúcar há mais de 100 anos. O visitante irá encontrar a verdadeira Cachaça-Arte, produzida em alambiques de cobre desde 2015. Para garantir a qualidade, a preocupação começa no plantio da cana de açúcar estendendo até a colheita, que é realizada manualmente. Outro ponto relevante é a higienização da fábrica que é feita a vapor para limpeza das tubulações e recipientes inox, eliminando a infecção bacteriana. A fermentação do caldo da cana é realizada com fermentos selecionados livres de bactérias prejudiciais. A destilação segue, rigorosamente, um processo de separação das frações da cabeça, coração e cauda; usando só o coração em sua produção, resultando uma cachaça de qualidade internacional. Em seguida a cachaça descansa em tonéis de madeiras nobres garantindo melhor aroma, cor e sabor ao produto final. Premiada em 2017 em Bruxelas onde recebeu reconhecimento do International Taste & Quality Institute gerando o certificado “Prêmio de Sabor Superior” (Superior Taste Award).', '07h às 17h', '(22) 3015-7435', '@tellura_arte', 'www.tellura.com.br', 'SIM', 'NÃO', 'NÃO', -21.7277573, -41.212958, 'endereco', 'https://www.google.com/maps/place/Alambique+Tellura/@-21.7277573,-41.2151467,17z/data=!3m1!4b1!4m5!3m4!1s0xbe86effc96e3d5:0x18fe76cbd84cd49a!8m2!3d-21.7277573!4d-41.212958', 3, 'publicado', 'guia', 'Costa Doce · pdf 7 p.5');
