INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (407, 1, 'cachaca-barra-velha', 'Cachaça Barra Velha', '3301009', 'Barra Velha - Farol', 'Responsável pela produção das Cachaças Premiadas “Barra Velha”, o Alambique do Leley é o local onde irá também encontrar uma excelente comida caseira feita no fogão à lenha, artesanatos e variados doces regionais. Localizado na praia campista Farol de São Thomé, precisamente na Fazenda São Thomé, encontrará as instalações para produção artesanal das famosas cachaças que são reconhecidas e certificadas pelo Ministério da Agricultura, Pecuária e Abastecimento do Brasil. Seu envelhecimento é feito em barris de carvalho Pernod Ricard, que aliado ao perfeccionismo do produtor Leley, garante sucesso agregando qualidade e refinamento aos produtos. A cachaça Branca amadurecida recebeu medalha de Ouro na Expocachaça de Belo Horizonte. Pelo terceiro ano consecutivo a cachaça “Barra Velha” chegou entre as melhores do Brasil e que também rendeu o reconhecimento Internacional.', '09h às 18h', '(22) 9995- 53364', '@cachacabarravelha', '', 'NÃO', 'NÃO', 'NÃO', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Cacha%C3%A7a%20Barra%20Velha%2C%20Campos%20dos%20Goytacazes%2C%20RJ', 3, 'publicado', 'guia', 'Costa Doce · pdf 7 p.6');
