INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (408, 1, 'cavalhada-de-santo-amaro', 'Cavalhada de Santo Amaro', '3301009', 'RJ-216', 'A Cavalhada é o Ponto Alto da maior festa religiosa tradicional do Norte Fluminense, a “Festa de Santo Amaro”, que é o padroeiro da Baixada Campista, comemorado no dia 15 de Janeiro. A Cavalhada é uma manifestação que remonta à Idade Média, na qual 24 cavaleiros divididos em dois grupos - determinados pelas cores vermelha e azul - simulam uma batalha entre Mouros e Cristãos demonstrando suas habilidades e sua devoção.', '', '(22) 99989-3317', '', '', 'NÃO', 'NÃO', 'NÃO', -21.7787303, -41.3050295, 'referencia', 'https://www.google.com/maps/search/?api=1&query=Cavalhada%20de%20Santo%20Amaro%2C%20Campos%20dos%20Goytacazes%2C%20RJ', 8, 'publicado', 'guia', 'Costa Doce · pdf 7 p.7');
