INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (409, 1, 'alambique-do-taizinho', 'Alambique do Taizinho', '3301009', 'Estrada Posse do Meio s/n', 'Localizado no distrito de Santa Maria, a Cachaça Soberana, produzida pelo Sr. Taizinho, apresenta uma grande diversidade de sabores incluindo a Cachaça de Jambu, tão difícil de ser encontrada.', 'SEG a SAB de 07h às 18h', '(22) 98126-7284 (Whatsapp)', '', '', 'NÃO', 'NÃO', 'NÃO', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Alambique%20do%20Taizinho%2C%20Campos%20dos%20Goytacazes%2C%20RJ', 3, 'publicado', 'guia', 'Costa Doce · pdf 7 p.7');
