INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (410, 1, 'cachoeira-do-bau', 'Cachoeira do Baú', '3301157', 'Estrada Pau Brasil - Baú', 'As responsabilidades e tarefas do dia a dia podem elevar nossos níveis de estresse. E para esquecer esses problemas da rotina, não há remédio melhor que a natureza. Relaxar em uma piscina de águas naturais formada por uma cachoeira, rodeado somente pelas árvores e montanhas, ao som do canto dos pássaros, esta é a experiência vivida por quem visita a Cachoeira do Baú, no interior de Cardoso Moreira. Este é o local certo para quem deseja lavar a alma nas águas geladas de uma cachoeira, sem pensar em mais nada além daquele momento único.', '', '(22) 99909-7902', '@imbelak', '', 'NÃO', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Cachoeira%20do%20Ba%C3%BA%2C%20Cardoso%20Moreira%2C%20RJ', 6, 'publicado', 'guia', 'Costa Doce · pdf 7 p.9');
