INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (411, 1, 'sitio-trapiche', 'Sítio Trapiche', '3301157', 'Rodovia BR 356', 'Com o autêntico “clima de interior”, o Sítio Trapiche oferece aos visitantes a estrutura perfeita para um bom final de semana em família. O local conta com duas piscinas, área coberta para churrasco, jogos de mesa, pula-pula e muito mais, tudo para te fazer reviver os bons momentos da infância. Quem conhece o Sítio Trapiche experimenta momentos únicos que reforçam ainda mais os laços familiares, com muita alegria e diversão.', 'QUA A DOM de 09h às 22h', '(22) 99889-2479 (Whatsapp)', '@sitiotrapiche', 'www.sitiotrapiche.com', 'SIM', 'SIM', 'SIM', -21.4959608, -41.623915, 'endereco', 'https://www.google.com/maps/search/RODOVIA+BR+356,+KM+90+-+ZONA+RURAL,+Cardoso+Moreira+-+RJ/@-21.4959608,-41.623915,15z/data=!3m1!4b1', 3, 'publicado', 'guia', 'Costa Doce · pdf 7 p.9');
