INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (414, 1, 'fazenda-da-pedra', 'Fazenda da Pedra', '3304805', 'Estrada Fazenda da Pedra', 'Um lugar histórico de uma família tradicional com inúmeras histórias e riquezas que os turistas possam se encantar e conhecer. Em 1883 a fazenda pertencia ao Barão de Azeredo Coutinho, e no dia 24 de junho daquele ano recebeu a visita de D. Pedro II para um almoço.  O imperador fazia a viagem de São Fidélis para Campos para, à noite, inaugurar a luz elétrica da cidade. Em 1976 foram gravadas cenas da primeira versão de A escrava Isaura na Fazenda da Pedra.', '09h às 18h', '(22) 99711-3166 e (22) 99982-9932', '', '', 'NÃO', 'SIM', 'SIM', -21.6242304, -41.5418884, 'endereco', 'https://www.google.com.br/maps/place/Estr.+Fazenda+da+Pedra,+Rio+de+Janeiro/@-21.6255596,-41.5419719,857m/data=!3m2!1e3!4b1!4m5!3m4!1s0xbc34b8c88de0a7:0x6ab93bf9a03e04c6!8m2!3d-21.6242304!4d-41.5418884', 1, 'publicado', 'guia', 'Costa Doce · pdf 7 p.12');
