INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (425, 1, 'cavalgada-dos-amigos', 'Cavalgada dos amigos', '3304755', '', 'A Cavalgada dos amigos é uma manifestação cultural em forma de passeio a cavalo, onde cavaleiros e amazonas, entre crianças e idosos que compartilham o gosto pela vida no campo se confraternizam durante o trajeto. O evento acontece anualmente no mês de maio e atrai visitantes de diversas cidades da região.', '10h às 00h', '(22) 99929-9999', '@marciocalixto21', '', 'SIM', 'SIM', 'SIM', -21.431895, -41.1877693, 'endereco', 'https://www.google.com/maps/place/Igreja+Cat%C3%B3lica+de+Nossa+Senhora+da+Penha/@-21.431895,-41.189958,17z/data=!3m1!4b1!4m5!3m4!1s0xbea355e3946073:0x892b68aa4c342cc9!8m2!3d-21.431895!4d-41.1877693', 8, 'publicado', 'guia', 'Costa Doce · pdf 7 p.18');
