INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (426, 1, 'sitio-vovo-berenice', 'Sítio Vovó Berenice', '3305000', 'Rua Alto do Cardeiro, 25', 'A propriedade conta com 2500 galinhas e uma produção de 200 dúzias de ovos por dia. Além dessa atividade, há o plantio de hortaliças e um coqueiral, onde os visitantes podem escolher o que levar para casa direto do pé. No local são comercializados ovos frescos, água de coco e as hortaliças colhidas na hora. Os visitantes são recebidos pela proprietária que conta a história da família e de como começou a criação que deu origem ao local.', '07h às 17h', '(22) 99809-7987', '', '', 'SIM', 'SIM', 'NÃO', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=S%C3%ADtio%20Vov%C3%B3%20Berenice%2C%20S%C3%A3o%20Jo%C3%A3o%20da%20Barra%2C%20RJ', 4, 'publicado', 'guia', 'Costa Doce · pdf 7 p.20');
