INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (427, 1, 'sitio-familia-toledo', 'Sítio Família Toledo', '3305000', 'Estrada de Palacete, 194', 'A propriedade rural  familiar conta com uma mandala de hortaliças variadas proporcionando uma experiência imersiva para os visitantes que também podem visitar o pomar  e colher dependendo da época do ano, laranjas, mexericas e melancias. Conhecer espécies como o pé de urucum e até mesmo recolher ovos frescos no pequeno galinheiro doméstico. Ao fim do passeio um simples porém típico café da roça, com batata doce e aipim cozidos e quentinhos, bolo de fubá, geleias e sucos  de frutas da estação e aquele café coado na hora. Isso sem falar na hospitalidade do proprietário Manoel Toledo que recebe a todos com um generoso sorriso. Os produtos colhidos podem ser adquiridos pelos visitantes , assim como os demais que também são comercializados no local. O Café da tarde faz parte da experiência e está incluso na entrada.', '9h às 17h', '(22) 99852-0862', '', '', 'SIM', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=S%C3%ADtio%20Fam%C3%ADlia%20Toledo%2C%20S%C3%A3o%20Jo%C3%A3o%20da%20Barra%2C%20RJ', 1, 'publicado', 'guia', 'Costa Doce · pdf 7 p.20');
