INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (445, 1, 'fazenda-monte-cafe', 'Fazenda Monte Café', '3305406', 'Estrada Fazenda Monte Café 1500 - Vila Nossa Senhora de Aparecida', 'Fazenda bi-centenaria escravocrata inventariada pelo Instituto Cidade Viva do Rio de Janeiro e Universidade Federal de Minas Gerais onde o visitante irá sentir a atmosfera de uma fazenda dos Barões do Café. Atuando hoje no Turismo Rural, o visitante vive a experiência do Carrossel de cavalos Pampa, a Meditação no Tanque dos Desejos de Isabel Libertadora, a alameda de palmeiras imperiais e a passagem pela pinguela, tirar leite de vaca, túnel de bambuzal, praia de rio, banho de barragem, mirante de cantaria, horto e pomar, pinturas de José Maria Vilarongo, ruínas de terreiro, aqueduto e moinho de pedra.', '24 horas.', '21 99955-3342', '@fazendamontecafe', '', 'SIM', 'SIM', 'SIM', -22.0055959, -42.789734, 'endereco', 'https://www.google.com.br/maps/place/Fazenda+Monte+Caf%C3%A9/@-22.0055959,-42.7919227,1026m/data=!3m2!1e3!4b1!4m5!3m4!1s0x980d45869fc511:0xb2b42ec6fdf142af!8m2!3d-22.0055959!4d-42.789734?shorturl=1', 1, 'publicado', 'guia', 'Caminhos Coloniais · pdf 8 p.18');
