INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (447, 1, 'fazenda-sao-fulgencio-alambique-sao-fulgencio', 'Fazenda São Fulgêncio Alambique São Fulgêncio', '3305406', 'Estrada Fazenda Monte Café, 1000', 'Visitação ao Alambique, que se agendado, poderá ser visto no momento da produção da cachaça. Também poderá ser provada a cachaça dos diferentes tonéis existentes. Nossa cachaça é produzida em sistema de alambique, porém com toda infraestrutura compatível com sistemas de agroindústrias.', 'Das 9h às 16h.', '24 99234-4994 / 21 99982-8674', '', '', 'NÃO', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Fazenda%20S%C3%A3o%20Fulg%C3%AAncio%20Alambique%20S%C3%A3o%20Fulg%C3%AAncio%2C%20Sapucaia%2C%20RJ', 3, 'publicado', 'guia', 'Caminhos Coloniais · pdf 8 p.19');
