INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (448, 1, 'alambique-cachaca-itajoana', 'Alambique Cachaça Itajoana', '3306008', 'Estrada Itajoana, km 6 - Bemposta', 'O Alambique está aberto à visitação e é possível conhecer todo o processo cuidadoso de produção da Itajoana, e em casos de grupo a partir de 10 pessoas é possível contratar um almoço lá de caprichado. A Cachaça Itajoana, produzida no distrito de Bemposta, na cidade de Três Rios, une o aconchego do campo com uma cachaça extremamente saborosa. A bebida Premium nascida em 2017, tem como um de seus objetivos apresentar aos apreciadores da cachaça opções de blends diferenciados e de qualidade. A Cachaça Itajoana ganhou em 2020, através do rótulo preto (Blends Bálsamo, Carvalho e Amburana), medalha de Ouro na Expocachaça, categoria Blends de Cachaça.', 'De segunda-feira a domingo, com agendamento prévio.', '24 99262-7094', '@cachacaitajoana', '', 'SIM', 'SIM', 'SIM', -22.11638, -43.043374, 'endereco', 'https://www.google.com.br/maps/place/22%C2%B006''59.0%22S+43%C2%B002''36.2%22W/@-22.11638,-43.0455627,17z/data=!3m1!4b1!4m5!3m4!1s0x0:0x1f087d1624549108!8m2!3d-22.11638!4d-43.043374?shorturl=1', 3, 'publicado', 'guia', 'Caminhos Coloniais · pdf 8 p.21');
