INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (449, 1, 'duvivier-hotel-fazenda', 'Duvivier Hotel Fazenda', '3306008', 'BR-040, KM 27,5 s/n', 'O Hotel Fazenda oferece experiências com animais e a possibilidade de colher em sua horta. Possui um moinho movido a energia das águas, onde o milho é moído. Em alguns quartos do Hotel, é possível desfrutar de uma banheira externa privativa aquecida à lenha, com uma estrutura para lá de requintada e aconchegante. Mediante agendamento, é possível realizar atividades como o Track Day, graças a uma parceria do hotel com a equipe RMattheis (Stock Car e Rally dos Sertões), onde funciona a pista Off Road da equipe.', '24 horas, mediante reserva.', '24 98831-3512', '@estanciasduvivierhotel', 'https://www.hotelestanciasduvivier.com/', 'SIM', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Duvivier%20Hotel%20Fazenda%2C%20Tr%C3%AAs%20Rios%2C%20RJ', 4, 'publicado', 'guia', 'Caminhos Coloniais · pdf 8 p.22');
