INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (450, 1, 'fazenda-da-paciencia', 'Fazenda da Paciência', '3306008', 'Estrada da Itajoana, KM 6,5 - Bemposta', 'A Fazenda da Paciência oferece hoje uma experiência única de hospedagem, visto que para que o visitante usufrua do espaço é necessário alugar a Fazenda em sua totalidade tendo uma experiência única e exclusiva da vida no meio rural. A gastronomia e a criação de cavalos árabes são os grandes diferenciais do local que conta ainda com uma pequena cachoeira localizada dentro da propriedade e de uso exclusivo para os visitantes.', 'Mediante agendamento.', '21 99636-0562', '@fazenda.paciencia', '', 'SIM', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Fazenda%20da%20Paci%C3%AAncia%2C%20Tr%C3%AAs%20Rios%2C%20RJ', 6, 'publicado', 'guia', 'Caminhos Coloniais · pdf 8 p.22');
