INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (463, 1, 'hotel-fazenda-minha-gloria', 'Hotel Fazenda Minha Glória', '3300506', 'Rua Rosário, Banquete, Bom Jardim - RJ, 28660-000', 'Situado em meio à natureza, em um cenário cinematográfico de 165 mil metros quadrados, proporciona contato direto com animais exóticos e confortáveis. Hospedagem em chalés independentes, no estilo rústico atrelado ao clima rural.', '24h.', '22 9779-2023', '@minhagloria', 'www.minhagloria.com.br', 'SIM', 'SIM', 'NÃO', -22.1603666, -42.4969675, 'endereco', 'https://www.google.com.br/maps/place/Hotel+Fazenda+Minha+Gl%C3%B3ria/@-22.1603616,-42.4995424,17z/data=!3m1!4b1!4m9!3m8!1s0x97f6e5d8a7a979:0x987525f07fb83b25!5m2!4m1!1i2!8m2!3d-22.1603666!4d-42.4969675!16s%2Fg%2F11cm_hv014', 7, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.13');
