INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (465, 1, 'sitio-aconchego', 'Sítio Aconchego', '3300506', 'Estrada Friburgo / Bom Jardim (RJ-116) km.93,5 - Pedra Branca', 'O entorno da propriedade é coberto pela natureza e ainda há um pomar com diversas opções de frutas como amora, manga, goiaba, abacate, carambola e banana. Serviço de quarto + café da manhã. O uso da piscina e demais dependências do terreno estão liberados, assim como o uso da churrasqueira e sauna.', 'Somente mediante agendamento.', '22 98807-9235', '', '', 'SIM', 'SIM', 'NÃO', -22.1961786, -42.4812249, 'endereco', 'https://www.google.com.br/maps/place/Pousada+sitio+Aconchego/@-22.1961786,-42.4812249,17z/data=!3m1!4b1!4m9!3m8!1s0x97f402a1659827:0xec18b96287ea445b!5m2!4m1!1i2!8m2!3d-22.1961786!4d-42.4812249!16s%2Fg%2F11cmc42_gv', 4, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.15');
