INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (467, 1, 'cafe-monthal', 'Café Monthal', '3300506', 'Estrada Municipal Bj 01 Km 20 Goiabal - Barra Alegre, Bom Jardim - RJ, 28660-000', 'Uma linda fazenda, reconhecida pelo seu café, leite, queijo e bolinho de chuva que periodicamente abre as portas para um tour de experiências, onde através de visitas guiadas o visitante pode conhecer um pouco da cultura do campo e as etapas de processamento do café. Da colheita a torra, com um pouco de história, culminando em um mini tour gustativo pelos diversos modos de preparo da bebida. Oportunidade para que você possa vivenciar o que é a colheita de montanha. Vivenciando ''in loco'' da plantação à torra final, desfrutando de uma natureza incrível.', 'De segunda-feira à sexta-feira, das 8h às 17h.', '22 2566-3520', '@cafemonthal', 'https://www.cafemonthal.com.br', 'SIM', 'SIM', 'SIM', -22.1798152, -42.3210222, 'endereco', 'https://www.google.com.br/maps/place/Caf%C3%A9+Fazenda+Monthal/@-22.1798102,-42.3235971,17z/data=!3m1!4b1!4m6!3m5!1s0x97ef9d582a3b3d:0x2c098d720698705f!8m2!3d-22.1798152!4d-42.3210222!16s%2Fg%2F11qr9tz49z', 1, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.16');
