INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (468, 1, 'vila-de-porto-marinho', 'Vila de Porto Marinho', '3301108', 'Distrito de São Sebastião do Paraíba Cantagalo / Venda Antiga de Porto Marinho', 'Visita aos pontos mais significativos referentes à produção e o beneficiamento do arroz Anã de Porto Marinho; Visita às casas dos produtores familiares; Passeio de barco pelo rio Paraíba do Sul e de carro de boi; Explanação in loco sobre a história da vila e do município, como também sobre as manifestações culturais da comunidade; comercialização da doceria e do artesanato típicos; degustação da culinária local, que tem como atrativos principais o arroz Anã de Porto Marinho, potencial indicação geográfica, e o pescado.', 'Finais de semana, das 10h.', '22 98140-2383 Whatsapp', '@vendaantigadeportomarinho', '', 'NÃO', 'SIM', 'SIM', -21.7142801, -42.263318, 'endereco', 'https://www.google.com.br/maps/place/Venda+Antiga/@-21.7142801,-42.263318,17z/data=!3m1!4b1!4m6!3m5!1s0xbd3fbfb298e4e7:0xdd7415beae80d047!8m2!3d-21.7142801!4d-42.263318!16s%2Fg%2F11tcjpfsp9', 5, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.18');
