INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (474, 1, 'laticinios-relogio', 'Laticínios Relógio', '3301207', 'Av. Sebastião Luterback Sobrinho, 70 - Carmo', 'Gastronomia, história e experiência com laticínio histórico. A história da Marca Relógio nos remete ao final do século XIX, precisamente a 13 de abril de 1871, data em que nasceu Joaquim Simões de Araújo, em Espinho, perro de Viseu, Portugal. Com o vigor dos seus vinte anos, juntou-se a três amigos portugueses, e embarcou em uma aventura para o Brasil, sonhando fazer a vida em melhores condições.Sempre animado pelo espírito empreendedor, em 1912, adquiriu a Fazenda João Dias e nela construiu um Laticínio. Com a estação ferroviária muito próxima ao laticínio, Joaquim despachada pelo trem toda a produção de leite e manteiga para as cidades maiores. Assim o horário em que o trem passava regulava a produção. Segundo consta, em meio às atividades, ele repetia com seu carregado sotaque português:_Olha o relógio! Olha o relógio! _ Alertando os funcionários para a hora certa da chegada do trem.E assim, nesse clima de trabalho e poesia, nasceu o nome Relógio para os produtos.', 'Das 8h às 17h.', '22 99204-7677', '', '', 'SIM', 'SIM', 'NÃO', -21.9211158, -42.6164932, 'endereco', 'https://www.google.com.br/maps/place/Cooperativa+Agropecu%C3%A1ria+de+Carmo/@-21.9219367,-42.6227428,16z/data=!4m10!1m2!2m1!1sAv+Sebasti%C3%A3o+Luterback+Sobrionho+,+70,+Carmo+-+RJ!3m6!1s0x9800912f1f72f3:0x13e08cabe6b3bb52!8m2!3d-21.9211158!4d-42.6164932!15sCjJBdiBTZWJhc3Rpw6NvIEx1dGVyYmFjayBTb2JyaW9uaG8gLCA3MCwgQ2FybW8gLSBSSlovIi1hdiBzZWJhc3Rpw6NvIGx1dGVyYmFjayBzb2JyaW9uaG8gNzAgY2FybW8gcmqSAQtjaGVlc2Vfc2hvcOABAA!16s%2Fg%2F1tkf25r_', 1, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.22');
