INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (479, 1, 'cachaca-da-quinta', 'Cachaça da Quinta', '3301207', 'Estrada Córrego do Prata - Porto Velho do Cunha RJ 158', 'Degustação da cachaça, história e contato com a natureza. Desde 1923 a Cachaça da Quinta é produzida na Fazenda da Quinta, em um vale próximo ao Rio Paraíba do Sul, com altitude em torno de duzentos e vinte metros. A propriedade possui solo, clima e microclima ideais ao cultivo da cana, à fermentação e à elaboração dos produtos. Ao terroir especialmente propício, somam-se os rigorosos padrões de qualidade na elaboração da Cachaça da Quinta. Vale a pena visitar e conhecer todo o processo produtivo. A propriedade possui solo e clima ideais ao cultivo da cana-de-açúcar, a fermentação e a elaboração dos produtos. Foi o primeiro destilado brasileiro a receber a Grand Gold Medal do Concours Mondial de Bruxelles. No Ranking Nacional da Cúpula da Cachaça (biênio 2022 - 2023), a Cachaça da Quinta - Branca recebeu a maior pontuação entre todas as concorrentes, protagonizando um fato inédito: uma branquinha ultrapassando a pontuação de cachaças oriundas de diferentes madeiras, armazenadas, envelhecidas, premium e extra premium.', 'Das 8h às 17h.', '22 99733-9033', '@cachacadaquinta_oficial', 'www.cachacadaquinta.com.br', 'SIM', 'SIM', 'NÃO', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Cacha%C3%A7a%20da%20Quinta%2C%20Carmo%2C%20RJ', 3, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.26');
