INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (509, 1, 'queijaria-fazenda-boa-fe', 'Queijaria Fazenda Boa Fé', '3304607', 'Estrada Madalena Loreti, km 17', 'No passeio até a Fazenda Boa Fé você vai percorrer uma antiga estrada de trem com passagens e cortes nas pedras, de paisagem bucólica e exuberante. Já na nossa fazenda, conhecerá sobre as técnicas de sustentabilidade, visitará a queijaria e criação de tilápias em cativeiro. Você ainda poderá degustar os produtos, como queijos e iogurtes fresquinhos.', 'Todos os dias.', '22 99212-2852', '@queijariafazendaboafe', '', 'SIM', 'SIM', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Queijaria%20Fazenda%20Boa%20F%C3%A9%2C%20Santa%20Maria%20Madalena%2C%20RJ', 2, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.51');
