INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (510, 1, 'fazenda-santa-cruz', 'Fazenda Santa Cruz', '3305703', 'Estrada Cascata, Km 2, s/n, Fazenda Santa Cruz - 1º distrito', 'A fazenda histórica, integrante de um valioso trecho da antiga linha férrea Leopoldina, encanta os visitantes com suas matas nativas, mirantes naturais e paisagens deslumbrantes. Construídos por engenheiros ingleses no século XIX, os três túneis na fazenda possuem grande valor histórico e cultural. A propriedade, fundada por volta de 1880, conta com uma casa-sede imponente, antigos engenhos de café, moinho de fubá, engenho de cana e uma pequena usina de energia hidrelétrica. Durante a visita, os hóspedes têm a oportunidade de explorar a capela, o alambique e o antigo moinho de pedra e madeira, além de desfrutar de petiscos, cervejas e da cachaça Santa Cruz, produzida no local. O cenário pitoresco, com estradas bem conservadas, proporciona aos visitantes uma experiência única, onde podem sentir a atmosfera da era colonial, capturar belas fotos e desfrutar da paisagem envolvente.', 'Finais de semana, das 09h às 17h.', '22 98128-2906', '@santacruzsumidouro', '', 'SIM', 'NÃO', 'NÃO', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Fazenda%20Santa%20Cruz%2C%20Sumidouro%2C%20RJ', 1, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.53');
