INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (511, 1, 'fazenda-boa-vista-alambique-sinha-brasil', 'Fazenda Boa Vista & Alambique Sinhá Brasil', '3305703', 'Estrada Municipal da Cascata, Km 2, s/n, Fazenda Boa Vista', 'Propriedade do século XIX abriga uma fábrica de cachaça de qualidade superior, um museu e uma coleção impressionante de mais de 800 rótulos de cachaça. Experimente a premiada SINHÁ BRASIL, uma cachaça produzida com rigoroso controle de qualidade, desde o cultivo da cana-de-açúcar até o engarrafamento. Explore o processo de produção em visitas mensais, onde você poderá degustar os diferentes rótulos e saborear um autêntico almoço preparado na fazenda. Uma experiência turística única que vai encantar todos os seus sentidos', 'Das 09h às 17h.', '22 99209-4673', '@fazendaboavista1882', 'https://www.sinhabrasil.com.br/principal.html', 'SIM', 'SIM', 'NÃO', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Fazenda%20Boa%20Vista%20%26%20Alambique%20Sinh%C3%A1%20Brasil%2C%20Sumidouro%2C%20RJ', 1, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.54');
