INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (514, 1, 'fazenda-do-canteiro', 'Fazenda do Canteiro', '3305901', 'RJ 146, km 30 - Dr. Elias', 'Turismo Rural e Gastronomia. Visitação a uma fazenda centenária de arquitetura colonial em pleno funcionamento de produção. Onde podemos oferecer experiências na bovinocultura de corte e leite, no plantio e colheita de goiabas, cana de açúcar, horta, eucalipto e etc.', 'Das 8h às 17h.', '22 98110-2783', '@do_canteiro', '', 'SIM', 'SIM', 'SIM', -22.1982914, -42.232818, 'endereco', 'https://www.google.com.br/maps/place/Fazenda+do+Canteiro/@-22.1982914,-42.232818,17z/data=!3m1!4b1!4m6!3m5!1s0x97c3b3bbd4582f:0x57bd220ad3aaeba2!8m2!3d-22.1982914!4d-42.232818!16s%2Fg%2F11kn4wpwd6', 1, 'publicado', 'guia', 'Caminhos da Serra · pdf 9 p.58');
