INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (523, 1, 'fabrica-de-bananada-rio-bonito', 'Fábrica de Bananada Rio Bonito', '3304300', 'Av Antônio Carlos de Souza Guadalupe, lote 10 Quadra 5 -Condomínio Industria', 'Rio Bonito é conhecido por sua riqueza em plantação de bananas, e a Fábrica de Bananada utiliza as frutas da região e agricultores locais. O visitante poderá participar e conhecer todo o processo do produto, desde a matéria prima, até a embalagem e futura distribuição, além de poder degustar os doces fabricados no local.', 'Das 8h às 17h.', '21 2734-3822 / 21 99695-4792', '@bananadariobonito_', '', 'NÃO', 'SIM', '', -22.7090675, -42.6663072, 'endereco', 'https://www.google.com/maps/place/F%C3%A1brica+de+doces+Bananada+Rio+Bonito/@-22.709091,-42.6669375,18.67z/data=!4m6!3m5!1s0x99da55b38acfd5:0x6e504fbfb938625b!8m2!3d-22.7090675!4d-42.6663072!16s%2Fg%2F11d_8ltyn4?entry=ttu', 3, 'publicado', 'guia', 'Caminhos da Mata · pdf 10 p.10');
