INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (526, 1, 'ecopolo', 'Ecopolo', '3304300', 'Rua Helena, n° 02', 'O visitante terá a experiência de ver a produção dos itens decorativos que são produzidos pelas artesãs do local, terão acesso às máquinas de tear, os tecidos e as peças já prontas. Além de desfrutar no jardim do Ecopolo um delicioso café da manhã, ou tarde, preparado pela equipe.Há 20 anos desenvolvemos bolsas, acessórios e produtos da Linha Home em tecelagem manual, uma técnica milenar onde o tecido é o resultado do entrelaçamento dos fios, através da urdidura (fios no sentido vertical no tear) e a trama (fios na horizontal). Todo o trabalho é feito de forma manual. Nova coleção com peças exclusivas de material reciclado.', 'De segunda-feira a sexta-feira, das 9h às 17h.', '21 98480-1397 / 21 98587-8505', '@ecopolo.tear', 'https://www.ecopolotecelagem.com', 'NÃO', 'SIM', 'SIM', -22.7081895, -42.6301114, 'endereco', 'https://www.google.com/maps/place/Ecopolo/@-22.7077959,-42.6306045,19.33z/data=!4m14!1m7!3m6!1s0x99da208cc2ba4b:0x1db1eff18ea8988c!2sR.+Helena,+2+-+Serra+do+Samb%C3%AA,+Rio+Bonito+-+RJ,+28800-000!3b1!8m2!3d-22.7081895!4d-42.6301114!3m5!1s0x99dbaf34966fad:0x985554abb2b66e3!8m2!3d-22.7077029!4d-42.6303043!16s%2Fg%2F11s1q4lqc2?entry=ttu', 4, 'publicado', 'guia', 'Caminhos da Mata · pdf 10 p.12');
