INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (537, 1, 'circuito-da-laranja', 'Circuito da Laranja', '3305752', 'O circuito percorre em diversos locais na cidade.', 'Quem gosta de laranja e de turismo rural, não pode deixar de fazê-lo. No percurso o visitante tem a oportunidade de conhecer um pomar de laranja, colher e degustar a fruta, além de visitar algumas propriedades rurais, e ainda comprar produtos agrícolas e artesanais, vivenciando assim um agradável dia no campo. Roteiro consolidado, funcionando desde 2010, de forma sazonal (no período da safra da laranja), o Circuito da Laranja já foi visitado por milhares de pessoas, vindas principalmente da região metropolitana do Rio de Janeiro. Todos os grupos são acompanhados por um condutor local, que transmite as informações sobre a história e dados da cidade. Além de orientar sobre os pontos de visitação. O Circuito oferece uma experiência rural inesquecível, criando um elo entre os visitantes com o meio rural. E deixa em todos a vontade de retornar e reviver a experiência.', 'Das 8h às 16h.', '21 2747-4113 de segunda-feira à sexta-feira, das 8h às 17h.', '', 'https://tangua.rj.gov.br/home/index.php/circuito-da-laranja/', 'SIM', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Circuito%20da%20Laranja%2C%20Tangu%C3%A1%2C%20RJ', 4, 'publicado', 'guia', 'Caminhos da Mata · pdf 10 p.20');
