INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (538, 1, 'sitio-juvak', 'Sítio JUVAK', '3305752', 'Estrada de Minérios, 01', 'Contato com a natureza, trilhas e contemplação de belas paisagens. Sítio inserido na Serra do Barbosão.', 'Durante o horário comercial, de terça a domingo não é necessário.', '21 2747-1099 / 21 97260-9105', '@juvaksitio', 'https://www.sitiojuvak.com/', 'SIM', 'SIM', 'SIM', -22.7192261, -42.7168577, 'endereco', 'https://www.google.com/maps/place/S%C3%ADtio+Juvak+%7C+Turismo+Rural+%7C+Pousada+e+Eventos+%7C+Serra+do+Barbos%C3%A3o+%7C+Tangu%C3%A1+-+Rio+de+Janeiro/@-22.7199436,-42.7187245,17z/data=!4m6!3m5!1s0x99c4b7506530a9:0x586c25a79499dcd!8m2!3d-22.7192261!4d-42.7168577!16s%2Fg%2F11ckqrb0ll?entry=ttu', 6, 'publicado', 'guia', 'Caminhos da Mata · pdf 10 p.21');
