INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (539, 1, 'festa-da-laranja', 'Festa da Laranja', '3305752', 'Estrada de Minérios, 01', 'O evento em suas últimas 15 edições contou com shows, gincanas e palestras para produtores rurais, concurso da rainha da laranja, concurso de melhor produtor de laranja, exposição de artesanato e barracas com comidas típicas rurais, valorizando a cultura rural da cidade e seus moradores. A Festa da Laranja está inserida no calendário oficial de eventos do município de Tanguá desde o ano 2002, através da Lei 352/02. Esse evento é tradicional no município e tem o intuito de promover e valorizar o principal produto agrícola do município, a laranja, contribuindo dessa maneira para fortalecer a cultura e tradições rurais da cidade.', 'Realizada na segunda quinzena de julho. Normalmente são 3 dias de festa. (sexta-feira, sábado e domingo)', '21 2747-4113 Secretaria Municipal de Cultura e Turismo. De segunda-feira à sexta-feira, de 8h às 17h.', '@prefeituradetangua', 'https://tangua.rj.gov.br/home/', 'NÃO', 'NÃO', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Festa%20da%20Laranja%2C%20Tangu%C3%A1%2C%20RJ', 7, 'publicado', 'guia', 'Caminhos da Mata · pdf 10 p.22');
