INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (540, 1, 'recanto-da-vovo-ruth', 'Recanto da Vovó Ruth', '3305752', 'Não informado.', 'Delicioso café da manhã ou almoço servidos com agendamento antecipado. É uma casa para até 6 pessoas, onde os visitantes podem usufruir de suas dependências. Durante o café da manhã são servidos doces e geleias produzidos na propriedade com produtos da estação.', 'Das 8h às 10h café da manhã e das 11h30 às 14h30 almoço.', '21 97186-9416', '@recantodavovoruth', '', 'SIM', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Recanto%20da%20Vov%C3%B3%20Ruth%2C%20Tangu%C3%A1%2C%20RJ', 3, 'publicado', 'guia', 'Caminhos da Mata · pdf 10 p.23');
