INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (541, 1, 'festa-do-aipim', 'Festa do Aipim', '3305752', 'Igreja Evangélica Congregacional em Posse dos Coutinhos', 'A Tradicional Festa do Aipim, realizada sempre no dia 1º de maio de cada ano, tornou-se uma atração turística e gastronômica da localidade, com diversos produtos derivados do aipim. Durante a Festa são comercializadas comidas típicas feitas com o Aipim, como: bolinho, pizza, sola, biju, italiano, aipim com carne seca, tapioca, caldo verde, vaca atolada, farinha de mandioca e bolo doce de aipim. Além de doces diversos, sucos variados e feira agrícola.', 'Das 10h às 22h (no dia da Festa)', '21 9734-8674', '@IEC-PC', '', 'SIM', 'NÃO', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Festa%20do%20Aipim%2C%20Tangu%C3%A1%2C%20RJ', 3, 'publicado', 'guia', 'Caminhos da Mata · pdf 10 p.23');
