INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (542, 1, 'instituto-sinal-do-vale', 'Instituto Sinal do Vale', '3301702', 'Rua da Cachoeira 345, Santo Antônio, Duque de Caxias', 'opção de alugar uma casa na natureza para grupo particular, alugar o espaço de reunião para encontros de empresas, Cada detalhe do espaço foi cuidadosamente desenhado em harmonia com a natureza: inspira conexão, engajamento, apreciação e alegria. Em relação à hospitalidade, o Sinal do Vale também atua no âmbito da gastronomia, por meio do método de preparação do alimento de Culinária Regenerativa. Usamos ingredientes locais, priorizando vegetais, as raízes, e as frutas produzidas em nossas hortas orgânicas e agroflorestas.', 'Só com agendamento para grupos fechados.', '21998928910', '@sinaldovale', 'www.sinaldovale.org', 'SIM', 'SIM', 'NÃO', -22.6012828, -43.2628249, 'endereco', 'https://www.google.com.br/maps/place/Sinal+do+Vale/@-22.6012828,-43.2628249,17z/data=!4m6!3m5!1s0x990c901ec3e62d:0xeac70471896688d7!8m2!3d-22.6012828!4d-43.2628249!16s%2Fg%2F11c6cqrw0k?entry=ttu', 4, 'publicado', 'guia', 'Baixada Verde · pdf 11 p.6');
