INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (543, 1, 'rancho-linda-vista', 'Rancho Linda Vista', '3301702', 'Estrada São Lourenço, 48.305-Xerém, Duque de Caxias-Rj', 'O Rancho Linda Vista é um restaurante rural pesqueiro localizado em Xerém, RJ. Mas vai além de um simples restaurante rural. Aqui, servimos um delicioso café da manhã e temos um lago para pesque e pague ou pesca esportiva, uma piscina e um parquinho para os pequenos. Além disso, há muito espaço para as crianças correrem e brincarem. Nossa fazendinha é um encanto, com diversos animais para as crianças conhecerem. No Rancho, também servimos um delicioso almoço feito à lenha. Alguns dos nossos pratos incluem posta de tilápia, carré com couve e frango com quiabo. E para finalizar a refeição, você pode saborear um pudim de dar água na boca, feito no forno à lenha. Depois do almoço, você pode descansar em uma das nossas redes espalhadas pelo Rancho, enquanto toma um café com uma broa. Aqui, você tem tudo para passar um dia delicioso e criar memórias afetivas com seus filhos, netos e amigos.*', 'De sexta-feira a domingo, das 8h às 17h.', '21 97461-1192 (ligação: segunda-feira a quinta-feira, WhatsApp: sexta a domingo).', '@rancholindavista', '', 'SIM', 'NÃO', 'SIM', -22.594597, -43.3668353, 'endereco', 'https://www.google.com.br/maps/place/Rancho+Linda+Vista+-+Restaurante+Pesqueiro/@-22.5947208,-43.3694102,17z/data=!4m6!3m5!1s0x991383d7a982b7:0x8936b94741412d75!8m2!3d-22.594597!4d-43.3668353!16s%2Fg%2F11st6dh65y?entry=ttu', 1, 'publicado', 'guia', 'Baixada Verde · pdf 11 p.7');
