INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (553, 1, 'chacara-vale-dos-manacas-sitio-pedra-lisa', 'Chácara Vale dos Manacás / Sítio Pedra Lisa', '3303500', 'Chácara: Rua Dom Paulo, 284, Jardim Montevideo – Tinguá, Nova Iguaçu/RJ. Sítio: Travessa Jacy, 49.552 - Tinguá - Nova Iguaçu/RJ', 'Experiência que o visitante terá: Café Colonial na Chácara Vale dos Manacás-Tinguá-NI, com pães produzidos no local e servidos quentinhos aos visitantes. Durante o Café Colonial, os convidados podem usufruir de toda estrutura da Chácara (duas piscinas, caiaque, redes, chuveirão e outros). Esse é o Café Colonial. Em se tratando do Roteiro Pedra Lisa, logo após o Café da Manhã Rural, iniciamos uma caminhada até o Sítio Pedra Lisa, onde usufruímos das belezas naturais desse incrível remanescente da Mata Atlântica. Após, retornamos para a Chácara, oportunidade em que servimos o almoço. No Sítio Pedra Lisa os visitantes desfrutarão de uma caminhada de 2,7km nas Áreas de Proteção Ambiental Municipal de Tinguá e Estadual do Alto Iguaçu. Durante o percurso terão vista para a cadeia de montanhas da Serra do Mar e ao longo da Baía da Guanabara. Já na propriedade serão conduzidos por trilhas em floresta de Mata Atlântica, onde poderão desfrutar de balneabilidade em 2 rios encachoeirados de águas cristalinas ou mesmo praticar contemplação das cachoeiras, lago, gruta de rocha Tinguaíto e das inúmeras espécies de fauna e flora da Mata Atlântica. Para os que curtem camping o sítio oferece o serviço na modalidade rústica Wild Camping com estrutura de banheiro, água encanada, fogão a gás e geladeira.', 'Day Use Sexta-feira à domingo e feriados de 8h às 17h (na chácara apenas em dias de eventos)', 'Chácara: 21 99828-9457 / Sítio: 21 99864.2578', '@chacaravaledosmanacasoficial; @pedralisa.rj', 'http://sitiopedralisa.blogspot.com/', 'SIM', 'SIM', 'SIM', -22.6214454, -43.3946598, 'endereco', 'https://www.google.com.br/maps/place/CH%C3%81CARA+VALE+DOS+MANAC%C3%81S/@-22.6212077,-43.3962262,17z/data=!4m6!3m5!1s0x996d70c75b8aa5:0x63f72bb353d762d3!8m2!3d-22.6214454!4d-43.3946598!16s%2Fg%2F11h0bl5xl8?entry=ttu', 4, 'publicado', 'guia', 'Baixada Verde · pdf 11 p.16');
