INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (558, 1, 'fazendinha-agroecologica-km-47', 'Fazendinha Agroecológica Km 47', '3305554', 'R. B, 1048 – Bairro Ecologia, Seropédica - RJ, 23890-000', 'A Fazendinha Agroecológica do km 47 é referência na produção orgânica e agroecológica no Brasil. É uma parceria do Colégio Técnico da Universidade Rural (CTUR), Embrapa Agrobiologia, Pesagro-Rio e da Universidade Federal Rural do Rio de Janeiro (UFRRJ). A Fazendinha é a âncora de uma série de projetos de transferência de tecnologias e extensão que possibilitam o intercâmbio de conhecimentos em relação à adoção e à adaptação de tecnologias, produtos, processos e serviços. Neste espaço são realizados cursos, dias de campo, palestras, visitas e reuniões técnicas, científicas e educativas para os mais diversos públicos. Nas visitas, os grupos têm contato com teoria e prática, vivenciando a educação pela agroecologia, o contato com a terra, o conhecimento dos ciclos biogeoquímicos, a adubação orgânica, a produção de substratos, a semeadura, a horticultura, os tratos culturais e a colheita.', 'Dias úteis, durante a semana, em horários pré-agendados.', '21 97656-8065', '', 'https://www.embrapa.br/en/agrobiologia/fazendinha-agroecologica; https://institucional.ufrrj.br/fazendinha/', 'NÃO', 'SIM', 'NÃO', -22.7573638, -43.6744156, 'endereco', 'https://www.google.com.br/maps/place/Fazendinha+Agroecol%C3%B3gica+km+47/@-22.7573588,-43.6769905,17z/data=!3m1!4b1!4m6!3m5!1s0x995700433c0a7d:0xcc315357ae28f46c!8m2!3d-22.7573638!4d-43.6744156!16s%2Fg%2F11cn12j375?entry=ttu', 4, 'publicado', 'guia', 'Baixada Verde · pdf 11 p.22');
