INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (559, 1, 'universidade-federal-rural-do-rio-de-janeiro-campu', 'Universidade Federal Rural do Rio de Janeiro – Campus Seropédica', '3305554', 'BR-465, Km 7 Seropédica-Rio de Janeiro - CEP: 23.897-000', 'A Universidade Federal Rural do Rio de Janeiro (UFRRJ), especificamente o conjunto arquitetônico, em estilo neocolonial, do campus de Seropédica, tombado pelo Instituto Estadual do Patrimônio Cultural (Inepac), começou a ser construído em 1939. O extenso e belo parque paisagístico de autoria do arquiteto paisagista Reynaldo Dierberger foi conjuntamente implantado, agregando aos pavilhões neocoloniais jardins, lagos artificiais, massas arbóreas compostas por espécies nativas, agrupamentos de palmeiras, maciços arbustivos, forração, taludes e canteiros gramados. O Campus sede da UFRRJ, também possui um papel muito importante no âmbito do lazer, como contemplação, caminhadas, passeios ciclísticos, piqueniques nas áreas próximas aos lagos existentes, bem como nas vias calçadas que recortam parte do campus sede.', 'Quartas-feiras, das 8h às 13h.', '21 98887-4755', '@universidadefederalrural/', 'https://portal.ufrrj.br/', 'SIM', 'SIM', 'SIM', -22.7692349, -43.6850841, 'endereco', 'https://www.google.com.br/maps/place/Universidade+Federal+Rural+do+Rio+de+Janeiro+(UFRRJ)/@-22.7692299,-43.687659,17z/data=!3m1!4b1!4m6!3m5!1s0x9955d8251e415f:0x613581ba0a2b68bd!8m2!3d-22.7692349!4d-43.6850841!16s%2Fm%2F05f6dj0?entry=ttu', 6, 'publicado', 'guia', 'Baixada Verde · pdf 11 p.23');
