INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (560, 1, 'alambique-barbinotto', 'Alambique Barbinotto', '3305554', 'Avenida Recife, 74 - Bairro Incra, Seropédica, RJ, Brazil, 23890000', 'Alambique e cachaçaria especializado na produção artesanal de licores e cachaças ouro, prata e mistas, com armazenamento em tonéis de aço inoxidável, barris de carvalho, castanha do pará e jequitibá rosa. Tem como diferencial a produção de cachaça pura e de qualidade e principalmente de bebidas alcoólicas aromatizadas com jambu. Possui um restaurante aberto para almoço aos finais de semana. Degustação gratuita de cachaças e licores artesanais produzidos no local, venda de cachaças e licores. No restaurante, almoços aos finais de semana, com comidas regionais.', 'De segunda-feira a domingo 8h30 às 17h . Restaurante: sexta-feira a domingo, a partir de 12h.', '21 98642-8536', '@barbinotto', 'cachaabarbinotto.mercadoshops.com.br', 'NÃO', 'NÃO', 'SIM', -22.7658398, -43.6524285, 'endereco', 'https://www.google.com.br/maps/place/Alambique+Cacha%C3%A7a+Barbinotto/@-22.7658348,-43.6550034,17z/data=!3m1!4b1!4m6!3m5!1s0x99579fad5e77e9:0xc93c1777b3936e30!8m2!3d-22.7658398!4d-43.6524285!16s%2Fg%2F11c32m5qby?entry=ttu', 3, 'publicado', 'guia', 'Baixada Verde · pdf 11 p.24');
