INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (591, 1, 'estancia-hidromineral-soledade', 'Estância Hidromineral Soledade', '3302205', 'Parque Soledade, 199 – Raposo', 'Com as nascentes no coração de Raposo, a Estância Hidromineral Soledade, vem se destacando ao longo dos tempos devido à alta qualidade de suas águas. Já famosas pelo seu poder curativo, vem atraindo milhares de turistas a cada ano. Além disso, a Estância Hidromineral Soledade disponibiliza também banhos de piscina com águas sulfurosas e águas fluoretadas sem o uso de produtos químicos. Venha você também, conhecer e desfrutar dessa maravilha da natureza!', 'De segunda-feira a sexta-feira, das 7h às 11h e das 13h às 17h. Sábados e Domingos, das 7h às 17h.', '22 3747-2133 / 22 3847-2568 / 22 99924-2133 (whatsapp / telegram)', '', 'www.aguamineralsoledade.com.br', 'NÃO', 'NÃO', '', -21.1029298, -42.118237, 'endereco', 'https://www.google.com.br/maps/place/Ãguas+Soledade/@-21.1029298,-42.1204257,17z/data=!3m1!4b1!4m5!3m4!1s0xbc93b344bc10af:0xf70995895a717ff!8m2!3d-21.1029298!4d-42.118237', 4, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.28');
