INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (595, 1, 'emporio-rural-miracema', 'Empório Rural Miracema', '3303005', 'Av. Deputado Luiz Fernando Linhares, 285 - Centro', 'O espaço reúne os produtos/artesanatos de artistas, artesãos e produtores rurais, num só espaço central na localidade, com fácil acesso e preços compatíveis com a realidade atual. Além disso, os visitantes têm a oportunidade de conhecer os produtos confeccionados/ fabricados no município enriquecendo, desta forma, seus conhecimentos culturais. Oferece opções de variadas mercadorias com a identidade cultural e turística da cidade, como também saborosos produtos produzidos na zona rural. Dentre os produtos rurais artesanais disponíveis encontram-se: café, queijo, linguiça, cachaça, mel, própolis, licores, doces em calda, cristalizados e compota, geleias de sabores variados. Os produtos de decoração para cama, mesa e banho, artigos religiosos (imagens, terços, estandartes e flâmulas), cestarias, produtos com motivos personalizados de miracema.', 'De segunda-feira a sexta-feira, das 8h às 17h. Sábado das 8h às 12h.', '22 99958-6787 Carlos Eduardo Fingolo Tostes - Duda / 22 99269-4131 Rose', '@emporioruraldemiracema', 'https://miracema.rj.gov.br/', 'NÃO', 'NÃO', 'SIM', -21.4140392, -42.194777, 'endereco', 'https://www.google.com.br/maps/place/EmpÃ³rio+Rural/@-21.4140392,-42.1969657,17z/data=!3m1!4b1!4m5!3m4!1s0xbce1b3719c33f7:0x848b870a513bc23!8m2!3d-21.4140392!4d-42.194777', 1, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.32');
