INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (598, 1, 'cachaca-miracema', 'Cachaça Miracema', '3303005', 'Fazenda Santa Rita', 'Visitação à produção de cachaça artesanal, que possui envelhecimento em tonéis de carvalho, amburana, castanheira, entre outros, com direito a degustação liberada . Plantio e moagem de cana na mesma propriedade, com diversos lagos para pesca e um belo visual rural.', 'Horário comercial.', '22 99103-8474', '@cachacamiracema', 'https://www.cachacamiracema.com/', 'SIM', 'NÃO', '', -21.3882154, -42.2144559, 'endereco', 'https://www.google.com.br/maps/place/CachaÃ§a+Miracema/@-21.3882008,-42.2166401,17z/data=!3m1!4b1!4m5!3m4!1s0xbce0f30daa6eaf:0x6f73249cde73bdfb!8m2!3d-21.3882154!4d-42.2144559', 3, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.34');
