INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (600, 1, 'sitio-do-engenho', 'Sítio do Engenho', '3303104', 'Estrada Natividade - Varre Sai - km 0,3', 'Visitação a uma propriedade do ano 1834, localizada às margens do ribeirão de São Sebastião.  É uma das propriedades que deram a base para a criação do município de Natividade. Parte da Fazenda do Engenho foi, há anos, transformada em loteamento, que deu origem ao bairro Morada do Engenho. Essa visita é uma verdadeira fuga da vivência urbana, e proporciona muito contato com a natureza.', 'Somente agendamento.', '22 3841-1031/ 22 98126-4489', '', '', 'SIM', 'SIM', 'SIM', -21.042905, -41.959116, 'endereco', 'https://www.google.com/maps/place/Fazenda+do+Engenho/@-21.9722082,-43.4487949,8z/data=!4m5!3m4!1s0xbc87cac41816a5:0x2f73282f0f68e09!8m2!3d-21.042905!4d-41.959116?shorturl=1', 9, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.37');
