INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (602, 1, 'cafeteria-boa-esperanca', 'Cafeteria Boa Esperança', '3304102', 'Santa Clara, Terceiro Distrito de Porciúncula Fazenda Boa Esperança', 'Diversos cafés torrados, café especial, bolos e doce de banana especial da casa. Visitação e experiência no processo produtivo dos cafés especiais, colhidos a 900 mts de altitude. A visita acontece desde a lavoura ao consumo, passando pelos maquinários, separação dos grãos e secagem, finalizando com uma deliciosa degustação. O Café foi eleito em 2019 o segundo melhor Café Especial do Rio de Janeiro. O local ainda conta com uma vista do Pico da Bandeira, o ponto mais alto da Região Sudeste do Brasil e também com um pesque pague, com possibilidade do manejo de banana e café.', 'Das 8h às 12h.', '32 99185-3547', '', '', 'SIM', 'SIM', 'SIM', -20.798556, -41.908661, 'endereco', 'https://www.google.com.br/maps/place/20%C2%B047''54.8%22S+41%C2%B054''31.2%22W/@-20.798556,-41.9108497,17z/data=!3m1!4b1!4m5!3m4!1s0x0:0xf2f89a378d4e73e2!8m2!3d-20.798556!4d-41.908661?shorturl=1', 1, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.39');
