INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (603, 1, 'cafe-iranita', 'Café Iranita', '3304102', 'Rodovia RJ-230, distrito de Purilândia.', 'Visitação à produção do Café Iranita 100% arábica, que é um produto da agricultura familiar, produzido em lavouras sustentáveis, que variam entre 400 a 600m. A propriedade nasceu em 1993, e leva o nome de Sítio Iranita, que vem da união dos nomes: Irany e Nita, pais do proprietário, Olympio Matheus Ribeiro. A partir de 2005, já sob o comando de Ana Regina e Suhail, foi investido na qualidade do café, desde a condução da lavoura até o café estar pronto para a venda. Hoje a propriedade conta com uma estrutura a dequada para a produção de um café de excelente qualidade.', 'De segunda à sexta, das 08h às 17h. Sábados, das 08h às 12h.', '22 3844-2233 (Atendimento via Whatsapp e Telefone)', '@cafeiranita', 'loja.cafeiranita.com.br/', 'SIM', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Caf%C3%A9%20Iranita%2C%20Porci%C3%BAncula%2C%20RJ', 1, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.39');
