INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (605, 1, 'bar-e-petiscaria-recanto-de-padua', 'Bar e Petiscaria Recanto de Pádua', '3304706', 'Avenida José Homem da Costa, S/N - Beira Rio', 'Petiscaria, espaço kids, aluguel para festas e eventos e produtos da terra.', 'Das 16h às 00h.', '22 98132-3315', '@recantodopomba', '', 'SIM', 'NÃO', 'SIM', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=Bar%20e%20Petiscaria%20Recanto%20de%20P%C3%A1dua%2C%20Santo%20Ant%C3%B4nio%20de%20P%C3%A1dua%2C%20RJ', 8, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.41');
