INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (606, 1, 'sitio-sao-francisco', 'Sítio São Francisco', '3305133', 'Estrada da Santa Cruz - Zona Rural', 'O espaço tem como objetivo o descanso e sossego, proporcionando a experiência da vida no campo. Nossa casa remete o tempo às lembranças que estão muito guardadas e quase esquecidas.Nos convida a relembrar-mos o tempo de criança, através de brincadeiras, jogos e aventuras. Cercado por belas árvores, que atuam como palco para as serenatas de várias espécies de passarinhos. Nos deixando mais próximos da natureza e bem perto da cidade. Temos uma varanda que rodeia toda casa. Cheia de redes convidativas para tirarmos aquele soninho após as refeições. Quando pensamos na expressão: "Tá nervoso? Vai pescar!" Aqui é o local certo! Temos um lago majestoso. Cheio de vida, onde podemos praticar o pesque e solte.', 'Das 9h às 18h.', '22 99907-1717', '@sítiosaofranciscouba', '', 'NÃO', 'SIM', 'SIM', -21.330148, -42.0486125, 'endereco', 'https://www.google.com.br/maps/search/Sitio+SÃ£o+Francisco+SÃ£o+JosÃ©+de+UbÃ¡/@-21.330148,-42.0486125,11.21z', 5, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.43');
