INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (614, 1, 'sitio-da-serra-boa-vista', 'Sítio da Serra Boa Vista', '3305133', 'Vila da Santa Maria - Zona Rural', 'Oferece um ambiente rural familiar, propício para a prática de passeio a cavalo e de micro trator, possibilita a prática de trilha, tanto caminhada, quanto motocross na Serra Boa Vista,  há possibilidade de pescaria no lago local, além de oferecer um café matutino, típico ubaense, para todos os visitantes. O lugar possui uma beleza única, convidativo para mergulho e contemplação de cachoeira no período de chuvas, possibilita o turista observar e/ou realizar a retirada do leite da vaca para visitantes interessados, possibilita pescaria, além de ser uma área destaque no nosso município no quesito de isolamento de nascentes, compartilhando com toda a população interessada em água natural potável, além de realizar o plantio de árvores para a proteção ambiental, sendo o principal diferencial é a proteção e conscientização ambiental.', 'Sábado e Domingo, das 8h às 17h.', '22 99936-5224', '', '', 'NÃO', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=S%C3%ADtio%20da%20Serra%20Boa%20Vista%2C%20S%C3%A3o%20Jos%C3%A9%20de%20Ub%C3%A1%2C%20RJ', 1, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.48');
