INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (628, 1, 'sitio-vai-e-volta-cafes-especiais', 'Sítio Vai e Volta - Cafés Especiais', '3306156', 'R. Projetada 2, Varre-Sai - RJ', 'Café cultivado na região noroeste fluminense, onde o clima tropical de altitude associado ao cuidadoso manejo pós-colheita de agricultores familiares favorecem a produção de grãos especiais. Da semente à xícara! O visitante vai conhecer a produção familiar de cafés especiais, produzidos e torrados pela família Rodolphi, que cuida de todos os detalhes da produção para garantir que o café chegue na xícara com a qualidade produzida pela planta. Produtor BiCampeão do primeiro concurso de cafés especiais do Noroeste Fluminense.', 'De segunda-feira a sexta-feira, das 8h às 17h, e sábados, das 09h às 12h.', '22 99913-5407', '@sitiovaievolta', 'https://sitiovaievolta.com.br', 'SIM', 'SIM', '', NULL, NULL, 'municipal', 'https://www.google.com/maps/search/?api=1&query=S%C3%ADtio%20Vai%20e%20Volta%20-%20Caf%C3%A9s%20Especiais%2C%20Varre-Sai%2C%20RJ', 1, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.56');
