INSERT INTO atrativos (id, mapa_id, codigo, nome, municipio_codigo, endereco, descricao, funcionamento, telefone, instagram, site, wifi, agendar, pet, lat, lng, precisao, mapa_url, rota_principal_id, status, origem, fonte_guia) VALUES (630, 1, 'pousada-chacara-vista-alegre', 'Pousada Chácara Vista Alegre', '3306156', 'Zona Rural-final do bairro São Miguel Arcanjo', 'Embora seja considerada zona rural, a pousada está localizada a 5 min de carro do centro de Varre-Sai. Pode-se ir a pé. O hóspede tem o privilégio de estar na roça e ao mesmo tempo dentro de Varre-Sai, ainda visitar uma linda plantação de lavanda', '24 horas.', '22 9998-5133 (Edinalva) / 21 99684-2278 (Zezé)', '@chacara_vista_alegre_varre_sai', '', 'SIM', 'SIM', 'SIM', -20.9215203, -41.8712194, 'endereco', 'https://www.google.com.br/maps/place/POUSADA+CH%C3%81CARA+VISTA+ALEGRE/@-20.9215153,-41.8734134,17z/data=!3m1!4b1!4m5!3m4!1s0xbc7f161e7655c9:0x4f645de0043f0f98!8m2!3d-20.9215203!4d-41.8712194?shorturl=1', 7, 'publicado', 'guia', 'Águas do Noroeste · pdf 12 p.57');
