INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 1, 'en', 'descricao', 'Located in the Historic Village of Ipiabas, in an architectural ensemble built in the 19th century, surrounded by nature and with a large garden, Pousada Vale do Café offers restful days at the gentle pace of the rural countryside, where time moves without hurry. Breakfast is served with selected local and homemade items.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 1, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 2, 'en', 'descricao', 'Builds partnerships and helps tourists fall in love with our destination. Offers the chance to enjoy new experiences, especially in the countryside.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 2, 'en', 'funcionamento', '8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 3, 'en', 'descricao', 'We want our guests to enjoy country life in a rustic, welcoming setting. Plenty of space for walks along trails and country roads, lakes for fishing, and a swimming pool with constantly renewed water.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 3, 'en', 'funcionamento', 'Monday to Saturday, 8:30 am–6 pm – Sunday, 9 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 4, 'en', 'descricao', 'A unique venue in the Vale do Café, located in the Historic Village of Piedade in Ipiabas, RJ, and built in 1874. Through the Handicraft Project, in which craftspeople from the Vale do Café take part, it offers products related to Neoclassical architecture and to the historical and cultural themes of the region. It provides tourist itineraries and city tours and hosts cultural events, organic produce markets and craft fairs. Through the Espaço Vida e Arte, it showcases local artists who wish to exhibit their work. It has a café that prioritizes regional products, and a space with antiques and collectibles.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 4, 'en', 'funcionamento', 'Thursday to Sunday, 10 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 5, 'en', 'descricao', 'When we talk about landscaping, we usually think of beautiful gardens and squares. Yet, when well planned, landscaping in a rural setting makes a property an even more pleasant place to enjoy, thus attracting more visitors.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 5, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 6, 'en', 'descricao', 'Receptive tourism throughout the Vale do Café, combining rural tourism with experiences in ecotourism, adventure, history and culture, and gastronomy. We value the particularities and potential of the district of Ipiabas and how it relates to the environment and sustainability.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 6, 'en', 'funcionamento', '9 am–7 pm / Weekends 7 am–9 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 7, 'en', 'descricao', 'Adventure Jeep Didu offers tours in 4x4 vehicles that seat up to 10 people. Visits to historic farms, cultural attractions and ecological parks. City tours that favor local businesses.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 8, 'en', 'descricao', 'A historic 19th-century farm that today runs a sustainable food-production project. They were pioneers in the Vale do Café region in organic buffalo farming and in organic specialty coffee, certified by IDB.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 8, 'en', 'funcionamento', 'Monday to Saturday, 9 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 9, 'en', 'descricao', 'Beer tour – an explanation of how the beer production process works.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 9, 'en', 'funcionamento', '9 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 10, 'en', 'descricao', 'Nearly two centuries old, the main house, still in perfect condition, preserves its history with original furniture and portraits. The property welcomes visitors from all over the world and offers a delicious lunch or colonial-style breakfast with products from the farm itself. There is also a tour of the coffee plantation, showing the entire coffee process through to processing.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 11, 'en', 'descricao', 'Since 1988, Haras Fire Notes has offered a variety of activities, such as riding lessons, show jumping, barrel racing, functional training, courses and horseback rides, where leisure goes hand in hand with environmental education and the sustainable development of the region. Visitors can interact with the natural environment of Ipiabas and its many attractions through different horseback routes (Pedra do Gavião, a waterfall and several trails).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 11, 'en', 'funcionamento', 'Tuesday to Saturday, 8 am–5 pm / Sunday, 8 am–noon');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 12, 'en', 'descricao', 'Colonial-style breakfast by appointment, with a guided tour telling the history of the farm.  The first building in Barra Mansa, dating from 1768, Fazenda da Posse today houses a Documentation and Memory Center, governed by the Municipal Culture Plan and the Artistic Occupation Program of Public Cultural Facilities. Run by the Fundação de Cultura, the CEDOC is a space devoted to research and to the production and storage of documents related to the historical, social, political and cultural universe of Barra Mansa and the region. It is of great historical and cultural value to the entire region. It is currently a Culture Center.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 12, 'en', 'funcionamento', '8 am–noon');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 13, 'en', 'descricao', 'Accommodation, horseback rides and coffee for non-guests.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 13, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 14, 'en', 'descricao', 'A Neoclassical building, its construction began in 1857 under Commander Lucas Antônio Monteiro de Barros and was completed in 1865 under Commendador Joaquim José Ferraz de Oliveira, the Baron of Guapi. It was listed as a heritage site in 1979 by the State Institute of Cultural Heritage (Inepac). In 1914, the City Council ceded the ground floor to house the Barra Mansa City Hall, which operated there for 70 years. In the legislative chamber, the carved leather chairs, crystal chandeliers and a picture gallery of significant historical value stand out. It currently houses the Municipal Library. The chamber hall and paintings have been preserved.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 14, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 15, 'en', 'descricao', 'Distillery tour with an explanation of the production process and history, plus a tasting shot of the 3 products. Amázzoni Gin was named the best gin in the world at the World Gin Awards in 2021.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 15, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 16, 'en', 'descricao', 'This park is home to 25 sloths that live freely among the trees and paths in the heart of the city. Parque Centenário, also known as Praça da Bandeira, is an urban park designed by the French engineer and landscape architect Auguste François Marie Glaziou, at the request of Joaquim José Ferraz de Oliveira, the Baron of Guapy, first president of the Barra Mansa City Council. Created in the 1870s, the park was later redesigned by the landscape architect Burle Marx, in 1991. The park was once called “Jardim de Baixo” (Lower Garden), since there was a “Jardim de Cima” (Upper Garden) in Largo da Matriz, but the name “Parque Centenário” was given in 1922, as a tribute to the centennial of Brazil''s Independence. Some time later, it took the name Praça Feliciano Sodré, in honor of the then governor of the State. In 1932, the year of Barra Mansa''s centennial, Mayor Izimbardo Peixoto, through a municipal law, restored the name “Parque Centenário”. Known as the Sloth Garden (Jardim das Preguiças), it earned the nickname for hosting sloths, which wander among the old, tall trees.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 16, 'en', 'funcionamento', '8 am–8 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 17, 'en', 'descricao', 'Carefully rebuilt, it retains the architectural features of the late 18th century, having been erected around 1717. Fazenda Cachoeira was initially devoted to growing sugarcane for the production of sugar and cachaça, and later adopted coffee cultivation, which was the town''s great product during the imperial period. The Cachaçaria Rochinha is open to visitors, including product tastings and an introduction to stages of the production process, a true journey back to Imperial Brazil, with the flavors and aromas of the countryside.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 17, 'en', 'funcionamento', '10 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 18, 'en', 'descricao', 'Pick and pay: visitors choose their vegetables, harvest them and pay. It has been a different and pleasant experience for tourists.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 19, 'en', 'descricao', 'Reception with colonial-style breakfast on the farm grounds.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 19, 'en', 'funcionamento', 'By appointment');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 20, 'en', 'descricao', 'A beautiful waterfall, a chance to connect with nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 20, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 21, 'en', 'descricao', 'It is right here that the craftspeople make their pieces and give craft classes to the district''s residents. Built by the Associação das Damas de Caridade de Amparo in 1981. Its goals include encouraging craft skills and making it easier to reach the sales market, with the proceeds going to the craftswomen, as a kind of cooperative. The project was designed by engineer Luiz Roberto Correia Reche and features a facade with colonial-style window frames, maintaining the atmosphere of Amparo''s historic setting. The patchwork quilts produced here are famous, known even in other countries, and have become a hallmark of Amparo.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 22, 'en', 'descricao', 'Pay-to-fish pond, restaurant, swimming pool, horseback rides and model aircraft flying. Lots of greenery and animals.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 22, 'en', 'funcionamento', 'Sunday, 8 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 23, 'en', 'descricao', 'What experience does the place offer? Zip line, football field, heated pool, lake with pedal boats, little farm (contact with animals), Mini Bugre, Kids Hall, Vale do Sol pool, Skibunda.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 23, 'en', 'funcionamento', '8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 24, 'en', 'descricao', 'Horseback rides, carriage rides, pedal boats, zip line over the lake, sport fishing, guided trails, recreation. Plenty of contact with nature, rest and leisure!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 24, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 25, 'en', 'descricao', 'Besides the castle itself, built in 1867 and a cultural heritage site of the municipality, the place is set in the middle of the Atlantic Forest, with lush fauna and flora.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 25, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 26, 'en', 'descricao', 'A beautiful property among the mountains of the Atlantic Forest, with bathing in spring water. Walks on easy and moderate trails, forest bathing, ecopsychology, observation fish farming and organic food, plus its own production of Shiitake mushrooms.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 26, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 27, 'en', 'descricao', 'Contact with the lush nature of the Garden, Music Labyrinth, 10 km of trails, exercise circuit, stunning views, showers, foot baths, massages, crystal tree, bell groves, webs and hammocks.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 27, 'en', 'funcionamento', '10 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 28, 'en', 'descricao', 'Accommodation in comfortable rooms with full board, daytime and evening entertainment, recreation, visits to the orchard, vegetable garden and little farm with animals. Extensive leisure facilities with sports courts, swimming pools, a waterfall and a lovely lake for water sports and fishing.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 28, 'en', 'funcionamento', '8 am–midnight');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 29, 'en', 'descricao', 'Pick and pay in an organic plantation of leafy greens, vegetables, PANCs (unconventional edible plants) and fruit on a family-run property.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 29, 'en', 'funcionamento', 'Monday and Tuesday, 9 am–3 pm / Saturday, 8–11 am');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 30, 'en', 'descricao', 'Visit to an organic dairy farm with hands-on lessons in cheese making.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 30, 'en', 'funcionamento', 'Saturday, 8 am–noon');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 31, 'en', 'descricao', 'Visit to a shiitake mushroom farm, with the chance to take part in the harvest.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 31, 'en', 'funcionamento', 'Tuesday, 8 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 32, 'en', 'descricao', 'Contact with local produce: fruit and vegetables, dairy products, preserves, seasonings, cured meats and sausages, flowers.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 32, 'en', 'funcionamento', 'Wednesday to Sunday, 7 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 33, 'en', 'descricao', 'Brewery visits.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 35, 'en', 'descricao', 'Guiding in rural tourism and in the Vale do Café.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 35, 'en', 'funcionamento', '10 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 36, 'en', 'descricao', 'Guided tour of the factory space, with a presentation on Bean to Bar chocolate production (from cacao to bar) and a guided chocolate tasting; an exclusive menu of spiced hot chocolate and chocolate fondue; chocolate shop for personal consumption and gifts.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 36, 'en', 'funcionamento', 'Wednesday to Saturday, 10 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 37, 'en', 'descricao', 'Liqueur tasting');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 37, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 38, 'en', 'descricao', 'Visitors can buy high-quality products made with organically and home-grown ingredients. The products are on display in the Espaço do Agricultor.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 38, 'en', 'funcionamento', '7 am–3 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 39, 'en', 'descricao', 'Visit to an artisanal cheese dairy, with tasting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 39, 'en', 'funcionamento', '8 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 40, 'en', 'descricao', 'Craft beer tasting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 40, 'en', 'funcionamento', '11 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 41, 'en', 'descricao', 'Tasting of the best craft beer in the Vale do Café.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 41, 'en', 'funcionamento', 'By appointment');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 42, 'en', 'descricao', 'The site has quality facilities, with a large area, several paddocks, 50 stables and five spacious arenas (two sand and three grass), all in excellent condition, as well as a riding ring and trails for ecological outings.  Luiz Felipe de Azevedo holds numerous titles, including two Olympic bronze medals (Atlanta and Sydney) and a gold medal won at the Pan American Games in Havana (Cuba), as well as the title of American Champion and the power-jump record set in Rome (Italy) in 2001, when he cleared 2.32 metres.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 42, 'en', 'funcionamento', '8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 43, 'en', 'descricao', 'Tourists will learn how kombucha is made, a probiotic drink with strong detoxifying power, from the bacterial culture all the way to the drink. Other products, both food and cosmetics, are made from the cultures. It is an incredible experience.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 44, 'en', 'descricao', 'Gastronomy and Gardening');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 44, 'en', 'funcionamento', '8 am–11:30 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 45, 'en', 'descricao', 'Tasting of sugarcane spirits');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 46, 'en', 'descricao', 'Tasting of sugarcane spirits');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 47, 'en', 'descricao', 'Orchid house, organic coffee harvest, fishing and agritourism.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 47, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 48, 'en', 'descricao', 'Tasting of Sugarcane Spirits');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 48, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 49, 'en', 'descricao', 'Leisure space and sport fishing.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 49, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 50, 'en', 'descricao', 'A short introduction to how cachaça is made, with a visit to the production and storage areas. At the end of the tour, a tasting of the cachaças.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 51, 'en', 'descricao', 'Tasting of local products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 51, 'en', 'funcionamento', '7 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 52, 'en', 'descricao', 'Visit to the Mini Farm and the Organic Vegetable Garden, plus holistic experiences.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 52, 'en', 'funcionamento', '7 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 53, 'en', 'descricao', 'Enjoy the view over part of the city from the lookout point, where the sunset is always beautiful.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 53, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 54, 'en', 'descricao', 'A peaceful spot to take in nature, go for a walk, ride a bike or a horse, or enjoy a family picnic.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 54, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 55, 'en', 'descricao', 'Tasting of sweets made in copper pots over a wood-fired stove.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 55, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 56, 'en', 'descricao', 'At the municipal botanical nursery you connect with nature through the garden itself, learning about the practices used for replanting and conservation and getting to know the different native trees grown there.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 56, 'en', 'funcionamento', 'Monday to Friday, 8 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 57, 'en', 'descricao', 'Experience the greenhouses, from planting to cultivation, with a carp pond, nature and sunset views, and lunch and snacks made with organic products (by appointment).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 57, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 58, 'en', 'descricao', 'Tasting of honey from different blossoms and a demonstration of how honey is harvested.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 58, 'en', 'funcionamento', 'Monday to Sunday, 9 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 59, 'en', 'descricao', 'Local cuisine and gastronomy.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 59, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 60, 'en', 'descricao', 'Visitors can interact with a variety of animals and enjoy a true country experience: riding a horse or pony, milking a cow, planting and harvesting vegetables in the garden, fishing, and dining at a great restaurant.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 60, 'en', 'funcionamento', 'Friday, 10 am–6 pm; Saturday and Sunday, 10 am–11 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 61, 'en', 'descricao', 'Learn about how the produce is grown and about the history of protected cultivation in greenhouses.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 61, 'en', 'funcionamento', 'Monday to Friday, 9 am–3 pm; Saturday, 9 am–noon');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 62, 'en', 'descricao', 'The Cachaça Museum is the first of its kind in the country. Its founders, Íris and Iale Renan (now deceased), opened the museum in 1991, after years of research in libraries and of collecting several hundred bottles bought in every corner of Brazil to build this vast and distinctive collection. It is presented to visitors alongside paintings, collections of chronicles and articles, specialized books, popular folk verses, an antique mini still, and many other attractions that make up the important history of cachaça. The Cachaça Museum also houses a craft spirits distillery, two cellars and a bar offering free tastings.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 62, 'en', 'funcionamento', 'Tuesday and Friday, 9 am–6 pm; Saturday, 9 am–7 pm, to Sunday, 9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 63, 'en', 'descricao', 'A-la-carte restaurant serving Brazilian and regional food, plus an emporium with local products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 63, 'en', 'funcionamento', 'Monday and Tuesday, 9 am–3 pm; Wednesday and Thursday, 9 am–3 pm and 6–11 pm; Friday to Sunday, 9 am–11 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 64, 'en', 'descricao', 'A visit to see where Fazenda São José dos Pinheiros once stood, a property dating from 1851 and a landmark of the Coffee Cycle in the Paraíba Valley.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 64, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 65, 'en', 'descricao', 'A cultural space housing the town''s craftspeople shop, with a variety of products on sale to the community and visitors.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 65, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 66, 'en', 'descricao', 'A Culture Hub that runs activities in schools, welcomes visitors and brings together other popular culture groups in the region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 66, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 67, 'en', 'descricao', 'A visit to the colonial past, with access to the main house, which is about to turn 200 years old. Visit the slave quarters, which still preserve features from the period of slavery, such as dungeons and the stocks.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 67, 'en', 'funcionamento', '8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 68, 'en', 'descricao', 'Agroecology, family farming and sustainable food production. Small-scale raising of cattle, chickens and ducks.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 68, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 69, 'en', 'descricao', 'Free-range chickens (egg production), ornamental plants, cacti, succulents, gardening, a home composting workshop, vegetable garden and earthworm humus production.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 69, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 70, 'en', 'descricao', 'Homemade manioc products (tapioca starch, manioc starch and manioc flour) and organic farming.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 70, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 71, 'en', 'descricao', 'Pay-to-fish pond, restaurant, eco-walks, pedal boats, swimming pools, football field and playground. Live music events on weekends. Inclusive tourism for seniors and people with disabilities. Time in nature in a family setting, with the option of weekend stays, picnic space rental, barbecue areas and countryside events.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 71, 'en', 'funcionamento', 'Tuesday to Friday, 8 am–4 pm; Saturday and Sunday, 8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 72, 'en', 'descricao', 'A vast rural area of more than 1 million square meters, made up of pastures, livestock, lakes, lots of greenery and fresh air, dairy and homemade sweets production, not to mention the indescribable views of sunrise and sunset. There is also a lake, ideal for sport fishing and water activities, offering unique experiences of genuine country life and an ideal setting for exercise, walking, running, cycling, horseback riding, off-road trails, mountain biking and any outdoor activity.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 73, 'en', 'descricao', 'Founded in 1966 by amateur anglers and Light employees, the Piraí Fishing Club played a major role in environmental conservation at the Ribeirão das Lajes Reservoir and its surroundings. In partnership with Light, it ran fish restocking campaigns and has served as a support base for various Navy and Army activities.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 74, 'en', 'descricao', 'Every proper countryside place has plenty of animals. At the Mini Farm, your children can get up close to our little animals and interact with them in a way that is nearly impossible in the country''s big cities today. Visiting the Mini Farm is also a chance for your child to have some unique experiences. Children can milk the cows or feed the many rabbits of Coelhândia. The little ones will also get to interact with chickens, ducklings and much more. The Mini Farm is also home to some very distinguished residents, such as the Three Little Pigs and the buffaloes Bull and Bill. The two stars of the farm are the mascots Bob Panga and Lili the Little Cow, who are the kids'' favorites. Another must-see stop on this tour, which pleases everyone from the youngest to the oldest, is the Boi Bandido (Outlaw Bull). There, the goal is to snap a photo of the fiercest animal on the farm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 75, 'en', 'descricao', 'A place that showcases the work of local craftspeople. It is the perfect spot to get to know and buy products that express the culture of the town.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 75, 'en', 'funcionamento', 'Monday to Friday, 9 am–3 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 76, 'en', 'descricao', 'Tribeca is a company working in the macadamia business at every stage of the production chain: seedling production, technical guidance for newcomers to the crop, technical support for partner growers, nut purchasing, nut processing, and the sale of kernels in domestic and foreign markets.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 77, 'en', 'descricao', 'Hotel Fazenda Cascatinha is set in a beautiful landscape surrounded by greenery and plenty of space, on a genuine, welcoming farm planned with comfortable facilities to host you and your family. An ideal place for those seeking hospitality, leisure, fun and relaxation, along with the peace and safety of a bucolic rural setting. A perfect place to take care of your mental health.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 77, 'en', 'funcionamento', 'Monday to Friday, 9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 78, 'en', 'descricao', 'A visit to the production of handcrafted aged cachaças, plus a chance to try the house''s other well-known products, such as Gabriela Cravo e Canela cachaça, and others in flavors like banana, coconut, sweet corn and strawberry.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 79, 'en', 'descricao', 'A 120 m² swimming pool in the middle of a lawn of more than 5,000 m², in a valley surrounded by Atlantic Forest with endless fruit trees and birds; a lake for rowing a boat alone or with someone you love; horseback riding on a Campolina horse over green hills, watching vast pastures with animals in complete harmony with nature; going to the corral to milk a Holstein cow; and hiking a trail while breathing the truly pure air of a preserved forest.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 80, 'en', 'descricao', 'Tourist transportation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 80, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 81, 'en', 'descricao', 'Rural lodging and gastronomy in the Sertão da Prata, in Rio Claro.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 81, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 82, 'en', 'descricao', 'Caters to tourists and workers.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 82, 'en', 'funcionamento', '7 am–10 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 83, 'en', 'descricao', 'Contact with nature, learning about agroforestry, understanding sustainable concepts, natural poultry farming, and harvesting organic agroforestry products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 83, 'en', 'funcionamento', 'Tuesday to Friday');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 84, 'en', 'descricao', 'At the Park, visitors enjoy comfort and safety in an experience for all the senses: admire the landscapes of the Atlantic Forest and Ribeirão das Lajes, listen to birdsong and try, at the Kiosk, treats rescued from the recipe book of Dona Cidinha, a former resident. Admission is free, as are all activities. On the Visitor Circuit, the highlights are the ruins of the Mother Church and of the Captain-Major''s House, a Memory Center with a scale model and exhibition, an amphitheater and a football field. There is also a bird observatory, a Creative Energy Room, an organic vegetable garden, a seedling nursery, a lookout point, the Fagundes Varela Reading Space, a sensory garden, and parking and restrooms with accessibility.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 84, 'en', 'funcionamento', 'Wednesday to Friday, 10 am–4 pm / Saturday and Sunday, 9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 85, 'en', 'descricao', 'Tasting of aged cachaças.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 85, 'en', 'funcionamento', 'Wednesday to Sunday, 9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 86, 'en', 'descricao', 'With 4.5 km of well-kept trails inside the forest and scenic attractions such as a cave, a waterfall and sweeping views, visitors step into the forest, hear the trilling of birds and feel the fresh air in a setting free of crowds, letting them disconnect from the city and the problems of everyday life and recharge their energy for a new journey.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 86, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 87, 'en', 'descricao', 'Eco-tour, lunch, breakfast, storytelling, waterfall and trail.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 87, 'en', 'funcionamento', 'During the day');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 88, 'en', 'descricao', 'Operates as a local tour operator selling travel packages focused on ecotourism in Atlantic Forest areas and on the region''s wealth of water (rivers, streams and waterfalls), with 4x4 and bike tours or visits to historic sites such as Fazenda da Grama, mountaineering, and lodging in country houses, small farms and inns. It also offers guided visits to dairies and agricultural production farms in the municipality.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 88, 'en', 'funcionamento', 'Monday to Friday, 8 am–5:30 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 89, 'en', 'descricao', 'We are a family-run rural inn offering the experience of country life: contact with nature and animals, and harvesting produce for your own meal.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 89, 'en', 'funcionamento', 'Monday to Friday');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 90, 'en', 'descricao', 'All products are made from buffalo milk and produced by hand, with state certification.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 90, 'en', 'funcionamento', 'By arrangement with the owner.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 91, 'en', 'descricao', 'Meditation spots, essential oils, handmade liqueurs, bamboo lamps, a laundry room, a lookout point and hammock area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 91, 'en', 'funcionamento', 'Saturday and Sunday, 8–10 am');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 92, 'en', 'descricao', 'More than one hundred and forty hectares of nature form a unique valley full of history. Incredible landscapes can be enjoyed while breathing in the scent of the flowers growing in the property''s gardens, leaving visitors with renewed energy. Horseback or quad bike rides, milking the mini cow, riding on the sandy bay, taking a photo with the friendly and photogenic little sheep or with the peacocks Custódio and Bernardino, not forgetting the mascot, the little donkey Ana-Bella, and also feeding the chickens and fishing in the lake. For those who simply like to enjoy nature, there is birdsong to admire, a walk along the farm''s trails, or even a little nap in the hammock area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 92, 'en', 'funcionamento', '8–10 am');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 93, 'en', 'descricao', 'Located in the beautiful former railway station building, visitors can learn a bit about the region''s history, told by the craftspeople themselves, and buy local crafts.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 93, 'en', 'funcionamento', '9:30 am–5:30 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 94, 'en', 'descricao', 'During the visit to this family-run artisanal cachaça producer, visitors learn about the production process, which meets standards of cleanliness and organization and uses state-of-the-art equipment while preserving the traditional, handcrafted way of making it.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 94, 'en', 'funcionamento', '8–10 am');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 95, 'en', 'descricao', 'Sale of local crafts.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 95, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 96, 'en', 'descricao', 'A craft cachaça with quality standards equivalent to those used in producing the world''s finest spirits, made by the couple Cilene and Eli Werneck. Visitors can see every stage of the process in detail, as Eli keeps spreadsheets for every stage of production, with full traceability. By looking at a bottle''s batch label, it is possible to tell which area of the sugarcane field the cane came from and on which day or period it was cut and milled. As a result, it became the first producer in the state of Rio de Janeiro to receive the INMETRO Quality and Sustainability Certification.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 97, 'en', 'descricao', 'A space for families, where tourists can go horseback riding, play football and meet the mini animals.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 98, 'en', 'descricao', 'A beautiful 19th-century historic farm, very well preserved, even with period furniture. The manor house has 99 windows and more than 2,000 square meters of built area. The owners live on site and lead the visit themselves, which also takes in the old coffee mill.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 99, 'en', 'descricao', 'Guided historical tour of the manor house and gardens, telling the whole story of the farm from the coffee cycle to the present day.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 99, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 100, 'en', 'descricao', 'Hotel Fazenda Vilarejo offers a petting farm with real animals, an organic vegetable garden, pedal boats on the lake, a fishing pond, horseback and bike rides, a large green area with recreation for all ages, themed parties all year round and Vilarejo Radical, with 2 mega ziplines, a high ropes course, a climbing wall and rappelling. There is an outdoor pool with a water slide and a children''s water park, plus an indoor pool. Cinema, Kids Space and Zen Space. Besides enjoying all of the hotel''s facilities, guests can have a unique experience visiting the production at Cachaçaria Vilarejo, where the Vilarejo cachaça and liqueur labels are handcrafted. Our all-inclusive plan offers breakfast, snacks, lunch, appetizers, dinner and themed meals following the hotel''s annual party calendar. Alcoholic and non-alcoholic drinks throughout your stay at the three bars available in the hotel.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 100, 'en', 'funcionamento', '10 am–8 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 101, 'en', 'descricao', 'Visit to the coffee plantation with tasting of its award-winning coffee; musical evenings (saraus); horseback and carriage rides; guided visit to the historic manor house of the Coffee Cycle.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 101, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 102, 'en', 'descricao', 'Açude da Concórdia is certainly a lovely place to stay in touch with nearly untouched nature and a great spot for one of those weekend family picnics. Its clear, cold waters have a shoreline of 4,170 meters. Set in a forested area with remnants of the Atlantic Forest, it is surrounded by pasture vegetation and a grassy path ideal for walking. Along the way you can hear animals such as the inhambu (tinamou), the juriti (dove) and the jacu (guan)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 102, 'en', 'funcionamento', 'Thursday to Sunday, 9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 103, 'en', 'descricao', 'Lake and petting farm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 103, 'en', 'funcionamento', 'With overnight stay: 24 hours | Without overnight stay: 7 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 104, 'en', 'descricao', 'The guided tour consists of a walk through the goat farm, taking part in feeding our goats and milking. There is also a tour with a tasting of products made from the milk of the goats of Lago, such as various cheeses, sweets and pies. It includes a snack with cakes, broas (cornmeal cookies), biscuits and juice. And a gift of goat''s milk soap and a handmade doce de leite. Besides the whole guided tour and the snack, children accompanying their parents on this tour with tasting are entitled to bottle-feed a goat at no extra charge');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 104, 'en', 'funcionamento', 'Sat, 9–11 am and 2–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 105, 'en', 'descricao', 'Dating from 1820, the program consists of a visit to the main house, where the story of the farm and its restoration is told, along with information about the existing furniture and objects, the gardens and lake, as well as a vintage car museum and the ruins of equipment once used to dry and process rice. These are unique experiences that the farm offers its visitors. At the end of the tour, a delicious coffee with typical foods is served.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 105, 'en', 'funcionamento', 'Monday to Monday, 10 am–7 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 106, 'en', 'descricao', 'A country-life experience. Visit to the property, which is dedicated to breeding and selling Saanen goats. During the visit there is a tasting of fine, artisanal cheeses inspired by the centuries-old French cheesemaking tradition.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 106, 'en', 'funcionamento', 'Sat, 10–11:30 am and 4–5:30 pm / Sun, 10 am');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 107, 'en', 'descricao', 'Visit to the facilities, which fully comply with the strictest quality norms and standards. You can taste a cachaça handcrafted in a copper still and aged in noble woods. Taste the woods of your choice, or even the pure, unaged cachaça ("purinha") – come and visit us.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 108, 'en', 'descricao', 'Welcomes visitors for guided tours, overnight stays, educational activities and tourist-cultural events. A true journey back in time. The visit to the farm also includes the only Coffee Museum in the state of Rio. A unique and very special experience. The museum was conceived so that the history of the enslaved people in the time of the Coffee Barons remains preserved and is told for many generations. An enriching visit full of culture and knowledge, giving visitors a unique experience.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 108, 'en', 'funcionamento', '2–3 am');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 109, 'en', 'descricao', 'Guided visit to the distillery, from the processing of sugarcane juice to storage in barrels. Tasting of cachaças and liqueurs, sugarcane juice with delicious pastéis and Luiza''s cakes. Ride on the little train of the Estrada de Ferro União Carvalheira railway. A circuit of approximately 1 km passing through a tunnel, bridges and lakes. There is a restaurant, as well as pedal boat rides on the lake.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 110, 'en', 'descricao', 'Built around 1830, the only privately owned farm listed as heritage by the National Historic and Artistic Heritage Institute (IPAM) in Vassouras, it is one of the most important historic buildings in the area. Guided visits with tourists through the buildings, with staff dressed in period clothing. The tour goes through three rooms furnished with period artifacts and the music room. At the end, visitors can taste the coffee produced on the farm, and it is also possible to book a picnic.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 110, 'en', 'funcionamento', 'On request');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 111, 'en', 'descricao', 'Fazenda Mulungu Vermelho welcomes visitors and takes part in cultural events.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 112, 'en', 'descricao', 'The aim is to spread specialty coffee culture through training for people, technology in equipment and utensils, and promoting on-demand roasting of specialty coffees. A must for lovers of this drink!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 112, 'en', 'funcionamento', 'Sat, Sun and holidays, 9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 113, 'en', 'descricao', 'Pay-to-fish pond in a peaceful, tranquil setting for those seeking contact with nature and fishing.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 114, 'en', 'descricao', 'Visit to the coffee plantation, on-site roasting, and tasting of artisanal coffee.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 115, 'en', 'descricao', 'With a wide variety of packages, Vassouras Eco Resort is located in the Coffee Valley, an area full of breathtaking natural beauty. Here, we respect and care for nature and adopt a range of sustainable practices. In recognition of these efforts, and for complying with environmental protection regulations, we earned the Ibama Environmental Certificate. After all, we believe it is possible to offer the best for you without harming our natural resources, through quality sustainable tourism.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 115, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 116, 'en', 'descricao', 'A lovely L-shaped manor house set on a plateau flanked by a dry-stone retaining wall that marks the property''s old coffee drying yard. A vast grassy field and old ruins make perfect settings for outdoor ceremonies, bringing all the charm of country weddings with the beautiful historic farm as a backdrop. It stages a historical play with more than 10 actors and a jongo and maculelê group. The composition of the manor house, the large trees around it and the stone wall surrounding both conveys the beauty of the place. The property is dedicated to hospitality and historical tours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 117, 'en', 'descricao', 'At Hotel Fazenda Galo Vermelho you will find warmth, affection and a complete leisure structure. Besides a petting farm, organic vegetable garden, milking and carriage rides, it has a full range of leisure facilities for the whole family: recreation, canoeing, pool, heated pool, archery and a climbing wall, among others. All of this surrounded by beautiful historic farm manor houses.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 118, 'en', 'descricao', 'Shop with country products, horseback rides and a mini petting farm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 118, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 119, 'en', 'descricao', 'Horseback rides for tourists in the surrounding area, on the trails of Serra das Emerências and Caravelas. Horse riding at the stud farm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 119, 'en', 'funcionamento', 'Inquire directly.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 120, 'en', 'descricao', 'Riding lessons and horseback rides. The only riding school in the Lakes Region specializing in Classical Riding and Show Jumping, which is an Olympic discipline.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 120, 'en', 'funcionamento', 'From 8 am to 6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 121, 'en', 'descricao', 'The native women are older women who fish, process, prepare and sell their products. Besides being responsible for the whole process, they are active in the fight for artisanal fishing within the ResexMar of Arraial do Cabo (a Federal Conservation Unit), promote the revival of Cabo Frio-area traditions and teach other women to fish. At the headquarters of the Native Women''s Cooperative, you can taste dishes inspired by the sea and the culture of traditional fishing, and they also prepare cachaças with camboi – known as "Cabista whisky" – and other fruits and seeds of the Restinga de Massambaba, reviving part of the history and popular culture of Arraial do Cabo. All accompanied by plenty of conversation and incredible stories from the "WONDER WOMEN OF FISHING".');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 121, 'en', 'funcionamento', 'Not informed.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 122, 'en', 'descricao', 'Typical foods, horseback rides, sale of country products and popular music.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 122, 'en', 'funcionamento', 'From 9 am to 4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 123, 'en', 'descricao', 'Rural producers'' fair, crafts fair, horseback rides, country gastronomy, visits to the 300-year-old chapel of Santo Inácio de Loyola and the surroundings of the Jesuit manor house, children''s games, musical performances, a sensory trail, among others.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 123, 'en', 'funcionamento', 'From 9 am to 3 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 124, 'en', 'descricao', 'Stud farm with roping and barrel events, breeding of miniature horses and other farm animals, rural events, shows and a three-barrel championship.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 124, 'en', 'funcionamento', 'Not informed.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 125, 'en', 'descricao', 'Colonial-style suites, pool with leisure area, horseback rides and ecological walks in a private preservation area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 125, 'en', 'funcionamento', 'By reservation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 126, 'en', 'descricao', 'Suites, pool, stud farm and venue rental for events.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 126, 'en', 'funcionamento', 'Weekends, 9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 127, 'en', 'descricao', 'Patron saint''s cavalcade, held on the holiday celebrating the festivities of the city''s patron saint, in August.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 127, 'en', 'funcionamento', 'Not informed.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 128, 'en', 'descricao', 'Walk celebrating the anniversary of PARNA da Restinga de Jurubatiba (national park), April 29. Walk celebrating Environment Week, in May. Eco-rural walking circuit of Rancho Ouro Preto, to the international standards of Anda Brasil, in September.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 129, 'en', 'descricao', 'A place where guests can experience a day on the farm: milking, horseback and carriage rides, contact with the animals, and also the famous walk around Morro São João, or the Volcano walk. The 18th-century property, built in Portuguese colonial style, keeps its historical and natural features preserved. The 200-alqueire area lies 50 meters above sea level, on Morro São João.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 129, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 130, 'en', 'descricao', 'Free fishing experience, contact with nature and outdoor leisure.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 130, 'en', 'funcionamento', 'From 8 am to 12 pm. Every two weeks.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 131, 'en', 'descricao', 'Works in ecological agritourism, with agroecological production and certified organic food. Welcomes educational tourism groups. Rural camping area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 131, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 132, 'en', 'descricao', 'The Arrastão da Cultura route recalls history, bringing curiosities about the local culture. Passing through historic places such as the Estação neighborhood, you can see the site where the old railway station once stood. The tour follows the old muleteers'' route, past old warehouses and archaeological sites. Located on the shores of Lagoa de Araruama, you can board at Coração de Iguaba Grande. At Sítio Palinha, a typical country breakfast is served. At Sítio Angino, the highlight is the old muleteers'' route and its springs. The welcome is given by the owners of the place, where agroecological products are sold. Stops at Sítio dos Dias, Sítio da Dona Vilma and Espaço Ecológico Celia Barbosa da Silva (Lagoa do Bulcão), where you can take a short trail and enjoy some species of Aroeira, Ipê, Flamboyant, marmosets, Galo da Serra, Canário da Terra and other fauna and flora present there, are also part of the route. The route ends with a delicious lunch at Restaurante Mineiro.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 132, 'en', 'funcionamento', 'The route is made by open-sided tour truck (jardineira) or minibus, lasting 7 hours, and the farms visited are scheduled in advance');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 133, 'en', 'descricao', 'Located on the banks of Rodovia Amaral Peixoto, the space was revitalized in 2020, becoming a meeting point and photo spot that promotes the city.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 133, 'en', 'funcionamento', 'Open access.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 134, 'en', 'descricao', 'An ecological space created in 2020 with the aim of preserving and providing a place for leisure and environmental education, comprising a court, a trail leading to the prayer mount, a space for displaying local crafts, a children''s play area and a lake. Here you can take a short trail and enjoy some species of Aroeira, Ipê, Flamboyant and marmosets, Galo da Serra, Canário da Terra and other fauna and flora present in our city.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 134, 'en', 'funcionamento', 'Open access.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 135, 'en', 'descricao', 'On arriving at the farm, we are welcomed with a delicious breakfast of tapioca, corn cake, savory couscous (cuscuz), sweets and natural fruit juices made from fruit picked in the backyard itself.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 135, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 136, 'en', 'descricao', 'Interaction and direct contact with pets such as calves and horses, feeding fish in the lake, recreation, pool and foosball games, a soccer field, wood-fired kitchen, barbecue grill, and an inviting space suited to offering and serving meals such as breakfast, snacks and lunch.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 136, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 137, 'en', 'descricao', 'Delicious country lunch.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 137, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 138, 'en', 'descricao', 'Products from the farm are sold, and visitors are offered a rural-life experience with fish and shrimp raised in captive tanks, and some birds such as pheasants, ducks, geese, chickens, as well as pigs, sheep, among others.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 138, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 139, 'en', 'descricao', 'On arriving at the property, visitors are welcomed warmly by the owner. The farm has several species of banana trees and beds of agroecological vegetables that can be bought directly from the producer.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 139, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 140, 'en', 'descricao', 'A typical country breakfast is offered, with cassava cake, cornmeal cake, seasonal fruit juices and herbal teas from herbs grown on the property');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 140, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 141, 'en', 'descricao', 'A farm with cattle raising, and production and sale of milk and queijo minas cheese made on the property.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 141, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 142, 'en', 'descricao', 'On the way, you pass along the old muleteers'' route and the spring. Arriving at the property, agroecological products are sold, along with a delicious pastel with sugarcane juice.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 142, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 143, 'en', 'descricao', 'We can admire various crops such as coconut, cassava, orange, mango, a variety of vegetables, among others.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 143, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 144, 'en', 'descricao', 'Board at Coração de Iguaba Grande, located on the shores of the Araruama lagoon, and head to Parque Ecológico Célia Barbosa Da Silva - Lagoa Do Bulcão, an ecological space created in 2020 with the aim of preserving and promoting environmental education. Here you can take a short trail and enjoy some species of Aroeira, Ipê, Pau Brasil, Pau Ferro, marmosets, Galo da Serra, Canário da Terra, Tiê-sangue, Tiziu and other fauna and flora present in our city. The next stop is Sítio Ivonilda, where a country breakfast is offered and you can taste cakes, fruits and natural juices made with products harvested on the property. After breakfast, the visit is to Sítio Faisão Dourado, where products from the farm are sold and a rural-life experience is offered with fish and shrimp raised in captive tanks, and some birds such as pheasants, ducks, geese, chickens, as well as pigs, sheep, among others. Next, the visit is to Sítio dos Chaves, a property with several species of banana trees and beds of agroecological vegetables that can be bought directly from the producer. Then the stop is at Rancho Gratidão, a lovely place with the look of a farm where you can enjoy experiences of interaction and direct contact with animals such as calves and horses, feeding fish in the lake, recreation, pool and foosball games, a soccer field, wood-fired kitchen, barbecue grill, and an inviting space suited to offering and serving meals such as breakfast, snacks and lunch.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 144, 'en', 'funcionamento', 'The route is made by open-sided tour truck (jardineira) or minibus, lasting 7 hours, and the farms visited are scheduled in advance.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 145, 'en', 'descricao', 'An integration experience for the whole family. Agroecological walks, workshops focusing on organic food and agroecological practices. The main project is "from garden to table", with workshops on planting, harvesting and cooking on the wood-fired stove, aimed at experiencing rural life. Observation of free birds in their natural environments, pay-to-fish pond, guided trails to Peito do Pombo, walks with identification of plants, trees and the medicinal garden, and for children, the "Pé no Chão" (Feet on the Ground) project, with tree climbing, scrambling, and other games in the countryside in direct contact with nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 145, 'en', 'funcionamento', 'From 6 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 146, 'en', 'descricao', 'Farm hotel: lodging, dining and leisure services.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 146, 'en', 'funcionamento', '8 am–9 pm. Every day of the year.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 147, 'en', 'descricao', 'Visit to the city''s main flower shops + the Agroecological Square (praça Agroecológica).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 147, 'en', 'funcionamento', '8 am–9 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 148, 'en', 'descricao', 'Total immersion in nature through trails, waterfalls and viewpoints.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 148, 'en', 'funcionamento', '8 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 149, 'en', 'descricao', 'Day use on Sundays with a large, shaded area of identified native trees, streams, a waterfall and leisure facilities including a swimming pool, games room, on-site parking and ecotourism.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 149, 'en', 'funcionamento', 'Sundays. 8 am–4 pm. Day use by reservation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 150, 'en', 'descricao', 'Connecting tourists with nature through a dip in a waterfall, a short trail walk, horseback rides and a taste of local culture. The tour ends on the rural circuit and the beach.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 150, 'en', 'funcionamento', '9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 151, 'en', 'descricao', 'Ceramics classes, sale of homemade products, coffee and cake baked on a wood-fired stove with free-range eggs from the house''s own hens, in a homely setting with beautiful views. Fresh air.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 151, 'en', 'funcionamento', 'Weekend mornings.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 152, 'en', 'descricao', 'Pastel (fried pastry), broth, cassava fritters, typical fruits and lunch.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 152, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 153, 'en', 'descricao', 'Specialized in German-speaking guests who want to get to know Rio de Janeiro, Niterói, Maricá or Brazil and see as much as possible in a short time. German-Brazilian cuisine. Ideal for cruise visitors who would like to explore Rio in detail before or after their trip, with round-trip airport / port transfers.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 153, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 154, 'en', 'descricao', 'We are surrounded by nature, offering quality, handcrafted products. A place to enjoy a delicious rural-style coffee, surrounded by nature, with a beautiful panoramic view of Pedra de Itaocaia and a great spot for watching the moon and the stars.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 154, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 155, 'en', 'descricao', 'Event production, contact with nature and a football field.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 155, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 156, 'en', 'descricao', 'Family-run place with home-style cooking, cozy and pleasant.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 156, 'en', 'funcionamento', '12 pm–2 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 157, 'en', 'descricao', 'Ceramics classes, handmade ceramic tableware and handcrafted work.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 157, 'en', 'funcionamento', '9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 158, 'en', 'descricao', 'Ecotourism trail and horseback riding, typical Chilean food and traditional Brazilian cuisine.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 158, 'en', 'funcionamento', 'Wednesday to Sunday, 9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 159, 'en', 'descricao', 'Buffet or à la carte, drinks extra. Swimming pool, stream, games room, children''s playground, hammock area, inflatable slide, trampolines and ball pit.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 159, 'en', 'funcionamento', 'Weekends and public holidays. 10 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 160, 'en', 'descricao', 'Ecotourism, zip line, waterfall, hang-gliding ramp. Visitors are taken to incredible, hard-to-reach places in a savanna-style 4x4 jeep that seats 9. Locations: Espraiado, Itaipuaçu beachfront, Araçatiba.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 160, 'en', 'funcionamento', '8 am–7 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 161, 'en', 'descricao', 'Tapestries, reclaimed-wood furniture and handicrafts.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 161, 'en', 'funcionamento', '8 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 162, 'en', 'descricao', 'Experiential tourism focused on local rural gastronomy, time with farm animals and contact with nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 162, 'en', 'funcionamento', 'Monday to Saturday. 8 am–7 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 163, 'en', 'descricao', 'Sale of a variety of country products, exclusively handcrafted and/or produced on site in an agroecology project of approximately 1,000 m².');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 163, 'en', 'funcionamento', '8 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 164, 'en', 'descricao', 'Sale of cow''s milk, cheese, manure, plants and snacks.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 164, 'en', 'funcionamento', 'Business hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 165, 'en', 'descricao', 'Countryside venue for rent, with landscaping that blends nature and people, tailored to many kinds of events, for a single day or even for individual, family and group stays.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 165, 'en', 'funcionamento', '9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 166, 'en', 'descricao', 'Rural gastronomic experience, pesticide-free food produced on site, fishing, horseback rides, mountain trails, a place for astrotourism and a camping area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 166, 'en', 'funcionamento', 'Weekends.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 167, 'en', 'descricao', 'Visit to the coconut water bottling plant, with tasting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 167, 'en', 'funcionamento', 'Monday to Saturday. 6 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 168, 'en', 'descricao', 'A place where Chico Tobias cachaça and blended drinks such as Meladinha are produced, with tasting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 169, 'en', 'descricao', 'An area of 100,000 m² with a great variety of fruit trees. Orchard, vegetable garden, corral, chicken coops, etc. Rural kitchen with barbecue grill and wood-fired stove, showers, leisure/dining area, product display area, hammock area, meadow, apiary area and three fish ponds.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 169, 'en', 'funcionamento', 'Business hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 170, 'en', 'descricao', 'Experiences of a journey back in time to the sugarcane era: former slave quarters (senzalas) still inhabited by residents who carry on the struggle of the enslaved, the ruined manor house of the Viscount of Ururaí and his daughter, the warehouse, the church built in 1833, the community restaurant Casa de Artes Machadinha and the Campos–Macaé canal, built by enslaved people, running from Campos to Macaé. Finally, it is important to highlight the quilombola way of life, in its ways of making and being.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 170, 'en', 'funcionamento', '10 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 171, 'en', 'descricao', 'Hydroponics, staple crops and dairy cattle.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 171, 'en', 'funcionamento', '7 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 172, 'en', 'descricao', 'Visit to the pasture production process and the milking process.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 172, 'en', 'funcionamento', '5:30–7 am and 3:30–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 173, 'en', 'descricao', 'On site you will see a demonstration of how the best-ranked cachaça in Rio''s cocktail scene is made, and you can taste or buy the products there. Schedule your visit to enjoy this experience!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 174, 'en', 'descricao', 'Activities in the vegetable-growing area, taking part in flour production and handling poultry, as well as joining in milking and rural sweet-making classes.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 175, 'en', 'descricao', 'Fazenda São Miguel was the first residence of the baron and viscount of Quissamã. The house, typical of the architecture of the end of the sugarcane cycle, is surrounded by palm trees and eucalyptus and houses furniture and objects from the early 20th century. Book a visit to step into this history and enjoy a delicious typical lunch.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 176, 'en', 'descricao', 'Visit to the vineyards, country-style coffee, and a small market with a variety of products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 176, 'en', 'funcionamento', '8–11:30 am and 2:30–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 177, 'en', 'descricao', 'Visit to the local mushroom production, with sale of derived products such as herb salt, risottos and canjiquinha (corn grits).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 177, 'en', 'funcionamento', 'Monday to Saturday, 9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 178, 'en', 'descricao', 'Restaurant with a leisure area, football field, horseback riding, catch-and-release fishing, swimming pools and children''s playground.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 178, 'en', 'funcionamento', 'Weekends. 9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 179, 'en', 'descricao', 'Pay-per-catch fishing, Minas Gerais-style food and a family atmosphere.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 179, 'en', 'funcionamento', 'Monday to Friday, 11 am–2:30 pm. Weekends, 11 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 180, 'en', 'descricao', 'Lodging with breakfast, treetop adventure course, sports court, swimming pool, and our macaw.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 180, 'en', 'funcionamento', 'Tuesday to Sunday, 10:30 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 181, 'en', 'descricao', 'Rural gastronomy, fishing, horseback riding, swimming pool and events.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 181, 'en', 'funcionamento', 'Weekends, 10 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 182, 'en', 'descricao', 'Rural activities, vegetable garden, horses, walks in the surrounding countryside always accompanied by physical education professionals, swimming pool, hot tub and gym. Fit menu and direct service from the owners.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 182, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 183, 'en', 'descricao', 'Panoramic view, apiary, orange and cassava plantations, barbecue area and football field. The visit is accompanied by a Canindé macaw named Amora.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 183, 'en', 'funcionamento', 'Monday to Saturday, 9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 184, 'en', 'descricao', 'It represents the rural culture of Aldeia through its rich cuisine, an authentic rural gastronomic experience with the flavors and atmosphere of the countryside. The swimming pool and horse rides on site are free of charge for visitors who have lunch or dinner with us.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 184, 'en', 'funcionamento', '12 pm–midnight.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 185, 'en', 'descricao', 'Horseback and carriage rides, interaction with the local animals, ecological walk, swimming pool, pay-per-catch fishing. Country cooking.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 185, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 186, 'en', 'descricao', 'Farm hotel built within a 480,000 m² farm of lush greenery and natural beauty, with varied activities led by a recreation team and farm-style cuisine.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 186, 'en', 'funcionamento', '8:30 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 187, 'en', 'descricao', 'Day-use hotel, horseback rides with experienced guides, botanical trail.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 187, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 188, 'en', 'descricao', 'Trails and natural attractions.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 188, 'en', 'funcionamento', '6 am–8 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 189, 'en', 'descricao', 'While enjoying a unique place close to nature and a waterfall, visitors can admire the handicrafts and plants. Crafts made on site, direct contact with the Master Artisan, felt art, clay roof tiles, art on mirrors, decorated and painted plaster pieces, sacred art, decorative pieces made from various elements, educational games, wood art (pine, eucalyptus or reclaimed wood), fabric painting, fridge magnets and other crafts. Plants: a variety of succulents, cacti, roses, terrariums, mini-worlds and a diversity of other plants. Kokedama art is under development.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 189, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 190, 'en', 'descricao', 'Family agribusiness producing preserves in jars, jams and cheeses using family recipes.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 190, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 191, 'en', 'descricao', 'Permaculture tour, guided visit to all the bioconstruction structures, agroforestry systems, bamboo planting and waste management, with a meal option.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 191, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 192, 'en', 'descricao', 'A pleasant experience with the drink that is part of the history of Brazil and of Porto Real. Guided visit led by the owner of the Alambique Cachaça Adelina distillery, explaining the whole cachaça production process, from planting the sugarcane to bottling. Tasting and sale at the end of the tour.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 192, 'en', 'funcionamento', '9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 193, 'en', 'descricao', 'At Sítio Romeu Verri you will experience moments of interaction with the reality of a family that preserves the traditions of its ancestors in growing vegetables and producing honey. At the end of the visit, everyone can buy fresh, tasty products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 193, 'en', 'funcionamento', '8 am–12 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 194, 'en', 'descricao', 'A peaceful spot with a fantastic view of the Paraíba do Sul River. Catch-and-pay fishing and sport fishing. Restaurant serving delicious dishes and portions featuring tilapia.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 194, 'en', 'funcionamento', '7 am–5 pm and 12–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 195, 'en', 'descricao', 'An incredible experience for equestrian sports lovers, with riding lessons given by competitors from major events, and the chance to get close to horses that hold several titles.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 195, 'en', 'funcionamento', '7 am–12 pm and 2–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 196, 'en', 'descricao', 'Visitors can experience the typical atmosphere of the old properties of the first settlers of Porto Real, and can also buy tilapia raised on site, as well as live or dressed ducks. The farm offers lunch for groups, by appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 196, 'en', 'funcionamento', '9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 197, 'en', 'descricao', 'On site, visitors can see a vegetable garden with a variety of leafy greens and vegetables, and follow the process of producing vegetable seedlings.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 197, 'en', 'funcionamento', '7 am–12 pm and 1–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 198, 'en', 'descricao', 'The Feira da Roça is a typical spot in Quatis, founded in 1985. Many people come looking for handmade rural products and crafts; there is also a good self-service restaurant with traditional dishes and a lively forró.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 198, 'en', 'funcionamento', '11 am–6 pm, every second and fourth Sunday of the month.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 199, 'en', 'descricao', 'A peaceful spot with a fantastic view of the Paraíba do Sul River. Catch-and-pay fishing and sport fishing. Restaurant serving delicious dishes and portions featuring tilapia.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 199, 'en', 'funcionamento', '12 pm–12 am.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 200, 'en', 'descricao', 'Tonico Sampaio, owner of Fazenda Bom Retiro, conceived in the early years of the last century (1912) the production of the purest cachaça in the region: Cachaça Quatis, a tradition kept up by his son Silvio Sampaio and continued today by his grandchildren.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 200, 'en', 'funcionamento', '8 am–10 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 201, 'en', 'descricao', 'Wake up to birdsong, walk barefoot on the grass, relax in a hammock under the rose-apple tree and pick fruit straight from the tree, with juices sweetened with sugarcane juice and biscuits made exclusively with the Pousada''s own products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 201, 'en', 'funcionamento', 'Monday to Sunday, 24 hours,');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 202, 'en', 'descricao', 'Feirarte has stalls selling handmade and gastronomic products from local artisans and micro-entrepreneurs of the municipality.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 202, 'en', 'funcionamento', '9 am–2 pm, 1st and 3rd Saturday of the month.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 203, 'en', 'descricao', 'Sport fishing');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 203, 'en', 'funcionamento', 'Thursday to Sunday, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 204, 'en', 'descricao', 'A historical experience that takes you back in time, where you can see up close wattle-and-daub houses and historic pieces from the quilombo, along with plenty of history and recipes found nowhere else.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 204, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 205, 'en', 'descricao', 'Visits to the cachaça production process, which began in 2017. Distillery, sport fishing and dairy production.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 205, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 206, 'en', 'descricao', 'The Rotas de Pedal project is adventure tourism for those who want to breathe fresh air and enjoy freedom in nature. We offer approximately 75 routes through a variety of rural landscapes.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 206, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 207, 'en', 'descricao', 'With a privileged view of the Capelinha area and the Serra da Mantiqueira, surrounded by greenery in a setting with typical rural touches, Recanto do Tambaqui offers visitors a welcoming, spacious outdoor area, with an airy and friendly restaurant. The food earns praise even from the most demanding guests. Not to mention its own production of 100% natural handmade jams and homemade sweets. Country delights.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 207, 'en', 'funcionamento', 'The fishing area is open Wednesday to Monday, 8 am–6 pm. The restaurant is open Thursday to Sunday and on public holidays, 11:30 am–3:45 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 208, 'en', 'descricao', 'Trutas da Serrinha is a pleasant retreat and one of the landmarks of Serrinha do Alambari. Nestled among the green arms of the forest, it has very cold water tanks, ideal for trout farming, a fish that is also a regional tradition. The trout farm produces and sells a range of trout-based delicacies, such as fillet, smoked fillet, pâté and casquinha (baked stuffed shell)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 208, 'en', 'funcionamento', 'Tuesday to Sunday, 9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 209, 'en', 'descricao', 'In the Serrinha do Alambari Environmental Protection Area, in Resende, you can find, amid the Atlantic Forest, a craft brewery in the Belgian brewing tradition: Elbers Bier. Crystal-clear, pure water from springs in the Serra da Mantiqueira is combined with the most traditional malts and other Belgian ingredients to produce a variety of beers ranging from Ales to the classic Blonde, Trippel, Witbier and Dubbel, and even one made with pinhão, the seed of the Araucaria, the typical pine tree of the region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 209, 'en', 'funcionamento', 'The brewery is in operation Monday to Friday, 7 am–3 pm. The brewery bar welcomes visitors on Saturdays, Sundays and public holidays, 11 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 210, 'en', 'descricao', 'At Fazenda Valparaíso stands the beautiful Alambique da Cachaça Reserva do Nosco distillery, highly awarded both in Brazil and abroad. The visit includes a tasting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 210, 'en', 'funcionamento', '10 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 211, 'en', 'descricao', 'Contact with nature, forest, trails, waterfalls, and a manioc flour mill believed to date from the 20th century, a time when there was no electricity in the region and the whole production process was entirely handmade; a dirt road that brings all the richness of a rural area, with views of farms, horse studs and plantations. The place brings with it a revival of all the simplicity of rural life as it was lived in the past.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 211, 'en', 'funcionamento', 'To be arranged');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 212, 'en', 'descricao', 'Homemade country food and homemade products. Available to serve at any time, for groups or individuals.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 212, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 213, 'en', 'descricao', 'REGUA has trails created around the wetlands near the Visitor Centre and other trails that bring visitors closer to the forest and the areas restored by the reserve. An experience that aims to raise visitors'' awareness of the unique relevance and beauty of the Atlantic Forest and all its biodiversity. REGUA specializes in welcoming birdwatchers. We offer a space very close to Rio de Janeiro with suitable infrastructure to receive nature-loving visitors in a region that is still very well preserved. To better serve birdwatchers, we have trails, 3 observation towers and a hide, all at REGUA''s headquarters.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 213, 'en', 'funcionamento', '7 am–4:30 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 214, 'en', 'descricao', 'Rural outings in Cachoeiras de Macacu');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 215, 'en', 'descricao', 'Horseback rides, riding lessons, and trails through forests and mountains on foot, on horseback and by mountain bike. Well-trained, reliable horses, highly qualified instructors and guides, time spent among horses roaming free in nature, and preserved and regenerating Atlantic Forest areas open for visits. Viewpoints, gardens, floodplains, streams and springs.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 215, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 216, 'en', 'descricao', 'Customer service point with illustrated brochures of tourist destinations, accompaniment by an accredited guide, insured transport and interactive activities, onboard service, participation in fairs and conferences, cultural meetings with education professionals, religious gatherings, by night.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 216, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 217, 'en', 'descricao', 'A divine connection with nature and waterfalls. Trails through the Atlantic Forest, a visit to the past. We are located inside the environmental preservation area of Parque Estadual dos Três Picos, with access to the Cachoeira 7 Quedas trail and the 1,600-year-old Jequitibá tree, as well as other waterfalls that spring from the Alto da Serra de Cachoeiras.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 217, 'en', 'funcionamento', '8 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 218, 'en', 'descricao', 'Visit to Alambique Serra Verde, horseback ride, lunch, and sale of cheeses and fruit preserves.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 218, 'en', 'funcionamento', 'Monday to Monday (every day), by prior appointment');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 219, 'en', 'descricao', 'Home-style cooking on a wood-fired stove, catch-and-release fishing and a playground for children.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 219, 'en', 'funcionamento', '7 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 220, 'en', 'descricao', 'Production of handmade organic cachaça and rental of the space for holiday stays. No meals are served on site. The highlight is the hospitality of the owners, Mr. Isaac and Mrs. Vera.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 220, 'en', 'funcionamento', 'Monday to Monday (every day), by prior appointment with accredited guides.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 221, 'en', 'descricao', 'Rural breakfast, catch-and-pay fishing and sale of sweets, free-range eggs and homemade liqueur: the best experiences for tourists.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 221, 'en', 'funcionamento', 'Sat and Sun, 9 am–6 pm. Tuesday to Friday by prior appointment only.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 222, 'en', 'descricao', 'Explanation of the entire cachaça production process and a tasting with snacks. The visit can be made on horseback in partnership with Fazenda Tringuelé.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 222, 'en', 'funcionamento', 'Monday to Monday (every day)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 223, 'en', 'descricao', 'Visit to the guava orchard, fruit picking, the history of the place, an explanation of how goiabada (guava paste) is made, and tasting and sale of guavas and goiabada. The highlight is the chance to pick the fruit straight from the tree.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 223, 'en', 'funcionamento', 'Mon to Sat');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 224, 'en', 'descricao', 'A bar with craft beers and a brewery tour with explanations of the brewing process, the story behind the beers'' names, and a tasting. Great service, a variety of craft beer styles and fantastic snacks to pair with the beers. An open-air venue immersed in nature with a spectacular view of the Serra dos Órgãos.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 224, 'en', 'funcionamento', 'Fri 5–9 pm - Sat 12–9 pm - Sun 11 am–1 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 225, 'en', 'descricao', 'Trails and horseback rides with specialist guides. Equine therapy for adults and children.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 225, 'en', 'funcionamento', 'Every day, by appointment');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 226, 'en', 'descricao', 'Open-air market of organic products from family farming in Guapimirim');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 226, 'en', 'funcionamento', '8 am–1 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 227, 'en', 'descricao', 'Sale of tours and attractions in the city of Guapimirim. The city''s first inbound tourism agency.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 227, 'en', 'funcionamento', 'Mon 1–6 pm - Tue to Fri 9 am–6 pm - Sat 9 am–1 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 228, 'en', 'descricao', 'Outbound and inbound travel agency');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 228, 'en', 'funcionamento', '8 am–1 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 229, 'en', 'descricao', 'Outbound and inbound travel agency');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 230, 'en', 'descricao', 'Bike rides through organic production areas and regional coffee. No competitors.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 230, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 231, 'en', 'descricao', 'A place with a rural character offering a wide range of regional products, as well as meals on Sundays and homemade pasta made fresh on the spot.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 231, 'en', 'funcionamento', 'Fri 9 am–10 pm, Sat 9 am–10 pm and Sun 9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 232, 'en', 'descricao', 'Zip line, creek bathing, natural pool, organic vegetable garden, trails and 4x4 tours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 232, 'en', 'funcionamento', 'By reservation');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 233, 'en', 'descricao', 'The farm produces trout.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 233, 'en', 'funcionamento', '8 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 234, 'en', 'descricao', 'Inbound tour agency. An experience-based tourism offering a range of attractions, from natural dairy products free of chemical additives, thick-cut goiabada (guava paste) cooked in a copper pot over a wood-fired stove, a craft cachaça distillery, wood-fired restaurants, truffle cheeses, trout farming, an experience in a stone castle, a 100% organic farm with pick-your-own, a strawberry plantation, a hop plantation, flower bouquet-making experiences, a farm with day use and an eco-jewelry-making experience, a nursery with a distinctive range of products, crafts and garden decoration, and several places with distinctive jams, featuring hop-based products. Catch-and-pay fishing, a poultry farm with top-quality free-range eggs, camping, a shed with antiques reviving the past, a century-old general store specializing in organic food and traditional carne na lata (canned-style preserved meat). Breakfast or afternoon tea experiences to choose from. The main distinguishing feature of the service is exclusivity for groups at each individual attraction. The group is treated like family.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 234, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 235, 'en', 'descricao', 'Truffle cheeses');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 235, 'en', 'funcionamento', '1–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 236, 'en', 'descricao', 'Tasting of the products and an immersive experience at a cachaça and liqueur factory. Service provided by the owners. Handmade products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 236, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 237, 'en', 'descricao', 'A sensory and cognitive gastronomic experience, raising awareness of natural and healthy eating. Our production, starting with the milk, is our own. Everything is made on the premises. Natural, handmade foods, free of chemical additives. A pleasant, bucolic setting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 237, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 238, 'en', 'descricao', 'Contact with nature, learning about the care and supply of ornamental plants, interior and exterior decoration, growing organic food, seasonings and medicinal herbs, and reusing organic waste (composting, worm humus, biofertilizer). We believe in sustainability and show our visitors the importance of recycling our waste, both for the environment and for our own benefit; organic waste, for example, as a source of nutrients for plants.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 238, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 239, 'en', 'descricao', 'We are a gourmet cultural space with excellent hospitality. Cultural gatherings with local artists, photo spots and handmade products from the Circuito Rural.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 239, 'en', 'funcionamento', 'Fri to Sun, 12 pm–11 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 240, 'en', 'descricao', 'The space is located inside a residential development, with a huge organic vegetable garden and a wonderful lake, the best carne de lata and the coldest beer in the region!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 240, 'en', 'funcionamento', 'Sat 9 am–10 pm, Sun 9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 241, 'en', 'descricao', 'A place to relax in the midst of nature, with fishing, bar service, a restaurant serving homestyle cooking, a variety of snack platters, a party area and barbecue.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 241, 'en', 'funcionamento', 'Sat, Sundays and public holidays - 8 am–8 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 242, 'en', 'descricao', 'Rural immersion and organic vegetable garden workshop. Preservation of local culture, heirloom seeds, family farming, and organic growing with participatory certification.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 243, 'en', 'descricao', 'Crafts with natural flowers. Visitors make their own craft piece.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 243, 'en', 'funcionamento', '9 am–1 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 244, 'en', 'descricao', 'Hand-weaving workshop and products. There is nothing else like it.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 244, 'en', 'funcionamento', '10 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 245, 'en', 'descricao', 'Craft beer tasting and a connection with nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 245, 'en', 'funcionamento', 'Weekends and holidays');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 246, 'en', 'descricao', 'A place in the heart of nature with simple, rustic accommodation, a restaurant and a craft brewery. Warm hospitality and nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 246, 'en', 'funcionamento', 'Sat and Sun');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 247, 'en', 'descricao', 'Brewery tour, factory bar, live music.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 247, 'en', 'funcionamento', 'Fri 2–6 pm; Sat and Sun 11 am–7 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 248, 'en', 'descricao', 'Sustainable inn built from a shipping container, with the Sawabona experience, plus a charming café and bistro serving handmade treats such as cakes, tea, crêpes, ice cream and bonbons. A container-stay experience combined with meditation and the contemplation of a panoramic view in complete privacy, along with sustainable practices such as a vegetable garden grown in reused tires, among other examples.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 248, 'en', 'funcionamento', '12 pm–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 249, 'en', 'descricao', 'The Altos da Serramar network is made up of rural producers who carry out remarkable initiatives with sustainable practices for agriculture and tourism in the districts of Mury, Lumiar and São Pedro da Serra (Nova Friburgo) and Barra Alegre (Bom Jardim), in the mountain region of the state of Rio de Janeiro. The properties, notable for their excellent environmental conservation, are located in the territory of the Macaé de Cima Environmental Protection Area (APA) or around it. Agritourism brings together the region''s potential, integrating environmental conservation with agriculture and tourism, and is a major boost to agroecology');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 249, 'en', 'funcionamento', 'By appointment only');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 250, 'en', 'descricao', 'Mosaic workshops (with or without accommodation), nature-immersion experiences (with lunch), lodging, a mosaic studio, heartfelt home cooking with produce from the farm (wood-fired stove), and interactive conversation circles.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 250, 'en', 'funcionamento', '8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 251, 'en', 'descricao', 'Visit to the strawberry greenhouse, with more than 10,000 plants, where visitors can have their photo taken and, at certain times, pick their own strawberries. For strawberry picking, please get in touch and check beforehand, as picking is only possible during certain periods depending on production. There is also a large, comfortable shop with ample parking, offering many sweets made with the fruit, natural fruit juice, the house pastel with homemade dough, and many other products from small producers in our region and our state.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 251, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 252, 'en', 'descricao', 'Our confectionery offers customers a tour of the strawberry greenhouses at Cabana dos Morangos. Learn about strawberry growing and family farming. The place sells fresh, just-picked strawberries, as well as handmade products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 252, 'en', 'funcionamento', 'Tue 1–6 pm / Wed to Sun 10 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 253, 'en', 'descricao', 'Guided tours of rural properties along the main Eco-Rural Circuits of Petrópolis. Personalized support for tourists and visitors, bringing history, culture and information about each place visited.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 253, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 254, 'en', 'descricao', 'Guided factory tour and product tasting. Sustainability and organic production.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 254, 'en', 'funcionamento', '11 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 255, 'en', 'descricao', 'Discover local craft production. Hands-on interaction with embroiderers.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 255, 'en', 'funcionamento', 'By appointment');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 256, 'en', 'descricao', 'Technical insights into ceramics, a one-of-a-kind activity of its kind.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 256, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 257, 'en', 'descricao', 'Visit to a natural dog treat factory, with tastings for dogs and curious humans. Our products are natural, free of colorings, preservatives and chemicals, made with fresh, carefully selected, locally grown ingredients.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 258, 'en', 'descricao', 'A visit among the organic crops, where tourists can pick produce themselves if they wish. An incredible experience! The owner shows visitors how to use the greens and vegetables, as well as some teas made from medicinal herbs. Working with organic products for 40 years.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 258, 'en', 'funcionamento', '9 am–2 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 259, 'en', 'descricao', 'Vira-Mundo is a non-profit community project based on the exchange of knowledge, experiences and ideas for the well-being of individuals, the community and the environment around us.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 259, 'en', 'funcionamento', '9 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 260, 'en', 'descricao', 'Guided jeep tours to the properties of the Caminhos do Brejal Eco-Rural Circuit. There is no similar service provider.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 260, 'en', 'funcionamento', '7 am–10 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 261, 'en', 'descricao', 'Property producing bonsai, organic seedlings of aromatic herbs, seasonings and medicinal plants; fruit trees, ornamentals and native trees, honey, jams and fruit preserves. Organic seedlings, produced with respect for the environment, reducing carbon emissions, making use of what nature offers as inputs and cutting back on industrial inputs as much as we can. A property with plenty of forest within and around it.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 261, 'en', 'funcionamento', '8 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 262, 'en', 'descricao', 'Visit to an escargot farm, with tasting and sale of the product. No competition, a one-of-a-kind experience in the country.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 262, 'en', 'funcionamento', '7 am–10 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 263, 'en', 'descricao', 'Countryside experience with organic production and laying hens. Communication, hospitality and love in everything we do.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 263, 'en', 'funcionamento', 'From 10 am');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 264, 'en', 'descricao', 'Gourmet tasting, lunch. PANC experience (non-conventional edible plants).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 265, 'en', 'descricao', 'Traditional country lunch cooked on a wood-fired stove, hiking, climbing, camping, a waterfall with a natural pool, bike rental and day use. There are no similar services.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 266, 'en', 'descricao', 'A wonderful house called "Sítio Vaca do Brejo". Without false modesty, a "five-star" place in the Brejal! Unmatched in infrastructure and comfort! From a heated infinity-edge pool to playgrounds for children and adults, a games room, and ultra-comfortable suites with panoramic views! In addition to the traditional fireplace, the whole house is fitted with heating and cooling! On top of all that, an excellent and irresistible gourmet area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 267, 'en', 'descricao', 'Nature and gastronomy. The owners'' personal presence and a human touch.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 267, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 268, 'en', 'descricao', 'Nature and gastronomy. The owners'' personal presence and a human touch.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 268, 'en', 'funcionamento', '8 am–8 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 269, 'en', 'descricao', 'Sport hiking, yoga in the heights, a walk through the forest up to the Lageado (a rise facing Pedra do Elefante, 300 m high), with Pranayama yoga (breathing) and transcendental meditation on arrival at the Lageado. A stunning view, with the walk ending at a crystal-clear spring at 300 m altitude.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 269, 'en', 'funcionamento', '8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 270, 'en', 'descricao', 'Breeding of dairy and wool goats and sale of breeding stock. Poultry farming with various kinds of birds. Beekeeping. Sale of farm products (eggs, honey, cheeses, jams, capers, some types of plants). Garden and orchard produce depending on the season. Bromeliad collection. Guided visit to the various animal-raising areas and a walk with a panoramic view of Pedra do Elefante and Maria Antônia. A variety of attractions, with service in English, Italian and Spanish as well as Portuguese.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 270, 'en', 'funcionamento', '9 am–12 pm and 2–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 271, 'en', 'descricao', 'Family-friendly atmosphere, private parking, chicken coop. Wood-fired stove, parking, outdoor tables, children''s swings.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 271, 'en', 'funcionamento', '11:30 am–4:30 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 272, 'en', 'descricao', 'Dulce de leche (compared to Uruguayan ones by customers) and artisanal cheese, canastra style. Everything is made by us, from the honey and eggs to 60 kinds of sweets, jams and chutneys, and 3 kinds of artisanal cheese');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 272, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 273, 'en', 'descricao', 'Handmade products from the region and craft beer with snacks. A wide variety of high-quality products made in the region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 273, 'en', 'funcionamento', 'Fri 2–10 pm; Sat 10 am–10 pm; Sun 10 am–2 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 274, 'en', 'descricao', 'Craft draft beer tasting and snacks.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 274, 'en', 'funcionamento', 'Thu and Fri 2–10 pm, and Sat 2–10 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 275, 'en', 'descricao', 'Educational tourism focused on environmental education. There is nothing similar in the region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 275, 'en', 'funcionamento', 'Mon to Fri 9 am–4 pm; Sun 10 am–2 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 276, 'en', 'descricao', 'At Fazenda Sertão, the planting area is entirely dedicated to syntropic farming methods.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 277, 'en', 'descricao', 'Spa, bike rides, restaurant.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 277, 'en', 'funcionamento', 'Thu and Sun 8 am–5 pm; Fri and Sat 8 am–11 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 278, 'en', 'descricao', 'Pony and horse rental and a mini petting farm. Contact with nature, wonderful local climate, a cozy, family-friendly place.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 278, 'en', 'funcionamento', '9–11:30 am and 1–2:30 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 279, 'en', 'descricao', 'Country café and vegan treats. A place to enjoy vegan products and to interact with and learn about social projects of public interest.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 279, 'en', 'funcionamento', 'Wed to Sun 10 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 280, 'en', 'descricao', 'Guided jeep tours to the properties of the Secretário Eco-Rural and Gastronomic Circuit. There is no similar service provider.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 280, 'en', 'funcionamento', '7 am–10 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 281, 'en', 'descricao', 'Cow milking and dairy factory. Artisanal production.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 281, 'en', 'funcionamento', '9 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 282, 'en', 'descricao', 'Historical and gastronomic. An itinerary by the chef who won the National Tourism Award');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 282, 'en', 'funcionamento', 'Fri 12–10 pm; Sat 12–10 pm; Sun 12–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 283, 'en', 'descricao', 'Oka Orgânicos is a small rural property that began production in 2015 with vegetables and later added egg-laying hens, both certified by Abio. On site, you can see the chicken coops and the vegetable garden. Not wheelchair accessible, as it is hilly terrain. A fully sustainable property, making full use of the land and reforesting with fruit trees and native plants.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 283, 'en', 'funcionamento', '9–11 am');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 284, 'en', 'descricao', 'A rigorous selection of quality products and attentive customer service. Buy handmade products from various producers in the region. You can enjoy a delicious coffee, a craft beer, savor excellent cheeses and relax in a friendly, interesting and welcoming setting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 284, 'en', 'funcionamento', 'Tue 11 am–6 pm; Wed and Thu 9 am–6 pm; Fri, Sat and Sun 9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 285, 'en', 'descricao', 'A bucolic little house in the center of Secretário that is both an art space and a place offering coffee and other souvenirs of our historic region. Located in the center of Secretário, the space is devoted to art and the sale of souvenirs from our historic region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 285, 'en', 'funcionamento', 'Fri and Sat 9 am–6 pm / Sun 10 am–3 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 286, 'en', 'descricao', 'MTB experience. We specialize in bicycle rental, sales and maintenance.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 286, 'en', 'funcionamento', 'Friday, Saturday and Sunday');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 287, 'en', 'descricao', 'Italian cuisine and, soon, accommodation in the style of home-stay tourism. The charm of being welcomed into a home, an Italian accent, a unique gastronomic experience, artisanal breads, everything made with care.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 287, 'en', 'funcionamento', 'Friday, Saturday and Sunday');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 288, 'en', 'descricao', 'Crafts, quality products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 288, 'en', 'funcionamento', 'Wed to Fri 12:30–4 pm; Sat 9 am–5 pm; Sun 9 am–1 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 289, 'en', 'descricao', 'Located next to the Serra dos Órgãos National Park in Petrópolis, 1.3 km from the Parnaso headquarters, recharge your energy on 17 hectares amid nature and wildlife, with all the comfort and facilities for the most relaxing stay possible. Quinta das Nascentes is a place where you will find, and take part in the development and creation of, a large organic farm in the mountain city. You will receive an excellent welcome from the owners, who live at the Quinta. You will enjoy quality accommodation with respect and without prejudice. Immersing yourself in the Atlantic Forest ecosystem in an organic way, with its climatic and physical curiosities, it is the perfect place for observation tourism.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 289, 'en', 'funcionamento', 'Fri to Sun');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 290, 'en', 'descricao', 'A restaurant by the waterfall with a sophisticated rustic touch, offering a self-service buffet cooked on a wood-fired stove, homestyle food and a varied menu. Surrounded by waterfalls in the middle of nature, with beautiful sunsets!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 290, 'en', 'funcionamento', '10 am–7 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 291, 'en', 'descricao', 'Food cooked on a wood-fired stove, outdoor dining, beautiful scenery. Very good quality food, great seasoning, good service, a rural experience.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 291, 'en', 'funcionamento', 'Monday to Friday, 12 pm–4 pm; Saturday and Sunday, 12 pm–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 292, 'en', 'descricao', 'Finding a place to chat and pass the time is easy. But Bar do Horto offers more than that: an ice-cold beer served with the house''s famous traditional pastel, a pleasant atmosphere and a menu with variety, from breakfast to snacks, craft cachaças and beers. Located in Itaipava, in the city of Petrópolis, Rio de Janeiro, inside the hortomercado.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 292, 'en', 'funcionamento', '8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 293, 'en', 'descricao', 'Exhibition by a collective of 30 local artisans, with a welcome at the shop by D Pedro II and Tereza. It features handcrafted pieces made from reused materials, original designs and souvenirs. There you will find exclusive pieces and the Cultural Stations that tell a little of the city''s history.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 293, 'en', 'funcionamento', 'Monday to Saturday, 10 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 294, 'en', 'descricao', 'Visits by appointment to the production of red and yellow bell peppers. There is a cave on the property. Coffee (morning/afternoon) and lunch on site. Wonderful scenery, and the property has a cave you can visit.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 294, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 295, 'en', 'descricao', 'The concept is a sensory experience, pairing the different blends with the local landscape. Available in different versions, a Reserva and a Reserva Especial, offering a diversity of flavors, with cachaças aged in different Brazilian woods. Cachaça Imbaúba is made entirely by hand. Our wish is to bring consumers a high-quality product, wrapped in the concepts of warmth, family work, sustainability and love for the city of Teresópolis. We are located in one of the most beautiful areas of the mountain region of Rio de Janeiro.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 295, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 296, 'en', 'descricao', 'A tour shows the goats, the cheese production, a visit to the shop and restaurant, tastings of various cheeses and sales of products made with goat''s milk, such as shampoos, soaps and creams. On site is the Cremerie Genève restaurant, which serves fresh cheeses alongside dishes made with ingredients from the property and beer brewed on site. Food production, cheesemaking, shop, tastings and restaurant');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 296, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 297, 'en', 'descricao', 'Visits to the production of 100% organic milk and its derivatives, such as fresh minas cheese, ricotta, curdled milk, cottage cheese and yogurt. Vale das Palmeiras has held Organic Certification since 1997. Private Natural Heritage Reserve (RPPN) Rildo de Oliveira Gomes II. Over an area of 200 hectares, the farm was restored through a simple and viable recovery plan that fenced off the springs, the legal reserve and the permanent preservation areas, and let the native vegetation regrow naturally');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 297, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 298, 'en', 'descricao', 'Visit to the Serra dos Órgãos Distillery, producer of craft gin');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 298, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 299, 'en', 'descricao', 'An interactive knowledge museum with images and aromas; by appointment. Hostel. With a seed bank available for reforestation, the Museu do Futuro seeks to teach and promote the preservation of the Atlantic Forest. The initiative came from the NGO Museu do Futuro, which invests in ecological education and bought 20,000 m² of native forest within the Três Picos Park reserve. The site lies in the midst of the Atlantic Forest, next to Cachoeira dos Frades. At the museum''s headquarters, which has ecological architecture, courses, research and cultural activities take place. There are seminars on ecology, pedagogy, art, architecture and sustainability. The museum also offers ecological therapies, with balanced nutrition, energy massages, breathing techniques and more, to bring people closer to nature. Visits by appointment. The latest activities held on site are: Meditation; Self-help techniques; Coaching; Biodanza; Hertz vibrational therapy; Cosmobiology for individuals and companies; among others, following a new worldwide trend in this tourism segment');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 299, 'en', 'funcionamento', '8 am–1 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 300, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Agroecological Association of Teresópolis. Organic crop production (fruit, vegetables, greens and grains), free-range animal production (chickens, ducks, rabbits, tilapia, chicken and duck eggs). Guided rural experience tour: sowing, planting and harvesting organic products (pick and pay), with more than 400,000 m² of Atlantic Forest to enjoy on hiking trails, plus internal lanes through the planting areas lined with various fruit trees. Brincarte space for the kids, with several options (tree swings, a tire circuit running through the swing tree, tire trampoline, grass slide, mini golf on the lawn, grass court). Bicharada space with a small pond, ducks, chickens and rabbits. Hammock area, with several hammocks for resting. Gastronomy space with a gourmet veranda equipped with a wood-fired stove and barbecue, where traditional rural meals are served (breakfast, lunch and afternoon snack). Rural lodging for groups in the main house (suite + bedroom + habitable mezzanine) and in an annex of two suites with double rooms, accommodating groups of up to 24 people. Camping area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 300, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 301, 'en', 'descricao', 'Lets visitors experience the daily routine of the countryside and the farmer: handle vegetables straight from the garden; plant seedlings of various plants and vegetables; harvest your own fresh food and buy some products made on site, such as jams and craft beers. The place has an open-concept kitchen where a homestyle lunch is served, prepared on a wood-fired stove with ingredients grown on the farm. Arugula, spinach and broccoli. The jams are made with fruit from the farm; our beers are not yet sold off the premises and can be enjoyed on the farm. They are usually made with our own products, our own hops, and we make witbiers with arugula, orange, Sicilian lemon and lemongrass.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 301, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 302, 'en', 'descricao', 'Stay, meals and a tour of the organic egg production areas.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 302, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 303, 'en', 'descricao', 'Organic fruit, root vegetables and leafy greens. Visit to the organic production. Gourmet space with barbecue, oven and wood-fired stove; trails, a small waterfall; a self-sufficient house, fully furnished, with two bedrooms, one double and one with three single beds.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 303, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 304, 'en', 'descricao', 'Lodging; breakfast; restaurant; guided trails; fishing lake; indigenous decor; not recommended for children; ideal for groups; reference center for aquaculture and hydroponics. Offers a sauna; football/volleyball field; swimming pool and wifi in the common areas. Spaces for workshops and events: rustic meeting room, a relaxed and simple setting, with capacity for up to 40 people. Equipment: TV, video, slide projector, outdoor amphitheater with capacity for 80 people. Ideal for immersive experiences, role-play and theatrical performances');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 304, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 305, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Agroecological Association of Teresópolis. Specializing in organic seedlings and fertilizers. Visit and hands-on experience in the production of seedlings, organic fertilizers and alternative organic inputs for planting. Visit and hands-on experience in the planting of organic products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 305, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 306, 'en', 'descricao', 'Exhibition and workshop on making folk toys; giant puppet workshop. They offer space for small events and guided visits for tourist and school groups, with sales of local products and an exhibition of folk toys. Small vegetable garden. A place that safeguards the forest, wild animals, toys and games, and traditional popular cultures. They work to revive family values, free time, togetherness and good practices linked to rural life.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 306, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 307, 'en', 'descricao', 'The townhouse (sobrado) houses and presents part of the history of Teresópolis: the life story of the Italian immigrant José Francisco Lippi and the beginnings of the village of Venda Nova. Besides documents, photographs, furniture and rooms from the late 19th century, the site includes gardens for strolling among flowers, fruit trees and birds. It covers 5,000 square meters prepared with nooks, corners and charms to welcome visitors and touch the hearts of children. School visits, group visits and research visits by appointment. Jabuticaba jam and liqueur, among other fruits and sweets.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 307, 'en', 'funcionamento', 'Saturday, Sunday and holidays, 1:30 pm–5:30 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 308, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Agroecological Association of Teresópolis. Production of organic vegetables, fruit trees, legumes and herbs. Hands-on planting and harvesting experience');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 308, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 309, 'en', 'descricao', 'Visits to the production of organic jams and preserves; organic liqueurs.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 309, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 310, 'en', 'descricao', 'Horseback rides, pre-booked riding lessons and spa services. Swimming pool, sauna, living room, games room, video room and gym. Inn (pousada).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 310, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 311, 'en', 'descricao', 'Farm hotel with several ecological trails, the largest lake in the region, and adventure activities integrated into nature such as treetop rope courses, a 500 m zip line and a climbing wall. Boa Vida has various animals such as chickens, ducks, ponies, a cow and more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 311, 'en', 'funcionamento', 'Saturday and Sunday, 8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 312, 'en', 'descricao', 'The farm hotel offers breakfast, lunch and dinner, with drinks charged separately. It has a team of children''s entertainers, live music at night and, on Sunday mornings, a circus troupe led by Fiapo the clown and his friends. Dry sauna, games room and restaurant with panoramic view, a chapel for religious purposes, swimming pool, football field, volleyball court, zip line, horseback rides, massage therapy and barbecue.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 312, 'en', 'funcionamento', '10 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 313, 'en', 'descricao', 'The farm hotel covers an area of more than 7,500,000 m², with 15 ponds and an area of virgin forest with waterfalls and cascades where local wildlife can be found, as well as cattle breeding, Mangalarga Marchador and pampa horses, and small farm animals. It has 4 swimming pools, 3 courts, a games room, a convention room, a TV room, a playground, horseback riding, pedal boats, a zip line and treetop ropes courses.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 313, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 314, 'en', 'descricao', 'The property offers a restaurant, piano bar, two outdoor swimming pools (one with a water slide), a gym, tennis courts and a running track, as well as saunas and a covered outdoor hot tub. Other activities include horseback rides and mini golf. Rowing boats are available, and guests are invited to interact with the animals on the farm. A wide range of leisure options.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 314, 'en', 'funcionamento', '10 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 315, 'en', 'descricao', 'The property offers a lounge for games and watching DVDs, a natural pool, a waterfall, trails, ecological walks, horseback rides, performances by artistic groups and music, workshops, courses in Indian and lacto-vegetarian cooking, mantras, dance, a bio-sauna, a games room, yoga, lectures, thermal baths, a living room, an events room, a panoramic deck, a lacto-vegetarian restaurant and a Natural Therapies Center.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 315, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 316, 'en', 'descricao', 'The farm hotel stands on a 960,000 m² property, of which 600,000 m² is preserved Atlantic Forest, crossed by a trail that ends at a viewpoint with a 360° panoramic view. It has pedal boats, a zip line (subject to weight and age), a games room, a billiards room (for adults), a water slide, ecological fishing, heated swimming pools for adults and children, outdoor swimming pools for adults and children, dry and steam saunas, karaoke, a "bicholândia" (animal corner), a volleyball court, a football field, a bocce court, horses (for children), a tennis court (bring your own tennis equipment), a water slide and other leisure options.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 316, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 317, 'en', 'descricao', 'The hotel sits in the middle of a 100-hectare private park at an altitude of 1,250 m and has three restaurant options. Leisure options include 10 kilometers of internal trails for ecological walks, a riding ring, stables, horses, tennis, volleyball and futsal-style society football courts, two solar-heated swimming pools and an outdoor hydromassage jacuzzi, boats and kayaks, and sport fishing in a mountain lake fed by springs and unpolluted rainwater.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 317, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 318, 'en', 'descricao', 'A traditional restaurant that has been open without interruption for more than 30 years, serving family recipes. There is a hydroponic vegetable garden for the restaurant, open to visitors. Sale of craft cachaça, beer, the house''s smoked sausage, sweets, honey, pepper and heart of palm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 318, 'en', 'funcionamento', '8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 319, 'en', 'descricao', 'A restaurant with a French touch, with recipes that use goat cheese in their compositions. The space has a mini playground and free visits to the animals - goats and chickens. Visit to the cheese dairy (production process and tasting) by appointment, and a chapel open to visitors. Craft beer production, served only on site.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 319, 'en', 'funcionamento', 'Thursday, 12 pm–5 pm; Friday and Saturday, 10 am–10 pm; Sunday, 10 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 320, 'en', 'descricao', 'Italian cuisine and an atmosphere reminiscent of a true Italian cantina. Ideal for all ages and all kinds of groups and families.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 320, 'en', 'funcionamento', 'Thursday, 11:30 am–3 pm; Friday, 11:30 am–4 pm and 7 pm–10 pm; Saturday, 11:30 am–4 pm and 7 pm–10 pm; Sunday, 11:30 am–4:30 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 321, 'en', 'descricao', 'Frozen pasta and savory dishes: quiche, empadão (savory pie) and pancakes, broths and sweets. Delivery only.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 321, 'en', 'funcionamento', 'Wednesday, Thursday and Friday, 9 am–6:30 pm; Saturday, 9 am–2 pm');
