INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 327, 'en', 'funcionamento', '11 am–10 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 328, 'en', 'descricao', 'Restaurant serving homestyle Minas Gerais food. It usually displays artistic pieces at the entrance.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 328, 'en', 'funcionamento', '9 am–6 pm');
