INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 330, 'en', 'descricao', 'A variety of starters, pastas and meats in a space with rustic decor and an elegant atmosphere, with an emphasis on wines.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 330, 'en', 'funcionamento', '12 pm–11 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 331, 'en', 'descricao', 'Shop selling antique, rustic and restored furniture and antiques such as chandeliers, paintings, rarities, works of art and more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 331, 'en', 'funcionamento', 'Thursday to Sunday, 10 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 332, 'en', 'descricao', 'A slow food concept, voted one of the 7 gastronomic wonders of the State of Rio de Janeiro. Its main products are sweets, craft jams and savory snacks, all 100% natural and organic.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 332, 'en', 'funcionamento', 'Tuesday to Sunday, 11 am–9 pm');
