INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 336, 'en', 'descricao', 'A commercial center offering rental of shops, office rooms, kiosks and a space for a gym. It includes shops, a café, a grocery store, a gym, crafts, balaio, real estate and sabor da roça.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 336, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 337, 'en', 'descricao', 'Commercial center.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 337, 'en', 'funcionamento', '5 pm–midnight');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 338, 'en', 'descricao', 'Wooden furniture workshop; gallery under development with a traditional restaurant');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 338, 'en', 'funcionamento', '7 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 339, 'en', 'descricao', 'Studio for furniture and sustainable crafts. Offers handicrafts and décor by 13 local artisans, with original, sustainable pieces that reflect the local cultural identity.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 339, 'en', 'funcionamento', 'Wednesday to Saturday, 9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 340, 'en', 'descricao', 'Accommodation with breakfast and/or full board; bamboo management and treatment courses; day-use of the leisure area with swimming pool, football field and barbecue at the Holiday club. Homemade preserves; organic vegetable garden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 340, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 341, 'en', 'descricao', 'Breakfast; lunch; farm visits; pick-your-own. Family farming and organic production.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 341, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 342, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Associação Agroecológica de Teresópolis. Organic crop production. Pick-your-own, forest walks, mini courses, meals. Visits by appointment, with or without a guide.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 342, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 343, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Associação Agroecológica de Teresópolis. Organic vegetables and honey. Courses, internships and agroecological immersion experiences.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 343, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 344, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Associação Agroecológica de Teresópolis. Organic production of leafy greens, vegetables and grains. Fishing, visits to the organic production area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 344, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 345, 'en', 'descricao', 'Free-range eggs and organic farming. Organic vegetable garden and animal husbandry. Lake with pedal boats; zip line; trails; breakfast; lunch; organic vegetable garden; animals and birds.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 345, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 346, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Associação Agroecológica de Teresópolis. Ecological trails and walks, guided insight into planting and harvesting, fishing, meals, overnight stays, visits to the municipal mountain park, organic produce for sale, birdwatching, talks on environmental education and agroforestry, animal husbandry.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 346, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 347, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Associação Agroecológica de Teresópolis. Diversified crop production, mainly bananas, sugarcane, cassava, corn, turmeric and okra. Beekeeping. Processing of farm produce into breads, cakes and tapioca dough. Guided tour of the fields and the processing area, organic farm lunch, activities for groups of children, agroecology class with hands-on activity suited to all audiences, discovery of PANCs (unconventional edible plants).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 347, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 348, 'en', 'descricao', 'Walks and trails; visits to the stables of purebred horses; organic farming, notably vegetables, herbs and leafy greens.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 348, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 349, 'en', 'descricao', 'Trout hatchery and trout depot');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 350, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Associação Agroecológica de Teresópolis. Organic chicken eggs, leafy greens, vegetables, fruit trees and honey. Private swimming lake, lodging for 80 people, grass football and volleyball pitch, walks and visits to the production area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 350, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 351, 'en', 'descricao', 'Organization of the rural producers of Lúcios, training for rural producers, courses leading them toward agroecology, technical assistance, community kitchen; seed bank; workshop on breads and sweets made with farm produce. Creation of a network of women producers.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 351, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 352, 'en', 'descricao', 'Organic food straight from the producers. Vegetables, leafy greens, fruit, eggs, honey, green juice, sugarcane juice, breads and cakes, homemade sweets, organic seedlings and fertilizers. Live music and lunch every Saturday, playground for children, cultural events, local crafts, home delivery of produce baskets. Free parking for customers.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 352, 'en', 'funcionamento', '8 am–1 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 353, 'en', 'descricao', 'Organic production unit affiliated with the AAT - Associação Agroecológica de Teresópolis. Organic leafy greens, fruit, vegetables and grains, jams, preserves and sweets. Visits, breakfast, lunch or afternoon snack, harvesting of produce.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 353, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 354, 'en', 'descricao', 'Pick-your-own. Nursery with 3 greenhouses. Products available: orchids, bromeliads, groundcovers, fruit trees, decorative stones, clay, polyethylene and cement pots, soils, palm trees, bougainvillea, rose seedlings, living fences, arrangements, and much more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 354, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 355, 'en', 'descricao', 'Overnight stays. Atlantic Forest.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 355, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 356, 'en', 'descricao', 'Tour operator. Priority segment: ecotourism. Specialized in beer tours. Sells domestic and international packages, operates transfers, sells European train tickets.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 356, 'en', 'funcionamento', '9 am–8 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 357, 'en', 'descricao', 'Tour operator specializing in ecotourism, family leisure, rural tourism, rappelling, trekking, trekking, horseback riding and rural experiences. Adventure tourism.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 357, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 358, 'en', 'descricao', 'Travel agency. Priority segment: ecotourism. Specialized in rural, gastronomic and educational tourism. Ecoplay offers visitors experiences that value the local community and raise environmental awareness. Has six structured, priced itineraries.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 359, 'en', 'descricao', 'Receptive (inbound) agency. Priority segment: cultural (civic, ethnic, religious, mystic and esoteric). Specialized in gastronomic, educational and cultural (historical heritage) tourism. Home-office agency.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 359, 'en', 'funcionamento', '8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 360, 'en', 'descricao', 'Travel agency. Priority segment: inbound and outbound tourism, cultural, rural, educational, religious, gastronomic and beer tourism, and ecotourism. RÉTOUR was the first to offer inbound and rural tourism in Teresópolis, with more than 15 years in the market.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 361, 'en', 'descricao', 'Fish-and-pay fishing, restaurant, horseback riding, animal visits, barbecue grill rental and a space with swimming pool, sauna and football field.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 361, 'en', 'funcionamento', 'Sat and Sun');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 362, 'en', 'descricao', 'Fazendinha Rio is one of the best attractions in Vargem Grande if you plan to visit the neighborhood with children. It is considered an educational rural park, where little ones can get in touch with farm animals, explore the vegetable garden and orchard, go horseback riding and even milk the cows.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 362, 'en', 'funcionamento', '10 am–5 pm – Saturdays, Sundays and public holidays');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 363, 'en', 'descricao', 'There you can visit the Quilombo Museum and also take the chance to try some of the restaurants within the community. Bar da Nilza and Bar e Restaurante Tá na Boa are the best known in the area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 363, 'en', 'funcionamento', 'By appointment only');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 364, 'en', 'descricao', 'This is your zoo in Guaratiba, in the West Zone of Rio de Janeiro. We have an interactive petting-farm area where visitors can feed animals such as ponies, llamas, goats, buffalo and many others, using food provided by the park. The Immersion Aviary is the highlight of the interaction, with nearly a hundred birds that eat from your hands! (a portion of seed is provided by the park)
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 364, 'en', 'funcionamento', '9 am–4 pm – Monday to Friday (school visits) | 9 am–4 pm – Saturdays, Sundays and public holidays (open to all)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 365, 'en', 'descricao', 'Route 1 - Fazenda Real de Santa Cruz: Before Petrópolis, the Imperial Family spent its holidays in Santa Cruz.
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 365, 'en', 'funcionamento', 'Advance booking with a registered guide is required');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 366, 'en', 'descricao', 'Rural Flavor at the Table: all-you-can-eat buffet of country food cooked on a wood-fired stove, just like typical farm cooking!
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 366, 'en', 'funcionamento', '7 am–6 pm – Saturdays, Sundays and public holidays | 7 am–12 pm – Breakfast | 11 am–4 pm – Lunch');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 367, 'en', 'descricao', 'Guided horseback rides, restaurant');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 367, 'en', 'funcionamento', 'Saturdays, Sundays and public holidays');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 368, 'en', 'descricao', 'Riding lessons for beginners');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 368, 'en', 'funcionamento', 'By appointment only');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 369, 'en', 'descricao', 'Get to know the places where agricultural produce is processed at an association, with a visit to the fields where the produce comes from. Experience the reality of a rural producer, always guided by a producer.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 369, 'en', 'funcionamento', 'Monday to Saturday, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 370, 'en', 'descricao', 'Connection with nature and visits to historical sites of the region, which was the stage for the passage of coffee from the Paraíba Valley during Brazil''s imperial period, and also for the Banana cycle in the 20th century. Departure from Sítio São João and walk to Cachoeira das Três Quedas, for swimming and contemplation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 370, 'en', 'funcionamento', '6 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 371, 'en', 'descricao', 'The Guarani preserve their ancestral traditions, such as dances and songs, and most are bilingual, since besides Tupi Guarani they also speak Portuguese. The residents lead a simple life, growing food such as cassava, banana and palm heart for their own sustenance, along with medicinal plants. Their colorful basketry, necklaces, bracelets and wooden crafts are much appreciated by tourists. When visiting the village you will be introduced to Guarani culture through activities such as cultural singing, body painting, conversation circles, traditional food, a guided tour and performances. For adventure lovers, there are also activities such as a guided trail to the beautiful Cachoeira da Aldeia, blowgun target shooting and archery.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 371, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 372, 'en', 'descricao', 'Birdwatching tour amid the Atlantic Forest and its scenic beauty.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 372, 'en', 'funcionamento', '6 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 373, 'en', 'descricao', 'Aiê Eletuloju: a door to the sacred in the Quilombo Santa Rita do Bracuí. Agroecosystem, immersive experiences, trails, talks, workshops, farm products, cultural activities, teaching on ethnobotany and ethnoecology, sustainable management practices. An agroecological hub focused on education, working around central axes such as Quilombo, Candomblé and the broad spectrum of permaculture.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 373, 'en', 'funcionamento', '7 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 374, 'en', 'descricao', 'A place to get to know native stingless bees, taste honey produced in the Atlantic Forest and learn about the importance of pollinators for forest health. Guided tour led by a professional with a university degree in beekeeping and meliponiculture (stingless beekeeping), opening of hives, tasting of honeys and orchard fruit. A meliponary licensed by the environmental authorities and open to visitors, ready to welcome tourists and offer a unique experience tasting the honeys of the native bees of the Costa Verde.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 374, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 375, 'en', 'descricao', 'Breakfast, lunch, camping. Starting at 8:30 am with a delicious breakfast until 10 am, followed by a walk to the wire bridge and waterfall at Sítio São João, returning at 12 pm for lunch!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 375, 'en', 'funcionamento', '8 am–7 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 376, 'en', 'descricao', 'Visit to the only distillery in the city - Cachaça Desinibida de Angra, with tasting, swimming pools, fish-and-pay fishing, a walk to a beautiful waterfall and a kids'' area. The distillery visit is a true immersion in cachaça production. The distillery is located inside Hotel Fazenda Vira Country, which offers fish-and-pay fishing, swimming pools, a kids'' area and a waterfall.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 376, 'en', 'funcionamento', '9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 377, 'en', 'descricao', 'Contemporary cuisine based on seafood, with beef and pork options as well as a variety of risottos. Mountain atmosphere, family-friendly setting and rustic décor, where guests can enjoy waterfalls and a natural pool with crystal-clear water, taking in nature and birdsong.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 377, 'en', 'funcionamento', 'Thursday to Sunday, 12 pm–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 378, 'en', 'descricao', 'The Quilombo Santa Rita do Bracuí has a beautiful history of struggle and tradition. Community-Based Tourism was the means the quilombolas used to share their history and earn an income. Options for tourists: spend a lovely day in the community, quilombola breakfast, trail, casual lodging, traditional meals, workshops, storytelling and other attractions. All activities are run by the quilombolas.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 378, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 379, 'en', 'descricao', 'Located across from the Janete Dias de Aguiar Tourist Terminal, the gateway to Vila do Abraão, the capital of Ilha Grande, the Republica Educação Solidária site houses a group of symbolic buildings meant to connect visitors with the community and help them recognize themselves in the space, giving new meaning to the visitor''s sense of belonging and territoriality. Our distinguishing feature is the Short Marketing Circuit, in which we offer the chance to meet the residents and buy directly from the producer, getting to know their space and helping to sell their versatile products and services. Visit duration: To uphold the principles of República Educação Solidária, there is no set average visit time, since the circuit can last from a few hours to a lifetime.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 379, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 380, 'en', 'descricao', 'Nativa da Ilha is a micro-enterprise created to be a tool for social impact in the Ilha Grande Bay region. Its mission is to support not only traditional communities, but also to help build an awareness of respect for and appreciation of popular culture, offering products and services that contribute to a new perspective and awareness that helps prevent traditional identities from being diluted. Our community-based tourism itineraries aim to promote fairer and more inclusive tourism, as they put the local population in the leading role in responding to the demands of local ecosystems and help generate income and autonomy for these rural populations.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 380, 'en', 'funcionamento', '9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 381, 'en', 'descricao', 'Visits to the rural properties of cooperative members and a look at the daily routine of family farmers, meals, farm breakfast, lake fishing, river swimming, and more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 381, 'en', 'funcionamento', '9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 382, 'en', 'descricao', 'Mini petting farm with plenty of attractions. Leisure area, games room and animals for the children. Minas Gerais-style restaurant. A space to rest after lunch, leisure area, walks around the farm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 382, 'en', 'funcionamento', 'Sundays from 11 am.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 383, 'en', 'descricao', 'Mini farm, horseback riding, mini zoo, lakes with fish, swimming pools, zip line, meals.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 383, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 384, 'en', 'descricao', 'Horseback riding, equine therapy, Mangalarga Marchador gait trials, mini petting farm, pick-your-own, café with coffee (under construction).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 384, 'en', 'funcionamento', 'Monday to Saturday, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 385, 'en', 'descricao', 'Restaurant amid nature with a historic trail and waterfall. Contact with nature in a rustic, welcoming setting with family-farm products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 385, 'en', 'funcionamento', 'Thursday to Sunday, 9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 386, 'en', 'descricao', 'A space devoted to sustainable practices: ecological trails, agroecological food production, sustainable management of the Juçara palm, and permaculture courses.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 386, 'en', 'funcionamento', '9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 387, 'en', 'descricao', 'The Mangaratiba Agroindustry processes local produce, making dried bananas, banana flour and a variety of sweets according to the local harvest. The building houses the Municipal Farmers'' Association, which is responsible for processing and selling the products. The site also has historical and cultural importance, as the building stands very close to the Ruins of Saco de Cima.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 387, 'en', 'funcionamento', '8 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 388, 'en', 'descricao', 'A historic farm from the coffee era of the former town of São João Marcos, also known as São João do Príncipe. It is located in the Serra do Piloto, on the Imperial Road of São João Marcos, the first carriage road in Brazil. The farm is open for visits and offers lodging, a restaurant and a thrift shop. It has horses, a chicken coop and dairy cattle, and produces artisanal cheese, organic bananas and a vegetable garden. The manor house is well preserved and has a period coffee-drying yard. There are trails through the Atlantic Forest, springs and a natural pool.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 388, 'en', 'funcionamento', 'Weekends, 11 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 389, 'en', 'descricao', 'A café with a cozy atmosphere, much-praised sausage bread and cornmeal cake, handicrafts and country products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 389, 'en', 'funcionamento', 'Friday to Sunday, 7 am–8 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 390, 'en', 'descricao', 'The tour includes a 4x4 ride, a historical guided tour of the sights along the route (with a Cadastur-accredited guide specialized in natural attractions), an ecological hike to the Ribeirão das Lajes Reservoir viewpoint and Ponte Bela, a snack kit, a waterfall swim, a wood-fired lunch (not included), and medical and hospital assistance insurance.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 390, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 391, 'en', 'descricao', 'An artisanal distillery with organic cachaça production, free-range hens producing eggs, a frog farm open to visitors for a hands-on experience, and an apiary producing mead.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 391, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 392, 'en', 'descricao', 'An artisanal distillery with guided visits and a shop offering a wide variety of handmade products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 392, 'en', 'funcionamento', '9:30 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 393, 'en', 'descricao', 'An artisanal distillery with a great view of the mountains and a shop selling local products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 393, 'en', 'funcionamento', '9:30 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 394, 'en', 'descricao', 'The oldest artisanal distillery still operating in the municipality, since 1803, with a shop selling local products at its headquarters. Guided tour of the distillery grounds, explaining the production process and telling the story of the oldest cachaça still in production in the municipality.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 394, 'en', 'funcionamento', '8 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 395, 'en', 'descricao', 'The only distillery in the municipality founded and run by a woman, who personally supervises every stage of production and gives the cachaça its name. An experience with a conversation circle led by the owner, who explains the stages of the production process and even the history of cachaça in the municipality of Paraty.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 395, 'en', 'funcionamento', '10 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 396, 'en', 'descricao', 'One of the most traditional distilleries in Paraty, run by the same family for decades and keeping its traditions alive. You can take a tour explaining the cachaça-making process and taste all the flavors in the shop.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 396, 'en', 'funcionamento', '7 am–12 pm and 1:30 pm–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 397, 'en', 'descricao', 'Guided tour telling the story of Engenho D''Ouro cachaça. The property has an old cassava flour house, a restaurant and a shop selling artisanal sweets, and the distillery sits next to the Tobogã waterfall.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 397, 'en', 'funcionamento', '8:30 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 398, 'en', 'descricao', 'A very well-organized travel agency with more than 28 years of experience.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 398, 'en', 'funcionamento', '8 am–9 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 399, 'en', 'descricao', 'An accredited travel agency with 12 years of experience in Paraty.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 399, 'en', 'funcionamento', '8 am–9 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 400, 'en', 'descricao', 'A travel agency focused on ecotourism, offering customized itineraries.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 400, 'en', 'funcionamento', '6 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 401, 'en', 'descricao', 'The families living in the Quilombo keep alive traditions such as Jongo and Capoeira, as well as stories and knowledge that trace back to the African continent. The tourism practiced there is community-based, and one of the main attractions is a beautiful waterfall, along with trails, ruins from the era of slavery, conversation circles and traditional cuisine, which visitors enjoy in a space built next to residents'' homes.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 401, 'en', 'funcionamento', '9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 402, 'en', 'descricao', 'Inn with spa and restaurant. Restaurant, leisure area with pool, game room, tennis court, sauna, reading lounge with hammocks, and a waterfall with a private natural pool within the inn''s grounds. A wellness area houses the inn''s spa, with massages, therapies, ofuro hot-tub baths and much more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 402, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 403, 'en', 'descricao', 'Community-based tourism celebrating the culture and identity of the traditional caiçara community of Trindade. Conversation circle with fishermen, a visit to the floating fish trap, a visit to the cassava flour house, puppet theater, a photo/video/documentary screening on the history of Trindade followed by a discussion, Folia de Reis, a crafts workshop, a net carving/sewing workshop, and more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 403, 'en', 'funcionamento', '9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 404, 'en', 'descricao', 'Activities include agroforestry work, birdwatching and visits to the waterfalls on the property.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 404, 'en', 'funcionamento', '7 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 405, 'en', 'descricao', 'Fazenda Bananal is an unmissable destination for rural tourism lovers, with 187 hectares open to visitors. Its highlight is sustainability, present in every respect: environmental, historical-cultural and social. The visit to Fazenda Bananal is personalized, allowing visitors to create their own itinerary. The first recommended stop is the Historic Manor House, listed by IPHAN, with its original structure preserved. Today the space is used for temporary exhibitions that tell the history and traditions of Paraty. The second stop is a route presenting models and technologies that use the strength and intelligence of nature to create cleaner, more sustainable production systems. During the tour you can see the agroforest, the organic vegetable garden, the green septic system, the biodigester and other good practices in our relationship with nature. The final tip is a visit to the restaurant, which serves delicious dishes that vary with the seasonality of the ingredients and prioritize local produce. The farm''s agroforest and garden supply the restaurant with more than 60 different products a year, grown without pesticides or chemical fertilizers. In short, Fazenda Bananal is an incredible place that combines development and sustainability, preserving historical and cultural heritage and promoting conscious tourism. If you want to learn more about sustainable practices, enjoy delicious organic meals and take a personalized tour, don''t miss Fazenda Bananal!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 405, 'en', 'funcionamento', 'Monday to Sunday, 10 am–5 pm. The restaurant requires advance reservations and is open from 12 pm to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 406, 'en', 'descricao', 'Produced at Fazenda Abadia, which has grown sugarcane for more than 100 years. Visitors will find true Cachaça-Art, produced in copper stills since 2015. To guarantee quality, the care starts with planting the sugarcane and extends to the harvest, which is done by hand. Another notable point is the sanitation of the factory, done with steam to clean the pipes and stainless-steel containers, eliminating bacterial infection. The fermentation of the cane juice uses selected yeasts free of harmful bacteria. Distillation strictly follows a process of separating the head, heart and tail fractions, using only the heart in production, resulting in an internationally acclaimed cachaça. The cachaça then rests in barrels of noble woods, ensuring better aroma, color and flavor in the final product. It was awarded in Brussels in 2017, where it received recognition from the International Taste & Quality Institute, earning the “Superior Taste Award” certificate.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 406, 'en', 'funcionamento', '7 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 407, 'en', 'descricao', 'Maker of the award-winning “Barra Velha” cachaças, Alambique do Leley is also where you will find excellent home-style food cooked on a wood-burning stove, handicrafts and a variety of regional sweets. Located on the Campos beach of Farol de São Thomé, specifically at Fazenda São Thomé, you will find the facilities for the artisanal production of these famous cachaças, which are recognized and certified by Brazil''s Ministry of Agriculture, Livestock and Supply. Aging takes place in Pernod Ricard oak barrels, which, together with the perfectionism of the producer Leley, ensures success by adding quality and refinement to the products. The aged white cachaça won a Gold medal at Expocachaça in Belo Horizonte. For the third consecutive year, “Barra Velha” cachaça ranked among the best in Brazil, which also earned international recognition.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 407, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 408, 'en', 'descricao', 'The Cavalhada is the highlight of the largest traditional religious festival in the Norte Fluminense region, the “Festa de Santo Amaro”, celebrated on January 15 in honor of the patron saint of the Baixada Campista. The Cavalhada is a tradition dating back to the Middle Ages, in which 24 horsemen divided into two groups, identified by the colors red and blue, stage a mock battle between Moors and Christians, showing off their skills and devotion.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 409, 'en', 'descricao', 'Located in the district of Santa Maria, Cachaça Soberana, produced by Mr. Taizinho, comes in a great variety of flavors, including the hard-to-find Jambu cachaça.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 409, 'en', 'funcionamento', 'Monday to Saturday, 7 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 410, 'en', 'descricao', 'Daily responsibilities and tasks can raise our stress levels, and to forget these routine worries there is no better remedy than nature. Relaxing in a natural pool formed by a waterfall, surrounded only by trees and mountains, to the sound of birdsong: this is the experience of those who visit Cachoeira do Baú, in the countryside of Cardoso Moreira. This is the right place for anyone who wants to refresh the soul in the icy waters of a waterfall, thinking of nothing but that unique moment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 411, 'en', 'descricao', 'With an authentic countryside feel, Sítio Trapiche offers visitors the perfect setting for a great family weekend. The property has two swimming pools, a covered barbecue area, table games, a bouncy castle and much more, all to help you relive the good moments of childhood. Those who get to know Sítio Trapiche experience unique moments that strengthen family bonds even further, with plenty of joy and fun.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 411, 'en', 'funcionamento', 'Wednesday to Sunday, 9 am–10 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 412, 'en', 'descricao', 'Unique handmade pieces representing the authentic art of Cardoso Moreira. The “Nós na Madeira” studio holds a large collection of cultural works by artists from the municipality of Cardoso Moreira, with pieces made from reforestation, reused and recycled wood, combining art and sustainability.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 412, 'en', 'funcionamento', 'Monday to Saturday, 8 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 413, 'en', 'descricao', 'Follow the artisanal cachaça production process, with sensory analysis and tasting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 413, 'en', 'funcionamento', 'Thursday to Sunday, 9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 414, 'en', 'descricao', 'A historic place belonging to a traditional family, with countless stories and riches for tourists to be enchanted by and discover. In 1883 the farm belonged to the Baron of Azeredo Coutinho, and on June 24 of that year it received a visit from Emperor Pedro II for lunch. The emperor was traveling from São Fidélis to Campos to inaugurate the city''s electric lighting that evening. In 1976, scenes from the first version of A escrava Isaura were filmed at Fazenda da Pedra.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 414, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 415, 'en', 'descricao', 'Close to the most beautiful waterfalls in the region, on the banks of the Colégio River, it offers contact with nature and a family-friendly atmosphere. It is also part of the cycling route.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 415, 'en', 'funcionamento', '24 hours');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 416, 'en', 'descricao', 'Visitors have the chance to see both the plantation and the production area of Casa de Farinha Amparo, a family-farming tradition. For 30 years they have produced a special cassava flour, considered the best in the region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 416, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 417, 'en', 'descricao', 'Made artisanally in copper stills, with natural fermentation and its own selected sugarcane field.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 417, 'en', 'funcionamento', '9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 418, 'en', 'descricao', 'The vineyard is already a family tradition and, besides producing delicious grapes that are sold around the region, welcomes visitors who can see the plantation. It is also a great option for students in the field to see the whole winegrowing process in practice. It also hosts June festivals, visits with tastings, and sales of its products. A family-friendly setting in direct contact with nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 418, 'en', 'funcionamento', '8 am–12 pm and 1 pm–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 419, 'en', 'descricao', 'The factory makes sweet cassava starch, sour cassava starch, tapioca starch, beiju and a cheese-bread mix. It also grows pink pepper and black pepper and manages eucalyptus.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 419, 'en', 'funcionamento', 'Tuesday to Friday, 5 am–9 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 420, 'en', 'descricao', 'A day-on-the-farm experience, with a variety of animals and tastings of artisanal products made on site.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 420, 'en', 'funcionamento', 'Wednesday to Sunday, 9 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 421, 'en', 'descricao', 'A variety of handicrafts made by local artisans.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 421, 'en', 'funcionamento', '8 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 422, 'en', 'descricao', 'Boat trip through the Gargaú Mangrove and along the Paraíba River coast. Service offered for more than 20 years.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 422, 'en', 'funcionamento', '7 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 423, 'en', 'descricao', 'Production of cascão guava paste in blocks and in straw-wrapped form. Everything is very artisanal.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 423, 'en', 'funcionamento', '8 am–4 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 424, 'en', 'descricao', 'A very pleasant spot, with a leisure area for adults and children, a pool, and delicious home-style food.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 424, 'en', 'funcionamento', '9:30 am–6 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 425, 'en', 'descricao', 'The Cavalgada dos Amigos is a cultural event in the form of a horseback ride, where riders of all ages, from children to seniors, who share a love of country life come together along the route. The event takes place every year in May and attracts visitors from several towns in the region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 425, 'en', 'funcionamento', '10 am–12 am');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 426, 'en', 'descricao', 'The property has 2,500 hens and produces 200 dozen eggs a day. Besides this activity, there is a vegetable garden and a coconut grove, where visitors can pick what they want to take home straight from the plant. Fresh eggs, coconut water and freshly harvested vegetables are sold on site. Visitors are welcomed by the owner, who tells the family''s story and how the farm that gave rise to the place began.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 426, 'en', 'funcionamento', '7 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 427, 'en', 'descricao', 'This family-run rural property has a mandala garden of assorted vegetables, offering an immersive experience for visitors, who can also tour the orchard and, depending on the time of year, pick oranges, tangerines and watermelons. You can get to know species such as the annatto tree and even collect fresh eggs in the small backyard chicken coop. At the end of the tour, a simple but typical country-style snack awaits, with hot boiled sweet potato and cassava, cornmeal cake, jams and juices from seasonal fruit, and freshly brewed coffee. Not to mention the hospitality of the owner, Manoel Toledo, who welcomes everyone with a generous smile. The harvested products can be bought by visitors, as can the others also sold on site. The afternoon snack is part of the experience and is included in the entrance fee.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 427, 'en', 'funcionamento', '9 am–5 pm');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 428, 'en', 'descricao', 'The ranch can accommodate 44 people, seated at tables for 8, 6 and 4, and operates for private events, with a set menu and by reservation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 428, 'en', 'funcionamento', 'Weekends');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 429, 'en', 'descricao', 'Flower growing and flower viewing.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 429, 'en', 'funcionamento', '9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 430, 'en', 'descricao', 'Hands-on experiences of the beer-brewing process, and tasting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 430, 'en', 'funcionamento', '9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 431, 'en', 'descricao', 'Leisure, fishing and gastronomy.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 431, 'en', 'funcionamento', 'Wednesday to Sunday, 10 am–7 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 432, 'en', 'descricao', 'Gastronomy. Tastings and wines. A wine cellar specializing in Brazilian wines, with labels tried and approved from hand-picked wineries.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 432, 'en', 'funcionamento', '6 pm–12 am.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 433, 'en', 'descricao', 'Planting, harvesting and contemplation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 433, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 434, 'en', 'descricao', 'Planting and harvesting food.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 434, 'en', 'funcionamento', '9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 435, 'en', 'descricao', 'Farm hotel, mini farm, recreation, cycle path, gastronomy, hiking trail and horseback riding.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 435, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 436, 'en', 'descricao', 'Interaction with agroecological crops and organic food produced on site.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 436, 'en', 'funcionamento', '7 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 437, 'en', 'descricao', 'Weaving. Handcrafted work. Visitors can operate the machines and make their own rug.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 437, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 438, 'en', 'descricao', 'Centuries-old farm, gastronomy, gin distillery, horseback riding, hiking trails, waterfall, music festivals, conventions and private events.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 438, 'en', 'funcionamento', '7 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 439, 'en', 'descricao', 'Restaurant specializing in fish, boat gatherings, kayaks and biking. Immersion in nature in the middle of the Paraíba River.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 439, 'en', 'funcionamento', 'Thursday to Sunday and public holidays, from 11 am.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 440, 'en', 'descricao', 'Native Atlantic Forest reserve, preserved by the farm''s owners. Cattle raising, fish farming, bromeliad, anthurium and orchid greenhouses, horseback and carriage rides, walks on exclusive trails, swimming and fishing in the ponds, watching the sunset with a picnic, planting and harvesting some food, visiting the vegetable garden and orchard, and feeding the animals.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 440, 'en', 'funcionamento', '8 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 441, 'en', 'descricao', 'Available for rent for events, retreats, parties, weddings and baptisms. It has a church, a colonial house, a waterfall, a swimming pool, horses, milking in the corral, trails, pig feeding, an old plough, an ox cart, and more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 441, 'en', 'funcionamento', 'From Friday 6 pm to Sunday 6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 442, 'en', 'descricao', 'Day use on an 18th-century farm, with period furniture, ecological trails, a registered climbing rock, refreshing showers, river bathing, horses for hire, full board, jams for sale, souvenir postcards, pesticide-free fruit, vegetables, eggs and milk, and items from the era of slavery.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 442, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 443, 'en', 'descricao', 'Horseback riding and equestrian show. Champion Pampa Marchador horses.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 443, 'en', 'funcionamento', '9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 444, 'en', 'descricao', 'Accommodation, breakfast, lunch, swimming pool, fishing and horseback riding.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 444, 'en', 'funcionamento', '9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 445, 'en', 'descricao', 'A two-hundred-year-old farm from the slavery era, inventoried by the Instituto Cidade Viva of Rio de Janeiro and the Federal University of Minas Gerais, where visitors will feel the atmosphere of a farm of the Coffee Barons. Now engaged in rural tourism, it offers visitors the Pampa horse carousel, meditation at Isabel Libertadora''s Wishing Pond, the avenue of imperial palms and the crossing of the footbridge, cow milking, a bamboo grove tunnel, a river beach, swimming in the dam, a stone lookout, a nursery and orchard, paintings by José Maria Vilarongo, the ruins of a drying yard, an aqueduct and a stone mill.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 445, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 446, 'en', 'descricao', 'A route visiting historic farms and attractions of the region. We are an agency and tour operator specializing in selling rural experience itineraries in Rio de Janeiro state to the travel trade.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 446, 'en', 'funcionamento', 'Monday to Friday, 9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 447, 'en', 'descricao', 'Distillery visit; if booked in advance, you can watch cachaça being made. You can also taste the cachaça from the different barrels. Our cachaça is produced in a traditional still, but with infrastructure comparable to agro-industrial systems.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 447, 'en', 'funcionamento', '9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 448, 'en', 'descricao', 'The distillery is open to visitors, and you can see the whole careful production process of Itajoana; for groups of 10 or more, a hearty lunch can be booked on site. Cachaça Itajoana, produced in the district of Bemposta, in the city of Três Rios, combines the warmth of the countryside with an extremely tasty cachaça. This premium spirit, launched in 2017, aims to offer cachaça lovers distinctive, high-quality blends. In 2020, Cachaça Itajoana won a gold medal at Expocachaça, in the Cachaça Blends category, with its black label (Balsam, Oak and Amburana blends).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 448, 'en', 'funcionamento', 'Monday to Sunday, by appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 449, 'en', 'descricao', 'The farm hotel offers experiences with animals and the chance to pick produce from its vegetable garden. It has a water-powered mill where corn is ground. In some of the hotel''s rooms, guests can enjoy a private outdoor wood-heated hot tub, in an exceptionally refined and cosy setting. By appointment, activities such as the Track Day are available, thanks to a partnership between the hotel and the RMattheis team (Stock Car and Rally dos Sertões), which runs its off-road track here.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 449, 'en', 'funcionamento', '24 hours, by reservation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 450, 'en', 'descricao', 'Fazenda da Paciência now offers a unique accommodation experience: to enjoy the property, guests must rent the whole farm, enjoying a unique and exclusive taste of country life. Gastronomy and the breeding of Arabian horses are the highlights of the place, which also has a small waterfall on the property for the exclusive use of visitors.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 450, 'en', 'funcionamento', 'By appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 451, 'en', 'descricao', 'The place is a true leisure complex with a distinctly rural character. It consists of an inn and a restaurant that share the name of the site: Pontal. It is a permanent preservation area of the Atlantic Forest, living in harmony with a variety of wild animals within the reserve, and also has the Cachaça Museum, hammock area, zip line, treetop adventure course and climbing. All this with an enchanting view of the meeting of the three rivers. The meeting of the three rivers (Piabanha, Paraibuna and Paraíba do Sul), the only triple delta in Latin America (a perfect triangle), takes place in a spacious spot for tourists who also enjoy extreme sports. Rafters run the rapids of the Paraibuna River on a course of about three hours that ends at the meeting of the rivers. The Paraibuna is considered one of the best rivers in Brazil for the sport, as it has a large volume of water and does not depend on rain for rafting, and its rapids are class 2 and 3, allowing the sport to be practised all year round.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 451, 'en', 'funcionamento', 'Accommodation, day use and meals by reservation and appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 452, 'en', 'descricao', 'Snacks, swimming pool, pay-and-fish pond, fun and a family-friendly atmosphere.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 452, 'en', 'funcionamento', 'Weekends, 10 am–7 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 453, 'en', 'descricao', 'Day use, fishing and restaurant.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 453, 'en', 'funcionamento', 'Weekends and public holidays. 9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 454, 'en', 'descricao', 'Discover how cachaça is made, from harvesting, milling, fermentation and distillation to ageing.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 454, 'en', 'funcionamento', '8 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 455, 'en', 'descricao', 'A pleasant, green setting where ornamental and fruit plants are grown, and where flower arrangements and much more are sold.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 455, 'en', 'funcionamento', 'Monday to Saturday, 7:30 am–5 pm. Sunday, 8:30–11 am.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 456, 'en', 'descricao', 'Experience tour of cachaça production, which has been going on for over 30 years. Visits by appointment. Access via dirt road.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 456, 'en', 'funcionamento', '12–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 457, 'en', 'descricao', 'Learn about the craft beer production process and get to know the raw materials.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 457, 'en', 'funcionamento', 'Tuesday, 5–11 pm. Friday, 7 pm–11:45 pm, and Saturday, 5 pm–midnight.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 458, 'en', 'descricao', 'Day use. Venue with swimming pools, a fish pond, waterfall, saunas and barbecue areas.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 458, 'en', 'funcionamento', 'Weekends and public holidays.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 459, 'en', 'descricao', 'Have you ever had the chance to see guava products being made by hand? No? Meet the Schott family and their homemade sweets, the guava plantation, the preparation of the fruit, the boiler and the product storage area. A small farm where the Schott family grows guavas and shows how the production process works. Access is via dirt road.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 459, 'en', 'funcionamento', 'By appointment only.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 460, 'en', 'descricao', 'Located 8 km from the centre of Bom Jardim, the farm is equipped to host a variety of events. An excellent option for relaxing, with facilities for get-togethers. A leisure area with a natural-water swimming pool, waterfall, football pitch and other activities.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 460, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 461, 'en', 'descricao', 'Camping Recanto da Siriema - A space dedicated to camping, with green area, lake and support facilities for those who want to enjoy this activity.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 461, 'en', 'funcionamento', 'Every day.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 462, 'en', 'descricao', 'Located in the district of Barra Alegre, Refúgio do Humaitá is a place offering a variety of experiences, from visiting the ornamental bird breeding facility to taking courses related to agro-industry.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 462, 'en', 'funcionamento', 'By appointment only.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 463, 'en', 'descricao', 'Set amid nature, in a cinematic landscape of 165,000 square metres, it offers direct contact with exotic and gentle animals. Accommodation in independent chalets, in a rustic style that blends with the rural atmosphere.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 463, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 464, 'en', 'descricao', 'Great for relaxing. The place is a simple, rustic but very cosy setting in the countryside. The leisure area has a swimming pool, a barbecue and a large lawn with swings and a treehouse for children.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 464, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 465, 'en', 'descricao', 'The property is surrounded by nature and also has an orchard with a variety of fruits such as mulberry, mango, guava, avocado, starfruit and banana. Room service plus breakfast. Use of the swimming pool and the other facilities on the grounds is included, as well as the barbecue and sauna.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 465, 'en', 'funcionamento', 'By appointment only.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 466, 'en', 'descricao', 'A lovely spot in the bucolic district of Bom Jardim. It offers irresistible treats: sweets, breads, cheeses and artisanal yoghurts that delight visitors'' palates.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 466, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 467, 'en', 'descricao', 'A beautiful farm, known for its coffee, milk, cheese and bolinho de chuva (sweet fried dough balls), which periodically opens its doors for an experience tour in which, through guided visits, visitors learn about country culture and the stages of coffee processing. From harvest to roasting, with a bit of history, culminating in a mini tasting tour of the different ways of preparing the drink. A chance to experience mountain harvesting. Live it on site, from the plantation to the final roast, enjoying incredible nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 467, 'en', 'funcionamento', 'Monday to Friday, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 468, 'en', 'descricao', 'Visit to the most significant sites for the production and processing of Anã de Porto Marinho rice; visits to the homes of family farmers; boat trip on the Paraíba do Sul River and ox-cart ride; on-site explanation of the history of the village and the municipality, as well as the community''s cultural traditions; sale of typical sweets and crafts; tasting of local cuisine, whose main attractions are Anã de Porto Marinho rice, a potential geographical indication, and fish.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 468, 'en', 'funcionamento', 'Weekends, from 10 am.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 469, 'en', 'descricao', 'Visit to the farm of Sister Zélia and Jerônimo, the couple declared Servants of God, the only married couple beatified and in the process of canonization. It is a historic site and a sanctuary.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 469, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 470, 'en', 'descricao', 'Fishing-inspired gastronomy, land trails, boat trips, sport fishing and crafts.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 470, 'en', 'funcionamento', '7 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 471, 'en', 'descricao', 'Contact with the work of the country people, with herbal medicine, medicinal plants, nursery, planting, knowledge and hospitality.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 471, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 472, 'en', 'descricao', 'Contact with nature, gastronomy, tree planting, hiking trails and horseback riding.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 472, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 473, 'en', 'descricao', 'Cheese tasting and a visit to the countryside.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 473, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 474, 'en', 'descricao', 'Gastronomy, history and an experience at a historic dairy. The history of the Relógio brand takes us back to the end of the 19th century, precisely 13 April 1871, the day Joaquim Simões de Araújo was born in Espinho, near Viseu, Portugal. In the vigour of his twenties, he joined three Portuguese friends and set out on an adventure to Brazil, dreaming of making a life under better conditions. Always driven by an entrepreneurial spirit, in 1912 he bought Fazenda João Dias and built a dairy there. With the railway station very close to the dairy, Joaquim shipped all the milk and butter by train to the larger cities. So the time the train passed set the pace of production. It is said that, in the middle of his work, he would repeat in his thick Portuguese accent: "Olha o relógio! Olha o relógio!" ("Mind the clock! Mind the clock!"), warning the employees of the right time for the train''s arrival. And so, in this atmosphere of work and poetry, the name Relógio was born for the products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 474, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 475, 'en', 'descricao', 'Fresh air, contact with wild animals, native trees, trails, seedling planting, local history, river bathing and camping.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 475, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 476, 'en', 'descricao', 'Contact with nature, wild animals, gastronomy, bike trails, waterfall swimming and plenty of history.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 476, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 477, 'en', 'descricao', 'Seedling planting and learning about plants.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 477, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 478, 'en', 'descricao', 'Horseback trail, caves and contact with nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 478, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 479, 'en', 'descricao', 'Cachaça tasting, history and contact with nature. Since 1923, Cachaça da Quinta has been produced at Fazenda da Quinta, in a valley near the Paraíba do Sul River, at an altitude of about two hundred and twenty metres. The property has soil, climate and microclimate ideal for growing sugarcane, for fermentation and for making the products. To this especially favourable terroir are added the rigorous quality standards in the making of Cachaça da Quinta. It is well worth visiting to see the whole production process. The property has soil and climate ideal for growing sugarcane, for fermentation and for making the products. It was the first Brazilian spirit to receive the Grand Gold Medal at the Concours Mondial de Bruxelles. In the National Ranking of the Cúpula da Cachaça (2022–2023 biennium), Cachaça da Quinta – Branca received the highest score among all competitors, in an unprecedented feat: a white cachaça surpassing the scores of cachaças from different woods, stored, aged, premium and extra premium.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 479, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 480, 'en', 'descricao', 'Contact with nature, waterfall swimming, gastronomy, local history and land trails.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 480, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 481, 'en', 'descricao', 'Gastronomy, culture, local literature, organic products, crafts, creative economy and family farming.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 481, 'en', 'funcionamento', 'Saturdays, 7 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 482, 'en', 'descricao', 'Contact with nature, gastronomy, and a chance to learn how rapadura (raw cane sugar) and molasses are made. Seedling planting, hiking trails, and swimming in the river.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 482, 'en', 'funcionamento', 'From 7 am to 6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 483, 'en', 'descricao', 'Handicrafts.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 483, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 484, 'en', 'descricao', 'The cooperative quickly stands out for the quality of its milk, cheese, requeijão (creamy spreadable cheese), and, above all, its butter.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 484, 'en', 'funcionamento', 'From 9 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 485, 'en', 'descricao', 'Talks, tastings, and honey sales. Keeping stingless bees is called meliponiculture and is aimed mainly at honey production.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 485, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 486, 'en', 'descricao', 'Visitors can discover Vinycios'' artistic collection, which gives his works a Renaissance feel, with scale and life-size sculptures.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 486, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 487, 'en', 'descricao', 'Cachaça Artesanal Rio do Meio began production in 2004. Rio do Meio cachaça, named after the Sítio where it is made, started out as a drink for personal consumption, for friends and fans of the spirit.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 487, 'en', 'funcionamento', 'From 9 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 488, 'en', 'descricao', 'The Exposition is an annual event (second half of July) aimed at promoting agribusiness, industry, and commerce in Cordeiro and the surrounding region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 488, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 489, 'en', 'descricao', 'Tour of the main house and of the cachaça and artisanal liqueur factory. Lunch, drinks, beers, appetizer platters, and à la carte meals. Sales of the farm''s own cachaça and artisanal liqueurs, and a bar.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 489, 'en', 'funcionamento', 'Monday to Friday by appointment. Weekends, 10 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 490, 'en', 'descricao', 'Capitão Bock''s bar brings together good food, a leisure area, and every style of craft beer in one place. A spacious, airy venue, ideal for spending quality time with family and friends.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 490, 'en', 'funcionamento', 'Weekends and holidays. 11 am–8 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 491, 'en', 'descricao', 'Sítio São Sebastião has a cachaça distillery and a whole space in harmony with nature. We also have our venda do barranco, a self-service pick-and-pay shop where you can find local products and seedlings of plants and fruit trees.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 491, 'en', 'funcionamento', 'Tuesday to Friday, 10 am–6 pm. Saturday, 8 am–6 pm. Sunday, 8 am–1 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 492, 'en', 'descricao', 'Space rental, waterfall swimming, bar, volleyball court, soccer field, fishing, sauna. A place of peace, connection with nature, and tranquility.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 492, 'en', 'funcionamento', 'From 9 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 493, 'en', 'descricao', 'The building itself is one of the few old mansions still standing in the town center. Inside, it tells part of the story of the railway that was part of the municipality''s founding and of great importance to the whole region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 493, 'en', 'funcionamento', 'Thursday to Saturday, 6 pm–2 am. Sunday from 12 noon.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 494, 'en', 'descricao', 'We open at 10 am for those who choose brunch, or from 12 noon for lunch, which can stretch into afternoon tea to the sound of an accordion.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 494, 'en', 'funcionamento', 'From 10:30 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 495, 'en', 'descricao', 'Tour of a century-old farm with its history, lunch cooked on a wood-fired stove, and sales of handicrafts and homemade sweets.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 495, 'en', 'funcionamento', 'From 10 am to 4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 496, 'en', 'descricao', 'Production of homemade products, home-cooked meals, and a rustic space for visitors.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 496, 'en', 'funcionamento', 'From 9 am to 6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 497, 'en', 'funcionamento', 'From 9 am to 6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 498, 'en', 'descricao', 'Mineral water springs and tours of them, a walk along the stone-paved yard and around the farm grounds.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 498, 'en', 'funcionamento', 'From 9 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 499, 'en', 'descricao', 'Production of dairy products, with tours and a café.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 499, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 500, 'en', 'descricao', 'Walk around the farm and workshops on making artisanal guava paste (goiabada) and banana paste (bananada).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 500, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 501, 'en', 'descricao', 'ATV tours along the rural circuit of Santa Maria Madalena. Along the Estrada do 17 route there is a stop at Fazenda Boa Fé for tasting artisanal cheeses, and a stop at the Auberge Valaissane hotel to learn about the agro-industries on the property.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 501, 'en', 'funcionamento', 'Every day.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 502, 'en', 'descricao', 'Souvenirs and decorative items featuring local handicrafts in general.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 502, 'en', 'funcionamento', 'Monday to Saturday, 9 am–6 pm. Sunday, 9 am–3 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 503, 'en', 'descricao', 'Country produce.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 503, 'en', 'funcionamento', 'Monday to Saturday, 7:30 am–7 pm. Sunday, 7:30 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 504, 'en', 'descricao', 'Auberge Valaisanne is more than a farm hotel; it is a refuge for carefree days. It has lakes for fishing, hiking trails, rapids, and visits to the plantations.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 504, 'en', 'funcionamento', 'From 9 am to 10 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 505, 'en', 'descricao', 'Souvenirs of Santa Maria Madalena made by the town''s craftspeople.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 505, 'en', 'funcionamento', 'Friday to Sunday, 8 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 506, 'en', 'descricao', 'Ground-handling services for sightseeing tours in the region, for example a Rural Jeep Tour.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 506, 'en', 'funcionamento', 'From 8 am to 4 pm. Online service.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 507, 'en', 'descricao', 'Tastings and sales of artisanal products made by the Association of Rural Women Producers of Ribeirão Santíssimo.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 507, 'en', 'funcionamento', 'Saturdays, 9 am–3 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 508, 'en', 'descricao', 'Homemade sweets, jellies, liqueurs, pickled peppers, caponatas, pickles, cachaças, cheese, handicrafts, and above all, typical country meals.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 508, 'en', 'funcionamento', 'From 8 am to 6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 509, 'en', 'descricao', 'On the way to Fazenda Boa Fé you travel along an old railway line, with passages and cuts through the rock and a bucolic, lush landscape. At our farm, you will learn about sustainability techniques, visit the cheese dairy and the tilapia farm. You can also taste the products, such as fresh cheeses and yogurts.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 509, 'en', 'funcionamento', 'Every day.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 510, 'en', 'descricao', 'This historic farm, part of a valuable stretch of the old Leopoldina railway line, delights visitors with its native forests, natural lookouts, and stunning landscapes. Built by English engineers in the 19th century, the three tunnels on the farm have great historical and cultural value. The property, founded around 1880, has an imposing main house, old coffee mills, a cornmeal mill, a sugarcane mill, and a small hydroelectric power plant. During the visit, guests can explore the chapel, the distillery, and the old stone-and-wood mill, as well as enjoy snacks, beers, and Santa Cruz cachaça, produced on site. The picturesque setting, with well-kept roads, offers visitors a unique experience in which they can feel the atmosphere of the colonial era, take beautiful photos, and enjoy the surrounding landscape.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 510, 'en', 'funcionamento', 'Weekends, 9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 511, 'en', 'descricao', 'A 19th-century property home to a premium cachaça distillery, a museum, and an impressive collection of more than 800 cachaça labels. Try the award-winning SINHÁ BRASIL, a cachaça produced under strict quality control, from growing the sugarcane to bottling. Explore the production process on monthly tours, where you can taste the different labels and enjoy an authentic lunch prepared on the farm. A unique tourist experience that will delight all your senses.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 511, 'en', 'funcionamento', 'From 9 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 512, 'en', 'descricao', 'ATV, off-road motorbike, and 4x4 tours. Trajano X Triunfo, Trajano X Sodrelândia and the Dam, Trajano X Sunset, Pedra da Torre trail, Carrapato trail, Pereirinha trail, Retiro trail.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 512, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 513, 'en', 'descricao', 'Vehicle rental and guided sightseeing tours. Rental of ATVs, off-road motorbikes, and buggies. Camping area and rooms, also offering meals (snacks).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 513, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 514, 'en', 'descricao', 'Rural Tourism and Gastronomy. Tour of a century-old farm of colonial architecture that is fully operational. We offer experiences in beef and dairy cattle farming, and in planting and harvesting guavas, sugarcane, vegetables, eucalyptus, and more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 514, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 515, 'en', 'descricao', 'Tour of the town''s old collection and of the historic 19th-century coffee-producing farm. The farm belonged to the traditional Moraes family, whose most prominent figure was Raul Veiga, who became governor of the state of Rio de Janeiro in the first half of the 20th century.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 515, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 516, 'en', 'descricao', 'Natural spring water source. Visit one of the best mineral water springs in the state.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 516, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 517, 'en', 'descricao', 'Horseback rides, sunset watching from a deck, with views of a paradise-like scenery of mountains and lush greenery.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 517, 'en', 'funcionamento', 'By appointment during the day.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 518, 'en', 'descricao', 'Typical music, modas de viola (traditional country songs), bonfires, horseback ride events, and sertanejo shows.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 518, 'en', 'funcionamento', 'By appointment only.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 519, 'en', 'descricao', 'All-you-can-eat home-style food cooked on a wood-fired stove in a family-friendly setting with outstanding service. Contact with animals raised at the ranch, a reference in Itaboraí and neighboring towns.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 519, 'en', 'funcionamento', 'Weekends, 11:30 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 520, 'en', 'descricao', 'Museum with various types of fossils, historical pieces, and a replica of the giant sloth. Connection with nature: lagoon, trails, wildlife watching.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 520, 'en', 'funcionamento', 'From 8 am to 8 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 521, 'en', 'descricao', 'Animal milking, pony and horse rides, a lake for sport fishing, little train rides around the property and surroundings, and sales of cheeses and jams made on the property, as well as fruit picked on the farm, such as banana, papaya, mango, siriguela, acerola, and orange, and various types of vegetables.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 521, 'en', 'funcionamento', 'By appointment only.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 522, 'en', 'descricao', 'Tour of the production area, with sales of ornamental plant and fruit tree seedlings. On-site sales are also possible.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 522, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 523, 'en', 'descricao', 'Rio Bonito is known for its wealth of banana plantations, and the Bananada Factory uses fruit from the region and from local farmers. Visitors can take part in and learn about the entire process, from raw material to packaging and eventual distribution, and can also taste the sweets made on site.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 523, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 524, 'en', 'descricao', 'The place offers corn-based products, unique in the region. The corn milkshake is the top seller, along with roasted corn, juices, sweets, and savory snacks made from corn.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 524, 'en', 'funcionamento', 'From 9 am to 8 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 525, 'en', 'descricao', 'Rustic setting surrounded by nature, fruit trees, a rural atmosphere, and meals cooked on a wood-fired stove. A space dedicated to an exhibition of antiques.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 525, 'en', 'funcionamento', 'Wednesday to Sunday, 11:30 am–3:30 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 526, 'en', 'descricao', 'Visitors will see how the decorative items are produced by the local craftswomen, with access to the looms, the fabrics, and the finished pieces. They can also enjoy a delicious breakfast or afternoon coffee in the Ecopolo garden, prepared by the team. For 20 years we have been making bags, accessories, and Home Line products using hand weaving, an ancient technique in which fabric results from interlacing threads through the warp (vertical threads on the loom) and the weft (horizontal threads). All the work is done by hand. New collection with exclusive pieces made from recycled material.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 526, 'en', 'funcionamento', 'Monday to Friday, 9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 527, 'en', 'descricao', 'Farm hotel with good accommodations and spacious rooms, pools for adults and children, multi-sport court, sauna, game room, bar, and restaurant. Contact with nature, bike rides, horseback rides, pedal boats.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 527, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 528, 'en', 'descricao', 'A great option for those seeking tranquility in the midst of nature. Lake with tambaqui and pacu for sport fishing, pool, grass soccer field, volleyball court, table football, vegetable garden outdoors, trails, and close to hang gliding ramps.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 528, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 529, 'en', 'descricao', 'Regional breakfast or afternoon coffee, with typical products from the countryside. The meal is served outdoors, amid a banana plantation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 529, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 530, 'en', 'descricao', 'Originally 500 ha of preserved and protected land and agricultural production. A working farm that offers eco-rural tourism on its grounds. It has a traditional main house and 5 apartments available for guests. Children are welcome. Activities include eco-walks, hands-on organic farming, tree planting, feeding the small animals, a visit to the orchid house, a swimming pool and sauna, a football field, volleyball, games and other fun.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 530, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 531, 'en', 'descricao', 'Family-friendly atmosphere, horseback rides, traditional country cooking, regional festivals, a swimming pool and the farm''s vegetable garden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 531, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 532, 'en', 'descricao', 'Rural lodging, alambique-distilled cachaça and ecotourism activities such as trekking, river swimming and the chance to go birdwatching.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 532, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 533, 'en', 'descricao', 'Organic farm where visitors can watch and learn about organic growing techniques and how dried bananas (banana passa) are made. They supply restaurants and organic produce boxes for families.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 533, 'en', 'funcionamento', 'Not specified.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 534, 'en', 'descricao', 'A commitment to living, natural food, respecting people, the environment, fair trade and good practices for healthy growing. All our food is naturally fertilized, with no chemical pesticides or agrochemicals.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 534, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 535, 'en', 'descricao', 'Farm hotel with horseback rides, a pay-to-fish pond, a swimming pool and trails surrounded by nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 535, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 536, 'en', 'descricao', 'The inn offers big-city comfort combined with rural tranquility. Swimming pool with swim-up bar, hot tub, steam sauna, games room, waterfalls, playground, pony rides for children, restaurant, convenience store and much more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 536, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 537, 'en', 'descricao', 'If you enjoy oranges and rural tourism, this is a must. Along the route, visitors can see an orange orchard, pick and taste the fruit, visit several farms and buy farm products and handicrafts, enjoying a pleasant day in the countryside. An established route running since 2010, seasonally (during the orange harvest), the Circuito da Laranja has already been visited by thousands of people, mainly from the metropolitan area of Rio de Janeiro. All groups are accompanied by a local guide, who shares information about the town''s history and facts, as well as guiding visitors through the stops. The Circuit offers an unforgettable rural experience, creating a bond between visitors and the countryside, and leaving everyone wanting to return and relive it.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 537, 'en', 'funcionamento', 'From 8 am to 4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 538, 'en', 'descricao', 'Contact with nature, trails and views of beautiful landscapes. A small farm set in the Serra do Barbosão.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 538, 'en', 'funcionamento', 'During business hours, Tuesday to Sunday; no advance booking required.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 539, 'en', 'descricao', 'Over its last 15 editions, the event has featured shows, games and talks for rural producers, the orange queen pageant, a best orange producer contest, a handicraft exhibition and stalls with typical rural food, celebrating the town''s rural culture and its residents. The Festa da Laranja has been part of the official events calendar of the municipality of Tanguá since 2002, under Law 352/02. It is a traditional event in the municipality, aimed at promoting and honoring its main agricultural product, the orange, thereby strengthening the town''s rural culture and traditions.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 539, 'en', 'funcionamento', 'Held in the second half of July. Usually a 3-day festival (Friday, Saturday and Sunday).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 540, 'en', 'descricao', 'Delicious breakfast or lunch served by advance booking. It is a house for up to 6 people, where visitors can enjoy all its facilities. At breakfast, sweets and jams made on the property from seasonal produce are served.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 540, 'en', 'funcionamento', 'Breakfast from 8 am to 10 am and lunch from 11:30 am to 2:30 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 541, 'en', 'descricao', 'The traditional Festa do Aipim, held every year on May 1st, has become a tourist and gastronomic attraction of the locality, with a variety of cassava-based products. During the festival, typical dishes made with cassava (aipim) are sold, such as bolinho (fritters), pizza, sola, biju, italiano, cassava with dried beef, tapioca, caldo verde, vaca atolada, cassava flour and sweet cassava cake. There are also assorted sweets, a variety of juices and a farmers'' market.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 541, 'en', 'funcionamento', 'From 10 am to 10 pm (on the day of the festival)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 542, 'en', 'descricao', 'You can rent a house in nature for a private group or rent the meeting space for company gatherings. Every detail of the space was carefully designed in harmony with nature: it inspires connection, engagement, appreciation and joy. In terms of hospitality, Sinal do Vale also works in gastronomy, using the Regenerative Cuisine method of food preparation. We use local ingredients, prioritizing vegetables, roots and fruits grown in our organic gardens and agroforests.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 542, 'en', 'funcionamento', 'Only by appointment for closed groups.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 543, 'en', 'descricao', 'Rancho Linda Vista is a rural fishing restaurant in Xerém, RJ. But it goes beyond a simple country restaurant. Here we serve a delicious breakfast and have a lake for pay-to-fish or sport fishing, a swimming pool and a playground for the little ones. There is also plenty of room for children to run and play. Our little farm is a delight, with a variety of animals for the children to meet. At the Rancho we also serve a delicious wood-fired lunch. Some of our dishes include tilapia steak, pork loin with collard greens and chicken with okra. And to finish the meal, you can enjoy a mouth-watering pudding baked in the wood-fired oven. After lunch, you can rest in one of the hammocks scattered around the Rancho while enjoying a coffee with a broa (cornmeal cake). Here you have everything you need to spend a delightful day and create fond memories with your children, grandchildren and friends.*');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 543, 'en', 'funcionamento', 'Friday to Sunday, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 544, 'en', 'descricao', 'Pay-to-fish pond, events, leisure (swimming pool) and accommodation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 544, 'en', 'funcionamento', 'Weekends and holidays, 7:30 am–5:30 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 545, 'en', 'descricao', 'Vaquejada park. The venue has swimming pools, a restaurant and event space. In 2022 it held the first vaquejada sanctioned by the ABVAQ in the Southeast, bringing in vaqueiros (cowboys) from many places.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 545, 'en', 'funcionamento', 'Weekends and holidays.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 546, 'en', 'descricao', 'Petting and feeding the animals, horseback riding, animal sales, photo opportunities.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 546, 'en', 'funcionamento', 'Saturdays, 10 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 547, 'en', 'descricao', 'Get to know Brazil''s native bees, taste the honey, and take beautiful photos that will be a hit on your social media.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 547, 'en', 'funcionamento', 'Wednesday to Sunday, 9 am–2 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 548, 'en', 'descricao', 'Organic vegetable growing, tilapia fish farming, fishing and river swimming (São Pedro River).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 548, 'en', 'funcionamento', 'Monday to Sunday.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 549, 'en', 'descricao', 'Leisure farm in a rural area, with a swimming pool and barbecue area, football field, fishing lake, lodging quarters, games room, day rentals for events and performances.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 549, 'en', 'funcionamento', 'Weekends and holidays.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 550, 'en', 'descricao', 'Sale of handmade products: cheese, cheese bread (pão de queijo), cheesecake, ricotta, cake, cookies and milk; organic products; sale of ornamental fish; and a hands-on experience of the production line of the handmade products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 550, 'en', 'funcionamento', 'Monday to Friday, 8 am–5 pm; weekends, 8 am–3 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 551, 'en', 'descricao', 'Food; visit to the agroforest with a clay bath; PANC (unconventional edible plants) handling course; sale of agroecological products, research area, camping area, catering services.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 551, 'en', 'funcionamento', 'Monday to Sunday.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 552, 'en', 'descricao', 'Pay-to-fish pond; horse riding course (book ahead); horseback rides; Delícias da Rosa restaurant; sale of handmade ceramics, homemade sweets and plants.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 552, 'en', 'funcionamento', 'Sundays, 9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 553, 'en', 'descricao', 'The experience awaiting visitors: a colonial-style breakfast at Chácara Vale dos Manacás-Tinguá-NI, with bread baked on site and served warm to visitors. During the colonial breakfast, guests can enjoy all the facilities of the Chácara (two swimming pools, kayak, hammocks, outdoor shower and more). That is the colonial breakfast. As for the Pedra Lisa Route, right after the Rural Breakfast we set off on a walk to Sítio Pedra Lisa, where we enjoy the natural beauty of this incredible remnant of the Atlantic Forest. Afterwards, we return to the Chácara, where we serve lunch. At Sítio Pedra Lisa, visitors will enjoy a 2.7 km walk through the Tinguá Municipal and Alto Iguaçu State Environmental Protection Areas. Along the way they will have views of the Serra do Mar mountain range and across Guanabara Bay. Once on the property, they will be led along Atlantic Forest trails, where they can swim in 2 crystal-clear, cascading rivers or simply admire the waterfalls, the lake, the Tinguaíto rock cave and the countless species of Atlantic Forest fauna and flora. For camping lovers, the farm offers rustic Wild Camping with bathroom facilities, running water, gas stove and refrigerator.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 553, 'en', 'funcionamento', 'Day Use Friday to Sunday and holidays, 8 am–5 pm (at the chácara only on event days)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 554, 'en', 'descricao', 'Visit to the distillery, the fruit plantations and the sugarcane field, and access to the deck with a panoramic view of the Serra do Vulcão, with the Caminho do Vulcão restaurant.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 554, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 555, 'en', 'descricao', 'A short introduction to cassava (aipim) growing (soil preparation, planting, upkeep and care, harvesting, processing), followed by a field experience demonstrating part of the necessary processes. Harvesting and preparing the dishes, and tasting, which depending on the program includes lunch or afternoon tea.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 555, 'en', 'funcionamento', 'From 10 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 556, 'en', 'descricao', 'The farm showcases agricultural and livestock activities, with plantations of various fruits, vegetables and greens and the raising of various animals. Production of cheeses and fruit preserves from seasonal fruit. The site is also used for events by cooperatives, partnerships and municipal schools.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 556, 'en', 'funcionamento', 'Day Use Friday to Sunday and holidays, 8 am–5 pm (at the chácara only on event days)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 557, 'en', 'descricao', 'Meet family farmers, organic producers and those transitioning to agroecology. Buy diverse, locally produced food.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 557, 'en', 'funcionamento', 'Wednesdays, 8 am–1 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 558, 'en', 'descricao', 'The Fazendinha Agroecológica do km 47 is a benchmark in organic and agroecological production in Brazil. It is a partnership between the Colégio Técnico da Universidade Rural (CTUR), Embrapa Agrobiologia, Pesagro-Rio and the Universidade Federal Rural do Rio de Janeiro (UFRRJ). The Fazendinha is the anchor of a series of technology-transfer and extension projects that enable the exchange of knowledge on the adoption and adaptation of technologies, products, processes and services. Courses, field days, lectures, visits and technical, scientific and educational meetings are held here for a wide range of audiences. During visits, groups experience both theory and practice, learning about education through agroecology, contact with the soil, biogeochemical cycles, organic fertilization, substrate production, sowing, horticulture, crop care and harvesting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 558, 'en', 'funcionamento', 'Weekdays, by pre-arranged appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 559, 'en', 'descricao', 'The Universidade Federal Rural do Rio de Janeiro (UFRRJ), specifically the neocolonial-style architectural complex of the Seropédica campus, listed by the Instituto Estadual do Patrimônio Cultural (Inepac), began construction in 1939. The extensive and beautiful landscaped park, designed by landscape architect Reynaldo Dierberger, was laid out at the same time, adding to the neocolonial pavilions gardens, artificial lakes, tree masses of native species, groves of palms, shrub clusters, ground cover, slopes and lawn beds. The main UFRRJ campus also plays a very important role in leisure, with sightseeing, walking, cycling and picnics in the areas near the existing lakes, as well as along the paved roads that cut through part of the main campus.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 559, 'en', 'funcionamento', 'Wednesdays, 8 am–1 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 560, 'en', 'descricao', 'A distillery and cachaça maker specializing in the artisanal production of liqueurs and gold, silver and blended cachaças, aged in stainless steel vats, oak barrels, Brazil nut wood and pink jequitibá wood. Its distinguishing features are pure, high-quality cachaça and, above all, alcoholic drinks flavored with jambu. It has a restaurant open for lunch on weekends. Free tasting of the cachaças and artisanal liqueurs produced on site, and sales of cachaças and liqueurs. At the restaurant, weekend lunches with regional food.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 560, 'en', 'funcionamento', 'Monday to Sunday, 8:30 am–5 pm. Restaurant: Friday to Sunday, from noon.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 561, 'en', 'descricao', 'A beautiful rural property that hosts events, most of them open to the public, in a relaxed setting with a pleasant atmosphere, animals and a kids'' area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 561, 'en', 'funcionamento', 'From 10 am to 7 pm (flexible on event days)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 562, 'en', 'descricao', 'Spacious setting in close contact with nature. Family-style service.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 562, 'en', 'funcionamento', 'From 9 am to 6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 563, 'en', 'descricao', 'A setting on the banks of the Paraíba do Sul River. Family boat rides. A spacious area with free-range chicken of unmatched flavor, plus appetizers.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 563, 'en', 'funcionamento', 'From 10 am to 10 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 564, 'en', 'descricao', 'Fish farm and pay-to-fish pond. A pleasant setting on the banks of the Paraíba do Sul River, where visitors can enjoy a meal.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 564, 'en', 'funcionamento', 'From 9 am to 6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 565, 'en', 'descricao', 'Artisan pizza made with homemade dough and baked on stone.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 565, 'en', 'funcionamento', 'Monday, Wednesday, Thursday and Sunday, 3 pm to midnight. Friday and Saturday, 3 pm to 2 am.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 566, 'en', 'descricao', 'High-quality free-range eggs. A place in the fresh air, with well-cared-for hens living with more freedom.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 566, 'en', 'funcionamento', 'From 8 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 567, 'en', 'descricao', 'Visit to the facilities, direct contact with nature, export-quality artisanal cachaça.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 567, 'en', 'funcionamento', 'Monday to Friday, 8–11:30 am and 1:30–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 568, 'en', 'descricao', 'Visitors can spend a relaxing day in contact with nature, enjoy a good meal and go fishing in a wonderful lake.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 568, 'en', 'funcionamento', 'Tuesday to Sunday, 8 am–7 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 569, 'en', 'descricao', 'Production and rooting during the harvest season. Service, artisanal cachaça and sales.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 569, 'en', 'funcionamento', 'Monday to Friday, 8 am–5 pm. Saturday, 8 am–noon.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 570, 'en', 'descricao', 'The place offers tourists the chance to swim in a beautiful waterfall, play football on a society (artificial turf) pitch and eat the best freshly made pastel (fried pastry) in the region. It has a large space for hosting events.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 570, 'en', 'funcionamento', 'Monday to Sunday, 7 am–9 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 571, 'en', 'descricao', 'Tourism in direct contact with nature, appreciation of local fauna and flora, and trails leading to waterfalls and rapids of the Itabapoana River.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 571, 'en', 'funcionamento', 'Saturday and Sunday, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 572, 'en', 'descricao', 'Direct contact with nature, lunch and sports events. Sustainability and social services.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 572, 'en', 'funcionamento', 'Restaurant: Saturday to Sunday, noon–4 pm; Pub: Friday, 6–10 pm; Saturday, 9 am–9 pm and Sunday, 9 am–5 pm; Lodging: Friday to Sunday, 24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 573, 'en', 'descricao', 'Reservoir fishing, a visit to the Pedra do Mutum de Baixo, declared a historical, cultural and tourist heritage site of the municipality, carriage rides, typical dishes (free-range chicken, steam-cooked ribs, etc.), among other things.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 573, 'en', 'funcionamento', 'Sunday to Monday, 7 am–8 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 574, 'en', 'descricao', 'The place offers direct contact with nature, fresh air and a beautiful landscape, perfect for peace, tranquility and rest. It has a restaurant serving typical dishes cooked on a wood-burning stove, and lodging in chalets. It has lakes with pedal boats, plus a waterfall for a refreshing swim. Perfect fun for the whole family!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 574, 'en', 'funcionamento', 'Monday to Friday, 24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 575, 'en', 'descricao', 'Fishing, a pleasant family-friendly, tree-shaded place with excellent service.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 575, 'en', 'funcionamento', 'Thursday to Sunday, 10 am–8 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 576, 'en', 'descricao', 'It offers lodging and a restaurant with a delicious buffet, providing much more than a simple lunch: a local gastronomic experience. A perfect place to breathe the fresh country air, overlooking the beautiful Itabapoana River. Nothing beats the peace that nature brings to this place!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 576, 'en', 'funcionamento', 'Restaurant: Saturday and Sunday, 9 am–6 pm. Lodging: every day, 24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 577, 'en', 'descricao', 'It offers cozy lodging, a welcome for guests in an intimate, family atmosphere, and a rural breakfast prepared with ingredients from the farm. Experience tourism with a corral next to the inn, where visitors can get close to the animals.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 577, 'en', 'funcionamento', 'The inn is open every day, but only by appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 578, 'en', 'descricao', 'A place to visit, view exhibitions and buy handmade products. The Casa do Artesão de Bom Jesus do Itabapoana is an income-generating alternative for the municipality, and includes the "Solidarity Economy" program.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 578, 'en', 'funcionamento', 'Monday to Friday, 9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 579, 'en', 'descricao', 'Visitors will learn about the stages of artisanal cachaça production, including milling and aging. They can also see how rapadura is made, another product that also comes from sugarcane.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 579, 'en', 'funcionamento', 'Weekends.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 580, 'en', 'descricao', 'Product tasting. Sustainable production, more flavor, more health on your table! Gastronomy and crafts. Black Ônix gourmet rice and red rice.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 580, 'en', 'funcionamento', 'Weekends.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 581, 'en', 'descricao', 'Small farm with a pay-to-fish pond, swimming pool and a spacious, tree-shaded kiosk.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 581, 'en', 'funcionamento', 'Weekends.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 582, 'en', 'descricao', 'Spacious venue with a wide choice of handicraft gifts.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 582, 'en', 'funcionamento', 'Monday to Friday, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 583, 'en', 'descricao', 'Learn how artisanal cachaça is made.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 583, 'en', 'funcionamento', '9 am–4 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 584, 'en', 'descricao', 'Horse breaking, horses for rides, exotic birds, dairy corral, pony, mini cattle and waterfowl.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 584, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 585, 'en', 'descricao', 'Professional production of free-range eggs.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 585, 'en', 'funcionamento', '4 pm–10 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 586, 'en', 'descricao', 'Follow the artisanal cachaça production process, with sensory analysis and tasting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 586, 'en', 'funcionamento', 'Thursday to Sunday, 9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 587, 'en', 'descricao', 'Family-farming cooperative, with visits to the production site and a shop selling regional products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 587, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 588, 'en', 'descricao', 'Gastronomy, wine cellar, rafting, trails, rural experience, contact with nature and live music.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 588, 'en', 'funcionamento', 'Every day.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 589, 'en', 'descricao', 'Rural tourism, enjoying the benefits of a hydromineral spa resort, contact with nature and shopping.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 589, 'en', 'funcionamento', 'Saturday and Sunday.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 590, 'en', 'descricao', 'We are the only farm in the region with artisanal production and a visitor area where you can see the whole process of making cheese, wine, cachaça, artisanal rapadura, brown sugar, yogurt and honey.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 590, 'en', 'funcionamento', 'Monday to Friday, 8 am–5 pm. Saturdays and Sundays, 8 am–12:30 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 591, 'en', 'descricao', 'With its springs in the heart of Raposo, the Estância Hidromineral Soledade has stood out over time for the high quality of its waters. Already famous for their healing power, they attract thousands of tourists every year. In addition, the Estância Hidromineral Soledade offers swimming pools with sulfurous and fluoridated waters, without the use of chemicals. Come and enjoy this wonder of nature!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 591, 'en', 'funcionamento', 'Monday to Friday, 7 am–11 am and 1 pm–5 pm. Saturdays and Sundays, 7 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 592, 'en', 'descricao', 'A place for leisure and tranquility. Tasting of various types of mineral water with proven medicinal benefits. The waters of Raposo have medicinal and beneficial properties found nowhere else in Brazil, thanks to the richness of mineral rocks in the subsoil and its exclusive geothermal area.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 592, 'en', 'funcionamento', '7 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 593, 'en', 'descricao', 'Fish farming and horseback riding.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 593, 'en', 'funcionamento', '7 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 594, 'en', 'descricao', 'Swimming pool, gym, wood-fired sauna, green area, barbecue kiosk, playgrounds, football field and a restaurant surrounded by plenty of greenery.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 594, 'en', 'funcionamento', '24 hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 595, 'en', 'descricao', 'The space brings together products and crafts by artists, artisans and rural producers in a single central location, easily accessible and with prices in line with today''s reality. Visitors also have the chance to discover products made in the municipality, enriching their cultural knowledge. It offers a variety of goods reflecting the cultural and tourist identity of the town, as well as delicious products from the countryside. Among the artisanal rural products available are: coffee, cheese, sausage, cachaça, honey, propolis, liqueurs, fruit in syrup, candied fruit and compotes, and jams in a variety of flavors. Also available are bed, table and bath decor, religious items (images, rosaries, banners and pennants), basketry, and products with personalized Miracema motifs.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 595, 'en', 'funcionamento', 'Monday to Friday, 8 am–5 pm. Saturday, 8 am–12 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 596, 'en', 'descricao', 'Horseback riding, pedal boats, traditional food cooked on a wood-fired stove, barbecue grill, outdoor shower and walks through forests, mountains and natural lagoons.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 596, 'en', 'funcionamento', 'Full day.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 597, 'en', 'descricao', 'Get to know and support local artists, artisans and handmade work in all its variety, with good service, courteous treatment of customers, and an airy, sanitized space that follows pandemic protocols. Goods are affordably priced and come in personalized packaging, ready for gifting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 597, 'en', 'funcionamento', 'Monday to Friday, 8 am–5 pm. Saturdays, 8 am–12 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 598, 'en', 'descricao', 'Visit to an artisanal cachaça production, with aging in oak, amburana and Brazil nut barrels, among others, and unlimited tasting. Sugarcane is planted and milled on the same property, which also has several ponds for fishing and a beautiful rural view.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 598, 'en', 'funcionamento', 'Business hours.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 599, 'en', 'descricao', 'Located very close to the Sanctuary of Nossa Senhora de Natividade, this open-air restaurant sits on a cozy small farm that uses produce grown and harvested on site to serve meals and snacks, all in a truly rural setting with room for the whole family.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 599, 'en', 'funcionamento', 'Friday to Sunday, 11 am–9 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 600, 'en', 'descricao', 'Visit to a property dating from 1834, on the banks of the São Sebastião stream. It is one of the properties that formed the foundation for the creation of the municipality of Natividade. Part of Fazenda do Engenho was turned into a housing development years ago, which gave rise to the Morada do Engenho neighborhood. This visit is a real escape from urban life and offers plenty of contact with nature.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 600, 'en', 'funcionamento', 'By appointment only.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 601, 'en', 'descricao', 'Lodging, breakfast and lunch, with all products grown and harvested on the property itself.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 601, 'en', 'funcionamento', 'Inn: 24 hours. Restaurant: 10:30 am–2 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 602, 'en', 'descricao', 'A variety of roasted coffees, specialty coffee, cakes and the house''s special banana sweet. Visit and experience the production process of specialty coffees, harvested at 900 meters above sea level. The visit goes from the field to the cup, passing through the machinery, bean sorting and drying, and ending with a delicious tasting. In 2019 the coffee was voted the second best Specialty Coffee in Rio de Janeiro. The site also offers a view of Pico da Bandeira, the highest point in Brazil''s Southeast Region, and a pay-to-fish pond, with the possibility of taking part in banana and coffee crop management.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 602, 'en', 'funcionamento', '8 am–12 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 603, 'en', 'descricao', 'Visit to the production of Café Iranita, 100% Arabica, a family-farming product grown on sustainable plantations at altitudes between 400 and 600 m. The property was founded in 1993 and is named Sítio Iranita, from the combination of the names Irany and Nita, parents of the owner, Olympio Matheus Ribeiro. From 2005, now under the leadership of Ana Regina and Suhail, investment went into coffee quality, from managing the crop to having the coffee ready for sale. Today the property has the right infrastructure to produce an excellent-quality coffee.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 603, 'en', 'funcionamento', 'Monday to Friday, 8 am–5 pm. Saturdays, 8 am–12 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 604, 'en', 'descricao', 'Rural restaurant, tour of the small farm, kids'' area, rental for parties and events.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 604, 'en', 'funcionamento', 'Flexible, by appointment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 605, 'en', 'descricao', 'Snack bar, kids'' area, rental for parties and events, and local farm products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 605, 'en', 'funcionamento', '4 pm–12 am.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 606, 'en', 'descricao', 'The space is meant for rest and quiet, offering a taste of country life. Our house takes us back to memories that are deeply stored and almost forgotten. It invites us to remember our childhood through games, play and adventures. Surrounded by beautiful trees that serve as a stage for the serenades of many species of birds, it leaves us closer to nature and yet very close to the city. We have a veranda that wraps around the whole house, full of inviting hammocks for a little nap after meals. When we think of the saying "Stressed out? Go fishing!", this is the right place! We have a majestic lake, full of life, where we can practice catch-and-release fishing.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 606, 'en', 'funcionamento', '9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 607, 'en', 'descricao', 'Visitors can see up close the making of handmade lamps crafted from recyclable materials such as glass bottles, bicycle rims, reclaimed wood and more. Our products are shipped to every region of the country, since sales are made mainly online.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 607, 'en', 'funcionamento', '9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 608, 'en', 'descricao', 'Healthy eating with rural, heartfelt cooking.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 608, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 609, 'en', 'descricao', 'Visit and product tasting.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 609, 'en', 'funcionamento', 'Every day, 6 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 610, 'en', 'descricao', 'Rural experience with a swimming pool, forested areas, a peaceful setting, contact with nature and easy access.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 610, 'en', 'funcionamento', '8 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 611, 'en', 'descricao', 'Presentation of the stages of the cachaça-making process (milling, fermentation and settling), a copper kettle for making rapadura and cane molasses, a shop selling the products made on site, and a large green area for taking photos. Artisanal cachaça production at the distillery and sale of bottled cachaça.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 611, 'en', 'funcionamento', '8 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 612, 'en', 'descricao', 'Learn about specialty coffee production. Trained, qualified professionals in their roles.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 612, 'en', 'funcionamento', '7 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 613, 'en', 'descricao', 'Fish farming, planting and milking. A completely original and diverse rural experience.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 613, 'en', 'funcionamento', '9 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 614, 'en', 'descricao', 'Offers a family-friendly rural setting, ideal for horseback rides and micro-tractor rides, with hiking trails as well as motocross in Serra Boa Vista, fishing in the local lake, and a typical Ubá-style morning coffee for all visitors. The place has a unique beauty, inviting for a dip and for admiring a waterfall during the rainy season; interested visitors can watch and/or take part in milking the cow. It is also a standout area in our municipality for protecting springs, sharing natural drinking water with the whole interested population, and it plants trees for environmental protection, its main distinguishing feature being environmental protection and awareness.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 614, 'en', 'funcionamento', 'Saturday and Sunday, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 615, 'en', 'descricao', 'The place has a simple kitchen. Appetizer platters, lunch, sweets and drinks. A place where contact with nature is essential. Sport fishing, exotic birds, a children''s area, a bar and a small restaurant in a family atmosphere. The place is inspiring. Nature, respect, tasty food and cold beer.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 615, 'en', 'funcionamento', 'Public holidays, Saturdays and Sundays, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 616, 'en', 'descricao', 'Dairy farming experience and a century-old colonial-style house.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 616, 'en', 'funcionamento', '8 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 617, 'en', 'descricao', 'Coffee production from Bean to Cup: we show the whole process of planting, post-harvest, soil, tasting and plenty of conversation. We are family farmers and produce specialty coffees in a 100% artisanal way.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 617, 'en', 'funcionamento', '8 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 618, 'en', 'descricao', 'Painting and craft classes, horseback riding, visit to the coffee and grape plantations.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 618, 'en', 'funcionamento', 'By appointment only.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 619, 'en', 'descricao', 'Run by Dona Conceição Bendia, it is the most rustic cellar among the city''s main jabuticaba wine producers, with more than 100 years of tradition. The wine''s alcohol content comes only from the fermentation of the fruit, following a family tradition of using no preservatives.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 619, 'en', 'funcionamento', '8 am–8 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 620, 'en', 'descricao', 'Tasting and purchase of various products made on the small farm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 620, 'en', 'funcionamento', '8 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 621, 'en', 'descricao', 'Not specified');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 621, 'en', 'funcionamento', 'Monday, 12 pm–6 pm. Tuesday, 9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 622, 'en', 'descricao', 'Visit the winery and see the production, with whole-juice processing and the making of wines, jams and liqueur, as well as plantations of various fruits such as jabuticaba, orange, pocan (mandarin), starfruit and more.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 622, 'en', 'funcionamento', '8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 623, 'en', 'descricao', 'Wines, liqueurs, handicrafts of all kinds, sweets, honey and jams. Visit to a small chapel and a calvary. Several pets on site.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 623, 'en', 'funcionamento', 'Saturday and Sunday, 8 am–5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 624, 'en', 'descricao', 'Visit to the production and preparation of specialty coffees. Café Pelegrini is grown on sustainable plantations by the Pelegrini Menezes Family and won 1st Place at Rio Coffee Nation in 2020.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 624, 'en', 'funcionamento', '9 am–6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 625, 'en', 'descricao', 'Visit to the storage cellar. Tasting of D''Chalet products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 625, 'en', 'funcionamento', 'Monday to Saturday, 8 am–6 pm. Sunday, 8 am–12 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 626, 'en', 'descricao', 'Get in touch with nature and with the making of handcrafted products.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 626, 'en', 'funcionamento', 'From 8 am to 6 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 627, 'en', 'descricao', 'Pizzeria with a stone oven, gourmet pizza and products from Fazenda Dendê (gourmet, traditional and specialty coffees (ground and beans), stone-ground flour from a water mill, honey, jam, dry jabuticaba wine and rosé wine made from Niágara Rosada grapes.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 627, 'en', 'funcionamento', 'Thursday to Sunday and on public holidays.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 628, 'en', 'descricao', 'Coffee grown in the northwest of the state of Rio de Janeiro, where a high-altitude tropical climate combined with the careful post-harvest handling of family farmers favors the production of specialty beans. From seed to cup! Visitors will get to know the family production of specialty coffees, grown and roasted by the Rodolphi family, who take care of every detail of production to ensure that the coffee reaches the cup with the quality the plant produced. Two-time champion producer of the first specialty coffee competition of the Northwest Fluminense region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 628, 'en', 'funcionamento', 'Monday to Friday, 8 am–5 pm, and Saturdays, 9 am–12 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 629, 'en', 'descricao', 'Property visits, tastings and sale of craft beer, jabuticaba wine and a variety of liqueurs.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 629, 'en', 'funcionamento', 'From 9 am to 5 pm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 630, 'en', 'descricao', 'Although it is considered a rural area, the pousada is a 5-minute drive from the center of Varre-Sai. You can also go on foot. Guests have the privilege of being in the countryside and yet within Varre-Sai, and can even visit a beautiful lavender plantation');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 630, 'en', 'funcionamento', '24 hours.');
