INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 6, 'fr', 'curto', 'Forêt et nature');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 7, 'fr', 'nome', 'Table et gîte à la campagne');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 7, 'fr', 'curto', 'Table et gîte');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 8, 'fr', 'nome', 'Culture, artisanat et fêtes');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 8, 'fr', 'curto', 'Culture et fêtes');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 9, 'fr', 'nome', 'Expériences à la campagne');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 9, 'fr', 'curto', 'Expériences à la campagne');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 10, 'fr', 'nome', 'Dégustation');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 10, 'fr', 'curto', 'Dégustation');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 11, 'fr', 'nome', 'Récolte');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 11, 'fr', 'curto', 'Récolte');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 12, 'fr', 'nome', 'Sentier / nature');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 12, 'fr', 'curto', 'Sentier / nature');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 13, 'fr', 'nome', 'Visite guidée');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 13, 'fr', 'curto', 'Visite guidée');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 14, 'fr', 'nome', 'Achat direct');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 14, 'fr', 'curto', 'Achat direct');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 15, 'fr', 'nome', 'Avec des enfants');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 15, 'fr', 'curto', 'Avec des enfants');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 16, 'fr', 'nome', 'Randonnée à cheval');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('termo', 16, 'fr', 'curto', 'Randonnée à cheval');
