INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 1, 'de', 'descricao', 'Die Pousada Vale do Café liegt im historischen Dorf Ipiabas in einem architektonischen Ensemble aus dem 19. Jahrhundert, umgeben von Natur und mit einem weitläufigen Garten. Sie bietet erholsame Tage im sanften Rhythmus des ländlichen Hinterlandes, wo die Zeit ohne Eile vergeht. Das Frühstück wird mit ausgewählten lokalen und hausgemachten Produkten serviert.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 1, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 2, 'de', 'descricao', 'Knüpft Partnerschaften und sorgt dafür, dass Touristen unser Reiseziel ins Herz schließen. Bietet die Möglichkeit, neue Erfahrungen zu machen, vor allem im ländlichen Raum.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 2, 'de', 'funcionamento', '8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 3, 'de', 'descricao', 'Wir möchten, dass unsere Gäste das Landleben in einer rustikalen, gemütlichen Umgebung genießen. Viel Platz für Wanderungen auf Pfaden und Landstraßen, Seen zum Angeln und ein Schwimmbad mit ständig erneuertem Wasser.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 3, 'de', 'funcionamento', 'Montag bis Samstag, 8.30–18 Uhr – Sonntag, 9–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 4, 'de', 'descricao', 'Ein einzigartiger Ort im Vale do Café, gelegen im historischen Dorf Piedade in Ipiabas (RJ) und 1874 erbaut. Über das Kunsthandwerksprojekt, an dem Kunsthandwerker aus dem Vale do Café teilnehmen, bietet es Produkte rund um die neoklassizistische Architektur sowie die historischen und kulturellen Themen der Region an. Es organisiert Touristenrouten und Stadtrundfahrten und veranstaltet Kulturevents, Märkte für Bioprodukte und Kunsthandwerksmärkte. Über den Espaço Vida e Arte würdigt es Künstler der Region, die ihre Arbeiten ausstellen möchten. Es verfügt über ein Café, in dem Produkte aus der Region im Vordergrund stehen, sowie über einen Bereich mit Antiquitäten und Sammlerstücken.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 4, 'de', 'funcionamento', 'Donnerstag bis Sonntag, 10–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 5, 'de', 'descricao', 'Wenn wir von Landschaftsgestaltung sprechen, denken wir meist an schöne Gärten und Plätze. Doch auch im ländlichen Raum macht eine gut geplante Landschaftsgestaltung ein Anwesen noch angenehmer und zieht dadurch mehr Besucher an.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 5, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 6, 'de', 'descricao', 'Empfangstourismus im gesamten Vale do Café, der ländlichen Tourismus mit Erlebnissen in den Bereichen Ökotourismus, Abenteuer, Geschichte und Kultur sowie Gastronomie verbindet. Wir schätzen die Besonderheiten und das Potenzial des Distrikts Ipiabas und seinen Bezug zu Umwelt und Nachhaltigkeit.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 6, 'de', 'funcionamento', '9–19 Uhr / Wochenende 7–21 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 7, 'de', 'descricao', 'Adventure Jeep Didu bietet Touren in Geländefahrzeugen (4x4) für bis zu 10 Personen an. Besuche historischer Farmen, kultureller Sehenswürdigkeiten und Ökoparks. Stadtrundfahrten, die den lokalen Handel in den Mittelpunkt stellen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 8, 'de', 'descricao', 'Eine historische Farm aus dem 19. Jahrhundert, die heute ein nachhaltiges Projekt zur Lebensmittelproduktion betreibt. Sie war in der Region Vale do Café Vorreiterin bei der Haltung von Bio-Wasserbüffeln und bei der Erzeugung von biologischem Spezialitätenkaffee, zertifiziert durch das IDB.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 8, 'de', 'funcionamento', 'Montag bis Samstag, 9–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 9, 'de', 'descricao', 'Bier-Tour – Erklärung, wie der Bierproduktionsprozess funktioniert.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 9, 'de', 'funcionamento', '9–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 10, 'de', 'descricao', 'Das fast zweihundert Jahre alte Herrenhaus, noch immer in perfektem Erhaltungszustand, bewahrt seine Geschichte mit Originalmöbeln und -porträts. Das Anwesen empfängt Besucher aus aller Welt und bietet ein köstliches Mittagessen oder ein Kolonial-Frühstück mit Produkten der Farm selbst. Außerdem gibt es eine Führung durch die Kaffeeplantage, die den gesamten Kaffeeprozess bis zur Aufbereitung zeigt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 11, 'de', 'descricao', 'Seit 1988 bietet das Haras Fire Notes verschiedene Aktivitäten an, darunter Reitunterricht, Springreiten, Tonnenrennen, Funktionstraining, Kurse und Ausritte, bei denen sich Freizeit mit Umweltbildung und nachhaltiger Entwicklung der Region verbindet. Besucher können die Natur von Ipiabas und ihre vielfältigen Attraktionen auf unterschiedlichen Reitrouten erleben (Pedra do Gavião, ein Wasserfall und zahlreiche Wanderwege).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 11, 'de', 'funcionamento', 'Dienstag bis Samstag, 8–17 Uhr / Sonntag, 8–12 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 12, 'de', 'descricao', 'Kolonial-Frühstück nach Voranmeldung, mit einer Führung, die die Geschichte der Farm erzählt.  Die Fazenda da Posse, das erste Bauwerk von Barra Mansa aus dem Jahr 1768, beherbergt heute ein Dokumentations- und Gedächtniszentrum, das den Bestimmungen des kommunalen Kulturplans und des Programms zur künstlerischen Nutzung öffentlicher Kultureinrichtungen unterliegt. Das von der Fundação de Cultura verwaltete CEDOC ist ein Ort für Forschung sowie für die Erstellung und Aufbewahrung von Dokumenten zur historischen, sozialen, politischen und kulturellen Welt von Barra Mansa und der Region. Es hat großen historisch-kulturellen Wert für die gesamte Region. Heute ist es ein Kulturzentrum.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 12, 'de', 'funcionamento', '8–12 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 13, 'de', 'descricao', 'Übernachtung, Ausritte und Kaffee auch für Gäste, die nicht dort übernachten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 13, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 14, 'de', 'descricao', 'Das neoklassizistische Gebäude wurde 1857 unter Kommandant Lucas Antônio Monteiro de Barros begonnen und 1865 unter Komtur Joaquim José Ferraz de Oliveira, dem Baron von Guapi, fertiggestellt. 1979 wurde es vom Staatlichen Institut für Kulturerbe (Inepac) unter Denkmalschutz gestellt. 1914 überließ der Stadtrat das Erdgeschoss, damit dort die Stadtverwaltung von Barra Mansa einziehen konnte, die 70 Jahre lang dort ihren Sitz hatte. Im Plenarsaal des Legislativorgans fallen die Stühle aus verziertem Leder, die Kristalllüster und eine Gemäldesammlung von bedeutendem historischem Wert auf. Heute beherbergt es die Stadtbibliothek. Der Plenarsaal und die Gemälde sind erhalten geblieben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 14, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 15, 'de', 'descricao', 'Rundgang durch die Destillerie mit Erläuterung des Produktionsprozesses und der Geschichte, dazu ein Verkostungsschluck der 3 Produkte. Amázzoni Gin wurde 2021 bei den World Gin Awards zum besten Gin der Welt gewählt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 15, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 16, 'de', 'descricao', 'In diesem Park leben 25 Faultiere frei zwischen den Bäumen und Wegen mitten in der Stadt. Der Parque Centenário, auch als Praça da Bandeira bekannt, ist ein Stadtpark, der von dem französischen Ingenieur und Landschaftsarchitekten Auguste François Marie Glaziou im Auftrag von Joaquim José Ferraz de Oliveira, dem Baron von Guapy und ersten Präsidenten des Stadtrats von Barra Mansa, entworfen wurde. Der in den 1870er-Jahren angelegte Park wurde 1991 vom Landschaftsarchitekten Burle Marx neu gestaltet. Er hieß früher „Jardim de Baixo“ (Unterer Garten), da es am Largo da Matriz einen „Jardim de Cima“ (Oberer Garten) gab; den Namen „Parque Centenário“ erhielt er 1922 zu Ehren des hundertjährigen Jubiläums der Unabhängigkeit Brasiliens. Einige Zeit später trug er den Namen Praça Feliciano Sodré, zu Ehren des damaligen Gouverneurs des Bundesstaates. 1932, im Jahr des hundertjährigen Bestehens von Barra Mansa, gab Bürgermeister Izimbardo Peixoto ihm durch ein städtisches Gesetz den Namen „Parque Centenário“ zurück. Unter dem Namen Jardim das Preguiças (Faultiergarten) bekannt, verdankt er seinen Beinamen den Faultieren, die in den alten, hohen Bäumen umherstreifen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 16, 'de', 'funcionamento', '8–20 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 17, 'de', 'descricao', 'Sorgfältig wiederaufgebaut, bewahrt sie die architektonischen Merkmale des späten 18. Jahrhunderts und wurde um 1717 errichtet. Die Fazenda Cachoeira widmete sich zunächst dem Zuckerrohranbau für die Herstellung von Zucker und Cachaça und ging später zum Kaffeeanbau über, dem großen Erzeugnis der Stadt während der Kaiserzeit. Die Cachaçaria Rochinha kann besichtigt werden, einschließlich Produktverkostung und Einblick in Phasen des Herstellungsprozesses – eine wahre Reise ins kaiserliche Brasilien, mit den Aromen und Düften des Landes.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 17, 'de', 'funcionamento', '10–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 18, 'de', 'descricao', 'Selbst ernten und bezahlen: Die Besucher suchen sich ihr Gemüse aus, ernten es und bezahlen. Für Touristen ist das eine abwechslungsreiche und angenehme Erfahrung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 19, 'de', 'descricao', 'Empfang mit Kolonial-Frühstück auf dem Gelände der Farm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 19, 'de', 'funcionamento', 'Nur nach Voranmeldung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 20, 'de', 'descricao', 'Ein schöner Wasserfall, Kontakt mit der Natur.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 20, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 21, 'de', 'descricao', 'Genau hier stellen die Kunsthandwerker ihre Stücke her und geben den Bewohnern des Distrikts Kunsthandwerkskurse. Erbaut 1981 von der Associação das Damas de Caridade de Amparo. Zu ihren Zielen gehören die Förderung handwerklicher Fähigkeiten und der erleichterte Zugang zum Absatzmarkt, dessen Erlöse den Kunsthandwerkerinnen zugutekommen, ähnlich wie bei einer Genossenschaft. Das Projekt stammt vom Ingenieur Luiz Roberto Correia Reche und zeigt eine Fassade mit Fensterrahmen im Kolonialstil, die die Atmosphäre des historischen Ortsbilds von Amparo bewahrt. Die hier gefertigten Patchwork-Decken sind berühmt, auch im Ausland bekannt und zu einem Markenzeichen von Amparo geworden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 22, 'de', 'descricao', 'Angelteich (Pay-to-fish), Restaurant, Schwimmbad, Ausritte und Modellflug. Viel Grün und Tiere.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 22, 'de', 'funcionamento', 'Sonntag, 8–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 23, 'de', 'descricao', 'Welches Erlebnis bietet der Ort? Seilrutsche, Fußballplatz, beheiztes Schwimmbad, See mit Tretbooten, kleiner Bauernhof (Kontakt mit Tieren), Mini Bugre, Kinderspielsaal, Schwimmbad Vale do Sol, Skibunda.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 23, 'de', 'funcionamento', '8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 24, 'de', 'descricao', 'Ausritte, Kutschfahrten, Tretboote, Seilrutsche über dem See, Sportangeln, geführte Wanderungen, Freizeitprogramm. Viel Kontakt mit der Natur, Erholung und Freizeitspaß!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 24, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 25, 'de', 'descricao', 'Neben dem Schloss selbst, das 1867 erbaut wurde und ein Kulturerbe der Gemeinde ist, liegt der Ort mitten im Atlantischen Regenwald mit üppiger Fauna und Flora.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 25, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 26, 'de', 'descricao', 'Ein wunderschönes Anwesen zwischen den Bergen des Atlantischen Regenwaldes mit Bademöglichkeit in Quellwasser. Wanderungen auf leichten und mittelschweren Pfaden, Waldbaden, Ökopsychologie, Beobachtungs-Fischzucht und Bio-Verpflegung sowie eigener Anbau von Shiitake-Pilzen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 26, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 27, 'de', 'descricao', 'Kontakt mit der üppigen Natur des Gartens, Musik-Labyrinth, 10 km Wanderwege, Fitnessparcours, atemberaubende Aussichten, Duschen, Fußbäder, Massagen, Kristallbaum, Glockenhaine, Netze und Hängematten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 27, 'de', 'funcionamento', '10–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 28, 'de', 'descricao', 'Übernachtung in komfortablen Zimmern mit Vollpension, Unterhaltung tagsüber und abends, Freizeitprogramm, Besuch von Obstgarten, Gemüsegarten und kleinem Bauernhof mit Tieren. Umfangreiche Freizeitanlagen mit Sportplätzen, Schwimmbädern, einem Wasserfall und einem schönen See für Wassersport und Angeln.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 28, 'de', 'funcionamento', '8 Uhr bis Mitternacht');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 29, 'de', 'descricao', 'Selbst ernten und bezahlen in einer Bio-Plantage mit Blattgemüse, Gemüse, PANC (unkonventionelle essbare Pflanzen) und Obst auf einem Familienbetrieb.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 29, 'de', 'funcionamento', 'Montag und Dienstag, 9–15 Uhr / Samstag, 8–11 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 30, 'de', 'descricao', 'Besuch eines biologischen Milchviehbetriebs mit praktischer Anleitung zur Käseherstellung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 30, 'de', 'funcionamento', 'Samstag, 8–12 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 31, 'de', 'descricao', 'Besuch einer Shiitake-Pilzzucht mit der Möglichkeit, bei der Ernte zuzusehen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 31, 'de', 'funcionamento', 'Dienstag, 8–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 32, 'de', 'descricao', 'Kontakt mit der lokalen Erzeugung: Obst und Gemüse, Milchprodukte, Konfitüren, Gewürze, Wurstwaren, Blumen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 32, 'de', 'funcionamento', 'Mittwoch bis Sonntag, 7–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 33, 'de', 'descricao', 'Brauereibesichtigung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 35, 'de', 'descricao', 'Führungen im ländlichen Tourismus und im Vale do Café.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 35, 'de', 'funcionamento', '10–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 36, 'de', 'descricao', 'Geführter Rundgang durch die Fabrik mit einer Präsentation zur Bean-to-Bar-Schokoladenherstellung (von der Kakaobohne bis zur Tafel) und angeleiteter Schokoladenverkostung; exklusive Karte mit gewürzter heißer Schokolade und Schokoladenfondue; Schokoladenladen für den Eigenbedarf und als Geschenk.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 36, 'de', 'funcionamento', 'Mittwoch bis Samstag, 10–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 37, 'de', 'descricao', 'Likörverkostung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 37, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 38, 'de', 'descricao', 'Besucher können hochwertige Produkte erwerben, hergestellt aus biologisch und hausgemacht angebauten Zutaten. Die Produkte sind im Espaço do Agricultor ausgestellt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 38, 'de', 'funcionamento', '7–15 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 39, 'de', 'descricao', 'Besuch einer handwerklichen Käserei mit Verkostung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 39, 'de', 'funcionamento', '8–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 40, 'de', 'descricao', 'Verkostung von Craft-Bier.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 40, 'de', 'funcionamento', '11–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 41, 'de', 'descricao', 'Verkostung des besten Craft-Biers im Vale do Café.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 41, 'de', 'funcionamento', 'Nur nach Voranmeldung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 42, 'de', 'descricao', 'Die Anlage verfügt über hochwertige Einrichtungen mit einem weitläufigen Gelände, mehreren Koppeln, 50 Boxen und fünf großzügigen Reitplätzen (zwei Sand- und drei Rasenplätze), alle in ausgezeichnetem Zustand, sowie eine Reithalle und Wege für Ausritte in der Natur.  Luiz Felipe de Azevedo hält zahlreiche Titel, darunter zwei olympische Bronzemedaillen (Atlanta und Sydney) und eine Goldmedaille bei den Panamerikanischen Spielen in Havanna (Kuba), außerdem den Titel des Amerikameisters und den Rekord im Mächtigkeitsspringen, aufgestellt 2001 in Rom (Italien) mit einem Sprung über 2,32 Meter.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 42, 'de', 'funcionamento', '8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 43, 'de', 'descricao', 'Die Besucher erleben, wie Kombucha hergestellt wird, ein probiotisches Getränk mit starker entgiftender Wirkung, von der Bakterienkultur bis zum fertigen Getränk. Aus den Kulturen werden auch weitere Produkte hergestellt, sowohl Lebensmittel als auch Kosmetika. Es ist ein unglaubliches Erlebnis.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 44, 'de', 'descricao', 'Gastronomie und Gartenbau');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 44, 'de', 'funcionamento', '8–23.30 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 45, 'de', 'descricao', 'Verkostung von Zuckerrohrbränden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 46, 'de', 'descricao', 'Verkostung von Zuckerrohrbränden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 47, 'de', 'descricao', 'Orchideenhaus, Ernte von Bio-Kaffee, Angeln und Agrotourismus.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 47, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 48, 'de', 'descricao', 'Verkostung von Zuckerrohrbränden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 48, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 49, 'de', 'descricao', 'Freizeitbereich und Sportangeln.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 49, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 50, 'de', 'descricao', 'Eine kurze Einführung in die Herstellung der Cachaça mit Besichtigung der Produktions- und Lagerbereiche. Zum Abschluss gibt es eine Verkostung der Cachaças.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 51, 'de', 'descricao', 'Verkostung lokaler Produkte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 51, 'de', 'funcionamento', '7–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 52, 'de', 'descricao', 'Besuch der Mini-Farm und des Bio-Gemüsegartens sowie ganzheitliche Erlebnisse.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 52, 'de', 'funcionamento', '7–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 53, 'de', 'descricao', 'Genießen Sie vom Aussichtspunkt den Blick auf einen Teil der Stadt; der Sonnenuntergang ist hier immer wunderschön.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 53, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 54, 'de', 'descricao', 'Ein ruhiger Ort, um die Natur zu bewundern, spazieren zu gehen, Rad oder zu Pferd zu fahren oder mit der Familie ein Picknick zu machen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 54, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 55, 'de', 'descricao', 'Verkostung von Süßspeisen, die im Kupferkessel auf dem Holzofen zubereitet werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 55, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 56, 'de', 'descricao', 'In der städtischen Baumschule kommen Sie über den Garten selbst mit der Natur in Berührung, lernen die Methoden der Wiederaufforstung und des Naturschutzes kennen und entdecken die verschiedenen einheimischen Baumarten, die dort gezogen werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 56, 'de', 'funcionamento', 'Montag bis Freitag, 8–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 57, 'de', 'descricao', 'Erleben Sie die Gewächshäuser vom Pflanzen bis zur Kultivierung, mit Karpfenteich, Naturbetrachtung und Sonnenuntergang sowie Mittagessen und Imbiss aus biologischen Produkten (nur nach Voranmeldung).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 57, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 58, 'de', 'descricao', 'Verkostung von Honig aus verschiedenen Blüten und Vorführung, wie der Honig geerntet wird.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 58, 'de', 'funcionamento', 'Montag bis Sonntag, 9–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 59, 'de', 'descricao', 'Lokale Küche und Gastronomie.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 59, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 60, 'de', 'descricao', 'Die Besucher können mit zahlreichen Tieren in Kontakt treten und ein echtes Landleben erleben: auf einem Pferd oder Pony reiten, eine Kuh melken, im Gemüsegarten Gemüse pflanzen und ernten, angeln und in einem hervorragenden Restaurant schlemmen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 60, 'de', 'funcionamento', 'Freitag, 10–18 Uhr; Samstag und Sonntag, 10–23 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 61, 'de', 'descricao', 'Lernen Sie den Anbau der Produkte und die Geschichte des geschützten Anbaus in Gewächshäusern kennen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 61, 'de', 'funcionamento', 'Montag bis Freitag, 9–15 Uhr; Samstag, 9–12 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 62, 'de', 'descricao', 'Das Cachaça-Museum ist das erste seiner Art im Land. Seine Gründer, Íris und Iale Renan (inzwischen verstorben), eröffneten das Museum 1991, nachdem sie jahrelang in Bibliotheken recherchiert und mehrere hundert Flaschen aus allen Winkeln Brasiliens gesammelt hatten, um diese umfangreiche und einzigartige Sammlung aufzubauen. Sie wird den Besuchern zusammen mit Gemälden, Sammlungen von Chroniken und Artikeln, Fachbüchern, Volksliedversen, einer alten Mini-Brennerei und vielen weiteren Attraktionen präsentiert, die die bedeutende Geschichte der Cachaça erzählen. Im Museum befinden sich außerdem eine handwerkliche Branntweinbrennerei, zwei Weinkeller und eine Bar mit kostenlosen Verkostungen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 62, 'de', 'funcionamento', 'Dienstag und Freitag, 9–18 Uhr; Samstag, 9–19 Uhr, bis Sonntag, 9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 63, 'de', 'descricao', 'À-la-carte-Restaurant mit brasilianischer und regionaler Küche sowie ein Feinkostladen mit lokalen Produkten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 63, 'de', 'funcionamento', 'Montag und Dienstag, 9–15 Uhr; Mittwoch und Donnerstag, 9–15 und 18–23 Uhr; Freitag bis Sonntag, 9–23 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 64, 'de', 'descricao', 'Besichtigung des Ortes, an dem die Fazenda São José dos Pinheiros stand, ein Anwesen von 1851 und ein Meilenstein des Kaffeezyklus im Paraíba-Tal.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 64, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 65, 'de', 'descricao', 'Ein Kulturraum, in dem der Laden der Kunsthandwerker der Stadt untergebracht ist, mit vielfältigen Produkten zum Verkauf an die Gemeinde und an Besucher.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 65, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 66, 'de', 'descricao', 'Ein Kulturzentrum (Ponto de Cultura), das Aktivitäten in Schulen entwickelt, Besucher empfängt und andere Gruppen der Volkskultur der Region vernetzt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 66, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 67, 'de', 'descricao', 'Ein Besuch in der Kolonialvergangenheit mit Zugang zum Herrenhaus, das bald 200 Jahre alt wird. Besichtigung der Senzala (Sklavenunterkunft), die noch Merkmale der Sklavereizeit wie Verliese und den Pranger bewahrt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 67, 'de', 'funcionamento', '8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 68, 'de', 'descricao', 'Agrarökologie, bäuerliche Familienlandwirtschaft und nachhaltige Lebensmittelproduktion. Kleine Haltung von Rindern, Hühnern und Enten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 68, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 69, 'de', 'descricao', 'Haltung von Freilandhühnern (Eierproduktion), Zierpflanzen, Kakteen, Sukkulenten, Gartenarbeit, Workshop zum Kompostieren zu Hause, Gemüsegarten und Herstellung von Wurmhumus.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 69, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 70, 'de', 'descricao', 'Hausgemachte Maniokprodukte (Tapiokastärke, Maniokstärke und Maniokmehl) und ökologischer Landbau.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 70, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 71, 'de', 'descricao', 'Angelteich (Pesque-pague), Restaurant, Öko-Wanderungen, Tretboote, Schwimmbecken, Fußballplatz und Spielplatz. An den Wochenenden gibt es Musikveranstaltungen. Inklusiver Tourismus für Senioren und Menschen mit Behinderung. Naturerlebnis in familiärer Atmosphäre mit der Möglichkeit zum Übernachten am Wochenende sowie zur Miete von Picknickflächen, Grillplätzen und für Veranstaltungen auf dem Land.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 71, 'de', 'funcionamento', 'Dienstag bis Freitag, 8–16 Uhr; Samstag und Sonntag, 8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 72, 'de', 'descricao', 'Ein weitläufiges ländliches Gelände von mehr als 1 Million Quadratmetern mit Weiden, Viehhaltung, Seen, viel Grün und reiner Luft, mit Herstellung von Milchprodukten und hausgemachten Süßspeisen – und nicht zu vergessen der unbeschreibliche Blick auf Sonnenaufgang und Sonnenuntergang. Außerdem gibt es einen See, der sich ideal zum Sportangeln und für Wasseraktivitäten eignet und einzigartige Erlebnisse mit echtem Landleben bietet. Ein idealer Ort für Sport, Spaziergänge, Joggen, Radtouren, Ausritte, Offroad-Wege, Mountainbiking und jede andere Aktivität im Freien.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 73, 'de', 'descricao', 'Der 1966 von Hobbyanglern und Mitarbeitern der Light gegründete Angelclub von Piraí spielte eine große Rolle für den Umweltschutz am Stausee Ribeirão das Lajes und in seiner Umgebung. In Zusammenarbeit mit Light führte er Kampagnen zum Wiederbesatz mit Fischen durch und dient als Stützpunkt für verschiedene Aktivitäten der Marine und des Heeres.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 74, 'de', 'descricao', 'Jedes echte Landleben hat viele Tiere. Auf der Mini-Farm (Mini Fazendinha) können Ihre Kinder unseren Tierchen ganz nah kommen und mit ihnen auf eine Weise umgehen, die in den Großstädten des Landes heute kaum noch möglich ist. Der Besuch der Mini Fazendinha ist außerdem eine Gelegenheit für Ihr Kind, einzigartige Erfahrungen zu sammeln. Die Kinder dürfen die Kühe melken oder die vielen Kaninchen von Coelhândia füttern. Die Kleinen können auch mit Hühnern, Entenküken und vielem mehr in Kontakt kommen. Die Mini Fazendinha beherbergt außerdem weitere sehr noble Bewohner, wie Die Drei Schweinchen und die Büffel Bull und Bill. Die beiden Stars der Farm sind die Maskottchen Bob Panga und das Kühlein Lili, die Lieblinge der Kinder. Ein weiterer Pflichtstopp dieses Rundgangs, der Klein und Groß gefällt, ist der Boi Bandido (Bandit-Stier). Dort geht es darum, ein Foto vom wildesten Tier der Farm zu machen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 75, 'de', 'descricao', 'Ein Ort, der die Arbeiten lokaler Kunsthandwerker zeigt. Hier lassen sich Produkte kennenlernen und erwerben, die die Kultur der Stadt widerspiegeln.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 75, 'de', 'funcionamento', 'Montag bis Freitag, 9–15 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 76, 'de', 'descricao', 'Tribeca ist ein Unternehmen, das in allen Stufen der Wertschöpfungskette der Macadamia tätig ist: Anzucht von Setzlingen, fachliche Beratung für Einsteiger im Anbau, technische Betreuung der Partnererzeuger, Ankauf von Nüssen, Verarbeitung der Nüsse und Vermarktung der Kerne auf dem Inlands- und Auslandsmarkt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 77, 'de', 'descricao', 'Das Hotel Fazenda Cascatinha liegt in einer wunderschönen Landschaft, umgeben von Grün und viel Platz, auf einer echten, einladenden Farm mit komfortabler Infrastruktur für Sie und Ihre Familie. Ein idealer Ort für alle, die Gastfreundschaft, Freizeit, Spaß und Entspannung suchen, dazu die Ruhe und Sicherheit einer idyllischen ländlichen Umgebung. Ein guter Ort, um etwas für die seelische Gesundheit zu tun.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 77, 'de', 'funcionamento', 'Montag bis Freitag, 9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 78, 'de', 'descricao', 'Besichtigung der Herstellung handwerklich gereifter Cachaças und Kennenlernen weiterer bekannter Produkte des Hauses wie der Cachaça Gabriela Cravo e Canela sowie anderer Geschmacksrichtungen wie Banane, Kokosnuss, Zuckermais und Erdbeere.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 79, 'de', 'descricao', 'Ein 120 m² großer Pool inmitten eines Rasens von mehr als 5.000 m² in einem von Atlantischem Regenwald (Mata Atlântica) umgebenen Tal mit unzähligen Obstbäumen und Vögeln; ein See zum Rudern, allein oder mit der liebsten Begleitung; Ausritte auf einem Campolina über grüne Hügel mit Blick auf riesige Weiden, auf denen Tiere in völligem Einklang mit der Natur leben; im Corral eine Holsteinkuh melken; und auf einem Pfad wandern und dabei die wirklich reine Luft eines geschützten Waldes atmen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 80, 'de', 'descricao', 'Touristische Transportdienste.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 80, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 81, 'de', 'descricao', 'Ländliche Unterkunft und Gastronomie im Sertão da Prata in Rio Claro.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 81, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 82, 'de', 'descricao', 'Für Touristen und Arbeiter.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 82, 'de', 'funcionamento', '7–22 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 83, 'de', 'descricao', 'Kontakt mit der Natur, Einblick in die Agroforstwirtschaft, Verständnis nachhaltiger Konzepte, natürliche Geflügelhaltung und Ernte biologischer Agroforstprodukte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 83, 'de', 'funcionamento', 'Dienstag bis Freitag');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 84, 'de', 'descricao', 'Im Park genießen die Besucher Komfort und Sicherheit bei einem Erlebnis für alle Sinne: die Landschaften der Mata Atlântica und von Ribeirão das Lajes bewundern, dem Vogelgesang lauschen und am Kiosk Leckereien probieren, die aus dem Rezeptbuch von Dona Cidinha, einer ehemaligen Bewohnerin, wiederentdeckt wurden. Der Eintritt ist frei, ebenso alle Aktivitäten. Auf dem Besichtigungsrundgang sind die Ruinen der Hauptkirche und des Hauses des Capitão-mor, ein Gedächtniszentrum mit Modell und Ausstellung, ein Amphitheater und ein Fußballplatz die Höhepunkte. Außerdem gibt es eine Vogelbeobachtungsstation, den Raum der Kreativen Energie, einen Bio-Gemüsegarten, eine Baumschule, einen Aussichtspunkt, den Leseraum Fagundes Varela, einen Sinnesgarten sowie einen barrierefreien Parkplatz und barrierefreie Toiletten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 84, 'de', 'funcionamento', 'Mittwoch bis Freitag, 10–16 Uhr / Samstag und Sonntag, 9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 85, 'de', 'descricao', 'Verkostung gereifter Cachaças.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 85, 'de', 'funcionamento', 'Mittwoch bis Sonntag, 9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 86, 'de', 'descricao', 'Auf 4,5 km gepflegten Wanderwegen im Wald mit landschaftlichen Attraktionen wie einer Grotte, einem Wasserfall und schönen Ausblicken betritt der Besucher den Wald, hört das Trillern der Vögel und spürt die frische Luft in einer Umgebung ohne Menschenmassen. So kann er sich von der Stadt und den Alltagssorgen lösen und neue Kraft für die nächste Etappe tanken.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 86, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 87, 'de', 'descricao', 'Öko-Ausflug, Mittagessen, Frühstück, Geschichtenerzählen, Wasserfall und Wanderweg.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 87, 'de', 'funcionamento', 'Tagsüber');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 88, 'de', 'descricao', 'Fungiert als lokaler Reiseveranstalter und verkauft Pauschalreisen mit Schwerpunkt Ökotourismus in Gebieten der Mata Atlântica, den Wasserreichtum der Region (Flüsse, Bäche und Wasserfälle), Touren im Geländewagen (4x4) oder mit dem Fahrrad oder zu historischen Stätten wie der Fazenda da Grama, Bergsteigen sowie Unterkünfte in Landhäusern (chácaras), kleinen Höfen (sítios) und Pousadas. Bietet außerdem geführte Besuche in Molkereien und landwirtschaftlichen Betrieben der Gemeinde an.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 88, 'de', 'funcionamento', 'Montag bis Freitag, 8–17.30 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 89, 'de', 'descricao', 'Wir sind eine familiengeführte ländliche Pousada: Erleben Sie das Leben auf dem Land, den Kontakt mit Natur und Tieren und die Ernte der Zutaten für Ihre eigene Mahlzeit.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 89, 'de', 'funcionamento', 'Montag bis Freitag');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 90, 'de', 'descricao', 'Alle Produkte werden aus Büffelmilch handwerklich hergestellt und sind staatlich zertifiziert.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 90, 'de', 'funcionamento', 'Nach Absprache mit dem Eigentümer.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 91, 'de', 'descricao', 'Meditationsplätze, ätherische Öle, handgemachte Liköre, Bambuslampen, Waschplatz, Aussichtspunkt und Hängemattenbereich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 91, 'de', 'funcionamento', 'Samstag und Sonntag, 8–10 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 92, 'de', 'descricao', 'Mehr als hundertvierzig Hektar Natur bilden ein einzigartiges, geschichtsträchtiges Tal. Atemberaubende Landschaften lassen sich genießen, während man den Duft der Blumen in den Gärten des Anwesens einatmet, was den Besuchern neue Energie schenkt. Ausritte oder Quad-Touren, die Mini-Kuh melken, Reiten in der Sandbucht, ein Foto mit den freundlichen und fotogenen Schäfchen oder mit den Pfauen Custódio und Bernardino, nicht zu vergessen das Maskottchen, die kleine Eselin Ana-Bella, außerdem die Hühner füttern und im See angeln. Wer einfach nur die Natur genießen möchte, kann dem Vogelgesang lauschen, auf den Wegen der Farm spazieren gehen oder sogar ein Nickerchen in den Hängematten halten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 92, 'de', 'funcionamento', '8–10 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 93, 'de', 'descricao', 'Im schönen Gebäude des ehemaligen Bahnhofs können Besucher von den Kunsthandwerkern etwas über die Geschichte der Region erfahren und lokales Kunsthandwerk erwerben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 93, 'de', 'funcionamento', '9.30–17.30 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 94, 'de', 'descricao', 'Beim Besuch dieses Familienbetriebs, der handwerkliche Cachaça herstellt, lernt der Besucher den Produktionsprozess kennen, der hohen Standards an Sauberkeit und Organisation entspricht und modernste Ausrüstung nutzt, dabei aber die handwerkliche Herstellungsweise bewahrt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 94, 'de', 'funcionamento', '8–10 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 95, 'de', 'descricao', 'Verkauf von lokalem Kunsthandwerk.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 95, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 96, 'de', 'descricao', 'Eine handwerklich hergestellte Cachaça mit Qualitätsstandards, die denen der besten Destillate der Welt entsprechen, produziert vom Ehepaar Cilene und Eli Werneck. Besucher können jede Phase des Prozesses im Detail kennenlernen, denn Eli führt Tabellen für alle Produktionsschritte mit lückenloser Rückverfolgbarkeit. Anhand des Chargenetiketts einer Flasche lässt sich feststellen, aus welchem Bereich des Zuckerrohrfelds das Rohr stammt und an welchem Tag oder in welchem Zeitraum es geschnitten und gemahlen wurde. Dadurch war er der erste Erzeuger im Bundesstaat Rio de Janeiro, der die INMETRO-Zertifizierung für Qualität und Nachhaltigkeit erhielt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 97, 'de', 'descricao', 'Ein Raum für Familien, in dem Touristen reiten, Fußball spielen und die Miniaturtiere kennenlernen können.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 98, 'de', 'descricao', 'Ein wunderschönes, sehr gut erhaltenes historisches Landgut aus dem 19. Jahrhundert, sogar mit Möbeln aus der Zeit. Das Herrenhaus hat 99 Fenster und mehr als 2.000 Quadratmeter Bebauung. Die Eigentümer wohnen vor Ort und führen die Besichtigung selbst durch, die auch an der alten Kaffeeaufbereitungsanlage vorbeiführt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 99, 'de', 'descricao', 'Historische Führung durch das Herrenhaus und die Gärten, bei der wir die gesamte Geschichte des Landguts vom Kaffeezyklus bis heute erzählen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 99, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 100, 'de', 'descricao', 'Das Hotel Fazenda Vilarejo bietet einen Streichelzoo mit echten Tieren, einen Biogemüsegarten, Tretboote auf dem See, einen Angelteich, Ausritte und Radtouren, eine große Grünfläche mit Freizeitangeboten für alle Altersgruppen, das ganze Jahr über Themenfeste sowie den Vilarejo Radical mit 2 Mega-Seilrutschen, Hochseilgarten, Kletterwand und Abseilen. Es gibt einen Außenpool mit Wasserrutsche und Kinder-Wasserpark sowie ein Hallenbad. Kino, Kids-Bereich und Zen-Bereich. Neben allen Einrichtungen des Hotels können die Gäste bei einem Besuch der Produktion der Cachaçaria Vilarejo ein einzigartiges Erlebnis genießen, wo die Cachaças und Liköre der Marke Vilarejo in Handarbeit hergestellt werden. Unser All-inclusive-Angebot umfasst Frühstück, Snack, Mittagessen, Häppchen, Abendessen und Themenmenüs gemäß dem jährlichen Festkalender des Hotels. Alkoholische und alkoholfreie Getränke während des gesamten Aufenthalts in den drei Bars des Hotels.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 100, 'de', 'funcionamento', '10–20 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 101, 'de', 'descricao', 'Besuch der Kaffeeplantage mit Verkostung des preisgekrönten Kaffees; Musik- und Literaturabende (Saraus); Ausritte und Kutschfahrten; Führung durch das historische Herrenhaus aus dem Kaffeezyklus.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 101, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 102, 'de', 'descricao', 'Der Açude da Concórdia ist zweifellos ein wunderschöner Ort, um mit nahezu unberührter Natur in Kontakt zu bleiben, und ein großartiger Platz für eines dieser Familienpicknicks am Wochenende. Sein klares, kaltes Wasser hat einen Uferumfang von 4.170 Metern. Er liegt in einem Waldgebiet mit Resten des Atlantischen Regenwalds und ist von Weidevegetation und einem Grasweg umgeben, der zum Wandern einlädt. Unterwegs kann man Tiere wie den Inhambu (Tinamu), die Juriti (Taube) und den Jacu (Guan) hören');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 102, 'de', 'funcionamento', 'Donnerstag bis Sonntag, 9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 103, 'de', 'descricao', 'See und Streichelzoo.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 103, 'de', 'funcionamento', 'Mit Übernachtung: 24 Stunden | Ohne Übernachtung: 7–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 104, 'de', 'descricao', 'Die Führung besteht aus einem Rundgang durch die Ziegenfarm mit Teilnahme an der Fütterung unserer Ziegen und am Melken. Es gibt auch eine Tour mit Verkostung von Produkten aus der Milch der Ziegen von Lago, wie verschiedene Käsesorten, Süßigkeiten und Kuchen. Inbegriffen ist ein Imbiss mit Kuchen, Broas (Maisgebäck), Keksen und Saft. Dazu ein Geschenk: Ziegenmilchseife und handgemachter Doce de Leite. Zusätzlich zur gesamten Führung und zum Imbiss dürfen Kinder, die ihre Eltern bei dieser Tour mit Verkostung begleiten, kostenlos eine Ziege mit der Flasche füttern');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 104, 'de', 'funcionamento', 'Sa., 9–11 Uhr und 14–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 105, 'de', 'descricao', 'Das Programm, das auf das Jahr 1820 zurückgeht, umfasst eine Besichtigung des Haupthauses, in dem die Geschichte des Landguts und seiner Wiederherstellung erzählt wird, mit Informationen zu den vorhandenen Möbeln und Gegenständen, den Gärten und dem See sowie einem Oldtimer-Museum und den Ruinen der Anlagen zum Trocknen und Aufbereiten von Reis – einzigartige Erlebnisse, die das Landgut seinen Besuchern bietet. Zum Abschluss der Tour wird ein köstlicher Kaffee mit typischen Speisen serviert.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 105, 'de', 'funcionamento', 'Montag bis Montag, 10–19 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 106, 'de', 'descricao', 'Ein Erlebnis des Landlebens. Besuch des Betriebs, der der Zucht und dem Verkauf von Saanenziegen gewidmet ist. Während des Besuchs gibt es eine Verkostung feiner, handwerklich hergestellter Käsesorten, die von der jahrhundertealten französischen Käsetradition inspiriert sind.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 106, 'de', 'funcionamento', 'Sa., 10–11:30 Uhr und 16–17:30 Uhr / So., 10 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 107, 'de', 'descricao', 'Besichtigung der Anlagen, die den strengsten Qualitätsnormen und -standards vollständig entsprechen. Sie können eine Cachaça probieren, die handwerklich in einer Kupferbrennblase hergestellt und in edlen Hölzern gelagert wurde. Probieren Sie die Hölzer Ihrer Wahl oder auch den reinen Cachaça („Purinha“) – besuchen Sie uns.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 108, 'de', 'descricao', 'Empfängt Besucher für Führungen, Übernachtungen, pädagogische Aktivitäten und touristisch-kulturelle Veranstaltungen. Eine echte Reise zurück in die Vergangenheit. Zum Besuch des Landguts gehört auch das einzige Kaffeemuseum des Bundesstaats Rio. Ein einzigartiges und ganz besonderes Erlebnis. Das Museum wurde so konzipiert, dass die Geschichte der Sklaven zur Zeit der Kaffeebarone bewahrt und über viele Generationen weitererzählt wird. Ein bereichernder Besuch voller Kultur und Wissen, der dem Besucher ein einzigartiges Erlebnis bietet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 108, 'de', 'funcionamento', '2–3 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 109, 'de', 'descricao', 'Geführter Besuch der Brennerei, von der Verarbeitung des Zuckerrohrsafts bis zur Lagerung in Fässern. Verkostung von Cachaças und Likören, Zuckerrohrsaft mit köstlichen Pastéis und Luizas Kuchen. Fahrt mit der kleinen Eisenbahn der Estrada de Ferro União Carvalheira. Rundkurs von etwa 1 km durch einen Tunnel, über Brücken und an Seen vorbei. Es gibt ein Restaurant sowie Tretbootfahrten auf dem See.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 110, 'de', 'descricao', 'Um 1830 erbaut, ist es das einzige in Privatbesitz befindliche Landgut in Vassouras, das vom Nationalen Institut für historisches und künstlerisches Erbe (IPAM) unter Denkmalschutz gestellt wurde, und eines der wichtigsten historischen Bauwerke der Gegend. Führungen mit Touristen durch die Gebäude, wobei das Personal Kleidung aus der Zeit trägt. Der Rundgang führt durch drei mit Gegenständen aus der Zeit möblierte Zimmer und durch den Musiksalon. Zum Abschluss können die Besucher den auf dem Landgut produzierten Kaffee probieren; auch ein Picknick kann gebucht werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 110, 'de', 'funcionamento', 'Auf Anfrage');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 111, 'de', 'descricao', 'Die Fazenda Mulungu Vermelho empfängt Besucher und beteiligt sich an kulturellen Veranstaltungen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 112, 'de', 'descricao', 'Ziel ist es, die Kultur des Spezialitätenkaffees zu verbreiten – durch Schulung von Menschen, Technologie bei Geräten und Utensilien sowie die Förderung der Röstung von Spezialitätenkaffees auf Bestellung. Ein Muss für Liebhaber dieses Getränks!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 112, 'de', 'funcionamento', 'Sa., So. und an Feiertagen, 9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 113, 'de', 'descricao', 'Angeln gegen Gebühr in friedlicher, ruhiger Umgebung für alle, die Naturnähe und das Angeln suchen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 114, 'de', 'descricao', 'Besuch der Kaffeeplantage, Rösten vor Ort und Verkostung von handwerklich hergestelltem Kaffee.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 115, 'de', 'descricao', 'Mit einer großen Auswahl an Paketen liegt das Vassouras Eco Resort im Vale do Café (Kaffeetal), einer Gegend voller atemberaubender Naturschönheiten. Hier respektieren wir die Natur, kümmern uns um sie und wenden verschiedene nachhaltige Praktiken an. In Anerkennung dieser Bemühungen und weil wir die Umweltschutzvorschriften einhalten, haben wir das Umweltzertifikat des Ibama erhalten. Denn wir glauben, dass es möglich ist, Ihnen das Beste zu bieten, ohne unsere natürlichen Ressourcen zu schädigen – durch hochwertigen nachhaltigen Tourismus.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 115, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 116, 'de', 'descricao', 'Ein schönes L-förmiges Herrenhaus auf einem Plateau, das von einer Trockenmauer aus Naturstein gesäumt wird, die den ehemaligen Kaffeetrockenplatz des Anwesens begrenzt. Eine weite Wiese und alte Ruinen bilden die perfekte Kulisse für Zeremonien im Freien und verleihen Hochzeiten auf dem Land ihren ganzen Charme, mit dem schönen historischen Landgut im Hintergrund. Es wird ein historisches Theaterstück mit mehr als 10 Schauspielern sowie einer Jongo- und Maculelê-Gruppe aufgeführt. Das Zusammenspiel von Herrenhaus, den großen Bäumen ringsum und der Steinmauer, die beide umgibt, zeigt, wie schön dieser Ort ist. Das Anwesen widmet sich der Hotellerie und der historischen Besichtigung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 117, 'de', 'descricao', 'Im Hotel Fazenda Galo Vermelho finden Sie Gemütlichkeit, Herzlichkeit und eine vollständige Freizeitinfrastruktur. Neben Streichelzoo, Biogemüsegarten, Melken und Kutschfahrten bietet es alles an Freizeitmöglichkeiten für die ganze Familie: Animation, Kanufahren, Pool, beheizter Pool, Bogenschießen und Kletterwand, unter anderem. All das umgeben von wunderschönen Herrenhäusern historischer Landgüter.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 118, 'de', 'descricao', 'Laden mit Produkten vom Land, Ausritte und kleiner Streichelzoo.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 118, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 119, 'de', 'descricao', 'Ausritte für Touristen in der Umgebung, auf den Pfaden der Serra das Emerências und von Caravelas. Reiten im Gestüt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 119, 'de', 'funcionamento', 'Direkt anfragen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 120, 'de', 'descricao', 'Reitunterricht und Ausritte. Die einzige Reitanlage der Região dos Lagos (Seenregion), die auf klassische Reitkunst und Springreiten spezialisiert ist, eine olympische Disziplin.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 120, 'de', 'funcionamento', 'Von 8 bis 18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 121, 'de', 'descricao', 'Die einheimischen Frauen sind ältere Frauen, die fischen, verarbeiten, zubereiten und ihre Produkte verkaufen. Neben der Verantwortung für den gesamten Prozess setzen sie sich aktiv für die handwerkliche Fischerei innerhalb der ResexMar von Arraial do Cabo (einem bundesstaatlichen Schutzgebiet) ein, fördern die Wiederbelebung der Traditionen von Arraial do Cabo und bringen anderen Frauen das Fischen bei. Im Sitz der Genossenschaft der einheimischen Frauen werden Gerichte mit Bezug zum Meer und zur Kultur der traditionellen Fischerei verkostet; außerdem stellen sie Cachaças mit Camboi – bekannt als „Cabista-Whisky“ – und anderen Früchten und Samen der Restinga de Massambaba her und beleben so einen Teil der Geschichte und Volkskultur von Arraial do Cabo wieder. Alles begleitet von viel Plauderei und unglaublichen Geschichten der „WUNDERFRAUEN DER FISCHEREI“.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 121, 'de', 'funcionamento', 'Keine Angabe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 122, 'de', 'descricao', 'Typische Speisen, Ausritte, Verkauf von Produkten vom Land und Volksmusik.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 122, 'de', 'funcionamento', 'Von 9 bis 16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 123, 'de', 'descricao', 'Markt der Landerzeuger, Kunsthandwerksmarkt, Ausritte, ländliche Gastronomie, Besuch der dreihundertjährigen Kapelle Santo Inácio de Loyola und der Umgebung des Jesuitenherrenhauses, Kinderspiele, Musikdarbietungen, Sinnespfad, unter anderem.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 123, 'de', 'funcionamento', 'Von 9 bis 15 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 124, 'de', 'descricao', 'Gestüt mit Lasso- und Fassrennen-Wettbewerben, Zucht von Miniaturpferden und anderen Nutztieren, ländlichen Veranstaltungen, Shows und einer Dreifass-Meisterschaft.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 124, 'de', 'funcionamento', 'Keine Angabe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 125, 'de', 'descricao', 'Suiten im Kolonialstil, Pool mit Freizeitbereich, Ausritte und ökologische Wanderungen in einem privaten Schutzgebiet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 125, 'de', 'funcionamento', 'Nur mit Reservierung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 126, 'de', 'descricao', 'Suiten, Pool, Gestüt und Vermietung für Veranstaltungen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 126, 'de', 'funcionamento', 'Wochenenden, 9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 127, 'de', 'descricao', 'Reiterumzug der Schutzheiligen, der an dem Feiertag zu den Festlichkeiten der Schutzheiligen der Stadt im August stattfindet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 127, 'de', 'funcionamento', 'Keine Angabe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 128, 'de', 'descricao', 'Wanderung zur Feier des Jahrestags des PARNA da Restinga de Jurubatiba (Nationalpark), am 29. April. Wanderung zur Feier der Woche der Umwelt, im Mai. Öko-ländlicher Wanderrundweg des Rancho Ouro Preto nach den internationalen Standards von Anda Brasil, im September.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 129, 'de', 'descricao', 'Ein Ort, an dem die Gäste einen Tag auf dem Landgut erleben können: Melken, Ausritte, Kutschfahrten, Kontakt mit den Tieren sowie die berühmte Wanderung um den Morro São João oder die Vulkanwanderung. Das Anwesen aus dem 18. Jahrhundert, im portugiesischen Kolonialstil erbaut, bewahrt seine historischen und natürlichen Merkmale. Das Gelände von 200 Alqueires liegt 50 Meter über dem Meeresspiegel auf dem Morro São João.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 129, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 130, 'de', 'descricao', 'Kostenloses Angelerlebnis, Naturkontakt und Freizeit im Freien.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 130, 'de', 'funcionamento', 'Von 8 bis 12 Uhr. Alle zwei Wochen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 131, 'de', 'descricao', 'Tätig im ökologischen Agrotourismus, mit agrarökologischer Produktion und zertifizierten Bio-Lebensmitteln. Empfängt Gruppen für pädagogischen Tourismus. Campingplatz auf dem Land.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 131, 'de', 'funcionamento', 'Von 8 bis 17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 132, 'de', 'descricao', 'Die Route Arrastão da Cultura lässt die Geschichte lebendig werden und bringt Wissenswertes über die lokale Kultur. Auf dem Weg durch historische Orte wie das Viertel Estação sieht man die Stelle, an der der alte Bahnhof stand. Die Fahrt folgt der alten Route der Maultiertreiber (Tropeiros), vorbei an alten Lagerhäusern und archäologischen Stätten. Am Ufer der Lagoa de Araruama gelegen, kann man am Coração de Iguaba Grande einsteigen. Im Sítio Palinha wird ein typisches ländliches Frühstück serviert. Im Sítio Angino sind die alte Route der Tropeiros und ihre Quellen das Highlight. Der Empfang erfolgt durch die Besitzer des Ortes, wo agrarökologische Produkte verkauft werden. Haltestationen am Sítio dos Dias, am Sítio da Dona Vilma und am Espaço Ecológico Celia Barbosa da Silva (Lagoa do Bulcão), wo man einen kleinen Pfad gehen und einige Arten von Aroeira, Ipê, Flamboyant, Krallenaffen, Galo da Serra, Canário da Terra und weitere dort vorkommende Tier- und Pflanzenarten bewundern kann, gehören ebenfalls zur Route. Die Tour endet mit einem köstlichen Mittagessen im Restaurante Mineiro.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 132, 'de', 'funcionamento', 'Die Strecke wird mit einer Jardineira (offener Ausflugswagen) oder einem Minibus zurückgelegt, Dauer 7 Stunden; die besuchten Sítios werden vorab vereinbart');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 133, 'de', 'descricao', 'Direkt an der Rodovia Amaral Peixoto gelegen, wurde der Ort 2020 aufgewertet und ist zu einem Treffpunkt und Fotomotiv geworden, das für die Stadt wirbt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 133, 'de', 'funcionamento', 'Freier Zugang.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 134, 'de', 'descricao', 'Ein ökologischer Raum, der 2020 mit dem Ziel geschaffen wurde, einen Ort für Freizeit und Umweltbildung zu bewahren und zu fördern. Er besteht aus einem Sportplatz, einem Pfad, der zum Gebetshügel führt, einem Bereich für die Ausstellung lokalen Kunsthandwerks, einem Spielbereich für Kinder und einem See. Hier kann man einen kleinen Pfad gehen und einige Arten von Aroeira, Ipê, Flamboyant sowie Krallenaffen, Galo da Serra, Canário da Terra und weitere in unserer Stadt vorkommende Tier- und Pflanzenarten bewundern.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 134, 'de', 'funcionamento', 'Freier Zugang.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 135, 'de', 'descricao', 'Bei der Ankunft auf dem Sítio werden wir mit einem köstlichen Frühstück empfangen: Tapioka, Maiskuchen, herzhafter Cuscuz, Süßes und natürliche Fruchtsäfte aus Früchten, die im eigenen Garten geerntet wurden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 135, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 136, 'de', 'descricao', 'Interaktion und direkter Kontakt mit Haustieren wie Kälbern und Pferden, Fische im See füttern, Freizeitangebote, Billard und Tischfußball, Fußballplatz, Holzofenküche, Grillplatz und ein einladender, geeigneter Raum für Mahlzeiten wie Frühstück, Imbisse und Mittagessen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 136, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 137, 'de', 'descricao', 'Köstliches ländliches Mittagessen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 137, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 138, 'de', 'descricao', 'Produkte des Sítios werden verkauft, und es wird ein Erlebnis des Landlebens geboten, mit der Zucht von Fischen und Garnelen in Becken, einigen Vögeln wie Fasanen, Enten, Gänsen, Hühnern sowie Schweinen, Schafen und anderen Tieren.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 138, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 139, 'de', 'descricao', 'Bei der Ankunft auf dem Anwesen werden die Besucher vom Eigentümer sehr herzlich empfangen. Der Sítio hat verschiedene Bananenarten und Beete mit agrarökologischem Gemüse, das direkt beim Erzeuger gekauft werden kann.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 139, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 140, 'de', 'descricao', 'Angeboten wird ein typisches ländliches Frühstück mit Maniokkuchen, Maismehlkuchen, Fruchtsäften der Saison und Kräutertees aus auf dem Anwesen angebauten Kräutern');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 140, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 141, 'de', 'descricao', 'Ein Landgut mit Rinderzucht sowie Herstellung und Verkauf von Milch und Queijo Minas (Minas-Käse), die auf dem Anwesen produziert werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 141, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 142, 'de', 'descricao', 'Auf dem Weg führt die Strecke an der alten Route der Tropeiros (Maultiertreiber) und an der Quelle vorbei. Auf dem Anwesen werden agrarökologische Produkte sowie ein köstliches Pastel mit Zuckerrohrsaft verkauft.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 142, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 143, 'de', 'descricao', 'Wir können verschiedene Kulturen bewundern, darunter Kokosnuss, Maniok, Orange, Mango, verschiedenes Gemüse und anderes.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 143, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 144, 'de', 'descricao', 'Einstieg am Coração de Iguaba Grande am Ufer der Lagune von Araruama, dann Weiterfahrt zum Parque Ecológico Célia Barbosa Da Silva - Lagoa Do Bulcão, einem ökologischen Raum, der 2020 mit dem Ziel geschaffen wurde, die Umweltbildung zu bewahren und zu fördern. Hier kann man einen kleinen Pfad gehen und einige Arten von Aroeira, Ipê, Pau Brasil, Pau Ferro, Krallenaffen, Galo da Serra, Canário da Terra, Tiê-sangue, Tiziu und weitere in unserer Stadt vorkommende Tier- und Pflanzenarten bewundern. Der nächste Halt ist der Sítio Ivonilda, wo ein ländliches Frühstück angeboten wird und man Kuchen, Obst und natürliche Säfte aus auf dem Anwesen geernteten Produkten probieren kann. Nach dem Frühstück folgt der Besuch im Sítio Faisão Dourado, wo Produkte des Sítios verkauft werden und ein Erlebnis des Landlebens geboten wird, mit der Zucht von Fischen und Garnelen in Becken, einigen Vögeln wie Fasanen, Enten, Gänsen, Hühnern sowie Schweinen, Schafen und anderen Tieren. Danach geht es zum Sítio dos Chaves, einem Anwesen mit verschiedenen Bananenarten und Beeten mit agrarökologischem Gemüse, das direkt beim Erzeuger gekauft werden kann. Anschließend folgt der Halt am Rancho Gratidão, einem schönen Ort mit Landgut-Charakter, wo man Interaktion und direkten Kontakt mit Tieren wie Kälbern und Pferden erleben, Fische im See füttern, Freizeitangebote, Billard und Tischfußball, einen Fußballplatz, eine Holzofenküche, einen Grillplatz und einen einladenden, geeigneten Raum für Mahlzeiten wie Frühstück, Imbisse und Mittagessen nutzen kann.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 144, 'de', 'funcionamento', 'Die Strecke wird mit einer Jardineira (offener Ausflugswagen) oder einem Minibus zurückgelegt, Dauer 7 Stunden; die besuchten Sítios werden vorab vereinbart.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 145, 'de', 'descricao', 'Ein Gemeinschaftserlebnis für die ganze Familie. Agrarökologische Wanderungen, Workshops mit Schwerpunkt auf Bio-Ernährung und agrarökologischen Praktiken. Das Hauptprojekt ist „vom Garten auf den Tisch“, mit Workshops zum Pflanzen, Ernten und Zubereiten von Speisen auf dem Holzofen, um das Landleben zu erleben. Beobachtung freilebender Vögel in ihrer natürlichen Umgebung, Angeln gegen Gebühr, geführte Wanderungen zum Peito do Pombo, Spaziergänge zum Erkennen von Pflanzen und Bäumen sowie zum Heilkräutergarten und für Kinder das Projekt „Pé no Chão“ („Füße auf dem Boden“) mit Baumklettern, Klettern und anderen Spielen auf dem Land in direktem Kontakt mit der Natur.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 145, 'de', 'funcionamento', 'Von 6 bis 17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 146, 'de', 'descricao', 'Hotel auf dem Bauernhof: Unterkunft, Verpflegung und Freizeitangebote.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 146, 'de', 'funcionamento', '8–21 Uhr. An allen Tagen des Jahres.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 147, 'de', 'descricao', 'Besuch der wichtigsten Blumengeschäfte der Stadt + des agroökologischen Platzes (praça Agroecológica).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 147, 'de', 'funcionamento', '8–21 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 148, 'de', 'descricao', 'Völliges Eintauchen in die Natur auf Wanderwegen, an Wasserfällen und Aussichtspunkten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 148, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 149, 'de', 'descricao', 'Day Use sonntags auf einem weitläufigen, schattigen Gelände mit beschilderten einheimischen Bäumen, Bächen, einem Wasserfall und Freizeiteinrichtungen mit Pool, Spielzimmer, hauseigenem Parkplatz und Ökotourismus.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 149, 'de', 'funcionamento', 'Sonntags. 8–16 Uhr. Day Use nur mit Reservierung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 150, 'de', 'descricao', 'Touristen mit der Natur verbinden: ein Bad im Wasserfall, ein kurzer Spaziergang auf einem Wanderweg, Ausritte und Nähe zur lokalen Kultur. Abschluss auf dem ländlichen Rundweg und am Strand.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 150, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 151, 'de', 'descricao', 'Keramikkurse, Verkauf selbst hergestellter Produkte, Kaffee und Kuchen aus dem Holzofen mit Freilandeiern aus eigener Haltung, in häuslicher Atmosphäre mit schöner Aussicht. Reine Luft.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 151, 'de', 'funcionamento', 'Am Wochenende vormittags.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 152, 'de', 'descricao', 'Pastel (frittierte Teigtasche), Brühe, Maniok-Küchlein, typische Früchte und Mittagessen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 152, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 153, 'de', 'descricao', 'Spezialisiert auf deutschsprachige Gäste, die Rio de Janeiro, Niterói, Maricá oder Brasilien kennenlernen und in kurzer Zeit möglichst viel sehen möchten. Deutsch-brasilianische Küche. Ideal für Kreuzfahrtgäste, die Rio vor oder nach ihrer Reise ausführlich besichtigen möchten, mit Hin- und Rücktransfer Flughafen / Hafen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 153, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 154, 'de', 'descricao', 'Wir liegen mitten in der Natur und bieten hochwertige, handgefertigte Produkte. Ein Ort, an dem Sie einen köstlichen ländlichen Kaffee genießen können, umgeben von viel Natur, mit herrlichem Panoramablick auf die Pedra de Itaocaia und einem hervorragenden Beobachtungspunkt für Mond und Sterne.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 154, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 155, 'de', 'descricao', 'Veranstaltungsorganisation, Naturerlebnis und Fußballplatz.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 155, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 156, 'de', 'descricao', 'Familiäres Lokal mit Hausmannskost, gemütlich und angenehm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 156, 'de', 'funcionamento', '12–14 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 157, 'de', 'descricao', 'Keramikkurse, handgefertigtes Keramikgeschirr und Handarbeit.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 157, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 158, 'de', 'descricao', 'Ökotouristischer Wanderweg und Ausritte, typisch chilenische Küche und traditionelle brasilianische Küche.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 158, 'de', 'funcionamento', 'Mittwoch bis Sonntag, 9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 159, 'de', 'descricao', 'Buffet oder à la carte, Getränke separat. Pool, Bach, Spielzimmer, Kinderspielplatz, Hängemattenbereich, aufblasbare Rutsche, Trampoline und Bällebad.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 159, 'de', 'funcionamento', 'Wochenenden und Feiertage. 10–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 160, 'de', 'descricao', 'Ökotourismus, Seilrutsche, Wasserfall, Startrampe für Drachenflieger. Die Besucher werden in einem 4x4-Jeep im Savannenstil mit 9 Plätzen zu beeindruckenden, schwer zugänglichen Orten gebracht. Orte: Espraiado, Strandpromenade von Itaipuaçu, Araçatiba.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 160, 'de', 'funcionamento', '8–19 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 161, 'de', 'descricao', 'Wandteppiche, Möbel aus Altholz und Kunsthandwerk.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 161, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 162, 'de', 'descricao', 'Erlebnistourismus mit Schwerpunkt auf der lokalen ländlichen Gastronomie, dem Leben mit den Tieren auf dem Bauernhof und dem Kontakt zur Natur.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 162, 'de', 'funcionamento', 'Montag bis Samstag. 8–19 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 163, 'de', 'descricao', 'Verkauf vielfältiger Produkte vom Land, ausschließlich handwerklich und/oder vor Ort hergestellt, in einem Agrarökologie-Projekt von etwa 1.000 m².');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 163, 'de', 'funcionamento', '8–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 164, 'de', 'descricao', 'Verkauf von Kuhmilch, Käse, Mist, Pflanzen und Snacks.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 164, 'de', 'funcionamento', 'Übliche Geschäftszeiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 165, 'de', 'descricao', 'Ländliche Location zur Miete mit Landschaftsgestaltung, die Natur und Menschen verbindet, für individuell gestaltete Veranstaltungen aller Art, für nur einen Tag oder sogar für Übernachtungen von Einzelpersonen, Familien und Gruppen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 165, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 166, 'de', 'descricao', 'Ländliches Gastronomieerlebnis, vor Ort erzeugte Lebensmittel ohne Pestizide, Angeln, Ausritte, Bergwanderungen, ein Ort für Astrotourismus und ein Campingplatz.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 166, 'de', 'funcionamento', 'Wochenenden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 167, 'de', 'descricao', 'Besichtigung der Abfüllanlage für Kokoswasser mit Verkostung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 167, 'de', 'funcionamento', 'Montag bis Samstag. 6–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 168, 'de', 'descricao', 'Ein Ort, an dem die Cachaça Chico Tobias und gemischte Getränke wie die Meladinha hergestellt werden, mit Verkostung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 169, 'de', 'descricao', 'Ein Areal von 100.000 m² mit großer Vielfalt an Obstbäumen. Obstgarten, Gemüsegarten, Viehgehege, Hühnerställe usw. Ländliche Küche mit Grill und Holzofen, Duschen, Freizeit- und Essbereich, Ausstellungsbereich für Produkte, Hängemattenbereich, Wiese, Imkereibereich und drei Fischteiche.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 169, 'de', 'funcionamento', 'Übliche Geschäftszeiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 170, 'de', 'descricao', 'Erlebnisse einer Zeitreise in die Epoche des Zuckerrohrs: ehemalige Sklavenunterkünfte (Senzalas), die noch von Bewohnern bewohnt werden, die den Widerstand und Kampf der Versklavten fortführen, das verfallene Herrenhaus des Visconde de Ururaí und seiner Tochter, das Lagerhaus, die 1833 erbaute Kirche, das Gemeinschaftsrestaurant Casa de Artes Machadinha und der von Versklavten erbaute Kanal Campos–Macaé, der von Campos nach Macaé führt. Hervorzuheben ist schließlich das Leben der Quilombola, in ihrer Art zu arbeiten und zu existieren.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 170, 'de', 'funcionamento', '10–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 171, 'de', 'descricao', 'Hydroponik, Grundnahrungspflanzen und Milchvieh.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 171, 'de', 'funcionamento', '7–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 172, 'de', 'descricao', 'Besichtigung der Weidewirtschaft und des Melkvorgangs.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 172, 'de', 'funcionamento', '5.30–7 Uhr und 15.30–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 173, 'de', 'descricao', 'Vor Ort sehen Sie eine Vorführung, wie die in der Cocktailszene von Rio am besten platzierte Cachaça hergestellt wird, und können die Produkte vor Ort probieren oder kaufen. Planen Sie Ihren Besuch, um dieses Erlebnis zu genießen!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 174, 'de', 'descricao', 'Aktivitäten im Gemüseanbau, Mitarbeit bei der Mehlherstellung und im Umgang mit Geflügel sowie Teilnahme am Melken und an Kursen zur Herstellung ländlicher Süßspeisen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 175, 'de', 'descricao', 'Die Fazenda São Miguel war die erste Residenz des Barons und Vicomte von Quissamã. Das Haus, typisch für die Architektur vom Ende des Zuckerrohrzyklus, ist von Palmen und Eukalyptusbäumen umgeben und beherbergt Möbel und Gegenstände vom Anfang des Jahrhunderts. Vereinbaren Sie einen Besuch, um in diese Geschichte einzutauchen und ein köstliches typisches Mittagessen zu genießen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 176, 'de', 'descricao', 'Besuch der Weinstöcke, Kaffee „da Roça“ (nach Landart), kleiner Markt mit vielfältigen Produkten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 176, 'de', 'funcionamento', '8–11.30 Uhr und 14.30–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 177, 'de', 'descricao', 'Besichtigung der lokalen Pilzproduktion, Verkauf von Folgeprodukten wie Kräutersalz, Risotto und Canjiquinha (Maisgrieß).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 177, 'de', 'funcionamento', 'Montag bis Samstag, 9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 178, 'de', 'descricao', 'Restaurant mit Freizeitbereich, Fußballplatz, Ausritten, Catch-and-Release-Angeln, Pools und Kinderspielplatz.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 178, 'de', 'funcionamento', 'Wochenenden. 9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 179, 'de', 'descricao', 'Angeln gegen Bezahlung (Fang wird abgerechnet), Küche aus Minas Gerais und familiäre Atmosphäre.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 179, 'de', 'funcionamento', 'Montag bis Freitag, 11–14.30 Uhr. Wochenenden, 11–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 180, 'de', 'descricao', 'Unterkunft mit Frühstück, Hochseilgarten, Sportplatz, Pool und unser Ara.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 180, 'de', 'funcionamento', 'Dienstag bis Sonntag, 10.30–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 181, 'de', 'descricao', 'Ländliche Gastronomie, Angeln, Ausritte, Pool und Veranstaltungen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 181, 'de', 'funcionamento', 'Wochenenden, 10–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 182, 'de', 'descricao', 'Ländliche Aktivitäten, Gemüsegarten, Pferde, Wanderungen in der ländlichen Umgebung, stets begleitet von Sportfachkräften, Pool, Whirlpool und Fitnessraum. Fit-Menü und direkte Betreuung durch die Eigentümer.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 182, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 183, 'de', 'descricao', 'Panoramablick, Imkerei, Orangen- und Maniokplantagen, Grillplatz und Fußballplatz. Der Besuch wird von einer Canindé-Ara namens Amora begleitet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 183, 'de', 'funcionamento', 'Montag bis Samstag, 9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 184, 'de', 'descricao', 'Es repräsentiert die ländliche Kultur von Aldeia durch seine reiche Küche, ein authentisches ländliches Gastronomieerlebnis mit den Aromen und der Atmosphäre des Landlebens. Pool und Reiten vor Ort sind für Besucher, die bei uns zu Mittag oder zu Abend essen, kostenlos.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 184, 'de', 'funcionamento', '12 Uhr bis Mitternacht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 185, 'de', 'descricao', 'Ausritte und Kutschfahrten, Kontakt mit den Tieren vor Ort, ökologische Wanderung, Pool, Angeln gegen Bezahlung (Fang wird abgerechnet). Landküche.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 185, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 186, 'de', 'descricao', 'Hotel auf einem Bauernhof von 480.000 m² mit viel Grün und natürlicher Schönheit, abwechslungsreiche Aktivitäten mit Animationsteam und Küche nach Bauernhofart.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 186, 'de', 'funcionamento', '8.30–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 187, 'de', 'descricao', 'Hotel mit Day-Use-Angebot, Ausritte mit erfahrenen Guides, botanischer Lehrpfad.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 187, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 188, 'de', 'descricao', 'Wanderwege und Naturattraktionen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 188, 'de', 'funcionamento', '6–20 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 189, 'de', 'descricao', 'In einer einzigartigen Umgebung nahe der Natur und einem Wasserfall können Besucher Kunsthandwerk und Pflanzen bewundern. Vor Ort gefertigtes Kunsthandwerk, direkter Kontakt zum Meister-Kunsthandwerker, Filzkunst, Tonziegel, Kunst auf Spiegeln, dekorierte und bemalte Gipsfiguren, sakrale Kunst, Herstellung von Dekorationsstücken aus verschiedenen Materialien, Lernspiele, Holzkunst (Kiefer, Eukalyptus oder Altholz), Stoffmalerei, Kühlschrankmagnete und weiteres Kunsthandwerk. Pflanzen: verschiedene Sukkulenten, Kakteen, Rosen, Terrarien, Miniaturwelten und eine Vielfalt weiterer Pflanzen. Die Kunst des Kokedama ist in Entwicklung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 189, 'de', 'funcionamento', 'Nicht angegeben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 190, 'de', 'descricao', 'Familiärer Agrarbetrieb, der nach Familienrezepten eingemachte Früchte im Glas, Konfitüren und Käse herstellt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 190, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 191, 'de', 'descricao', 'Permakultur-Tour, geführter Rundgang durch alle Bioconstruction-Bauten, Agroforstsysteme, Bambusanpflanzungen und das Abfallmanagement, mit optionaler Verpflegung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 191, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 192, 'de', 'descricao', 'Ein angenehmes Erlebnis rund um das Getränk, das Teil der Geschichte Brasiliens und von Porto Real ist. Führung durch den Besitzer der Brennerei Alambique Cachaça Adelina, der den gesamten Herstellungsprozess der Cachaça erklärt, vom Anbau des Zuckerrohrs bis zur Abfüllung. Verkostung und Verkauf am Ende der Tour.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 192, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 193, 'de', 'descricao', 'Auf dem Sítio Romeu Verri erleben Sie Momente der Begegnung mit dem Alltag einer Familie, die die Traditionen ihrer Vorfahren im Gemüseanbau und in der Honigproduktion bewahrt. Am Ende des Besuchs können alle frische, schmackhafte Produkte erwerben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 193, 'de', 'funcionamento', '8–12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 194, 'de', 'descricao', 'Ein ruhiger Ort mit einem fantastischen Blick auf den Rio Paraíba do Sul. Angeln mit Bezahlung nach Fang und Sportangeln. Restaurant mit köstlichen Gerichten und Portionen mit Tilapia.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 194, 'de', 'funcionamento', '7–17 Uhr und 12–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 195, 'de', 'descricao', 'Ein unglaubliches Erlebnis für Liebhaber des Reitsports, mit Reitunterricht von Teilnehmern großer Turniere und der Möglichkeit, Pferden nahezukommen, die mehrere Titel gewonnen haben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 195, 'de', 'funcionamento', '7–12 Uhr und 14–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 196, 'de', 'descricao', 'Besucher erleben die typische Atmosphäre der alten Anwesen der ersten Siedler von Porto Real und können außerdem vor Ort gezüchtete Tilapia sowie lebende oder geschlachtete Enten erwerben. Der Hof bietet Mittagessen für Gruppen nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 196, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 197, 'de', 'descricao', 'Vor Ort können Besucher einen Gemüsegarten mit zahlreichen Blatt- und Gemüsesorten besichtigen und die Anzucht von Gemüsepflanzen miterleben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 197, 'de', 'funcionamento', '7–12 Uhr und 13–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 198, 'de', 'descricao', 'Die Feira da Roça ist ein typischer Ort in Quatis, gegründet 1985. Viele Menschen kommen hierher, um handwerklich hergestellte ländliche Produkte und Kunsthandwerk zu finden; es gibt außerdem ein gutes Selbstbedienungsrestaurant mit typischen Gerichten und einen lebhaften Forró.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 198, 'de', 'funcionamento', '11–18 Uhr, jeden zweiten und vierten Sonntag im Monat.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 199, 'de', 'descricao', 'Ein ruhiger Ort mit einem fantastischen Blick auf den Rio Paraíba do Sul. Angeln mit Bezahlung nach Fang und Sportangeln. Restaurant mit köstlichen Gerichten und Portionen mit Tilapia.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 199, 'de', 'funcionamento', '12–24 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 200, 'de', 'descricao', 'Tonico Sampaio, Besitzer der Fazenda Bom Retiro, hatte in den ersten Jahren des vergangenen Jahrhunderts (1912) die Idee, den reinsten Zuckerrohrbrand der Region herzustellen: die Cachaça Quatis, eine Tradition, die sein Sohn Silvio Sampaio fortführte und die heute von seinen Enkeln weitergeführt wird.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 200, 'de', 'funcionamento', '8–22 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 201, 'de', 'descricao', 'Mit Vogelgezwitscher aufwachen, über das Gras laufen, in der Hängematte unter dem Rosenapfelbaum entspannen und die Früchte direkt vom Baum pflücken – dazu Säfte, die mit Zuckerrohrsaft gesüßt werden, und Kekse, die ausschließlich mit Erzeugnissen der Pousada gebacken werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 201, 'de', 'funcionamento', 'Montag bis Sonntag, 24 Stunden,');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 202, 'de', 'descricao', 'Die Feirarte bietet Stände mit handwerklichen und kulinarischen Produkten von Kunsthandwerkern und Kleinunternehmern der Gemeinde.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 202, 'de', 'funcionamento', '9–14 Uhr, am 1. und 3. Samstag im Monat.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 203, 'de', 'descricao', 'Sportangeln');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 203, 'de', 'funcionamento', 'Donnerstag bis Sonntag, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 204, 'de', 'descricao', 'Eine historische Reise in die Vergangenheit, bei der man Lehmflechtwerkhäuser und historische Stücke des Quilombo aus nächster Nähe sehen kann, dazu viel Geschichte und Rezepte, die es nur hier gibt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 204, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 205, 'de', 'descricao', 'Besichtigung der Cachaça-Herstellung, die 2017 begann. Brennerei, Sportangeln und Milchprodukte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 205, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 206, 'de', 'descricao', 'Das Projekt Rotas de Pedal ist Abenteuertourismus für alle, die frische Luft atmen und die Freiheit in der Natur genießen möchten. Wir bieten rund 75 Routen durch vielfältige ländliche Landschaften.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 206, 'de', 'funcionamento', 'Keine Angabe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 207, 'de', 'descricao', 'Mit privilegiertem Blick auf die Region Capelinha und die Serra da Mantiqueira, inmitten umgebender Natur und typisch ländlicher Kulisse, bietet das Recanto do Tambaqui seinen Besuchern ein einladendes, weitläufiges Freigelände mit einem luftigen, freundlichen Restaurant. Das Essen findet Lob selbst bei den anspruchsvollsten Gästen. Hinzu kommen eigene, handgemachte Konfitüren zu 100 % aus natürlichen Zutaten und hausgemachte Süßigkeiten. Köstlichkeiten vom Land.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 207, 'de', 'funcionamento', 'Der Angelteich ist von Mittwoch bis Montag von 8 bis 18 Uhr geöffnet. Das Restaurant ist von Donnerstag bis Sonntag und an Feiertagen von 11.30 bis 15.45 Uhr geöffnet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 208, 'de', 'descricao', 'Trutas da Serrinha ist ein angenehmer Zufluchtsort und eines der Wahrzeichen der Serrinha do Alambari. Eingebettet zwischen den grünen Armen des Waldes, verfügt es über Becken mit sehr kaltem Wasser, ideal für die Forellenzucht – ein Fisch, der auch eine regionale Tradition ist. Die Forellenzucht stellt verschiedene Forellenspezialitäten her und verkauft sie, etwa Filet, geräuchertes Filet, Pastete und Casquinha (überbackene gefüllte Schale)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 208, 'de', 'funcionamento', 'Dienstag bis Sonntag, 9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 209, 'de', 'descricao', 'Im Umweltschutzgebiet Serrinha do Alambari in Resende findet man mitten im Atlantischen Regenwald eine Craft-Brauerei in belgischer Brautradition: Elbers Bier. Kristallklares, reines Wasser aus den Quellen der Serra da Mantiqueira verbindet sich mit den traditionellsten Malzsorten und weiteren belgischen Zutaten zu einer Vielfalt an Bieren, von Ales über die klassischen Blonde, Trippel, Witbier und Dubbel bis hin zu einem Bier auf Basis von Pinhão, dem Samen der Araukarie, der typischen Kiefer der Region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 209, 'de', 'funcionamento', 'Die Brauerei ist montags bis freitags von 7 bis 15 Uhr in Betrieb. Die Brauereibar empfängt Besucher samstags, sonntags und an Feiertagen von 11 bis 18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 210, 'de', 'descricao', 'Auf der Fazenda Valparaíso liegt die schöne Brennerei Alambique da Cachaça Reserva do Nosco, die im In- und Ausland vielfach prämiert wurde. Der Besuch beinhaltet eine Verkostung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 210, 'de', 'funcionamento', '10–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 211, 'de', 'descricao', 'Kontakt mit der Natur, Wald, Wanderwege, Wasserfälle und eine Maniokmehlmühle, die vermutlich aus dem 20. Jahrhundert stammt, einer Zeit, in der es in der Region noch keinen Strom gab und der gesamte Herstellungsprozess rein handwerklich erfolgte; eine Erdstraße, die den ganzen Reichtum des ländlichen Raums mit Landschaften aus Farmen, Gestüten und Plantagen bietet. Der Ort lässt die ganze Einfachheit des Landlebens vergangener Zeiten wieder aufleben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 211, 'de', 'funcionamento', 'Nach Absprache');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 212, 'de', 'descricao', 'Typische hausgemachte Landküche und selbst gemachte Produkte. Zu jeder Zeit für Gruppen und Einzelbesucher da.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 212, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 213, 'de', 'descricao', 'Die REGUA verfügt über Wege rund um die Feuchtgebiete in der Nähe des Besucherzentrums und weitere Wege, die Besucher näher an den Wald und die vom Reservat renaturierten Flächen heranführen. Ein Erlebnis, das die Besucher für die einzigartige Bedeutung und Schönheit des Atlantischen Regenwalds und seiner gesamten Artenvielfalt sensibilisieren soll. Die REGUA ist auf die Aufnahme von Vogelbeobachtern spezialisiert. Wir bieten einen Ort ganz in der Nähe von Rio de Janeiro mit geeigneter Infrastruktur für naturliebende Besucher in einer noch sehr gut erhaltenen Region. Für Vogelbeobachter stehen Wege, 3 Beobachtungstürme und ein Unterstand bereit, alle am Sitz der REGUA.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 213, 'de', 'funcionamento', '7–16.30 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 214, 'de', 'descricao', 'Ausflüge ins ländliche Cachoeiras de Macacu');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 215, 'de', 'descricao', 'Ausritte, Reitunterricht und Touren durch Wälder und Berge zu Fuß, zu Pferd und mit dem Mountainbike. Gut ausgebildete, zuverlässige Pferde, hochqualifizierte Reitlehrer und Guides, das Zusammensein mit frei in der Natur lebenden Pferden sowie geschützte und sich regenerierende Gebiete des Atlantischen Regenwalds, die besucht werden können. Aussichtspunkte, Gärten, Auen, Bäche und Quellen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 215, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 216, 'de', 'descricao', 'Kundenservice-Stelle mit bebilderten Foldern zu Reisezielen, Begleitung durch einen zugelassenen Guide, versicherter Transport und interaktive Aktivitäten, Bordservice, Teilnahme an Messen und Kongressen, kulturelle Begegnungen mit Fachleuten aus dem Bildungsbereich, religiöse Treffen, Touren bei Nacht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 216, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 217, 'de', 'descricao', 'Eine göttliche Verbindung mit der Natur und den Wasserfällen. Wanderwege durch den Atlantischen Regenwald, ein Besuch in der Vergangenheit. Wir liegen innerhalb des Naturschutzgebiets des Parque Estadual dos Três Picos, mit Zugang zum Weg zur Cachoeira 7 Quedas und zum 1.600 Jahre alten Jequitibá-Baum sowie zu weiteren Wasserfällen, die im Alto da Serra de Cachoeiras entspringen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 217, 'de', 'funcionamento', '8–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 218, 'de', 'descricao', 'Besuch der Brennerei Alambique Serra Verde, Ausritt, Mittagessen und Verkauf von Käse und eingekochten Früchten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 218, 'de', 'funcionamento', 'Montag bis Montag (täglich), nur nach vorheriger Voranmeldung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 219, 'de', 'descricao', 'Hausmannskost vom Holzofen, Angeln mit Zurücksetzen der Fische (Catch and Release) und ein Spielplatz für Kinder.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 219, 'de', 'funcionamento', '7–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 220, 'de', 'descricao', 'Herstellung von handwerklichem Bio-Cachaça und Vermietung der Anlage für Ferienaufenthalte. Vor Ort werden keine Mahlzeiten angeboten. Das Besondere ist die Gastfreundschaft der Besitzer, Herr Isaac und Frau Vera.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 220, 'de', 'funcionamento', 'Montag bis Montag (täglich), nur nach vorheriger Voranmeldung bei zugelassenen Guides.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 221, 'de', 'descricao', 'Ländliches Frühstück, Angeln mit Bezahlung nach Fang und Verkauf von Süßigkeiten, Freilandeiern und handwerklichem Likör – die besten Erlebnisse für Touristen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 221, 'de', 'funcionamento', 'Sa und So 9–18 Uhr. Di bis Fr nur nach vorheriger Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 222, 'de', 'descricao', 'Erläuterung des gesamten Herstellungsprozesses der Cachaças und Verkostung mit Häppchen. Der Besuch kann in Partnerschaft mit der Fazenda Tringuelé auch zu Pferd erfolgen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 222, 'de', 'funcionamento', 'Montag bis Montag (täglich)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 223, 'de', 'descricao', 'Besuch der Guavenplantage, Obsternte, Geschichte des Ortes, Erläuterung der Herstellung von Goiabada (Guavenpaste), Verkostung und Verkauf von Guaven und Goiabada. Das Besondere: die Früchte direkt vom Baum pflücken zu können.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 223, 'de', 'funcionamento', 'Mo bis Sa');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 224, 'de', 'descricao', 'Bar mit Craft-Bieren und Brauereiführung mit Erläuterungen zum Brauprozess, zur Geschichte hinter den Biernamen und einer Verkostung. Ausgezeichneter Service, eine Vielfalt an Craft-Bierstilen und fantastische Häppchen, die perfekt zu den Bieren passen. Offener Ort inmitten der Natur mit spektakulärem Blick auf die Serra dos Órgãos.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 224, 'de', 'funcionamento', 'Fr 17–21 Uhr - Sa 12–21 Uhr - So 11–13 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 225, 'de', 'descricao', 'Wanderwege und Ausritte mit spezialisierten Guides. Reittherapie für Erwachsene und Kinder.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 225, 'de', 'funcionamento', 'Täglich nur nach Voranmeldung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 226, 'de', 'descricao', 'Wochenmarkt mit Bioprodukten aus der bäuerlichen Familienlandwirtschaft von Guapimirim');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 226, 'de', 'funcionamento', '8–13 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 227, 'de', 'descricao', 'Verkauf von Ausflügen und Sehenswürdigkeiten der Stadt Guapimirim. Erste Agentur für Incoming-Tourismus der Stadt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 227, 'de', 'funcionamento', 'Mo 13–18 Uhr - Di bis Fr 9–18 Uhr - Sa 9–13 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 228, 'de', 'descricao', 'Reisebüro für Outgoing- und Incoming-Reisen');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 228, 'de', 'funcionamento', '8–13 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 229, 'de', 'descricao', 'Reisebüro für Outgoing- und Incoming-Reisen');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 230, 'de', 'descricao', 'Radtouren durch Gebiete mit biologischem Anbau und regionalem Kaffee. Keine Konkurrenz.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 230, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 231, 'de', 'descricao', 'Ein Ort mit ländlichem Charakter, der die unterschiedlichsten Produkte der Region anbietet, dazu sonntags Mahlzeiten und hausgemachte Pasta, frisch zubereitet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 231, 'de', 'funcionamento', 'Fr 9–22 Uhr, Sa 9–22 Uhr und So 9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 232, 'de', 'descricao', 'Seilrutsche, Baden im Bach, Naturpool, Biogemüsegarten, Wanderwege und Geländewagen-Touren (4x4).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 232, 'de', 'funcionamento', 'Nur nach Reservierung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 233, 'de', 'descricao', 'Der Hof betreibt Forellenzucht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 233, 'de', 'funcionamento', '8–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 234, 'de', 'descricao', 'Agentur für Incoming-Tourismus. Ein Erlebnistourismus mit vielfältigen Attraktionen: natürliche Milchprodukte ohne chemische Zusätze, grobstückige Goiabada (Guavenpaste), im Kupferkessel auf dem Holzofen gekocht, eine handwerkliche Cachaça-Brennerei, Restaurants mit Holzofen, Trüffelkäse, Forellenzucht, ein Erlebnis in einem Steinschloss, ein zu 100 % biologischer Hof mit Selbstpflücken gegen Bezahlung, eine Erdbeerplantage, eine Hopfenplantage, Erlebnisse mit dem Binden von Blumensträußen, ein Hof mit Day Use und dem Erlebnis, Öko-Schmuck herzustellen, eine Gärtnerei mit einem besonderen Sortiment an Produkten, Kunsthandwerk und Gartendekoration sowie mehrere Orte mit besonderen Konfitüren, darunter Produkte mit Hopfen. Angeln mit Bezahlung nach Fang, ein Geflügelhof mit Freilandeiern von bester Qualität, Camping, eine Halle mit Antiquitäten, die die Vergangenheit wieder aufleben lässt, ein hundertjähriges Warenlager mit Spezialität für Bioprodukte und das traditionelle Carne na Lata (in der Dose konserviertes Fleisch). Frühstücks- oder Nachmittagskaffee-Erlebnisse zur Auswahl. Das wichtigste Merkmal des Services ist die Exklusivität für Gruppen bei jeder einzelnen Attraktion. Die Gruppe wird wie eine Familie betreut.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 234, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 235, 'de', 'descricao', 'Trüffelkäse');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 235, 'de', 'funcionamento', '13–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 236, 'de', 'descricao', 'Verkostung der Produkte und Erlebnis in einer Cachaça- und Likörmanufaktur. Betreuung durch die Besitzer. Handwerkliche Produkte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 236, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 237, 'de', 'descricao', 'Eine sinnliche und lehrreiche kulinarische Erfahrung, die das Bewusstsein für natürliche und gesunde Ernährung schärft. Unsere Produktion, angefangen bei der Milch, ist eigen. Alles wird im Haus hergestellt. Natürliche, handwerkliche Lebensmittel ohne chemische Zusätze. Eine idyllische, angenehme Umgebung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 237, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 238, 'de', 'descricao', 'Kontakt mit der Natur, Einblick in Pflege und Bezug von Zierpflanzen, Innen- und Außendekoration, Anbau von Bio-Lebensmitteln, Gewürzen und Heilkräutern sowie Wiederverwertung organischer Abfälle (Kompostierung, Wurmhumus, Biodünger). Wir glauben an Nachhaltigkeit und vermitteln unseren Besuchern, wie wichtig das Recycling unserer Abfälle ist, sowohl für die Umwelt als auch zu unserem eigenen Nutzen; organische Abfälle zum Beispiel als Nährstoffquelle für Pflanzen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 238, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 239, 'de', 'descricao', 'Wir sind ein kulinarisch-kultureller Treffpunkt mit hervorragender Gastfreundschaft. Kulturelle Begegnungen mit lokalen Künstlern, Fotospots und handwerkliche Produkte des Circuito Rural.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 239, 'de', 'funcionamento', 'Fr bis So, 12–23 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 240, 'de', 'descricao', 'Der Ort liegt innerhalb einer Wohnanlage, mit einem riesigen Biogemüsegarten und einem wunderschönen See, dem besten Carne de Lata und dem kältesten Bier der Region!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 240, 'de', 'funcionamento', 'Sa 9–22 Uhr, So 9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 241, 'de', 'descricao', 'Ein Ort zum Entspannen mitten in der Natur, mit Angeln, Barservice, einem Restaurant mit Hausmannskost, vielfältigen Snackplatten, einem Festbereich und Grillmöglichkeiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 241, 'de', 'funcionamento', 'Sa, So und an Feiertagen - 8–20 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 242, 'de', 'descricao', 'Ländliches Erlebnis und Workshop zu Biogärten. Bewahrung der lokalen Kultur, traditionelles Saatgut, bäuerliche Familienlandwirtschaft, Bioanbau mit partizipativer Zertifizierung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 243, 'de', 'descricao', 'Kunsthandwerk mit Naturblumen. Die Gäste fertigen ihr Kunstwerk selbst an.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 243, 'de', 'funcionamento', '9–13 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 244, 'de', 'descricao', 'Workshop für Handweberei und Produkte. Etwas Vergleichbares gibt es nicht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 244, 'de', 'funcionamento', '10–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 245, 'de', 'descricao', 'Verkostung von Craftbier, Kontakt mit der Natur.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 245, 'de', 'funcionamento', 'Wochenenden und Feiertage');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 246, 'de', 'descricao', 'Ein Ort mitten in der Natur mit einfacher, ländlicher Unterkunft, Restaurant und Craftbier-Brauerei. Herzliche Gastfreundschaft und Natur.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 246, 'de', 'funcionamento', 'Sa und So');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 247, 'de', 'descricao', 'Brauereitour, Fabrikbar, Livemusik.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 247, 'de', 'funcionamento', 'Fr 14–18 Uhr; Sa und So 11–19 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 248, 'de', 'descricao', 'Nachhaltige Pousada in einem umgebauten Container mit dem Sawabona-Erlebnis, dazu ein charmantes Café und Bistro mit handgemachten Spezialitäten wie Kuchen, Tee, Crêpes, Eis und Pralinen. Übernachtung im Container, verbunden mit Meditation und dem Genuss eines Panoramablicks in völliger Privatsphäre, dazu nachhaltige Praktiken wie ein Gemüsegarten in wiederverwendeten Reifen und weitere Beispiele.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 248, 'de', 'funcionamento', '12–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 249, 'de', 'descricao', 'Das Netzwerk Altos da Serramar besteht aus Landwirten, die in den Distrikten Mury, Lumiar und São Pedro da Serra (Nova Friburgo) sowie Barra Alegre (Bom Jardim) in der Bergregion des Bundesstaates Rio de Janeiro beeindruckende Initiativen mit nachhaltigen Praktiken für Landwirtschaft und Tourismus umsetzen. Die Betriebe, die sich durch einen hervorragenden Umweltschutz auszeichnen, liegen im Gebiet des Umweltschutzgebiets (APA) Macaé de Cima oder in dessen Umgebung. Der Agrotourismus vereint die Stärken der Region, indem er Umweltschutz mit Landwirtschaft und Tourismus verbindet, und ist ein starker Impuls für die Agrarökologie');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 249, 'de', 'funcionamento', 'Nur nach Voranmeldung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 250, 'de', 'descricao', 'Mosaik-Workshops (mit oder ohne Übernachtung), Naturerlebnisse zum Eintauchen (mit Mittagessen), Unterkunft, Mosaikatelier, herzliche Hausmannskost mit Produkten vom Hof (Holzofenherd) und Interaktion in Gesprächsrunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 250, 'de', 'funcionamento', '8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 251, 'de', 'descricao', 'Besichtigung des Erdbeergewächshauses mit mehr als 10.000 Pflanzen, in dem die Besucher sich fotografieren lassen und zu bestimmten Zeiten auch selbst Erdbeeren pflücken können. Für das Erdbeerpflücken bitte vorher Kontakt aufnehmen und sich erkundigen, da das Pflücken je nach Ernte nur in bestimmten Zeiträumen möglich ist. Außerdem gibt es einen großen, gemütlichen Laden mit reichlich Parkplätzen und vielen Süßwaren aus der Frucht, natürlichem Fruchtsaft, dem hauseigenen Pastel mit selbstgemachtem Teig sowie vielen weiteren Produkten kleiner Erzeuger aus unserer Region und unserem Bundesstaat.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 251, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 252, 'de', 'descricao', 'Unsere Konditorei bietet ihren Gästen eine Tour durch die Erdbeergewächshäuser der Cabana dos Morangos an. Lernen Sie den Erdbeeranbau und die bäuerliche Familienlandwirtschaft kennen. Vor Ort werden frisch gepflückte Erdbeeren sowie handgemachte Produkte verkauft.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 252, 'de', 'funcionamento', 'Di 13–18 Uhr / Mi bis So 10–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 253, 'de', 'descricao', 'Geführte Touren zu ländlichen Betrieben auf den wichtigsten Öko-Rural-Routen von Petrópolis. Persönliche Begleitung für Touristen und Besucher, mit Geschichte, Kultur und Informationen zu jedem besuchten Ort.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 253, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 254, 'de', 'descricao', 'Geführte Besichtigung der Fabrik und Verkostung der Produkte. Nachhaltigkeit und Bioproduktion.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 254, 'de', 'funcionamento', '11–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 255, 'de', 'descricao', 'Einblick in die lokale Kunsthandwerksproduktion. Praktischer Austausch mit den Stickerinnen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 255, 'de', 'funcionamento', 'Nur nach Voranmeldung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 256, 'de', 'descricao', 'Technische Einblicke in die Keramik, eine einzigartige Aktivität in ihrer Art.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 256, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 257, 'de', 'descricao', 'Besichtigung einer Manufaktur für natürliche Hundeleckerlis mit Verkostung für Hunde und neugierige Menschen. Unsere Produkte sind natürlich, ohne Farb- und Konservierungsstoffe oder Chemie und werden aus frischen, sorgfältig ausgewählten, lokal angebauten Zutaten hergestellt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 258, 'de', 'descricao', 'Ein Besuch zwischen den Bio-Pflanzungen, bei dem die Gäste auf Wunsch selbst ernten können. Ein unglaubliches Erlebnis! Der Besitzer zeigt den Besuchern, wie man Blattgemüse und Gemüse verwendet, und stellt einige Tees aus Heilkräutern vor. Seit 40 Jahren arbeitet er mit Bioprodukten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 258, 'de', 'funcionamento', '9–14 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 259, 'de', 'descricao', 'Vira-Mundo ist ein gemeinnütziges Gemeinschaftsprojekt, das auf dem Austausch von Wissen, Erfahrungen und Ideen beruht – für das Wohlergehen des Einzelnen, der Gemeinschaft und der Umwelt, die uns umgibt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 259, 'de', 'funcionamento', '9–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 260, 'de', 'descricao', 'Geführte Jeeptouren zu den Betrieben der Öko-Rural-Route Caminhos do Brejal. Einen vergleichbaren Anbieter gibt es nicht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 260, 'de', 'funcionamento', '7–22 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 261, 'de', 'descricao', 'Betrieb, der Bonsai, biologische Setzlinge von Gewürz-, Küchen- und Heilkräutern, Obstbäume, Zierpflanzen und heimische Bäume, Honig, Marmeladen und eingemachtes Obst erzeugt. Bio-Setzlinge, Produktion im Einklang mit der Umwelt, mit reduziertem CO₂-Ausstoß, unter Nutzung dessen, was die Natur uns als Ressourcen bietet, und mit möglichst wenig industriellen Betriebsmitteln. Ein Anwesen mit viel Wald auf dem Gelände und in der Umgebung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 261, 'de', 'funcionamento', '8–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 262, 'de', 'descricao', 'Besuch einer Schneckenzucht mit Verkostung und Verkauf des Produkts. Ohne Konkurrenz, ein einzigartiges Erlebnis im ganzen Land.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 262, 'de', 'funcionamento', '7–22 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 263, 'de', 'descricao', 'Landerlebnis mit biologischer Erzeugung und Haltung von Legehennen. Kommunikation, Gastfreundschaft und Liebe zu dem, was wir tun.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 263, 'de', 'funcionamento', 'Ab 10 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 264, 'de', 'descricao', 'Gourmet-Verkostung, Mittagessen. Erlebnis mit PANCs (unkonventionelle essbare Pflanzen).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 265, 'de', 'descricao', 'Traditionelles Landessen vom Holzofenherd, Wandern, Klettern, Camping, Wasserfall mit Naturpool, Fahrradverleih und Day Use. Vergleichbare Angebote gibt es nicht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 266, 'de', 'descricao', 'Ein wunderbares Haus namens „Sítio Vaca do Brejo“. Ohne falsche Bescheidenheit: ein „Fünf-Sterne-Haus“ im Brejal! Unvergleichlich in Ausstattung und Komfort! Von einem beheizten Infinity-Pool über Spielplätze für Kinder und Erwachsene und einen Spielesaal bis hin zu superbequemen Suiten mit Panoramablick! Neben dem traditionellen Kamin verfügt das ganze Haus über Heizung und Kühlung! Und obendrein ein hervorragender, unwiderstehlicher Gourmetbereich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 267, 'de', 'descricao', 'Natur und Gastronomie. Persönliche Präsenz der Besitzer und menschliche Zuwendung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 267, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 268, 'de', 'descricao', 'Natur und Gastronomie. Persönliche Präsenz der Besitzer und menschliche Zuwendung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 268, 'de', 'funcionamento', '8–20 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 269, 'de', 'descricao', 'Sportliche Wanderung, Yoga in der Höhe, Spaziergang durch einen Wald bis zum Lageado (eine Anhöhe gegenüber der Pedra do Elefante, in 300 m Höhe), mit Pranayama-Yoga (Atemübungen) und transzendentaler Meditation bei der Ankunft am Lageado. Atemberaubender Blick, der Ausflug endet an einer kristallklaren Quelle auf 300 m Höhe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 269, 'de', 'funcionamento', '8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 270, 'de', 'descricao', 'Zucht von Milch- und Wollziegen und Verkauf von Zuchttieren. Geflügelhaltung mit verschiedenen Vogelarten. Imkerei. Verkauf von Hofprodukten (Eier, Honig, Käse, Marmeladen, Kapern, einige Pflanzenarten). Gemüse und Obst aus Garten und Obstgarten je nach Jahreszeit. Bromeliensammlung. Geführter Besuch der verschiedenen Tierhaltungen und Wanderung mit Panoramablick auf die Pedra do Elefante und die Maria Antônia. Vielfältige Attraktionen und Betreuung auf Englisch, Italienisch und Spanisch sowie Portugiesisch.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 270, 'de', 'funcionamento', '9–12 Uhr und 14–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 271, 'de', 'descricao', 'Familiäre Atmosphäre, eigener Parkplatz, Hühnerstall. Holzofenherd, Parkplatz, Tische im Freien, Kinderschaukeln.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 271, 'de', 'funcionamento', '11.30–16.30 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 272, 'de', 'descricao', 'Dulce de leche (von Kunden mit dem uruguayischen verglichen) und handwerklich hergestellter Käse nach Canastra-Art. Alles stellen wir selbst her, vom Honig über Eier und 60 Sorten Süßwaren, Marmeladen und Chutneys bis zu 3 Sorten handwerklichem Käse');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 272, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 273, 'de', 'descricao', 'Handgemachte Produkte aus der Region und Craftbier mit Snacks. Sehr vielfältige, hochwertige Produkte aus der Region.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 273, 'de', 'funcionamento', 'Fr 14–22 Uhr; Sa 10–22 Uhr; So 10–14 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 274, 'de', 'descricao', 'Verkostung von handwerklichem Fassbier und Snacks.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 274, 'de', 'funcionamento', 'Do und Fr 14–22 Uhr und Sa 14–22 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 275, 'de', 'descricao', 'Pädagogischer Tourismus mit Schwerpunkt Umweltbildung. In der Region gibt es nichts Vergleichbares.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 275, 'de', 'funcionamento', 'Mo bis Fr 9–16 Uhr; So 10–14 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 276, 'de', 'descricao', 'Auf der Fazenda Sertão ist die Anbaufläche vollständig der syntropischen Landwirtschaft gewidmet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 277, 'de', 'descricao', 'Spa, Radtouren, Restaurant.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 277, 'de', 'funcionamento', 'Do und So 8–17 Uhr; Fr und Sa 8–23 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 278, 'de', 'descricao', 'Verleih von Ponys und Pferden und kleiner Streichelzoo. Kontakt mit der Natur, wunderbares Klima in der Region, gemütlicher und familiärer Ort.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 278, 'de', 'funcionamento', '9–11.30 Uhr und 13–14.30 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 279, 'de', 'descricao', 'Landcafé und vegane Leckereien. Ein Ort, an dem man vegane Produkte genießen und soziale Projekte von öffentlichem Interesse kennenlernen und mit ihnen in Austausch treten kann.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 279, 'de', 'funcionamento', 'Mi bis So 10–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 280, 'de', 'descricao', 'Geführte Jeeptouren zu den Betrieben der Öko-Rural- und Gastronomie-Route von Secretário. Einen vergleichbaren Anbieter gibt es nicht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 280, 'de', 'funcionamento', '7–22 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 281, 'de', 'descricao', 'Kühe melken und Molkerei. Handwerkliche Herstellung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 281, 'de', 'funcionamento', '9–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 282, 'de', 'descricao', 'Historisch und gastronomisch. Route des Küchenchefs, Gewinner des Nationalen Tourismuspreises');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 282, 'de', 'funcionamento', 'Fr 12–22 Uhr; Sa 12–22 Uhr; So 12–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 283, 'de', 'descricao', 'Oka Orgânicos ist ein kleiner landwirtschaftlicher Betrieb, der 2015 mit Gemüse begann und später die Haltung von Hühnern für die Eierproduktion hinzufügte, beides von Abio zertifiziert. Vor Ort kann man die Hühnerställe und den Gemüsegarten besichtigen. Für Rollstuhlfahrer nicht geeignet, da es sich um hügeliges Gelände handelt. Ein vollständig nachhaltiger Betrieb, der die Fläche voll nutzt und mit Obstbäumen und heimischen Pflanzen aufforstet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 283, 'de', 'funcionamento', '9–11 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 284, 'de', 'descricao', 'Eine strenge Auswahl hochwertiger Produkte und aufmerksamer Kundenservice. Hier kaufen Sie handgemachte Produkte verschiedener Erzeuger der Region. Sie können einen köstlichen Kaffee oder ein Craftbier genießen, hervorragende Käsesorten probieren und sich in einer sympathischen, interessanten und einladenden Atmosphäre wohlfühlen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 284, 'de', 'funcionamento', 'Di 11–18 Uhr; Mi und Do 9–18 Uhr; Fr, Sa und So 9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 285, 'de', 'descricao', 'Ein idyllisches Häuschen im Zentrum von Secretário, das nicht nur ein Kunstraum ist, sondern auch Kaffee und weitere Souvenirs unserer historischen Region anbietet. Der im Zentrum von Secretário gelegene Raum ist der Kunst und dem Verkauf von Souvenirs aus unserer historischen Region gewidmet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 285, 'de', 'funcionamento', 'Fr und Sa 9–18 Uhr / So 10–15 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 286, 'de', 'descricao', 'MTB experience. Wir sind auf Verleih, Verkauf und Wartung von Fahrrädern spezialisiert.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 286, 'de', 'funcionamento', 'Freitag, Samstag und Sonntag');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 287, 'de', 'descricao', 'Italienische Küche und bald auch Unterkunft nach dem Vorbild des Wohnens bei Gastgebern. Der Charme, wie zu Hause empfangen zu werden, italienischer Akzent, ein einzigartiges kulinarisches Erlebnis, handwerklich gebackenes Brot, alles mit Liebe zubereitet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 287, 'de', 'funcionamento', 'Freitag, Samstag und Sonntag');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 288, 'de', 'descricao', 'Kunsthandwerk, Qualitätsprodukte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 288, 'de', 'funcionamento', 'Mi bis Fr 12.30–16 Uhr; Sa 9–17 Uhr; So 9–13 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 289, 'de', 'descricao', 'Direkt neben dem Nationalpark Serra dos Órgãos in Petrópolis gelegen, 1,3 km von der Parnaso-Zentrale entfernt, tanken Sie auf 17 Hektar inmitten von Natur und Wildtieren neue Energie, mit allem Komfort und aller Ausstattung für einen möglichst entspannenden Aufenthalt. Die Quinta das Nascentes ist ein Ort, an dem Sie eine große Bio-Anbaufläche der Bergstadt vorfinden und an ihrer Entwicklung und Gestaltung teilhaben können. Sie werden von den Besitzern, die auf der Quinta wohnen, herzlich empfangen. Sie erwartet ein qualitätvoller Aufenthalt mit Respekt und ohne Vorurteile. Das Eintauchen in das Ökosystem des Atlantischen Regenwalds auf organische Weise, mit seinen klimatischen und landschaftlichen Besonderheiten, macht den Ort zum perfekten Ziel für Beobachtungstourismus.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 289, 'de', 'funcionamento', 'Freitag bis Sonntag');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 290, 'de', 'descricao', 'Restaurant direkt am Wasserfall mit raffiniert-rustikalem Flair, mit Selbstbedienungsbuffet vom Holzherd, hausgemachtem Geschmack und sehr abwechslungsreicher Speisekarte. Umgeben von Wasserfällen mitten in der Natur, mit herrlichen Sonnenuntergängen!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 290, 'de', 'funcionamento', '10–19 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 291, 'de', 'descricao', 'Speisen vom Holzherd, Essen im Freien, schöne Landschaft. Sehr gute Qualität, hervorragende Würze, guter Service, ein Erlebnis auf dem Land.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 291, 'de', 'funcionamento', 'Montag bis Freitag, 12–16 Uhr; Samstag und Sonntag, 12–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 292, 'de', 'descricao', 'Einen Ort zum Plaudern zu finden, ist leicht. Doch die Bar do Horto bietet mehr: ein eiskaltes Bier zum berühmten traditionellen Pastel des Hauses, eine angenehme Atmosphäre und eine abwechslungsreiche Speisekarte vom Frühstück bis zu Snacks, mit handwerklich gebrannter Cachaça und Bieren. Sie liegt in Itaipava, in der Stadt Petrópolis, Rio de Janeiro, im Inneren des Hortomercado.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 292, 'de', 'funcionamento', '8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 293, 'de', 'descricao', 'Ausstellung eines Kollektivs von 30 Kunsthandwerkern der Region, mit Empfang im Laden durch D Pedro II und Tereza. Zu sehen sind handgefertigte Stücke aus wiederverwerteten Materialien, eigene Entwürfe und Souvenirs. Hier finden Sie exklusive Stücke und die Kulturstationen, die ein wenig von der Geschichte der Stadt erzählen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 293, 'de', 'funcionamento', 'Montag bis Samstag, 10–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 294, 'de', 'descricao', 'Besichtigung nach Voranmeldung der Produktion von roten und gelben Paprika. Auf dem Gelände befindet sich eine Höhle. Kaffee (vormittags/nachmittags) und Mittagessen vor Ort. Wunderbare Landschaft, und auf dem Grundstück gibt es eine Höhle, die besichtigt werden kann.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 294, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 295, 'de', 'descricao', 'Das Konzept ist ein Sinneserlebnis, bei dem die verschiedenen Blends mit der Landschaft der Umgebung harmonieren. In unterschiedlichen Ausführungen, einer Reserva und einer Reserva Especial, bietet sie eine Vielfalt an Geschmacksrichtungen, mit Cachaças, die in verschiedenen brasilianischen Hölzern gelagert werden. Die Cachaça Imbaúba wird vollständig in Handarbeit hergestellt. Unser Wunsch ist es, den Kunden ein hochwertiges Produkt zu bieten, das von Gemütlichkeit, Familienarbeit, Nachhaltigkeit und der Liebe zur Stadt Teresópolis geprägt ist. Wir befinden uns in einer der schönsten Gegenden der Bergregion von Rio de Janeiro.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 295, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 296, 'de', 'descricao', 'Bei einer Führung lernen Sie die Ziegen und die Käseherstellung kennen, besuchen den Laden und das Restaurant, probieren verschiedene Käsesorten und können Produkte aus Ziegenmilch wie Shampoos, Seifen und Cremes kaufen. Vor Ort befindet sich das Restaurant Cremerie Genève, das frischen Käse zusammen mit Gerichten aus Zutaten des Hofes und vor Ort gebrautem Bier serviert. Lebensmittelproduktion, Käseherstellung, Laden, Verkostung und Restaurant');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 296, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 297, 'de', 'descricao', 'Besichtigung der Produktion von 100 % Bio-Milch und ihrer Erzeugnisse wie frischem Minas-Käse, Ricotta, Dickmilch, Hüttenkäse und Joghurt. Vale das Palmeiras ist seit 1997 Bio-zertifiziert. Privates Naturerbe-Reservat (RPPN) Rildo de Oliveira Gomes II. Auf einer Fläche von 200 Hektar wurde die Farm durch einen einfachen und praktikablen Renaturierungsplan wiederhergestellt, der die Quellen, die gesetzliche Reservefläche und die dauerhaften Schutzgebiete einzäunte und die einheimische Vegetation sich von selbst wieder erholen ließ');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 297, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 298, 'de', 'descricao', 'Besuch der Destillerie Serra dos Órgãos, Herstellerin von handwerklich gebranntem Gin');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 298, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 299, 'de', 'descricao', 'Interaktives Wissensmuseum mit Bildern und Aromen; nur nach Voranmeldung. Hostel. Mit einer Saatgutbank für die Wiederaufforstung will das Museu do Futuro den Schutz des Atlantischen Regenwaldes vermitteln und fördern. Die Initiative geht auf die NGO Museu do Futuro zurück, die in ökologische Bildung investiert und 20.000 m² einheimischen Waldes im Schutzgebiet des Parks Três Picos erworben hat. Das Gelände liegt mitten im Atlantischen Regenwald, direkt am Wasserfall Cachoeira dos Frades. Im Hauptgebäude des Museums mit seiner ökologischen Architektur finden Kurse, Forschungsarbeiten und Kulturveranstaltungen statt. Es gibt Seminare zu Ökologie, Pädagogik, Kunst, Architektur und Nachhaltigkeit. Das Museum bietet außerdem ökologische Therapien an, mit ausgewogener Ernährung, energetischen Massagen, Atemtechniken und mehr, um den Menschen mit der Natur zu verbinden. Besuch nach Voranmeldung. Zu den aktuellsten Angeboten vor Ort zählen: Meditation; Selbsthilfetechniken; Coaching; Biodanza; Vibrationstherapie in Hertz; Kosmobiologie für Privatpersonen und Unternehmen; unter anderem, entsprechend einem neuen weltweiten Trend in diesem Tourismussegment');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 299, 'de', 'funcionamento', '8–13 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 300, 'de', 'descricao', 'Bio-Produktionsbetrieb, angeschlossen an die AAT - Agroökologische Vereinigung von Teresópolis. Ökologischer Pflanzenbau (Obst, Gemüse, Blattgemüse und Getreide), Freilandtierhaltung (Hühner, Enten, Kaninchen, Tilapia, Hühner- und Enteneier). Geführte Tour zum Erleben des Landlebens: Säen, Pflanzen und Ernten von Bio-Produkten (selbst pflücken und bezahlen), mit mehr als 400.000 m² Atlantischem Regenwald für Wanderungen auf Pfaden sowie Alleen innerhalb der Anbauflächen, gesäumt von verschiedenen Obstbäumen. Brincarte-Bereich für die Kinder mit vielen Möglichkeiten (Baumschaukeln, Reifenparcours durch den Schaukelbaum, Reifentrampolin, Rasenrutsche, Minigolf auf Rasen, Rasenplatz). Bicharada-Bereich mit kleinem Teich, Enten, Hühnern und Kaninchen. Hängemattenbereich mit mehreren Hängematten zum Ausruhen. Gastronomiebereich mit Gourmet-Veranda, ausgestattet mit Holzherd und Grill, wo traditionelle ländliche Mahlzeiten serviert werden (Frühstück, Mittagessen und Nachmittagsimbiss). Ländliche Unterkunft für Gruppen im Haupthaus (Suite + Zimmer + bewohnbares Zwischengeschoss) und in einem Nebengebäude mit zwei Suiten mit Doppelzimmern, für Gruppen von bis zu 24 Personen. Campingplatz.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 300, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 301, 'de', 'descricao', 'Bietet Besuchern die Möglichkeit, den Alltag auf dem Land und des Landwirts zu erleben: Gemüse und Salat direkt im Garten anfassen; Setzlinge verschiedener Pflanzen und Gemüsesorten pflanzen; die eigene frische Nahrung ernten und einige vor Ort hergestellte Produkte wie Marmeladen und Craft-Biere kaufen. Es gibt eine offene Küche, in der ein hausgemachtes Mittagessen vom Holzherd mit auf dem Hof angebauten Zutaten serviert wird. Rucola, Spinat und Brokkoli. Die Marmeladen werden aus Früchten vom Hof hergestellt; unsere Biere werden noch nicht außer Haus verkauft und können auf dem Hof getrunken werden. Sie werden meist aus unseren eigenen Erzeugnissen und unserem eigenen Hopfen gebraut, und wir machen Witbiers mit Rucola, Orange, sizilianischer Zitrone und Zitronengras.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 301, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 302, 'de', 'descricao', 'Übernachtung, Mahlzeiten und Rundgang durch die Bereiche der Bio-Eierproduktion.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 302, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 303, 'de', 'descricao', 'Bio-Obst, -Wurzelgemüse und -Blattgemüse. Besichtigung der Bio-Produktion. Gourmet-Bereich mit Grill, Ofen und Holzherd; Wanderwege, kleiner Wasserfall; autarkes, komplett eingerichtetes Haus mit zwei Schlafzimmern, eines mit Doppelbett und eines mit drei Einzelbetten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 303, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 304, 'de', 'descricao', 'Unterkunft; Frühstück; Restaurant; Wanderwege mit Führern; Angelsee; indigene Dekoration; für Kinder nicht empfehlenswert; ideal für Gruppen; Referenzzentrum für Aquakultur und Hydroponik. Mit Sauna; Fußball-/Volleyballfeld; Schwimmbad und WLAN in den Gemeinschaftsbereichen. Räume für Workshops und Veranstaltungen: rustikaler Besprechungsraum in entspannter, schlichter Atmosphäre für bis zu 40 Personen. Ausstattung: Fernseher, Video, Diaprojektor, Freilufttheater für 80 Personen. Ideal für Erlebnisse, Rollenspiele und Theateraufführungen');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 304, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 305, 'de', 'descricao', 'Bio-Produktionsbetrieb, angeschlossen an die AAT - Agroökologische Vereinigung von Teresópolis. Spezialisiert auf Setzlinge und Bio-Dünger. Besichtigung und praktisches Erleben der Produktion von Setzlingen, Bio-Dünger und alternativen ökologischen Betriebsmitteln für den Anbau. Besichtigung und praktisches Erleben beim Anpflanzen von Bio-Produkten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 305, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 306, 'de', 'descricao', 'Ausstellung und Werkstatt zur Herstellung von Volksspielzeug; Werkstatt für Riesenpuppen. Es gibt Räume für kleine Veranstaltungen und begleitete Besuche für Touristen- und Schulgruppen, mit Verkauf lokaler Produkte und einer Ausstellung von Volksspielzeug. Kleiner Gemüsegarten. Ein Ort zum Schutz des Waldes, der wilden Tiere, des Spielzeugs und der Spiele sowie der traditionellen Volkskulturen. Hier setzt man sich dafür ein, die Werte der Familie, der freien Zeit, der Begegnung und der guten Praktiken des Landlebens wiederzubeleben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 306, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 307, 'de', 'descricao', 'Das Sobrado (Stadthaus) beherbergt und vermittelt einen Teil der Geschichte von Teresópolis: den Lebensweg des italienischen Einwanderers José Francisco Lippi und die Anfänge des Dorfes Venda Nova. Neben Dokumenten, Fotos, Möbeln und Räumen aus dem späten 19. Jahrhundert gibt es Gärten zum Spazierengehen zwischen Blumen, Obstbäumen und Vögeln. Auf 5.000 Quadratmetern laden Ecken, Winkel und viel Charme die Besucher ein und rühren die Herzen der Kinder. Schulbesuche sowie Besuche von Gruppen und Forschenden nach Voranmeldung. Jabuticaba-Marmelade und -Likör, unter anderem aus weiteren Früchten, sowie Süßwaren.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 307, 'de', 'funcionamento', 'Samstag, Sonntag und feiertags, 13.30–17.30 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 308, 'de', 'descricao', 'Bio-Produktionsbetrieb, angeschlossen an die AAT - Agroökologische Vereinigung von Teresópolis. Anbau von Bio-Gemüse, Obstbäumen, Hülsenfrüchten und Kräutern. Praktisches Erleben von Pflanzen und Ernten');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 308, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 309, 'de', 'descricao', 'Besichtigung der Produktion von Bio-Marmeladen und -Kompotten; Bio-Liköre.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 309, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 310, 'de', 'descricao', 'Ausritte, Reitunterricht nach Voranmeldung und Spa-Angebote. Schwimmbad, Sauna, Wohnzimmer, Spielzimmer, Videoraum und Fitnessraum. Pousada (Gasthaus).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 310, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 311, 'de', 'descricao', 'Hotelfarm mit zahlreichen Öko-Wanderwegen, dem größten See der Region und Abenteueraktivitäten in der Natur wie Hochseilgarten, Seilrutsche mit 500 m Seil und Kletterwand. Auf dem Boa Vida leben verschiedene Tiere wie Hühner, Enten, Ponys, eine Kuh und mehr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 311, 'de', 'funcionamento', 'Samstag und Sonntag, 8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 312, 'de', 'descricao', 'Die Hotelfarm bietet Frühstück, Mittag- und Abendessen, Getränke gehen extra. Es gibt ein Team von Kinderbetreuern, abends Live-Musik und sonntagmorgens eine Zirkustruppe unter Leitung von Clown Fiapo und seinen Freunden. Trockensauna, Spielsaal und Restaurant mit Panoramablick, Kapelle für religiöse Zwecke, Schwimmbad, Fußballplatz, Volleyballfeld, Seilrutsche, Ausritte, Massagetherapie und Grill.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 312, 'de', 'funcionamento', '10–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 313, 'de', 'descricao', 'Die Hotelfarm erstreckt sich über mehr als 7.500.000 m², mit 15 Stauseen und einem Urwaldgebiet mit Wasserfällen und Kaskaden, in dem man Tiere der Region antreffen kann, dazu Rinderzucht, Mangalarga-Marchador- und Pampa-Pferde sowie kleine Hoftiere. Es gibt 4 Schwimmbäder, 3 Sportplätze, einen Spielsaal, einen Konferenzraum, einen Fernsehraum, einen Spielplatz, Ausritte, Tretboote, eine Seilrutsche und einen Hochseilgarten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 313, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 314, 'de', 'descricao', 'Die Anlage bietet ein Restaurant, eine Piano-Bar, zwei Außenpools (einer davon mit Rutsche), einen Fitnessraum, Tennisplätze und eine Laufbahn sowie Saunen und einen überdachten Außen-Whirlpool. Weitere Aktivitäten sind Ausritte und Minigolf. Ruderboote stehen zur Verfügung, und die Gäste sind eingeladen, mit den Tieren auf dem Hof in Kontakt zu treten. Vielfältige Freizeitmöglichkeiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 314, 'de', 'funcionamento', '10–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 315, 'de', 'descricao', 'Die Anlage bietet eine Lounge zum Spielen und DVD-Schauen, einen Naturpool, einen Wasserfall, Wanderwege, ökologische Wanderungen, Ausritte, Auftritte von Performance- und Musikgruppen, Workshops, Kochkurse für indische und laktovegetarische Küche, Mantras, Tanz, eine Bio-Sauna, einen Spielsaal, Yoga, Vorträge, Thermalbäder, einen Aufenthaltsraum, einen Veranstaltungssaal, eine Panoramaterrasse, ein laktovegetarisches Restaurant und ein Zentrum für Naturheilverfahren.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 315, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 316, 'de', 'descricao', 'Die Hotelfarm liegt auf einem Grundstück von 960.000 m², davon 600.000 m² geschützter Atlantischer Regenwald, durchzogen von einem Pfad, der an einem Aussichtspunkt mit 360°-Panoramablick endet. Es gibt Tretboote, eine Seilrutsche (abhängig von Gewicht und Alter), einen Spielsaal, einen Billardraum (für Erwachsene), eine Wasserrutsche, ökologisches Angeln, beheizte Pools für Erwachsene und Kinder, Freibäder für Erwachsene und Kinder, Trocken- und Dampfsauna, Karaoke, eine „Bicholândia“ (Tierecke), ein Volleyballfeld, einen Fußballplatz, ein Boccia-Feld, Pferde (für Kinder), einen Tennisplatz (die Tennisausrüstung muss mitgebracht werden), eine Wasserrutsche und weitere Freizeitangebote.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 316, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 317, 'de', 'descricao', 'Das Hotel liegt mitten in einem 100 Hektar großen Privatpark auf 1.250 m Höhe und bietet drei Restaurants zur Auswahl. Zu den Freizeitmöglichkeiten gehören 10 Kilometer interne Wanderwege für ökologische Ausflüge, eine Reitbahn, Stallungen, Pferde, Tennis-, Volleyball- und Fußballplätze (Society-Fußball), zwei solarbeheizte Pools und ein Außen-Whirlpool mit Hydromassage, Boot und Kajaks sowie Sportangeln in einem Bergsee, der von Quellen und unverschmutztem Regenwasser gespeist wird.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 317, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 318, 'de', 'descricao', 'Traditionelles Restaurant, das seit mehr als 30 Jahren ununterbrochen geöffnet ist und Familienrezepte serviert. Für das Restaurant gibt es einen hydroponischen Gemüsegarten, der besichtigt werden kann. Verkauf von handwerklich gebrannter Cachaça, Bier, hauseigener Räucherwurst, Süßwaren, Honig, Pfeffer und Palmherzen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 318, 'de', 'funcionamento', '8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 319, 'de', 'descricao', 'Restaurant mit französischem Touch und Rezepten, in denen Ziegenkäse verwendet wird. Es gibt einen Mini-Spielplatz und freien Zugang zu den Tieren - Ziegen- und Hühnerhaltung. Besuch der Käserei (Herstellungsprozess und Verkostung) nach Voranmeldung sowie eine Kapelle zur Besichtigung. Herstellung von Craft-Bier, das nur vor Ort ausgeschenkt wird.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 319, 'de', 'funcionamento', 'Donnerstag, 12–17 Uhr; Freitag und Samstag, 10–22 Uhr; Sonntag, 10–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 320, 'de', 'descricao', 'Italienische Küche und ein Ambiente, das an eine echte italienische Cantina erinnert. Ideal für alle Altersgruppen und jede Art von Gruppen und Familien.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 320, 'de', 'funcionamento', 'Donnerstag, 11.30–15 Uhr; Freitag, 11.30–16 Uhr und 19–22 Uhr; Samstag, 11.30–16 Uhr und 19–22 Uhr; Sonntag, 11.30–16.30 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 321, 'de', 'descricao', 'Tiefgekühlte Teigwaren und herzhafte Gerichte: Quiche, Empadão (herzhafte Pastete) und Pfannkuchen, Brühen und Süßes. Nur mit Lieferservice.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 321, 'de', 'funcionamento', 'Mittwoch, Donnerstag und Freitag, 9–18.30 Uhr; Samstag, 9–14 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 322, 'de', 'descricao', 'Imbiss, Bäckerei und Konditorei. Feinkostladen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 322, 'de', 'funcionamento', '8–20 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 323, 'de', 'descricao', 'Brot und Süßwaren');
