INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 325, 'de', 'funcionamento', '11–24 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 326, 'de', 'descricao', 'Hausmannskost aus Minas Gerais. Spezialität des Hauses: Rippchen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 326, 'de', 'funcionamento', '8–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 327, 'de', 'descricao', 'Speisen vom Holzfeuer. Restaurant und Pousada (Gasthaus).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 327, 'de', 'funcionamento', '11–22 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 328, 'de', 'descricao', 'Restaurant mit Hausmannskost aus Minas Gerais. Am Eingang werden meist Kunstwerke ausgestellt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 328, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 329, 'de', 'descricao', 'Hausmannskost aus Minas Gerais. Am Wochenende Portionen zum Teilen und Brühen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 329, 'de', 'funcionamento', '11.30–15.30 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 330, 'de', 'descricao', 'Vielfalt an Vorspeisen, Nudelgerichten und Fleisch in einem rustikal eingerichteten Raum mit eleganter Atmosphäre und besonderem Schwerpunkt auf Weinen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 330, 'de', 'funcionamento', '12–23 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 331, 'de', 'descricao', 'Geschäft für antike, rustikale und restaurierte Möbel sowie Antiquitäten wie Kronleuchter, Gemälde, Raritäten, Kunstwerke und mehr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 331, 'de', 'funcionamento', 'Donnerstag bis Sonntag, 10–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 332, 'de', 'descricao', 'Slow-Food-Konzept, gewählt zu einem der 7 kulinarischen Wunder des Bundesstaates Rio de Janeiro. Die wichtigsten Produkte sind Süßwaren, handgemachte Marmeladen und herzhafte Snacks, alle zu 100 % natürlich und biologisch.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 332, 'de', 'funcionamento', 'Dienstag bis Sonntag, 11–21 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 333, 'de', 'descricao', 'Verkauf von Möbeln aller Art, Matratzen, Dekorationsartikeln und Haushaltswaren.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 333, 'de', 'funcionamento', 'Dienstag bis Sonntag, 11–21 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 334, 'de', 'descricao', 'Verkauf von Zutaten zum Bierbrauen und Kurse zum Brauen von Craft-Bier.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 335, 'de', 'descricao', 'Basar mit Dekorationsobjekten, Möbeln, Antiquitäten und Kunsthandwerk');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 335, 'de', 'funcionamento', '9.30–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 336, 'de', 'descricao', 'Einkaufszentrum mit Vermietung von Geschäften, Büroräumen, Kiosken und einer Fläche für ein Fitnessstudio. Es umfasst Geschäfte, ein Café, einen Lebensmittelladen, ein Fitnessstudio, Kunsthandwerk, Balaio, Immobilien und Sabor da Roça.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 336, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 337, 'de', 'descricao', 'Einkaufszentrum.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 337, 'de', 'funcionamento', '17–24 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 338, 'de', 'descricao', 'Herstellung von Holzmöbeln; Galerie im Aufbau mit traditionellem Restaurant');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 338, 'de', 'funcionamento', '7–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 339, 'de', 'descricao', 'Atelier für Möbel und nachhaltiges Kunsthandwerk. Angeboten werden Kunsthandwerk und Dekoration von 13 Kunsthandwerkern der Region, mit eigenen, nachhaltigen Stücken, die die lokale kulturelle Identität widerspiegeln.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 339, 'de', 'funcionamento', 'Mittwoch bis Samstag, 9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 340, 'de', 'descricao', 'Unterkunft mit Frühstück und/oder Vollpension; Kurse zu Bambusanbau und -behandlung; Tagesnutzung des Freizeitbereichs mit Swimmingpool, Fußballplatz und Grillstelle im Club Holiday. Hausgemachte Konfitüren und Eingemachtes; Bio-Gemüsegarten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 340, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 341, 'de', 'descricao', 'Frühstück; Mittagessen; Besichtigung der Produktion; Selbstpflücken und bezahlen. Familienlandwirtschaft und Bio-Erzeugung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 341, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 342, 'de', 'descricao', 'Biologische Erzeugereinheit, die der AAT - Associação Agroecológica de Teresópolis angehört. Biologischer Pflanzenanbau. Selbstpflücken und bezahlen, Waldspaziergänge, Minikurse, Mahlzeiten. Besichtigung nur nach Voranmeldung, mit oder ohne Führer.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 342, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 343, 'de', 'descricao', 'Biologische Erzeugereinheit, die der AAT - Associação Agroecológica de Teresópolis angehört. Bio-Gemüse und Honig. Kurse, Praktika und agroökologische Erlebnisaufenthalte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 343, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 344, 'de', 'descricao', 'Biologische Erzeugereinheit, die der AAT - Associação Agroecológica de Teresópolis angehört. Biologischer Anbau von Blattgemüse, Gemüse und Getreide. Angeln, Besichtigung der biologischen Produktion.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 344, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 345, 'de', 'descricao', 'Freilandeier und biologische Landwirtschaft. Bio-Gemüsegarten und Tierhaltung. See mit Tretbooten; Seilrutsche; Wanderwege; Frühstück; Mittagessen; Bio-Gemüsegarten; Tiere und Vögel.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 345, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 346, 'de', 'descricao', 'Biologische Erzeugereinheit, die der AAT - Associação Agroecológica de Teresópolis angehört. Ökologische Wanderwege und Spaziergänge, begleitetes Kennenlernen von Aussaat und Ernte, Angeln, Mahlzeiten, Übernachtung, Besuch des städtischen Bergparks, Kauf von Bio-Produkten, Vogelbeobachtung, Vorträge über Umweltbildung und Agroforstwirtschaft, Tierhaltung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 346, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 347, 'de', 'descricao', 'Biologische Erzeugereinheit, die der AAT - Associação Agroecológica de Teresópolis angehört. Vielfältiger Pflanzenanbau, vor allem Bananen, Zuckerrohr, Maniok, Mais, Kurkuma und Okra. Imkerei. Verarbeitung der Feldfrüchte zu Broten, Kuchen und Tapioka-Teig. Geführte Besichtigung der Anbauflächen und des Verarbeitungsbereichs, biologisches Mittagessen vom Land, Aktivitäten für Kindergruppen, Agrarökologie-Unterricht mit praktischer Aktivität für jedes Publikum, Entdeckung der PANCs (unkonventionelle essbare Pflanzen).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 347, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 348, 'de', 'descricao', 'Spaziergänge und Wanderwege; Besichtigung der Stallungen mit reinrassigen Pferden; Bio-Landwirtschaft, vor allem Gemüse, Gewürzkräuter und Blattgemüse.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 348, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 349, 'de', 'descricao', 'Forellenzucht und Forellenhandelsstelle');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 350, 'de', 'descricao', 'Biologische Erzeugereinheit, die der AAT - Associação Agroecológica de Teresópolis angehört. Bio-Hühnereier, Blattgemüse, Gemüse, Obstbäume und Honig. Eigener Badesee, Unterkünfte für 80 Personen, Fußball- und Volleyballplatz auf Rasen, Spaziergänge und Besichtigung des Produktionsbereichs.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 350, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 351, 'de', 'descricao', 'Organisation der ländlichen Erzeuger von Lúcios, Fortbildung der Landwirte, Kurse zur Hinführung zur Agrarökologie, technische Beratung, Gemeinschaftsküche; Saatgutbank; Werkstatt für Brot und Süßwaren aus Erzeugnissen vom Land. Aufbau eines Netzwerks von Erzeugerinnen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 351, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 352, 'de', 'descricao', 'Bio-Lebensmittel direkt von den Erzeugern. Gemüse, Blattgemüse, Obst, Eier, Honig, grüner Saft, Zuckerrohrsaft, Brot und Kuchen, hausgemachte Süßigkeiten, Bio-Setzlinge und -Dünger. Jeden Samstag Livemusik und Mittagessen, Spielplatz für Kinder, Kulturveranstaltungen, lokales Kunsthandwerk, Lieferung von Obst- und Gemüsekörben nach Hause. Kostenlose Parkplätze für Kunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 352, 'de', 'funcionamento', '8–13 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 353, 'de', 'descricao', 'Biologische Erzeugereinheit, die der AAT - Associação Agroecológica de Teresópolis angehört. Bio-Blattgemüse, -Obst, -Gemüse und -Getreide, Konfitüren, Eingemachtes und Süßigkeiten. Besichtigung, Frühstück, Mittagessen oder Nachmittagsimbiss, Ernte von Produkten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 353, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 354, 'de', 'descricao', 'Selbstpflücken und bezahlen. Gärtnerei mit 3 Gewächshäusern. Angebotene Produkte: Orchideen, Bromelien, Bodendecker, Obstbäume, Dekosteine, Töpfe aus Ton, Polyethylen und Zement, Erden, Palmen, Bougainvillea, Rosensetzlinge, lebende Zäune, Gestecke und vieles mehr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 354, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 355, 'de', 'descricao', 'Übernachtung. Atlantischer Regenwald.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 355, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 356, 'de', 'descricao', 'Reiseveranstalter. Schwerpunkt: Ökotourismus. Spezialisiert auf Bierreisen. Verkauf von Inlands- und Auslandspaketen, Transferdienste, Verkauf von europäischen Bahntickets.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 356, 'de', 'funcionamento', '9–20 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 357, 'de', 'descricao', 'Reiseveranstalter mit Schwerpunkt auf Ökotourismus, Familienfreizeit, ländlichem Tourismus, Abseilen, Trekking, Trekking, Reitausflügen und ländlichen Erlebnissen. Abenteuertourismus.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 357, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 358, 'de', 'descricao', 'Reisebüro. Schwerpunkt: Ökotourismus. Spezialisiert auf ländlichen, gastronomischen und pädagogischen Tourismus. Ecoplay bietet Besuchern Erlebnisse, die die lokale Gemeinschaft wertschätzen und ein Umweltbewusstsein wecken. Verfügt über sechs ausgearbeitete Routen mit festen Preisen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 359, 'de', 'descricao', 'Incoming-Agentur. Schwerpunkt: Kultur (bürgerlich, ethnisch, religiös, mystisch und esoterisch). Spezialisiert auf gastronomischen, pädagogischen und kulturellen Tourismus (historisches Erbe). Agentur im Homeoffice.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 359, 'de', 'funcionamento', '8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 360, 'de', 'descricao', 'Reisebüro. Schwerpunkt: Incoming- und Outgoing-Tourismus, Kultur-, ländlicher, pädagogischer, religiöser, gastronomischer und Biertourismus sowie Ökotourismus. RÉTOUR war die erste Agentur, die in Teresópolis Incoming- und ländlichen Tourismus anbot, und ist seit mehr als 15 Jahren am Markt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 361, 'de', 'descricao', 'Angeln mit Bezahlung des Fangs (Pesque e Pague), Restaurant, Ausritte, Tierbesichtigung, Vermietung von Grillstellen sowie Bereich mit Swimmingpool, Sauna und Fußballplatz.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 361, 'de', 'funcionamento', 'Sa und So');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 362, 'de', 'descricao', 'Die Fazendinha Rio ist eine der besten Attraktionen von Vargem Grande, wenn Sie den Stadtteil mit Kindern besuchen möchten. Der Ort gilt als pädagogischer ländlicher Park, in dem die Kleinen mit Bauernhoftieren in Kontakt kommen, den Gemüsegarten und den Obstgarten kennenlernen, Ausritte unternehmen und sogar Kühe melken können.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 362, 'de', 'funcionamento', '10–17 Uhr – samstags, sonntags und an Feiertagen');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 363, 'de', 'descricao', 'Dort können Sie das Quilombo-Museum besuchen und die Gelegenheit nutzen, einige der Restaurants innerhalb der Gemeinschaft kennenzulernen. Das Bar da Nilza und das Bar e Restaurante Tá na Boa sind die bekanntesten vor Ort.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 363, 'de', 'funcionamento', 'Nur nach Voranmeldung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 364, 'de', 'descricao', 'Das ist Ihr Zoo in Guaratiba, in der Westzone von Rio de Janeiro. Wir verfügen über einen interaktiven Streichelzoo-Bereich, in dem Besucher Tiere wie Ponys, Lamas, Ziegen, Büffel und viele andere mit vom Park bereitgestelltem Futter füttern können. Die Begehbare Voliere ist der Höhepunkt der Interaktion, mit fast hundert Vögeln, die Ihnen aus der Hand fressen! (eine Portion Körner wird vom Park bereitgestellt)
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 364, 'de', 'funcionamento', '9–16 Uhr – Montag bis Freitag (Schulausflüge) | 9–16 Uhr – samstags, sonntags und an Feiertagen (freier Zugang)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 365, 'de', 'descricao', 'Route 1 - Fazenda Real de Santa Cruz: Vor Petrópolis verbrachte die Kaiserfamilie ihre Ferien in Santa Cruz.
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 365, 'de', 'funcionamento', 'Vorherige Buchung bei einem registrierten Führer erforderlich');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 366, 'de', 'descricao', 'Ländlicher Geschmack am Tisch: freies Buffet mit Landküche, die auf dem Holzofen zubereitet wird, ganz wie typisches Essen auf der Farm!
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 366, 'de', 'funcionamento', '7–18 Uhr – samstags, sonntags und an Feiertagen | 7–12 Uhr – Frühstück | 11–16 Uhr – Mittagessen');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 367, 'de', 'descricao', 'Geführte Ausritte, Restaurant');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 367, 'de', 'funcionamento', 'Samstags, sonntags und an Feiertagen');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 368, 'de', 'descricao', 'Reitunterricht für Anfänger');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 368, 'de', 'funcionamento', 'Nur nach Voranmeldung');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 369, 'de', 'descricao', 'Lernen Sie die Orte kennen, an denen die landwirtschaftlichen Erzeugnisse in einer Genossenschaft verarbeitet werden, mit Besuch der Felder, von denen die Produktion stammt. Erleben Sie den Alltag eines Landwirts, stets von einem Erzeuger begleitet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 369, 'de', 'funcionamento', 'Montag bis Samstag, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 370, 'de', 'descricao', 'Naturerlebnis und Besuch historischer Stätten der Region, die zur Kaiserzeit Brasiliens Schauplatz des Kaffeetransports aus dem Paraíba-Tal war, ebenso wie des Bananenzyklus im 20. Jahrhundert. Start am Sítio São João und Wanderung zur Cachoeira das Três Quedas zum Baden und Genießen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 370, 'de', 'funcionamento', '6–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 371, 'de', 'descricao', 'Die Guarani bewahren ihre überlieferten Traditionen wie Tänze und Gesänge, und die meisten sind zweisprachig, da sie neben Tupi-Guarani auch Portugiesisch sprechen. Die Bewohner führen ein einfaches Leben und bauen zur Selbstversorgung Lebensmittel wie Maniok, Bananen und Palmherzen sowie Heilpflanzen an. Ihre farbenfrohen Flechtarbeiten, Halsketten, Armbänder und Holzhandwerke sind bei Touristen sehr beliebt. Beim Besuch des Dorfes werden Sie durch Aktivitäten wie kulturellen Gesang, Körperbemalung, Gesprächsrunden, typische Speisen, einen geführten Rundgang und Vorführungen in die Kultur der Guarani eingeführt. Für Abenteuerlustige gibt es außerdem Aktivitäten wie eine geführte Wanderung zum schönen Cachoeira da Aldeia, Zielschießen mit dem Blasrohr und Bogenschießen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 371, 'de', 'funcionamento', 'Keine Angabe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 372, 'de', 'descricao', 'Ausflug zur Vogelbeobachtung (Birdwatching) im Atlantischen Regenwald mit seinen landschaftlichen Schönheiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 372, 'de', 'funcionamento', '6–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 373, 'de', 'descricao', 'Aiê Eletuloju: eine Tür zum Heiligen im Quilombo Santa Rita do Bracuí. Agrarökosystem, Erlebnisaufenthalte, Wanderwege, Vorträge, Workshops, Erzeugnisse vom Land, Kulturveranstaltungen, Unterricht in Ethnobotanik und Ethnoökologie, nachhaltige Bewirtschaftung. Ein agrarökologisches Zentrum mit Schwerpunkt Bildung, das sich um zentrale Achsen wie Quilombo, Candomblé und das breite Spektrum der Permakultur dreht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 373, 'de', 'funcionamento', '7–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 374, 'de', 'descricao', 'Ein Ort, um einheimische stachellose Bienen kennenzulernen, im Atlantischen Regenwald erzeugten Honig zu probieren und mehr über die Bedeutung der Bestäuber für die Gesundheit der Wälder zu erfahren. Geführte Tour durch eine Fachkraft mit Hochschulabschluss in Imkerei und Meliponikultur (Zucht stachelloser Bienen), Öffnen der Bienenkästen, Verkostung von Honigen und Früchten aus dem Obstgarten. Ein bei den Umweltbehörden zugelassenes und für Besucher geöffnetes Meliponarium, das Touristen empfängt und ein einzigartiges Erlebnis bei der Verkostung der Honige einheimischer Bienen der Costa Verde bietet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 374, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 375, 'de', 'descricao', 'Frühstück, Mittagessen, Camping. Beginn um 8:30 Uhr mit einem köstlichen Frühstück bis 10 Uhr, danach Wanderung zur Drahtseilbrücke und zum Wasserfall am Sítio São João, Rückkehr um 12 Uhr zum Mittagessen!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 375, 'de', 'funcionamento', '8–19 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 376, 'de', 'descricao', 'Besichtigung der einzigen Brennerei der Stadt - Cachaça Desinibida de Angra, mit Verkostung, Swimmingpools, Angeln mit Bezahlung des Fangs (Pesque e Pague), Wanderung zu einem wunderschönen Wasserfall und Kinderbereich. Die Besichtigung der Brennerei ist ein echtes Eintauchen in die Cachaça-Herstellung. Die Brennerei befindet sich im Hotel Fazenda Vira Country, das Angeln mit Bezahlung des Fangs, Swimmingpools, einen Kinderbereich und einen Wasserfall bietet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 376, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 377, 'de', 'descricao', 'Zeitgenössische Küche auf Basis von Meeresfrüchten, mit Rind- und Schweinefleischgerichten sowie einer Auswahl an Risotti. Bergatmosphäre, familiäres Ambiente und rustikale Einrichtung, in der die Gäste Wasserfälle und einen Naturpool mit kristallklarem Wasser genießen und dabei Natur und Vogelgesang erleben können.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 377, 'de', 'funcionamento', 'Donnerstag bis Sonntag, 12–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 378, 'de', 'descricao', 'Das Quilombo Santa Rita do Bracuí hat eine schöne Geschichte von Kampf und Tradition. Der gemeindebasierte Tourismus war das Mittel, mit dem die Quilombolas ihre Geschichte weitergeben und ein Einkommen erzielen. Angebote für Touristen: ein schöner Tag in der Gemeinschaft, Quilombola-Frühstück, Wanderweg, einfache Unterkunft, traditionelle Mahlzeiten, Workshops, Geschichtenerzählen und weitere Attraktionen. Alle Aktivitäten werden von den Quilombolas durchgeführt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 378, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 379, 'de', 'descricao', 'Gegenüber dem Touristenterminal Janete Dias de Aguiar gelegen, dem Eingangstor zur Vila do Abraão, der Hauptstadt der Ilha Grande, beherbergt das Gelände der Republica Educação Solidária eine Reihe symbolträchtiger Gebäude, die den Besucher mit der Gemeinschaft verbinden und ihn dazu bringen sollen, sich im Raum wiederzuerkennen, und so sein Zugehörigkeits- und Territorialitätsgefühl neu deuten. Unser Alleinstellungsmerkmal ist der Kurze Vermarktungskreislauf, bei dem wir die Möglichkeit bieten, die Bewohner kennenzulernen und direkt beim Erzeuger zu kaufen, dessen Raum kennenzulernen und beim Absatz seiner vielseitigen Produkte und Dienstleistungen zu helfen. Besuchsdauer: Um den Prinzipien der República Educação Solidária treu zu bleiben, gibt es keine festgelegte durchschnittliche Besuchsdauer, denn der Rundgang kann von wenigen Stunden bis zu einem ganzen Leben dauern.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 379, 'de', 'funcionamento', 'Keine Angabe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 380, 'de', 'descricao', 'Nativa da Ilha ist ein Kleinstunternehmen, das als Werkzeug mit sozialer Wirkung in der Region der Bucht von Ilha Grande geschaffen wurde. Seine Mission ist es, nicht nur die traditionellen Gemeinschaften zu unterstützen, sondern auch zu einem Bewusstsein für Respekt und Wertschätzung der Volkskultur beizutragen, indem es Produkte und Dienstleistungen anbietet, die zu einer neuen Perspektive und einem Bewusstsein beitragen, das verhindern hilft, dass traditionelle Identitäten verwässert werden. Unsere gemeindebasierten Tourismusrouten wollen einen gerechteren und inklusiveren Tourismus fördern, da sie die lokale Bevölkerung in die Hauptrolle setzen, um auf die Anforderungen der lokalen Ökosysteme zu reagieren und Einkommen und Eigenständigkeit für diese ländlichen Bevölkerungsgruppen zu schaffen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 380, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 381, 'de', 'descricao', 'Besuch der landwirtschaftlichen Betriebe der Genossenschaftsmitglieder und Einblick in den Alltag der Familienbetriebe, Mahlzeiten, Frühstück vom Land, Angeln in Seen, Baden im Fluss und mehr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 381, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 382, 'de', 'descricao', 'Kleiner Streichelzoo mit vielen Attraktionen. Freizeitbereich, Spielraum und Tiere für die Kinder. Restaurant nach Art von Minas Gerais. Ruhebereich nach dem Mittagessen, Freizeitbereich, Spaziergänge über das Gelände.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 382, 'de', 'funcionamento', 'Sonntags ab 11 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 383, 'de', 'descricao', 'Kleiner Bauernhof, Ausritte, Minizoo, Seen mit Fischen, Swimmingpools, Seilrutsche, Mahlzeiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 383, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 384, 'de', 'descricao', 'Ausritte, Reittherapie, Gangartprüfung (Marcha), kleiner Streichelzoo, Selbstpflücken und bezahlen, Kantine mit Kaffee (im Bau).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 384, 'de', 'funcionamento', 'Montag bis Samstag, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 385, 'de', 'descricao', 'Restaurant inmitten der Natur mit historischem Wanderweg und Wasserfall. Naturnähe in rustikalem, einladendem Ambiente mit Produkten aus der Familienlandwirtschaft.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 385, 'de', 'funcionamento', 'Donnerstag bis Sonntag, 9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 386, 'de', 'descricao', 'Ein Ort für nachhaltige Praktiken: Ökopfade, agrarökologische Lebensmittelproduktion, nachhaltige Bewirtschaftung der Juçara-Palme und Permakultur-Kurse.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 386, 'de', 'funcionamento', '9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 387, 'de', 'descricao', 'Die Agrarindustrie von Mangaratiba verarbeitet lokale Erzeugnisse, etwa getrocknete Bananen, Bananenmehl und verschiedene Süßwaren je nach lokaler Ernte. Im Gebäude hat die Vereinigung der Landwirte der Gemeinde ihren Sitz, die für die Verarbeitung und den Verkauf der Produkte zuständig ist. Der Ort hat zudem historische und kulturelle Bedeutung, da das Gebäude ganz in der Nähe der Ruinen von Saco de Cima liegt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 387, 'de', 'funcionamento', '8–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 388, 'de', 'descricao', 'Historische Farm aus der Kaffeezeit der ehemaligen Stadt São João Marcos, auch São João do Príncipe genannt. Sie liegt in der Serra do Piloto an der Kaiserstraße von São João Marcos, der ersten befahrbaren Straße Brasiliens. Die Farm ist für Besichtigungen geöffnet und bietet Übernachtung, ein Restaurant und einen Secondhandladen. Es gibt Pferde, einen Hühnerstall und Milchviehhaltung; produziert werden handwerklich hergestellter Käse, Bio-Bananen und Gemüse aus dem Garten. Das Herrenhaus ist gut erhalten und hat einen historischen Trockenplatz für Kaffee. Wanderwege führen durch den Atlantischen Regenwald, zu Quellen und zu einem natürlichen Badebecken.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 388, 'de', 'funcionamento', 'Am Wochenende, 11–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 389, 'de', 'descricao', 'Café mit gemütlicher Atmosphäre, sehr gelobtem Brot mit Wurst und Maismehlkuchen, Kunsthandwerk und Produkten vom Land.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 389, 'de', 'funcionamento', 'Freitag bis Sonntag, 7–20 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 390, 'de', 'descricao', 'Die Tour umfasst eine Fahrt im Geländewagen (4x4), eine historische Führung zu den Sehenswürdigkeiten entlang der Strecke (mit einem von Cadastur zertifizierten, auf Naturattraktionen spezialisierten Guide), eine Öko-Wanderung zum Aussichtspunkt am Stausee Ribeirão das Lajes und zur Ponte Bela, ein Snackpaket, ein Bad im Wasserfall, ein Mittagessen vom Holzfeuer (nicht inbegriffen) sowie eine Kranken- und Krankenhausversicherung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 390, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 391, 'de', 'descricao', 'Handwerkliche Brennerei mit biologischer Cachaça-Produktion, Hühnerhaltung mit Eiererzeugung, eine Froschfarm mit Besichtigungs- und Erlebnisangebot sowie ein Bienenstand mit Metproduktion.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 391, 'de', 'funcionamento', 'Keine Angabe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 392, 'de', 'descricao', 'Handwerkliche Brennerei mit Führungen und einem Laden mit großer Auswahl an handgemachten Produkten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 392, 'de', 'funcionamento', '9.30–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 393, 'de', 'descricao', 'Handwerkliche Brennerei mit herrlichem Blick auf die Berge und einem Laden mit lokalen Produkten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 393, 'de', 'funcionamento', '9.30–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 394, 'de', 'descricao', 'Die älteste noch in Betrieb befindliche handwerkliche Brennerei der Gemeinde, seit 1803, mit einem Laden für lokale Produkte am Firmensitz. Geführte Tour über das Brennereigelände mit Erklärungen zum Herstellungsprozess und der Geschichte des ältesten noch produzierten Cachaça der Gemeinde.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 394, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 395, 'de', 'descricao', 'Die einzige Brennerei der Gemeinde, die von einer Frau gegründet wurde und geleitet wird; sie überwacht alle Produktionsschritte persönlich und gibt dem Cachaça ihren Namen. Erlebnis mit Gesprächsrunde mit der Inhaberin, die die Schritte des Herstellungsprozesses und sogar die Geschichte des Cachaça in der Gemeinde Paraty erzählt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 395, 'de', 'funcionamento', '10–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 396, 'de', 'descricao', 'Eine der traditionsreichsten Brennereien von Paraty, seit Jahrzehnten in Familienbesitz und den Traditionen treu geblieben. Es gibt eine Tour mit Erklärungen zur Herstellung des Cachaça, und im Laden können alle Sorten verkostet werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 396, 'de', 'funcionamento', '7–12 Uhr und 13.30–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 397, 'de', 'descricao', 'Geführte Tour zur Geschichte des Cachaça Engenho D''Ouro. Auf dem Anwesen gibt es ein altes Maniokmehl-Haus, ein Restaurant und einen Laden für handgemachte Süßwaren; die Brennerei liegt neben dem Wasserfall Tobogã.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 397, 'de', 'funcionamento', '8.30–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 398, 'de', 'descricao', 'Sehr gut organisiertes Reisebüro mit mehr als 28 Jahren Erfahrung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 398, 'de', 'funcionamento', '8–21 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 399, 'de', 'descricao', 'Zugelassenes Reisebüro mit 12 Jahren Erfahrung in Paraty.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 399, 'de', 'funcionamento', '8–21 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 400, 'de', 'descricao', 'Reisebüro mit Schwerpunkt Ökotourismus, das individuell zugeschnittene Routen anbietet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 400, 'de', 'funcionamento', '6–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 401, 'de', 'descricao', 'Die im Quilombo lebenden Familien halten Traditionen wie Jongo und Capoeira sowie Geschichten und Wissen mit Wurzeln auf dem afrikanischen Kontinent lebendig. Der dortige Tourismus ist gemeindebasiert; zu den Hauptattraktionen zählen ein wunderschöner Wasserfall, Wanderwege, Ruinen aus der Zeit der Sklaverei, Gesprächsrunden und die traditionelle Küche, die die Besucher in einem Raum neben den Häusern der Bewohner genießen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 401, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 402, 'de', 'descricao', 'Pousada mit Spa und Restaurant. Restaurant, Freizeitbereich mit Pool, Spielzimmer, Tennisplatz, Sauna, Leselounge mit Hängematten und ein Wasserfall mit privatem Naturbecken auf dem Gelände der Pousada. Im Wellnessbereich befindet sich das Spa der Pousada mit Massagen, Therapien, Ofuro-Bädern und vielem mehr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 402, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 403, 'de', 'descricao', 'Gemeindebasierter Tourismus. Wertschätzung der Kultur und Identität der traditionellen Caiçara-Gemeinschaft von Trindade. Gesprächsrunde mit Fischern, Besuch der schwimmenden Fischfanganlage, Besuch des Maniokmehl-Hauses, Puppentheater, Foto-/Video-/Dokumentarfilm-Vorführung zur Geschichte von Trindade mit anschließender Diskussion, Folia de Reis, Kunsthandwerk-Workshop, Workshop zum Schnitzen und Nähen von Netzen und vieles mehr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 403, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 404, 'de', 'descricao', 'Auf dem Programm stehen agroforstwirtschaftliche Arbeit, Vogelbeobachtung und Ausflüge zu den Wasserfällen auf dem Gelände.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 404, 'de', 'funcionamento', '7–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 405, 'de', 'descricao', 'Die Fazenda Bananal ist ein unverzichtbares Ziel für Liebhaber des Landtourismus, mit 187 Hektar, die für Besucher geöffnet sind. Im Mittelpunkt steht die Nachhaltigkeit, die in allen Bereichen präsent ist: ökologisch, historisch-kulturell und sozial. Der Besuch der Fazenda Bananal ist individuell gestaltbar, die Besucher stellen ihre eigene Route zusammen. Die erste empfohlene Station ist das historische Herrenhaus, das vom IPHAN unter Denkmalschutz gestellt wurde und dessen ursprüngliche Struktur erhalten ist. Heute dient der Raum für Wechselausstellungen, die die Geschichte und Traditionen von Paraty erzählen. Die zweite Station ist ein Rundgang, der Modelle und Technologien vorstellt, die die Kraft und Intelligenz der Natur nutzen, um sauberere und nachhaltigere Produktionssysteme zu schaffen. Bei dem Rundgang lernt man den Agroforst, den Biogarten, die grüne Kläranlage, die Biogasanlage und weitere gute Praktiken im Umgang mit der Natur kennen. Der letzte Tipp ist ein Besuch im Restaurant, in dem köstliche Gerichte serviert werden, die je nach Saison der Lebensmittel variieren und lokale Zutaten bevorzugen. Der Agroforst und der Garten der Farm versorgen das Restaurant jährlich mit mehr als 60 verschiedenen Produkten, die ohne Pestizide oder chemische Düngemittel angebaut werden. Kurz gesagt: Die Fazenda Bananal ist ein beeindruckender Ort, der Entwicklung und Nachhaltigkeit verbindet, das historische und kulturelle Erbe bewahrt und bewussten Tourismus fördert. Wenn Sie mehr über nachhaltige Praktiken erfahren, köstliche Bio-Mahlzeiten genießen und einen individuellen Rundgang erleben möchten, besuchen Sie unbedingt die Fazenda Bananal!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 405, 'de', 'funcionamento', 'Montag bis Sonntag, 10–17 Uhr. Das Restaurant erfordert eine Reservierung im Voraus und ist von 12 bis 17 Uhr geöffnet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 406, 'de', 'descricao', 'Hergestellt auf der Fazenda Abadia, die seit mehr als 100 Jahren Zuckerrohr anbaut. Besucher finden hier echten Cachaça-Art, der seit 2015 in Kupferbrennblasen produziert wird. Zur Qualitätssicherung beginnt die Sorgfalt beim Anpflanzen des Zuckerrohrs und reicht bis zur Ernte, die von Hand erfolgt. Ein weiterer wichtiger Punkt ist die Hygiene der Fabrik, bei der Rohrleitungen und Edelstahlbehälter mit Dampf gereinigt werden, wodurch bakterielle Infektionen ausgeschlossen werden. Die Gärung des Zuckerrohrsafts erfolgt mit ausgewählten, von schädlichen Bakterien freien Hefen. Die Destillation folgt streng einem Verfahren zur Trennung von Vorlauf, Herzstück und Nachlauf; nur das Herzstück wird verwendet, was einen Cachaça von internationaler Qualität ergibt. Anschließend ruht der Cachaça in Fässern aus Edelhölzern, die dem Endprodukt besseres Aroma, bessere Farbe und besseren Geschmack verleihen. 2017 wurde er in Brüssel ausgezeichnet, wo er vom International Taste & Quality Institute das Zertifikat „Prêmio de Sabor Superior“ (Superior Taste Award) erhielt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 406, 'de', 'funcionamento', '7–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 407, 'de', 'descricao', 'Der Alambique do Leley, Hersteller der preisgekrönten Cachaças „Barra Velha“, ist auch ein Ort für ausgezeichnete Hausmannskost vom Holzofen, Kunsthandwerk und vielfältige regionale Süßwaren. Er liegt am Strand Farol de São Thomé im Raum Campos, genauer gesagt auf der Fazenda São Thomé, wo sich die Anlagen zur handwerklichen Herstellung dieser berühmten Cachaças befinden, die vom brasilianischen Ministerium für Landwirtschaft, Viehzucht und Versorgung anerkannt und zertifiziert sind. Die Reifung erfolgt in Eichenfässern von Pernod Ricard, die zusammen mit dem Perfektionismus des Produzenten Leley den Erfolg sichern und den Produkten Qualität und Raffinesse verleihen. Der gereifte weiße Cachaça gewann eine Goldmedaille auf der Expocachaça in Belo Horizonte. Im dritten Jahr in Folge zählte der Cachaça „Barra Velha“ zu den besten Brasiliens, was ihm auch internationale Anerkennung einbrachte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 407, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 408, 'de', 'descricao', 'Die Cavalhada ist der Höhepunkt des größten traditionellen religiösen Festes im Norte Fluminense, der „Festa de Santo Amaro“, die am 15. Januar zu Ehren des Schutzpatrons der Baixada Campista gefeiert wird. Die Cavalhada ist ein Brauch, der bis ins Mittelalter zurückreicht: 24 Reiter, in zwei Gruppen aufgeteilt und an den Farben Rot und Blau erkennbar, stellen eine Schlacht zwischen Mauren und Christen nach und zeigen dabei ihr Können und ihre Frömmigkeit.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 409, 'de', 'descricao', 'Im Bezirk Santa Maria gelegen, bietet der von Herrn Taizinho produzierte Cachaça Soberana eine große Vielfalt an Geschmacksrichtungen, darunter den schwer zu findenden Jambu-Cachaça.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 409, 'de', 'funcionamento', 'Montag bis Samstag, 7–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 410, 'de', 'descricao', 'Alltägliche Pflichten und Aufgaben können unser Stressniveau erhöhen. Um diese Alltagssorgen zu vergessen, gibt es kein besseres Heilmittel als die Natur. Entspannen in einem natürlichen Becken, das von einem Wasserfall gebildet wird, nur von Bäumen und Bergen umgeben, begleitet vom Gesang der Vögel: Das erleben die Besucher der Cachoeira do Baú im Hinterland von Cardoso Moreira. Der richtige Ort für alle, die im eiskalten Wasser eines Wasserfalls die Seele baumeln lassen möchten, ohne an etwas anderes zu denken als an diesen einzigartigen Moment.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 411, 'de', 'descricao', 'Mit seinem authentischen Landflair bietet das Sítio Trapiche den Besuchern die perfekte Ausstattung für ein schönes Wochenende mit der Familie. Auf dem Gelände gibt es zwei Schwimmbecken, einen überdachten Grillbereich, Tischspiele, eine Hüpfburg und vieles mehr, damit Sie die schönen Momente der Kindheit noch einmal erleben. Wer das Sítio Trapiche kennenlernt, erlebt einzigartige Augenblicke, die die familiären Bande noch weiter stärken, voller Freude und Spaß.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 411, 'de', 'funcionamento', 'Mittwoch bis Sonntag, 9–22 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 412, 'de', 'descricao', 'Einzigartige handgefertigte Stücke, die die authentische Kunst von Cardoso Moreira repräsentieren. Das Atelier „Nós na Madeira“ besitzt eine große Sammlung kultureller Werke von Künstlern aus der Gemeinde Cardoso Moreira, mit Stücken aus Holz aus Wiederaufforstung sowie aus wiederverwendetem und recyceltem Holz, die Kunst und Nachhaltigkeit verbinden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 412, 'de', 'funcionamento', 'Montag bis Samstag, 8–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 413, 'de', 'descricao', 'Den Herstellungsprozess des handwerklichen Cachaça begleiten, mit sensorischer Analyse und Verkostung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 413, 'de', 'funcionamento', 'Donnerstag bis Sonntag, 9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 414, 'de', 'descricao', 'Ein historischer Ort einer traditionsreichen Familie mit unzähligen Geschichten und Schätzen, die Touristen verzaubern und entdecken können. 1883 gehörte die Farm dem Baron von Azeredo Coutinho und erhielt am 24. Juni jenes Jahres den Besuch von Dom Pedro II. zum Mittagessen. Der Kaiser war auf der Reise von São Fidélis nach Campos, um am Abend die elektrische Beleuchtung der Stadt einzuweihen. 1976 wurden auf der Fazenda da Pedra Szenen der ersten Verfilmung von A escrava Isaura („Die Sklavin Isaura“) gedreht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 414, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 415, 'de', 'descricao', 'In der Nähe der schönsten Wasserfälle der Region, am Ufer des Rio do Colégio, bietet er Naturnähe und eine familiäre Atmosphäre. Er liegt außerdem an der Radroute.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 415, 'de', 'funcionamento', '24 Stunden');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 416, 'de', 'descricao', 'Besucher können sowohl die Pflanzung als auch den Produktionsbereich der Casa de Farinha Amparo kennenlernen, einer Tradition der bäuerlichen Familienlandwirtschaft. Seit 30 Jahren wird hier ein besonderes Maniokmehl hergestellt, das als das beste der Region gilt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 416, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 417, 'de', 'descricao', 'Handwerklich in Kupferbrennblasen hergestellt, mit natürlicher Gärung und eigenem, ausgewähltem Zuckerrohrfeld.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 417, 'de', 'funcionamento', '9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 418, 'de', 'descricao', 'Der Weinberg ist bereits eine Familientradition: Neben köstlichen Trauben, die in der Region verkauft werden, empfängt er Besucher, die die Pflanzung kennenlernen können. Auch für Studierende des Fachs ist er eine großartige Gelegenheit, den gesamten Weinbauprozess in der Praxis zu sehen. Außerdem gibt es Festas Juninas (Johannisfeste), Besichtigungen mit Verkostung und den Verkauf der Produkte. Familiäre Atmosphäre mit direktem Kontakt zur Natur.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 418, 'de', 'funcionamento', '8–12 Uhr und 13–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 419, 'de', 'descricao', 'Hergestellt werden süße und saure Maniokstärke (Polvilho), Tapiokastärke, Beiju und eine Mischung für Käsebrötchen (Pão de Queijo). Außerdem werden rosa und schwarzer Pfeffer angebaut und Eukalyptus bewirtschaftet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 419, 'de', 'funcionamento', 'Dienstag bis Freitag, 5–21 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 420, 'de', 'descricao', 'Ein Tag auf der Farm mit vielen verschiedenen Tieren und einer Verkostung handwerklicher Produkte, die vor Ort hergestellt werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 420, 'de', 'funcionamento', 'Mittwoch bis Sonntag, 9–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 421, 'de', 'descricao', 'Vielfältiges Kunsthandwerk lokaler Kunsthandwerker.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 421, 'de', 'funcionamento', '8–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 422, 'de', 'descricao', 'Bootsfahrt durch die Mangroven von Gargaú und entlang der Küste des Rio Paraíba. Dieser Service wird seit mehr als 20 Jahren angeboten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 422, 'de', 'funcionamento', '7–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 423, 'de', 'descricao', 'Herstellung von Goiabada Cascão (Guavenpaste) in Tafeln sowie von Goiabada em Palha. Alles ist sehr handwerklich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 423, 'de', 'funcionamento', '8–16 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 424, 'de', 'descricao', 'Ein sehr angenehmer Ort mit Freizeitbereich für Erwachsene und Kinder, Pool und köstlicher Hausmannskost.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 424, 'de', 'funcionamento', '9.30–18 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 425, 'de', 'descricao', 'Die Cavalgada dos Amigos ist eine kulturelle Veranstaltung in Form eines Ausritts, bei der Reiterinnen und Reiter jeden Alters, von Kindern bis zu Senioren, die die Liebe zum Landleben teilen, unterwegs zusammenkommen. Die Veranstaltung findet jedes Jahr im Mai statt und zieht Besucher aus mehreren Städten der Region an.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 425, 'de', 'funcionamento', '10 Uhr bis Mitternacht');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 426, 'de', 'descricao', 'Auf dem Anwesen leben 2.500 Hühner, die täglich 200 Dutzend Eier legen. Daneben gibt es Gemüseanbau und einen Kokospalmenhain, wo Besucher direkt von der Pflanze aussuchen können, was sie mit nach Hause nehmen. Vor Ort werden frische Eier, Kokoswasser und frisch geerntetes Gemüse verkauft. Die Besucher werden von der Besitzerin empfangen, die die Geschichte der Familie erzählt und davon, wie die Tierhaltung begann, aus der dieser Ort entstanden ist.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 426, 'de', 'funcionamento', '7–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 427, 'de', 'descricao', 'Der familiengeführte landwirtschaftliche Betrieb hat einen Mandala-Garten mit verschiedenen Gemüsesorten, der den Besuchern ein intensives Erlebnis bietet; sie können auch den Obstgarten besuchen und je nach Jahreszeit Orangen, Mandarinen und Wassermelonen ernten. Man lernt Arten wie den Annattostrauch (Urucum) kennen und kann sogar frische Eier im kleinen Hühnerstall einsammeln. Zum Abschluss des Rundgangs gibt es eine einfache, aber typische ländliche Kaffeetafel mit warm gekochten Süßkartoffeln und Maniok, Maismehlkuchen, Marmeladen und Säften aus Früchten der Saison sowie frisch gebrühtem Kaffee. Ganz zu schweigen von der Gastfreundschaft des Besitzers Manoel Toledo, der alle mit einem herzlichen Lächeln empfängt. Die geernteten Produkte können von den Besuchern gekauft werden, ebenso wie die anderen, die vor Ort verkauft werden. Der Nachmittagskaffee ist Teil des Erlebnisses und im Eintritt enthalten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 427, 'de', 'funcionamento', '9–17 Uhr');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 428, 'de', 'descricao', 'Das Rancho bietet Platz für 44 Personen an Tischen für 8, 6 und 4 Personen und steht für geschlossene Veranstaltungen mit festgelegtem Menü und nach Reservierung zur Verfügung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 428, 'de', 'funcionamento', 'Am Wochenende');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 429, 'de', 'descricao', 'Blumenanbau und Blumenbetrachtung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 429, 'de', 'funcionamento', '9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 430, 'de', 'descricao', 'Erlebnisse rund um den Bierbrauprozess und Verkostung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 430, 'de', 'funcionamento', '9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 431, 'de', 'descricao', 'Freizeit, Angeln und Gastronomie.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 431, 'de', 'funcionamento', 'Mittwoch bis Sonntag, 10–19 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 432, 'de', 'descricao', 'Gastronomie. Verkostung und Weine. Weinkeller mit Schwerpunkt auf brasilianischen Weinen, mit bewährten und geschätzten Etiketten von sorgfältig ausgewählten Weingütern.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 432, 'de', 'funcionamento', '18 Uhr bis Mitternacht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 433, 'de', 'descricao', 'Pflanzen, Ernten und Betrachten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 433, 'de', 'funcionamento', 'Keine Angabe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 434, 'de', 'descricao', 'Anpflanzen und Ernten von Lebensmitteln.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 434, 'de', 'funcionamento', '9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 435, 'de', 'descricao', 'Farmhotel, Mini-Farm, Freizeitangebote, Radweg, Gastronomie, Wanderweg und Ausritte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 435, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 436, 'de', 'descricao', 'Kontakt mit agrarökologischen Anpflanzungen und vor Ort erzeugten Bio-Lebensmitteln.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 436, 'de', 'funcionamento', '7–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 437, 'de', 'descricao', 'Weberei. Handwerkliche Arbeit. Die Besucher können die Maschinen bedienen und ihren eigenen Teppich weben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 437, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 438, 'de', 'descricao', 'Jahrhundertealte Farm, Gastronomie, Gin-Destillerie, Ausritte, Wanderwege, Wasserfall, Musikfestivals, Tagungen und private Veranstaltungen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 438, 'de', 'funcionamento', '7–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 439, 'de', 'descricao', 'Restaurant mit Schwerpunkt auf Fisch, Bootstreffen, Kajaks und Radfahren. Naturerlebnis mitten im Rio Paraíba.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 439, 'de', 'funcionamento', 'Donnerstag bis Sonntag und an Feiertagen, ab 11 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 440, 'de', 'descricao', 'Naturreservat des Atlantischen Regenwalds, von den Eigentümern der Farm geschützt. Rinderzucht, Fischzucht, Bromelien-, Anthurien- und Orchideengarten, Ausritte und Kutschfahrten, Wanderungen auf exklusiven Pfaden, Schwimmen und Angeln in den Teichen, Sonnenuntergang mit Picknick, Anpflanzen und Ernten einiger Lebensmittel, Besuch von Gemüsegarten und Obstgarten sowie Füttern der Tiere.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 440, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 441, 'de', 'descricao', 'Zu mieten für Veranstaltungen, Retreats, Feiern, Hochzeiten und Taufen. Mit Kirche, Kolonialhaus, Wasserfall, Pool, Pferden, Melken im Kuhstall, Wanderwegen, Schweinefütterung, altem Pflug, Ochsenkarren usw.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 441, 'de', 'funcionamento', 'Von Freitag 18 Uhr bis Sonntag 18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 442, 'de', 'descricao', 'Tagesaufenthalt auf einer Farm aus dem 18. Jahrhundert mit zeitgenössischen Möbeln, ökologischen Wanderwegen, einem bereits erfassten Kletterfelsen, erfrischenden Duschen, Baden im Fluss, Pferden zum Mieten, Vollpension, Marmeladen zum Verkauf, Souvenir-Postkarten, Obst, Gemüse, Eiern und Milch ohne Pestizide sowie Gegenständen aus der Zeit der Sklaverei.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 442, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 443, 'de', 'descricao', 'Ausritte und Reitshow. Preisgekrönte Pampa-Marchador-Pferde.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 443, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 444, 'de', 'descricao', 'Unterkunft, Frühstück, Mittagessen, Pool, Angeln und Ausritte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 444, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 445, 'de', 'descricao', 'Zweihundert Jahre alte Farm aus der Zeit der Sklaverei, vom Instituto Cidade Viva in Rio de Janeiro und der Bundesuniversität von Minas Gerais inventarisiert, in der die Besucher die Atmosphäre einer Farm der Kaffeebarone spüren. Heute im ländlichen Tourismus tätig, bietet sie den Besuchern das Pampa-Pferdekarussell, Meditation am Wunschteich von Isabel Libertadora, die Allee der Königspalmen und die Überquerung der Hängebrücke, Kühe melken, einen Bambustunnel, einen Flussstrand, Baden im Stausee, eine Aussichtsplattform aus Naturstein, Pflanzgarten und Obstgarten, Gemälde von José Maria Vilarongo, die Ruinen eines Trockenplatzes, ein Aquädukt und eine Steinmühle.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 445, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 446, 'de', 'descricao', 'Eine Route zu historischen Farmen und Attraktionen der Region. Wir sind eine Agentur und ein Reiseveranstalter, die sich auf den Vertrieb (an die Reisebranche) von Routen mit ländlichen Erlebnissen im Bundesstaat Rio de Janeiro spezialisiert haben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 446, 'de', 'funcionamento', 'Montag bis Freitag, 9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 447, 'de', 'descricao', 'Besuch der Brennerei; bei vorheriger Anmeldung kann man die Herstellung der Cachaça miterleben. Außerdem kann man die Cachaça aus den verschiedenen Fässern verkosten. Unsere Cachaça wird in einer Brennblase hergestellt, jedoch mit einer Infrastruktur, die der von Agrarbetrieben entspricht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 447, 'de', 'funcionamento', '9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 448, 'de', 'descricao', 'Die Brennerei ist für Besucher geöffnet, und man kann den gesamten sorgfältigen Herstellungsprozess der Itajoana kennenlernen; für Gruppen ab 10 Personen kann vor Ort ein reichhaltiges Mittagessen gebucht werden. Die Cachaça Itajoana, hergestellt im Distrikt Bemposta in der Stadt Três Rios, verbindet die Gemütlichkeit des Landlebens mit einer außerordentlich schmackhaften Cachaça. Das 2017 entstandene Premium-Getränk will Cachaça-Liebhabern unter anderem besondere, hochwertige Blends bieten. 2020 gewann die Cachaça Itajoana mit dem schwarzen Etikett (Blends Bálsamo, Carvalho und Amburana) eine Goldmedaille bei der Expocachaça in der Kategorie Cachaça-Blends.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 448, 'de', 'funcionamento', 'Montag bis Sonntag, nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 449, 'de', 'descricao', 'Das Farmhotel bietet Erlebnisse mit Tieren und die Möglichkeit, im eigenen Gemüsegarten zu ernten. Es verfügt über eine Wassermühle, in der Mais gemahlen wird. In einigen Zimmern des Hotels gibt es einen privaten, holzbefeuerten Außenwhirlpool in außergewöhnlich edlem und gemütlichem Ambiente. Nach Voranmeldung sind Aktivitäten wie der Track Day möglich, dank einer Partnerschaft des Hotels mit dem Team RMattheis (Stock Car und Rally dos Sertões), das hier seine Offroad-Strecke betreibt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 449, 'de', 'funcionamento', '24 Stunden, nur mit Reservierung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 450, 'de', 'descricao', 'Die Fazenda da Paciência bietet heute ein einzigartiges Übernachtungserlebnis: Um das Anwesen zu nutzen, muss die gesamte Farm gemietet werden, was ein einzigartiges und exklusives Erlebnis des Landlebens ermöglicht. Die Gastronomie und die Zucht von Araberpferden sind die großen Besonderheiten des Ortes, der außerdem einen kleinen Wasserfall auf dem Gelände hat, der den Besuchern exklusiv zur Verfügung steht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 450, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 451, 'de', 'descricao', 'Der Ort ist ein echter Freizeitkomplex mit ausgeprägt ländlichem Charakter. Er besteht aus einer Pousada und einem Restaurant, die den Namen des Ortes tragen: Pontal. Es ist ein dauerhaftes Schutzgebiet des Atlantischen Regenwalds mit einem harmonischen Miteinander vieler wilder Tierarten im Reservat, dazu gibt es das Cachaça-Museum, einen Hängemattenbereich, eine Seilrutsche, einen Hochseilgarten und Klettern. All das mit bezauberndem Blick auf den Zusammenfluss der drei Flüsse. Der Zusammenfluss der drei Flüsse (Piabanha, Paraibuna und Paraíba do Sul), das einzige Dreifachdelta Lateinamerikas (ein perfektes Dreieck), liegt an einem weitläufigen Ort für Touristen, die auch Extremsport mögen. Rafter fahren die Stromschnellen des Rio Paraibuna auf einer etwa dreistündigen Strecke hinab, die am Zusammenfluss der Flüsse endet. Der Paraibuna gilt als einer der besten Flüsse Brasiliens für diesen Sport, da er viel Wasser führt, fürs Rafting nicht vom Regen abhängt und seine Stromschnellen der Klasse 2 und 3 den Sport das ganze Jahr über ermöglichen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 451, 'de', 'funcionamento', 'Unterkunft, Tagesaufenthalt und Mahlzeiten nur mit Reservierung und Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 452, 'de', 'descricao', 'Snacks, Pool, Angeln gegen Gebühr, Spaß und familiäre Atmosphäre.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 452, 'de', 'funcionamento', 'Wochenenden, 10–19 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 453, 'de', 'descricao', 'Tagesaufenthalt, Angeln und Restaurant.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 453, 'de', 'funcionamento', 'Wochenenden und Feiertage. 9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 454, 'de', 'descricao', 'Die Herstellung der Cachaça kennenlernen: von der Ernte über das Mahlen, die Gärung und die Destillation bis zur Reifung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 454, 'de', 'funcionamento', '8–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 455, 'de', 'descricao', 'Eine angenehme, grüne Umgebung, in der Zierpflanzen und Obstgehölze gezogen werden und in der außerdem Blumengestecke und vieles mehr verkauft werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 455, 'de', 'funcionamento', 'Montag bis Samstag, 7:30–17 Uhr. Sonntag, 8:30–11 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 456, 'de', 'descricao', 'Erlebnistour durch die Cachaça-Herstellung, die seit über 30 Jahren besteht. Besuche nur nach Voranmeldung. Zufahrt über eine unbefestigte Straße.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 456, 'de', 'funcionamento', '12–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 457, 'de', 'descricao', 'Den Herstellungsprozess von Craft-Bier verstehen und die Rohstoffe kennenlernen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 457, 'de', 'funcionamento', 'Dienstag, 17–23 Uhr. Freitag, 19–23:45 Uhr, und Samstag, 17–24 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 458, 'de', 'descricao', 'Tagesaufenthalt. Anlage mit Pools, Fischteich, Wasserfall, Saunen und Grillplätzen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 458, 'de', 'funcionamento', 'Wochenenden und Feiertage.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 459, 'de', 'descricao', 'Hatten Sie schon einmal die Gelegenheit, die handwerkliche Herstellung von Guavenprodukten mitzuerleben? Nein? Lernen Sie die Familie Schott und ihre hausgemachten Süßwaren kennen, die Guavenplantage, die Zubereitung der Früchte, den Kessel und den Lagerraum der Produkte. Auf diesem Landgut baut die Familie Schott Guaven an und zeigt, wie der Herstellungsprozess funktioniert. Die Zufahrt erfolgt über eine unbefestigte Straße.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 459, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 460, 'de', 'descricao', 'Die 8 km vom Zentrum von Bom Jardim entfernte Farm ist für verschiedenste Veranstaltungen ausgestattet. Eine ausgezeichnete Option zur Erholung, mit Einrichtungen für gesellige Zusammenkünfte. Ein Freizeitbereich mit Naturwasser-Pool, Wasserfall, Fußballplatz und weiteren Aktivitäten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 460, 'de', 'funcionamento', 'Nicht angegeben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 461, 'de', 'descricao', 'Camping Recanto da Siriema – Ein dem Camping gewidmeter Platz mit Grünfläche, See und Einrichtungen für alle, die diese Aktivität ausüben möchten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 461, 'de', 'funcionamento', 'Täglich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 462, 'de', 'descricao', 'Das im Distrikt Barra Alegre gelegene Refúgio do Humaitá bietet vielfältige Erlebnisse, vom Besuch der Zucht von Ziervögeln bis hin zu Kursen rund um die Agrarindustrie.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 462, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 463, 'de', 'descricao', 'Mitten in der Natur, in einer filmreifen Kulisse von 165.000 Quadratmetern, bietet es direkten Kontakt zu exotischen und zutraulichen Tieren. Unterkunft in separaten Chalets im rustikalen Stil, der zur ländlichen Atmosphäre passt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 463, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 464, 'de', 'descricao', 'Ideal zum Entspannen. Der Ort zeichnet sich durch eine einfache, rustikale, aber sehr gemütliche Atmosphäre auf dem Land aus. Der Freizeitbereich umfasst einen Pool, einen Grillplatz und eine große Rasenfläche mit Schaukeln und einem Baumhaus für Kinder.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 464, 'de', 'funcionamento', 'Nicht angegeben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 465, 'de', 'descricao', 'Die Umgebung des Grundstücks ist von Natur geprägt, und es gibt einen Obstgarten mit vielen Früchten wie Maulbeeren, Mangos, Guaven, Avocados, Sternfrüchten und Bananen. Zimmerservice plus Frühstück. Die Nutzung des Pools und der übrigen Bereiche des Grundstücks ist frei, ebenso die des Grills und der Sauna.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 465, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 466, 'de', 'descricao', 'Ein reizender Ort im ländlich-idyllischen Distrikt Bom Jardim. Er bietet unwiderstehliche Köstlichkeiten: Süßes, Brot, Käse und handwerklich hergestellte Joghurts, die den Gaumen der Besucher erfreuen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 466, 'de', 'funcionamento', 'Nicht angegeben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 467, 'de', 'descricao', 'Eine wunderschöne Farm, bekannt für ihren Kaffee, ihre Milch, ihren Käse und ihre Bolinhos de Chuva (süße frittierte Teigbällchen), die regelmäßig ihre Türen für eine Erlebnistour öffnet, bei der die Besucher in geführten Besichtigungen etwas über die Kultur des Landlebens und die Verarbeitungsschritte des Kaffees erfahren. Von der Ernte bis zur Röstung, mit etwas Geschichte, und zum Abschluss eine kleine Verkostungstour durch die verschiedenen Zubereitungsarten des Getränks. Eine Gelegenheit, die Bergernte selbst zu erleben. Vor Ort erleben, von der Plantage bis zur fertigen Röstung, inmitten einer unglaublichen Natur.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 467, 'de', 'funcionamento', 'Montag bis Freitag, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 468, 'de', 'descricao', 'Besuch der wichtigsten Stätten der Erzeugung und Verarbeitung des Reises Anã de Porto Marinho; Besuch bei den Häusern der Familienbetriebe; Bootsfahrt auf dem Rio Paraíba do Sul und Fahrt im Ochsenkarren; Erläuterungen vor Ort zur Geschichte des Dorfes und der Gemeinde sowie zu den kulturellen Traditionen der Dorfgemeinschaft; Verkauf typischer Süßwaren und Kunsthandwerks; Verkostung der lokalen Küche, deren Hauptattraktionen der Reis Anã de Porto Marinho, eine mögliche geschützte geografische Angabe, und der Fisch sind.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 468, 'de', 'funcionamento', 'Wochenenden, ab 10 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 469, 'de', 'descricao', 'Besuch der Farm von Schwester Zélia und Jerônimo, dem Ehepaar, das zu Dienern Gottes erklärt wurde, dem einzigen seliggesprochenen Ehepaar, dessen Heiligsprechungsverfahren läuft. Es ist ein historischer Ort und ein Heiligtum.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 469, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 470, 'de', 'descricao', 'Fischgerichte, Wanderwege an Land, Bootsfahrten, Sportfischen und Kunsthandwerk.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 470, 'de', 'funcionamento', '7–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 471, 'de', 'descricao', 'Kontakt mit der Arbeit der Landbevölkerung, mit Pflanzenheilkunde, Heilpflanzen, Pflanzgarten, Anbau, Wissen und Gastfreundschaft.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 471, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 472, 'de', 'descricao', 'Naturerlebnis, Gastronomie, Baumpflanzen, Wanderwege und Ausritte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 472, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 473, 'de', 'descricao', 'Käseverkostung und Besuch im ländlichen Raum.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 473, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 474, 'de', 'descricao', 'Gastronomie, Geschichte und Erlebnis in einer historischen Molkerei. Die Geschichte der Marke Relógio führt uns ans Ende des 19. Jahrhunderts, genau zum 13. April 1871, dem Geburtstag von Joaquim Simões de Araújo in Espinho bei Viseu in Portugal. Mit der Kraft seiner zwanzig Jahre schloss er sich drei portugiesischen Freunden an und brach zu einem Abenteuer nach Brasilien auf, in der Hoffnung, sich dort bessere Lebensbedingungen zu schaffen. Stets von Unternehmergeist beseelt, erwarb er 1912 die Fazenda João Dias und baute dort eine Molkerei. Da der Bahnhof ganz in der Nähe der Molkerei lag, schickte Joaquim die gesamte Milch- und Butterproduktion per Zug in die größeren Städte. So bestimmte die Durchfahrtszeit des Zuges den Produktionsrhythmus. Der Überlieferung nach rief er mitten in der Arbeit mit seinem starken portugiesischen Akzent: „Olha o relógio! Olha o relógio!“ („Achtung, die Uhr! Achtung, die Uhr!“) und mahnte die Angestellten so zur rechten Zeit für die Ankunft des Zuges. Und so entstand in dieser Atmosphäre aus Arbeit und Poesie der Name Relógio für die Produkte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 474, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 475, 'de', 'descricao', 'Frische Luft, Kontakt mit Wildtieren, einheimische Bäume, Wanderwege, Pflanzen von Setzlingen, lokale Geschichte, Baden im Fluss und Camping.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 475, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 476, 'de', 'descricao', 'Naturerlebnis, Wildtiere, Gastronomie, Radwege, Baden im Wasserfall und viel Geschichte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 476, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 477, 'de', 'descricao', 'Pflanzen von Setzlingen und Pflanzenkunde.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 477, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 478, 'de', 'descricao', 'Reitweg, Höhlen und Naturerlebnis.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 478, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 479, 'de', 'descricao', 'Cachaça-Verkostung, Geschichte und Naturerlebnis. Seit 1923 wird die Cachaça da Quinta auf der Fazenda da Quinta hergestellt, in einem Tal nahe dem Rio Paraíba do Sul auf einer Höhe von etwa zweihundertzwanzig Metern. Das Anwesen besitzt Boden, Klima und Mikroklima, die ideal für den Zuckerrohranbau, die Gärung und die Herstellung der Produkte sind. Zu diesem besonders günstigen Terroir kommen die strengen Qualitätsstandards bei der Herstellung der Cachaça da Quinta hinzu. Es lohnt sich, den gesamten Produktionsprozess zu besuchen und kennenzulernen. Das Anwesen besitzt Boden und Klima, die ideal für den Zuckerrohranbau, die Gärung und die Herstellung der Produkte sind. Sie war das erste brasilianische Destillat, das die Grand Gold Medal des Concours Mondial de Bruxelles erhielt. Im nationalen Ranking der Cúpula da Cachaça (Zweijahreszeitraum 2022–2023) erhielt die Cachaça da Quinta – Branca die höchste Punktzahl aller Teilnehmer und schuf damit ein Novum: Eine klare Cachaça übertraf die Punktzahlen von Cachaças aus verschiedenen Hölzern, gelagert, gereift, Premium und Extra Premium.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 479, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 480, 'de', 'descricao', 'Naturerlebnis, Baden im Wasserfall, Gastronomie, lokale Geschichte und Wanderwege an Land.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 480, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 481, 'de', 'descricao', 'Gastronomie, Kultur, lokale Literatur, Bio-Produkte, Kunsthandwerk, Kreativwirtschaft und familiäre Landwirtschaft.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 481, 'de', 'funcionamento', 'Samstags, 7–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 482, 'de', 'descricao', 'Naturerlebnis, Gastronomie und Einblick in die Herstellung von Rapadura (Rohrzuckerblöcken) und Zuckerrohrmelasse. Pflanzen von Setzlingen, Wanderwege und Baden im Fluss.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 482, 'de', 'funcionamento', '7–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 483, 'de', 'descricao', 'Kunsthandwerk.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 483, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 484, 'de', 'descricao', 'Die Genossenschaft fällt schnell durch die Qualität ihrer Milch, ihres Käses, ihres Requeijão (streichfähiger Frischkäse) und besonders ihrer Butter auf.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 484, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 485, 'de', 'descricao', 'Vorträge, Verkostungen und Honigverkauf. Die Haltung stachelloser Bienen heißt Meliponikultur und dient vor allem der Honigproduktion.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 485, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 486, 'de', 'descricao', 'Besucher können die Kunstsammlung von Vinycios kennenlernen, dessen Werke eine Renaissance-Note tragen, mit maßstabsgetreuen und lebensgroßen Skulpturen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 486, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 487, 'de', 'descricao', 'Die Produktion der Cachaça Artesanal Rio do Meio begann 2004. Die Cachaça Rio do Meio, benannt nach dem Sítio, auf dem sie hergestellt wird, entstand zunächst für den Eigenbedarf, für Freunde und Liebhaber des Getränks.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 487, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 488, 'de', 'descricao', 'Die Ausstellung ist eine jährliche Veranstaltung (zweite Julihälfte), die Agrarwirtschaft, Industrie und Handel in Cordeiro und Umgebung fördern soll.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 488, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 489, 'de', 'descricao', 'Besichtigung des Haupthauses sowie der Fabrik für Cachaça und handwerkliche Liköre. Mittagessen, Drinks, Biere, Snackplatten und Gerichte à la carte. Verkauf von eigener Cachaça und handwerklichen Likören sowie eine Bar.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 489, 'de', 'funcionamento', 'Montag bis Freitag nur nach Voranmeldung. Am Wochenende 10–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 490, 'de', 'descricao', 'Die Bar von Capitão Bock vereint gute Gastronomie, Freizeitbereich und sämtliche Craft-Bier-Stile an einem Ort. Ein großzügiger, luftiger Raum, ideal für schöne Stunden mit Familie und Freunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 490, 'de', 'funcionamento', 'Am Wochenende und an Feiertagen. 11–20 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 491, 'de', 'descricao', 'Der Sítio São Sebastião verfügt über eine Cachaça-Brennerei und ein ganzes Areal, das im Einklang mit der Natur steht. Dazu gibt es unsere Venda do Barranco, einen Selbstbedienungsladen (Pegue e Pague), in dem man lokale Produkte sowie Setzlinge von Pflanzen und Obstbäumen findet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 491, 'de', 'funcionamento', 'Dienstag bis Freitag 10–18 Uhr. Samstag 8–18 Uhr. Sonntag 8–13 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 492, 'de', 'descricao', 'Raumvermietung, Baden am Wasserfall, Bar, Volleyballplatz, Fußballplatz, Angeln, Sauna. Ein Ort des Friedens, der Verbundenheit mit der Natur und der Ruhe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 492, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 493, 'de', 'descricao', 'Das Gebäude selbst ist eines der wenigen noch erhaltenen alten Herrenhäuser im Stadtzentrum. Im Inneren erzählt es ein Stück der Geschichte der Eisenbahn, die zur Entstehung der Gemeinde beitrug und für die ganze Region von großer Bedeutung war.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 493, 'de', 'funcionamento', 'Donnerstag bis Samstag 18–2 Uhr. Sonntag ab 12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 494, 'de', 'descricao', 'Wir öffnen um 10 Uhr für alle, die sich für einen Brunch entscheiden, oder ab 12 Uhr für das Mittagessen, das sich bis zur Nachmittagsjause bei Akkordeonklängen ausdehnen kann.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 494, 'de', 'funcionamento', '10.30–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 495, 'de', 'descricao', 'Besichtigung eines hundertjährigen Hofs mit seiner Geschichte, Mittagessen vom Holzofenherd sowie Verkauf von Kunsthandwerk und hausgemachten Süßigkeiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 495, 'de', 'funcionamento', '10–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 496, 'de', 'descricao', 'Herstellung hausgemachter Produkte, Hausmannskost und ein rustikaler Bereich zur Besichtigung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 496, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 497, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 498, 'de', 'descricao', 'Mineralwasserquellen mit Besichtigung, Spaziergang über den Steinhof und die Umgebung des Hofs.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 498, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 499, 'de', 'descricao', 'Herstellung von Milchprodukten mit Besichtigung und Café.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 499, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 500, 'de', 'descricao', 'Wanderung über den Hof und Workshops zur handwerklichen Herstellung von Goiabada (Guavenpaste) und Bananada (Bananenpaste).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 500, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 501, 'de', 'descricao', 'Quad-Touren auf dem ländlichen Rundkurs von Santa Maria Madalena. Auf der Strecke der Estrada do 17 gibt es einen Halt auf der Fazenda Boa Fé zur Verkostung handwerklicher Käse und einen Halt im Hotel Auberge Valaissane, um die Agrarbetriebe des Anwesens kennenzulernen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 501, 'de', 'funcionamento', 'Täglich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 502, 'de', 'descricao', 'Souvenirs und Dekoration aus lokalem Kunsthandwerk aller Art.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 502, 'de', 'funcionamento', 'Montag bis Samstag 9–18 Uhr. Sonntag 9–15 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 503, 'de', 'descricao', 'Produkte vom Land.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 503, 'de', 'funcionamento', 'Montag bis Samstag 7.30–19 Uhr. Sonntag 7.30–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 504, 'de', 'descricao', 'Die Auberge Valaisanne ist mehr als ein Landhotel, sie ist ein Rückzugsort für unbeschwerte Tage. Es gibt Seen zum Angeln, Wanderwege, Stromschnellen und Besichtigungen der Plantagen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 504, 'de', 'funcionamento', '9–22 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 505, 'de', 'descricao', 'Andenken an Santa Maria Madalena, hergestellt von Kunsthandwerkern der Stadt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 505, 'de', 'funcionamento', 'Freitag bis Sonntag, 8–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 506, 'de', 'descricao', 'Empfangsagentur für Ausflüge in der Region, zum Beispiel eine ländliche Jeep-Tour.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 506, 'de', 'funcionamento', '8–16 Uhr. Online-Beratung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 507, 'de', 'descricao', 'Verkostung und Verkauf handwerklicher Produkte der Vereinigung der Landwirtinnen von Ribeirão Santíssimo.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 507, 'de', 'funcionamento', 'Samstags 9–15 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 508, 'de', 'descricao', 'Hausgemachte Süßigkeiten, Gelees, Liköre, eingelegte Chilis, Caponatas, Pickles, Cachaças, Käse, Kunsthandwerk und vor allem typisch ländliche Küche.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 508, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 509, 'de', 'descricao', 'Auf dem Weg zur Fazenda Boa Fé fahren Sie entlang einer alten Bahntrasse mit Durchgängen und Felseinschnitten durch eine idyllische, üppige Landschaft. Auf unserem Hof lernen Sie Nachhaltigkeitstechniken kennen und besuchen die Käserei sowie die Tilapia-Zucht. Außerdem können Sie die Produkte probieren, etwa frischen Käse und Joghurt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 509, 'de', 'funcionamento', 'Täglich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 510, 'de', 'descricao', 'Die historische Farm, Teil eines wertvollen Abschnitts der alten Leopoldina-Eisenbahnstrecke, begeistert Besucher mit ihren ursprünglichen Wäldern, natürlichen Aussichtspunkten und atemberaubenden Landschaften. Die drei Tunnel auf dem Gelände, im 19. Jahrhundert von englischen Ingenieuren erbaut, haben großen historischen und kulturellen Wert. Das um 1880 gegründete Anwesen verfügt über ein imposantes Herrenhaus, alte Kaffeemühlen, eine Maismehlmühle, eine Zuckerrohrmühle und ein kleines Wasserkraftwerk. Beim Besuch können die Gäste die Kapelle, die Brennerei und die alte Stein-und-Holz-Mühle erkunden und dazu Snacks, Biere und die vor Ort hergestellte Cachaça Santa Cruz genießen. Die malerische Kulisse mit gut gepflegten Straßen bietet ein einmaliges Erlebnis, bei dem man die Atmosphäre der Kolonialzeit spüren, schöne Fotos machen und die umgebende Landschaft genießen kann.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 510, 'de', 'funcionamento', 'Am Wochenende, 9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 511, 'de', 'descricao', 'Auf dem Anwesen aus dem 19. Jahrhundert befinden sich eine Cachaça-Brennerei von höchster Qualität, ein Museum und eine beeindruckende Sammlung von mehr als 800 Cachaça-Etiketten. Probieren Sie die preisgekrönte SINHÁ BRASIL, eine Cachaça, die unter strenger Qualitätskontrolle hergestellt wird, vom Anbau des Zuckerrohrs bis zur Abfüllung. Erkunden Sie den Herstellungsprozess bei monatlichen Führungen, bei denen Sie die verschiedenen Sorten verkosten und ein authentisches, auf dem Hof zubereitetes Mittagessen genießen können. Ein einzigartiges Reiseerlebnis, das alle Ihre Sinne begeistern wird.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 511, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 512, 'de', 'descricao', 'Touren mit Quad, Offroad-Motorrad und Geländewagen (4x4). Trajano X Triunfo, Trajano X Sodrelândia und Staudamm, Trajano X Sonnenuntergang, Wanderweg Pedra da Torre, Wanderweg Carrapato, Wanderweg Pereirinha, Wanderweg Retiro.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 512, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 513, 'de', 'descricao', 'Fahrzeugvermietung und geführte Ausflüge. Vermietung von Quads, Offroad-Motorrädern und Buggys. Campingplatz und Zimmer, außerdem Verpflegung (Snacks).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 513, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 514, 'de', 'descricao', 'Landtourismus und Gastronomie. Besichtigung eines hundertjährigen Hofs im Kolonialstil, der in vollem Produktionsbetrieb ist. Wir bieten Erlebnisse in der Rinderhaltung (Fleisch und Milch), beim Pflanzen und Ernten von Guaven, Zuckerrohr, Gemüsegarten, Eukalyptus und mehr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 514, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 515, 'de', 'descricao', 'Besichtigung der alten Sammlung der Stadt und der historischen Kaffeefarm aus dem 19. Jahrhundert. Die Farm gehörte der traditionsreichen Familie Moraes, deren bedeutendster Vertreter Raul Veiga war, der in der ersten Hälfte des 20. Jahrhunderts Gouverneur des Bundesstaats Rio de Janeiro wurde.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 515, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 516, 'de', 'descricao', 'Natürliche Wasserquelle. Besuch einer der besten Mineralwasserquellen des Bundesstaats.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 516, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 517, 'de', 'descricao', 'Ausritte, Sonnenuntergang von einem Deck aus genießen, mit Blick auf eine paradiesische Kulisse aus Bergen und viel Grün.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 517, 'de', 'funcionamento', 'Nur nach Voranmeldung, tagsüber.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 518, 'de', 'descricao', 'Typische Musik, Modas de Viola (traditionelle Landlieder), Lagerfeuer, Reitveranstaltungen und Sertanejo-Konzerte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 518, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 519, 'de', 'descricao', 'Rodízio mit Hausmannskost vom Holzofenherd in familiärer Atmosphäre und besonderem Service. Kontakt mit den auf der Ranch gehaltenen Tieren, eine Referenz in Itaboraí und den Nachbarstädten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 519, 'de', 'funcionamento', 'Am Wochenende, 11.30–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 520, 'de', 'descricao', 'Museum mit verschiedenen Fossilien, historischen Stücken und einer Nachbildung des Riesenfaultiers. Naturverbundenheit: Lagune, Wanderwege, Beobachtung von Wildtieren.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 520, 'de', 'funcionamento', '8–20 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 521, 'de', 'descricao', 'Melken von Tieren, Ausritte auf Ponys und Pferden, ein See zum Sportangeln, Fahrten mit einem kleinen Zug über das Gelände und die Umgebung, Verkauf von auf dem Anwesen hergestelltem Käse und Marmelade sowie von auf dem Hof gepflückten Früchten wie Banane, Papaya, Mango, Siriguela, Acerola und Orange und verschiedenen Gemüsesorten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 521, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 522, 'de', 'descricao', 'Besichtigung der Produktion, Verkauf von Setzlingen von Zierpflanzen und Obstbäumen. Verkauf vor Ort möglich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 522, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 523, 'de', 'descricao', 'Rio Bonito ist bekannt für seine zahlreichen Bananenplantagen, und die Bananada-Fabrik verwendet Früchte aus der Region und von lokalen Landwirten. Besucher können den gesamten Herstellungsprozess miterleben und kennenlernen, vom Rohstoff bis zur Verpackung und späteren Verteilung, und die vor Ort hergestellten Süßigkeiten probieren.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 523, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 524, 'de', 'descricao', 'Der Ort bietet Produkte aus Mais an, einzigartig in der Region. Der Mais-Milchshake ist der Verkaufsschlager, dazu gibt es gerösteten Mais, Säfte, Süßes und herzhafte Snacks aus Mais.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 524, 'de', 'funcionamento', '9–20 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 525, 'de', 'descricao', 'Rustikales Ambiente inmitten von Natur und Obstbäumen, ländliche Atmosphäre und Gerichte vom Holzofenherd. Ein Bereich ist einer Antiquitätenausstellung gewidmet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 525, 'de', 'funcionamento', 'Mittwoch bis Sonntag, 11.30–15.30 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 526, 'de', 'descricao', 'Besucher erleben die Herstellung der Dekorationsartikel durch die Kunsthandwerkerinnen vor Ort, haben Zugang zu den Webstühlen, den Stoffen und den fertigen Stücken. Außerdem können sie im Garten des Ecopolo ein köstliches Frühstück oder einen Nachmittagskaffee genießen, zubereitet vom Team. Seit 20 Jahren entwickeln wir Taschen, Accessoires und Produkte der Home-Linie in Handweberei, einer uralten Technik, bei der der Stoff durch das Verflechten von Fäden entsteht, mit der Kette (senkrechte Fäden am Webstuhl) und dem Schuss (waagerechte Fäden). Die gesamte Arbeit wird von Hand erledigt. Neue Kollektion mit exklusiven Stücken aus recyceltem Material.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 526, 'de', 'funcionamento', 'Montag bis Freitag, 9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 527, 'de', 'descricao', 'Landhotel mit guter Unterbringung und geräumigen Zimmern, Pools für Erwachsene und Kinder, Mehrzwecksportplatz, Sauna, Spielzimmer, Bar und Restaurant. Naturerlebnis, Radtouren, Ausritte, Tretboot.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 527, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 528, 'de', 'descricao', 'Eine ausgezeichnete Wahl für alle, die Ruhe inmitten der Natur suchen. See mit Tambaquis und Pacus zum Sportangeln, Pool, Rasenfußballplatz, Volleyballplatz, Tischfußball, Gemüsegarten im Freien, Wanderwege und in der Nähe von Startrampen für Drachen- und Gleitschirmflieger.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 528, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 529, 'de', 'descricao', 'Regionales Frühstück oder Nachmittagskaffee mit typischen Produkten aus dem Landesinneren. Serviert wird im Freien, inmitten einer Bananenplantage.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 529, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 530, 'de', 'descricao', 'Ursprünglich 500 ha geschützte und bewahrte Flächen sowie landwirtschaftliche Produktion. Ein produktiver Hof, der auf seinem Gelände ökologischen Landtourismus anbietet. Es gibt ein traditionelles Haupthaus und 5 Apartments für Gäste. Kinder sind willkommen. Geboten werden ökologische Wanderungen, Einblicke in den Bio-Anbau, Baumpflanzungen, das Füttern der Kleintiere, der Besuch des Orchideenhauses, Pool und Sauna, Fußballplatz, Volleyball, Spiele und weitere Freizeitangebote.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 530, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 531, 'de', 'descricao', 'Familiäre Atmosphäre, Ausritte, typische Landküche, regionale Feste, Pool und der Gemüsegarten der Farm.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 531, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 532, 'de', 'descricao', 'Ländliche Unterkunft, Cachaça aus der Brennerei und Ökotourismus-Aktivitäten wie Trekking, Baden im Fluss und die Möglichkeit zur Vogelbeobachtung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 532, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 533, 'de', 'descricao', 'Bio-Landwirtschaftsbetrieb, in dem man die Anbautechniken des Bio-Landbaus und die Herstellung von Trockenbananen (banana passa) beobachten und kennenlernen kann. Beliefert werden Restaurants sowie Familien mit Bio-Kisten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 533, 'de', 'funcionamento', 'Nicht angegeben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 534, 'de', 'descricao', 'Ein Bekenntnis zu lebendiger, natürlicher Nahrung, im Respekt vor Menschen, Umwelt, fairem Handel und guten Praktiken eines gesunden Anbaus. Alle unsere Lebensmittel werden natürlich gedüngt, ohne chemische Pflanzenschutzmittel oder Agrargifte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 534, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 535, 'de', 'descricao', 'Farmhotel mit Ausritten, Angelteich (Pesque e Pague, Angeln gegen Gebühr), Pool und Wanderwegen mitten in der Natur.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 535, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 536, 'de', 'descricao', 'Die Pousada bietet den Komfort der Großstadt in ländlicher Ruhe. Pool mit Swim-up-Bar, Whirlpool, Dampfsauna, Spielraum, Wasserfälle, Spielplatz, Ponyreiten für Kinder, Restaurant, Minimarkt und vieles mehr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 536, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 537, 'de', 'descricao', 'Wer Orangen und Landtourismus mag, sollte sich diese Route nicht entgehen lassen. Unterwegs besuchen die Gäste eine Orangenplantage, pflücken und probieren die Früchte, besichtigen mehrere landwirtschaftliche Betriebe und können landwirtschaftliche Erzeugnisse und Kunsthandwerk kaufen – ein angenehmer Tag auf dem Land. Die etablierte Route besteht seit 2010 und findet saisonal statt (während der Orangenernte). Der Circuito da Laranja wurde bereits von Tausenden Menschen besucht, die vor allem aus dem Großraum Rio de Janeiro kommen. Alle Gruppen werden von einem örtlichen Führer begleitet, der Informationen zur Geschichte und zu Daten der Stadt vermittelt und zudem durch die Besichtigungsstationen leitet. Die Route bietet ein unvergessliches Landerlebnis, schafft eine Verbindung zwischen Besuchern und ländlichem Raum und weckt bei allen den Wunsch, wiederzukommen und es noch einmal zu erleben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 537, 'de', 'funcionamento', '8–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 538, 'de', 'descricao', 'Naturerlebnis, Wanderwege und schöne Landschaften zum Genießen. Kleiner Landbesitz (Sítio) in der Serra do Barbosão.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 538, 'de', 'funcionamento', 'Während der Geschäftszeiten, Dienstag bis Sonntag; keine Voranmeldung erforderlich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 539, 'de', 'descricao', 'In den letzten 15 Ausgaben bot das Fest Shows, Wettspiele und Vorträge für Landwirte, die Wahl der Orangenkönigin, einen Wettbewerb um den besten Orangenerzeuger, eine Kunsthandwerksausstellung und Stände mit typisch ländlichen Speisen und würdigt so die ländliche Kultur der Stadt und ihrer Bewohner. Die Festa da Laranja steht seit 2002 im offiziellen Veranstaltungskalender der Gemeinde Tanguá, gemäß Gesetz 352/02. Das Fest hat in der Gemeinde Tradition und soll das wichtigste landwirtschaftliche Erzeugnis der Gemeinde, die Orange, fördern und würdigen und damit die ländliche Kultur und die Traditionen der Stadt stärken.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 539, 'de', 'funcionamento', 'Findet in der zweiten Julihälfte statt. In der Regel dauert das Fest 3 Tage (Freitag, Samstag und Sonntag).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 540, 'de', 'descricao', 'Köstliches Frühstück oder Mittagessen auf Voranmeldung. Es handelt sich um ein Haus für bis zu 6 Personen, dessen Räumlichkeiten die Gäste nutzen können. Zum Frühstück werden Süßspeisen und Marmeladen serviert, die auf dem Anwesen aus Produkten der Saison hergestellt werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 540, 'de', 'funcionamento', 'Frühstück 8–10 Uhr und Mittagessen 11.30–14.30 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 541, 'de', 'descricao', 'Das traditionelle Festa do Aipim, das jedes Jahr am 1. Mai stattfindet, hat sich zu einer touristischen und kulinarischen Attraktion des Ortes entwickelt, mit zahlreichen Produkten aus Maniok (Aipim). Während des Festes werden typische Gerichte aus Maniok verkauft, zum Beispiel: Bolinho (Küchlein), Pizza, Sola, Biju, Italiano, Maniok mit Trockenfleisch, Tapioca, Caldo Verde, Vaca Atolada, Maniokmehl und süßer Maniokkuchen. Dazu gibt es verschiedene Süßigkeiten, diverse Säfte und einen Bauernmarkt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 541, 'de', 'funcionamento', '10–22 Uhr (am Tag des Festes)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 542, 'de', 'descricao', 'Es besteht die Möglichkeit, ein Haus in der Natur für eine private Gruppe zu mieten oder den Tagungsraum für Firmentreffen zu mieten. Jedes Detail des Ortes wurde sorgfältig im Einklang mit der Natur gestaltet: Er inspiriert zu Verbundenheit, Engagement, Wertschätzung und Freude. Im Bereich Gastfreundschaft ist das Sinal do Vale auch in der Gastronomie tätig, nach der Zubereitungsmethode der Regenerativen Küche. Wir verwenden lokale Zutaten und bevorzugen Gemüse, Wurzeln und Früchte aus unseren Bio-Gärten und Agroforsten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 542, 'de', 'funcionamento', 'Nur nach Voranmeldung für geschlossene Gruppen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 543, 'de', 'descricao', 'Das Rancho Linda Vista ist ein ländliches Fischrestaurant in Xerém, RJ. Aber es ist mehr als nur ein einfaches Landrestaurant. Hier servieren wir ein köstliches Frühstück und haben einen See zum Angeln gegen Gebühr (Pesque e Pague) oder zum Sportangeln, einen Pool und einen Spielplatz für die Kleinen. Außerdem gibt es viel Platz zum Rennen und Spielen für die Kinder. Unsere kleine Farm ist bezaubernd, mit vielen Tieren, die die Kinder kennenlernen können. Auf dem Rancho servieren wir auch ein köstliches Mittagessen vom Holzfeuer. Zu unseren Gerichten gehören Tilapia-Steak, Schweinekarree mit Grünkohl und Hähnchen mit Okra. Zum Abschluss der Mahlzeit können Sie einen zum Dahinschmelzen guten Pudding genießen, der im Holzofen gebacken wird. Nach dem Mittagessen können Sie sich in einer der überall auf dem Rancho verteilten Hängematten ausruhen und dazu einen Kaffee mit Broa (Maiskuchen) trinken. Hier haben Sie alles, um einen herrlichen Tag zu verbringen und schöne Erinnerungen mit Kindern, Enkeln und Freunden zu schaffen.*');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 543, 'de', 'funcionamento', 'Freitag bis Sonntag, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 544, 'de', 'descricao', 'Angelteich (Pesque e Pague, Angeln gegen Gebühr), Veranstaltungen, Freizeit (Pool) und Übernachtung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 544, 'de', 'funcionamento', 'Wochenenden und Feiertage, 7.30–17.30 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 545, 'de', 'descricao', 'Vaquejada-Park. Die Anlage verfügt über Pools, ein Restaurant und Räume für Veranstaltungen. 2022 fand hier die erste von der ABVAQ anerkannte Vaquejada im Südosten statt, mit Vaqueiros (Cowboys) aus vielen Orten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 545, 'de', 'funcionamento', 'Wochenenden und Feiertage.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 546, 'de', 'descricao', 'Tiere streicheln und füttern, Reiten, Tierverkauf, Fotos machen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 546, 'de', 'funcionamento', 'Samstags, 10–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 547, 'de', 'descricao', 'Brasiliens einheimische Bienen kennenlernen, den Honig probieren und schöne Fotos machen, die in Ihren sozialen Netzwerken gut ankommen werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 547, 'de', 'funcionamento', 'Mittwoch bis Sonntag, 9–14 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 548, 'de', 'descricao', 'Anbau von Bio-Gemüse, Tilapia-Fischzucht, Angeln und Baden im Fluss (Rio São Pedro).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 548, 'de', 'funcionamento', 'Montag bis Sonntag.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 549, 'de', 'descricao', 'Freizeitanwesen im ländlichen Raum mit Pool und Grillplatz, Fußballplatz, Angelsee, Schlafunterkünften, Spielraum und Tagesmiete für Veranstaltungen und Auftritte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 549, 'de', 'funcionamento', 'Wochenenden und Feiertage.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 550, 'de', 'descricao', 'Verkauf handwerklich hergestellter Produkte: Käse, Pão de Queijo (Käsebrötchen), Cheesecake, Ricotta, Kuchen, Kekse und Milch; Bio-Produkte; Verkauf von Zierfischen; sowie Mitmachen in der Produktionslinie der handwerklichen Produkte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 550, 'de', 'funcionamento', 'Montag bis Freitag, 8–17 Uhr; am Wochenende 8–15 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 551, 'de', 'descricao', 'Verpflegung; Besuch des Agroforsts mit Lehmbad; Kurs zur Zubereitung von PANC (unkonventionelle Nahrungspflanzen); Verkauf agrarökologischer Produkte, Forschungsgelände, Campingplatz, Catering-Service.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 551, 'de', 'funcionamento', 'Montag bis Sonntag.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 552, 'de', 'descricao', 'Angelteich (Pesque e Pague, Angeln gegen Gebühr); Reitkurs (Termin vereinbaren); Ausritte; Restaurant Delícias da Rosa; Verkauf von Keramik-Kunsthandwerk, hausgemachten Süßigkeiten und Pflanzen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 552, 'de', 'funcionamento', 'Sonntags, 9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 553, 'de', 'descricao', 'Das erwartet die Besucher: ein Frühstück im Kolonialstil in der Chácara Vale dos Manacás-Tinguá-NI, mit vor Ort gebackenem Brot, das den Gästen noch warm serviert wird. Während des Kolonialfrühstücks können die Gäste die gesamte Anlage der Chácara nutzen (zwei Pools, Kajak, Hängematten, Außendusche und mehr). Das ist das Kolonialfrühstück. Zur Route Pedra Lisa: Direkt nach dem ländlichen Frühstück beginnen wir eine Wanderung zum Sítio Pedra Lisa, wo wir die Naturschönheiten dieses beeindruckenden Überrests des Atlantischen Regenwalds genießen. Danach kehren wir zur Chácara zurück, wo wir das Mittagessen servieren. Im Sítio Pedra Lisa erwartet die Besucher eine 2,7 km lange Wanderung durch die kommunalen Umweltschutzgebiete von Tinguá und das staatliche Schutzgebiet Alto Iguaçu. Unterwegs haben sie Blick auf die Gebirgskette der Serra do Mar und entlang der Guanabara-Bucht. Auf dem Anwesen werden sie über Pfade im Atlantischen Regenwald geführt, wo sie in 2 Flüssen mit Wasserfällen und kristallklarem Wasser baden oder einfach die Wasserfälle, den See, die Felsgrotte Tinguaíto und die zahllosen Tier- und Pflanzenarten des Atlantischen Regenwalds bewundern können. Für Campingfreunde bietet das Sítio rustikales Wild Camping mit Sanitäranlage, Leitungswasser, Gaskocher und Kühlschrank.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 553, 'de', 'funcionamento', 'Day Use Freitag bis Sonntag und an Feiertagen, 8–17 Uhr (in der Chácara nur an Veranstaltungstagen)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 554, 'de', 'descricao', 'Besuch der Brennerei, der Obstplantagen und des Zuckerrohrfelds sowie Zugang zur Aussichtsterrasse mit Panoramablick auf die Serra do Vulcão, mit dem Restaurant Caminho do Vulcão.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 554, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 555, 'de', 'descricao', 'Kurze Einführung in den Maniokanbau (Aipim): Bodenvorbereitung, Anbau, Pflege und Instandhaltung, Ernte, Verarbeitung. Anschließend ein Feld-Erlebnis, das einen Teil der nötigen Arbeitsschritte praktisch zeigt. Ernte und Zubereitung der Gerichte sowie Verkostung, die je nach Programm ein Mittagessen oder eine Nachmittagsjause umfasst.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 555, 'de', 'funcionamento', '10–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 556, 'de', 'descricao', 'Das Sítio zeigt landwirtschaftliche Tätigkeiten und Viehhaltung, mit Anbau verschiedener Früchte, Gemüse und Blattgemüse sowie der Haltung unterschiedlicher Tiere. Herstellung von Käse und Fruchtkompotten aus Früchten der Saison. Der Ort wird auch für Veranstaltungen von Genossenschaften, Partnerschaften und städtischen Schulen genutzt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 556, 'de', 'funcionamento', 'Day Use Freitag bis Sonntag und an Feiertagen, 8–17 Uhr (in der Chácara nur an Veranstaltungstagen)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 557, 'de', 'descricao', 'Familienbetriebe sowie Bio-Erzeuger und Betriebe in der agrarökologischen Umstellung kennenlernen. Vielfältige, lokal erzeugte Lebensmittel genießen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 557, 'de', 'funcionamento', 'Mittwochs, 8–13 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 558, 'de', 'descricao', 'Die Fazendinha Agroecológica do km 47 ist ein Vorbild für ökologische und agrarökologische Produktion in Brasilien. Sie ist eine Partnerschaft des Colégio Técnico da Universidade Rural (CTUR), der Embrapa Agrobiologia, der Pesagro-Rio und der Universidade Federal Rural do Rio de Janeiro (UFRRJ). Die Fazendinha ist der Ankerpunkt einer Reihe von Projekten zu Technologietransfer und Beratung, die den Wissensaustausch über Einführung und Anpassung von Technologien, Produkten, Verfahren und Dienstleistungen ermöglichen. Hier finden Kurse, Feldtage, Vorträge, Besuche sowie technische, wissenschaftliche und pädagogische Treffen für unterschiedlichste Zielgruppen statt. Bei den Besuchen erleben die Gruppen Theorie und Praxis, lernen Bildung durch Agrarökologie kennen, den Kontakt mit der Erde, biogeochemische Kreisläufe, organische Düngung, die Herstellung von Substraten, Aussaat, Gemüsebau, Kulturpflege und Ernte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 558, 'de', 'funcionamento', 'Werktage, unter der Woche, zu im Voraus vereinbarten Zeiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 559, 'de', 'descricao', 'Die Universidade Federal Rural do Rio de Janeiro (UFRRJ), insbesondere das neokoloniale Gebäudeensemble des Campus Seropédica, das vom Instituto Estadual do Patrimônio Cultural (Inepac) unter Denkmalschutz gestellt wurde, wurde ab 1939 errichtet. Der weitläufige, schöne Landschaftspark des Landschaftsarchitekten Reynaldo Dierberger wurde zeitgleich angelegt und ergänzt die neokolonialen Pavillons um Gärten, künstliche Seen, Baumgruppen aus heimischen Arten, Palmengruppen, Strauchpflanzungen, Bodendecker, Böschungen und Rasenbeete. Der Hauptcampus der UFRRJ spielt zudem eine wichtige Rolle für die Freizeit: zum Betrachten, Spazierengehen, Radfahren und für Picknicks in der Nähe der Seen sowie entlang der gepflasterten Wege, die einen Teil des Hauptcampus durchziehen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 559, 'de', 'funcionamento', 'Mittwochs, 8–13 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 560, 'de', 'descricao', 'Brennerei und Cachaçaria, spezialisiert auf die handwerkliche Herstellung von Likören sowie goldenen, silbernen und gemischten Cachaças, gelagert in Edelstahltanks, Eichenfässern, Paranussholz- und Jequitibá-Rosa-Fässern. Besonderheit sind reine, hochwertige Cachaça und vor allem alkoholische Getränke mit Jambu-Aroma. Es gibt ein Restaurant, das am Wochenende zum Mittagessen geöffnet ist. Kostenlose Verkostung der vor Ort hergestellten Cachaças und handwerklichen Liköre, Verkauf von Cachaças und Likören. Im Restaurant gibt es am Wochenende Mittagessen mit regionalen Gerichten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 560, 'de', 'funcionamento', 'Montag bis Sonntag, 8.30–17 Uhr. Restaurant: Freitag bis Sonntag, ab 12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 561, 'de', 'descricao', 'Ein schönes ländliches Anwesen, auf dem Veranstaltungen stattfinden, die meist öffentlich zugänglich sind, in ruhiger Umgebung mit angenehmem Klima, Tieren und Kinderbereich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 561, 'de', 'funcionamento', '10–19 Uhr (an Veranstaltungstagen flexibel)');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 562, 'de', 'descricao', 'Weitläufige Umgebung in direktem Kontakt mit der Natur. Familiäre Bedienung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 562, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 563, 'de', 'descricao', 'Lage am Ufer des Rio Paraíba do Sul. Familienfreundliche Bootsfahrt. Weitläufiger Bereich mit Freilandhuhn von unvergleichlichem Geschmack, dazu Appetithäppchen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 563, 'de', 'funcionamento', '10–22 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 564, 'de', 'descricao', 'Fischzucht und Angelteich (Pesque e Pague, Angeln gegen Gebühr). Angenehme Umgebung am Ufer des Rio Paraíba do Sul, wo die Besucher eine Mahlzeit genießen können.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 564, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 565, 'de', 'descricao', 'Handwerklich hergestellte Pizza mit hausgemachtem Teig, auf dem Stein gebacken.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 565, 'de', 'funcionamento', 'Montag, Mittwoch, Donnerstag und Sonntag, 15–24 Uhr. Freitag und Samstag, 15–2 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 566, 'de', 'descricao', 'Hochwertige Freilandeier. Ein Ort an der frischen Luft, mit gut versorgten Hühnern, die mit mehr Freiheit leben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 566, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 567, 'de', 'descricao', 'Besichtigung der Anlagen, direkter Kontakt mit der Natur, handwerklich hergestellte Cachaça in Exportqualität.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 567, 'de', 'funcionamento', 'Montag bis Freitag, 8–11.30 Uhr und 13.30–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 568, 'de', 'descricao', 'Die Besucher können einen ruhigen Tag in der Natur verbringen, ein gutes Essen genießen und an einem wunderschönen See angeln.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 568, 'de', 'funcionamento', 'Dienstag bis Sonntag, 8–19 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 569, 'de', 'descricao', 'Produktion und Verwurzelung während der Erntezeit. Empfang, handwerklich hergestellte Cachaça und Verkauf.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 569, 'de', 'funcionamento', 'Montag bis Freitag, 8–17 Uhr. Samstag, 8–12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 570, 'de', 'descricao', 'Der Ort bietet Touristen die Möglichkeit, in einem schönen Wasserfall zu baden, auf einem Society-Platz (Kunstrasen) Fußball zu spielen und das beste frisch zubereitete Pastel (frittierte Teigtasche) der Region zu essen. Es gibt viel Platz für Veranstaltungen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 570, 'de', 'funcionamento', 'Montag bis Sonntag, 7–21 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 571, 'de', 'descricao', 'Tourismus in direktem Kontakt mit der Natur, Beobachtung der lokalen Tier- und Pflanzenwelt, Wanderwege zu Wasserfällen und Stromschnellen des Rio Itabapoana.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 571, 'de', 'funcionamento', 'Samstag und Sonntag, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 572, 'de', 'descricao', 'Direkter Kontakt mit der Natur, Mittagessen und Sportveranstaltungen. Nachhaltigkeit und soziale Dienste.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 572, 'de', 'funcionamento', 'Restaurant: Samstag bis Sonntag, 12–16 Uhr; Pub: Freitag 18–22 Uhr, Samstag 9–21 Uhr und Sonntag 9–17 Uhr; Unterkunft: Freitag bis Sonntag, 24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 573, 'de', 'descricao', 'Angeln im Stausee, Besuch der Pedra do Mutum de Baixo, die zum historischen, kulturellen und touristischen Erbe der Gemeinde erklärt wurde, Kutschfahrt, typische Gerichte (Freilandhuhn, im Dampf gegarte Rippchen usw.) und mehr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 573, 'de', 'funcionamento', 'Sonntag bis Montag, 7–20 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 574, 'de', 'descricao', 'Der Ort bietet direkten Kontakt mit der Natur, frische Luft und eine wunderschöne Landschaft, ideal für Frieden, Ruhe und Erholung. Es gibt ein Restaurant mit typischen Gerichten vom Holzofen und Unterkunft in Chalets. Es gibt Seen mit Tretbooten sowie einen Wasserfall für ein herrliches Bad. Perfekt für den Spaß der ganzen Familie!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 574, 'de', 'funcionamento', 'Montag bis Freitag, 24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 575, 'de', 'descricao', 'Angeln, ein angenehmer, familiärer, baumbestandener Ort mit hervorragendem Service.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 575, 'de', 'funcionamento', 'Donnerstag bis Sonntag, 10–20 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 576, 'de', 'descricao', 'Es gibt Unterkunft und ein Restaurant mit köstlichem Buffet, das weit mehr bietet als ein einfaches Mittagessen: ein lokales kulinarisches Erlebnis. Ein perfekter Ort, um die reine Landluft zu atmen, mit Blick auf den wunderschönen Rio Itabapoana. Nichts übertrifft die Ruhe, die die Natur an diesem Ort vermittelt!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 576, 'de', 'funcionamento', 'Restaurant: Samstag und Sonntag, 9–18 Uhr. Unterkunft: täglich, 24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 577, 'de', 'descricao', 'Sie bietet gemütliche Unterkunft, einen Empfang der Gäste in intimer, familiärer Atmosphäre und ein ländliches Frühstück aus Zutaten vom Hof. Erlebnistourismus mit einem Corral neben der Pousada, wo die Besucher den Tieren nahekommen können.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 577, 'de', 'funcionamento', 'Die Pousada hat täglich geöffnet, aber nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 578, 'de', 'descricao', 'Ort zum Besuchen, Ausstellen und Verkaufen von Kunsthandwerk. Die Casa do Artesão de Bom Jesus do Itabapoana ist eine Einkommensalternative für die Gemeinde und umfasst das Programm „Solidarische Wirtschaft“.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 578, 'de', 'funcionamento', 'Montag bis Freitag, 9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 579, 'de', 'descricao', 'Besucher lernen die Etappen der handwerklichen Cachaça-Herstellung kennen, darunter das Mahlen und die Reifung. Sie können außerdem die Herstellung von Rapadura sehen, einem weiteren Produkt aus Zuckerrohr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 579, 'de', 'funcionamento', 'Am Wochenende.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 580, 'de', 'descricao', 'Verkostung der Produkte. Nachhaltige Erzeugung, mehr Geschmack, mehr Gesundheit auf Ihrem Tisch! Gastronomie und Kunsthandwerk. Schwarzer Gourmetreis Ônix und roter Reis.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 580, 'de', 'funcionamento', 'Am Wochenende.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 581, 'de', 'descricao', 'Kleiner Hof mit Angelteich (Pesque e Pague), Schwimmbecken und einem großen, von Bäumen beschatteten Kiosk.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 581, 'de', 'funcionamento', 'Am Wochenende.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 582, 'de', 'descricao', 'Großzügiger Ort mit vielen Geschenkideen aus Kunsthandwerk.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 582, 'de', 'funcionamento', 'Montag bis Freitag, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 583, 'de', 'descricao', 'Einblick in die handwerkliche Herstellung von Cachaça.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 583, 'de', 'funcionamento', '9–16 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 584, 'de', 'descricao', 'Zureiten von Pferden, Pferde für Ausritte, exotische Vögel, Milchviehgehege, Pony, Minirind und Wasservögel.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 584, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 585, 'de', 'descricao', 'Professionelle Erzeugung von Eiern aus Freilandhaltung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 585, 'de', 'funcionamento', '16–22 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 586, 'de', 'descricao', 'Den Herstellungsprozess der handwerklichen Cachaça verfolgen, mit sensorischer Analyse und Verkostung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 586, 'de', 'funcionamento', 'Donnerstag bis Sonntag, 9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 587, 'de', 'descricao', 'Genossenschaft der bäuerlichen Familienbetriebe, mit Besichtigung der Produktionsstätte und einem Laden mit regionalen Produkten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 587, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 588, 'de', 'descricao', 'Gastronomie, Weinkeller, Rafting, Wanderwege, ländliches Erlebnis, Naturnähe und Livemusik.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 588, 'de', 'funcionamento', 'Täglich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 589, 'de', 'descricao', 'Ländlicher Tourismus, die Vorzüge eines Mineralheilbads genießen, Naturnähe und Einkaufen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 589, 'de', 'funcionamento', 'Samstag und Sonntag.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 590, 'de', 'descricao', 'Wir sind der einzige Hof der Region mit handwerklicher Produktion und einem Besucherbereich, in dem man den gesamten Herstellungsprozess von Käse, Wein, Cachaça, handwerklicher Rapadura, braunem Zucker, Joghurt und Honig kennenlernen kann.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 590, 'de', 'funcionamento', 'Montag bis Freitag, 8–17 Uhr. Samstag und Sonntag, 8–12:30 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 591, 'de', 'descricao', 'Mit ihren Quellen im Herzen von Raposo zeichnet sich die Estância Hidromineral Soledade seit jeher durch die hohe Qualität ihres Wassers aus. Es ist bereits für seine heilende Wirkung berühmt und zieht jedes Jahr Tausende von Touristen an. Darüber hinaus bietet die Estância Hidromineral Soledade Bäder in Becken mit schwefelhaltigem und fluoridiertem Wasser, ganz ohne chemische Zusätze. Kommen auch Sie und genießen Sie dieses Naturwunder!');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 591, 'de', 'funcionamento', 'Montag bis Freitag, 7–11 Uhr und 13–17 Uhr. Samstag und Sonntag, 7–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 592, 'de', 'descricao', 'Ort der Erholung und Ruhe. Verkostung verschiedener Mineralwässer mit nachgewiesener heilender Wirkung. Die Wässer von Raposo besitzen heilende und wohltuende Eigenschaften, die es sonst nirgendwo in Brasilien gibt, dank des Reichtums an Mineralgestein im Untergrund und seines einzigartigen geothermischen Gebiets.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 592, 'de', 'funcionamento', '7–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 593, 'de', 'descricao', 'Fischzucht und Ausritte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 593, 'de', 'funcionamento', '7–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 594, 'de', 'descricao', 'Schwimmbad, Fitnessraum, holzbeheizte Sauna, Grünanlage, Grillkiosk, Spielplätze, Fußballplatz und ein von viel Grün umgebenes Restaurant.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 594, 'de', 'funcionamento', '24 Stunden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 595, 'de', 'descricao', 'Der Raum vereint Produkte und Kunsthandwerk von Künstlern, Kunsthandwerkern und ländlichen Erzeugern an einem zentralen, leicht erreichbaren Ort, zu Preisen, die der heutigen Realität entsprechen. Die Besucher können außerdem die in der Gemeinde angefertigten und hergestellten Produkte kennenlernen und so ihr kulturelles Wissen bereichern. Angeboten wird eine Vielfalt an Waren mit der kulturellen und touristischen Identität der Stadt sowie köstliche Erzeugnisse vom Land. Zu den verfügbaren handwerklichen ländlichen Produkten gehören: Kaffee, Käse, Wurst, Cachaça, Honig, Propolis, Liköre, Früchte in Sirup, kandierte Früchte und Kompott sowie Konfitüren in vielen Geschmacksrichtungen. Außerdem gibt es Dekoartikel für Bett, Tisch und Bad, religiöse Artikel (Bilder, Rosenkränze, Banner und Wimpel), Flechtwaren und Produkte mit individuellen Miracema-Motiven.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 595, 'de', 'funcionamento', 'Montag bis Freitag, 8–17 Uhr. Samstag, 8–12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 596, 'de', 'descricao', 'Ausritte, Tretboote, typische Küche vom Holzherd, Grillplatz, Außendusche und Wanderungen durch Wälder, Berge und natürliche Lagunen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 596, 'de', 'funcionamento', 'Ganztägig.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 597, 'de', 'descricao', 'Die örtlichen Künstler, Kunsthandwerker und ihre handwerkliche Arbeit in ihrer ganzen Produktvielfalt kennenlernen und wertschätzen, mit gutem Service, höflichem Umgang mit den Kunden und einem gut belüfteten, hygienisch gereinigten Raum, der auch die Pandemie-Protokolle einhält. Die Waren sind erschwinglich und werden in individueller Geschenkverpackung angeboten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 597, 'de', 'funcionamento', 'Montag bis Freitag, 8–17 Uhr. Samstag, 8–12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 598, 'de', 'descricao', 'Besichtigung einer handwerklichen Cachaça-Produktion, mit Reifung in Fässern aus Eiche, Amburana, Paranuss und anderen Hölzern sowie freier Verkostung. Zuckerrohranbau und -mahlung finden auf demselben Grundstück statt, außerdem gibt es mehrere Teiche zum Angeln und eine schöne ländliche Aussicht.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 598, 'de', 'funcionamento', 'Übliche Geschäftszeiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 599, 'de', 'descricao', 'Ganz in der Nähe des Heiligtums von Nossa Senhora de Natividade liegt dieses Open-Air-Restaurant auf einem gemütlichen kleinen Hof, der vor Ort angebaute und geerntete Produkte für Mahlzeiten und Snacks verwendet, alles in ausgesprochen ländlicher Atmosphäre und mit Platz für die ganze Familie.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 599, 'de', 'funcionamento', 'Freitag bis Sonntag, 11–21 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 600, 'de', 'descricao', 'Besichtigung eines Anwesens aus dem Jahr 1834 am Ufer des Bachs São Sebastião. Es ist eines der Anwesen, die die Grundlage für die Entstehung der Gemeinde Natividade bildeten. Ein Teil der Fazenda do Engenho wurde vor Jahren in ein Wohngebiet umgewandelt, aus dem das Viertel Morada do Engenho hervorging. Dieser Besuch ist eine echte Flucht aus dem Stadtleben und bietet viel Naturnähe.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 600, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 601, 'de', 'descricao', 'Unterkunft, Frühstück und Mittagessen, mit Produkten, die alle auf dem Hof selbst angebaut und geerntet werden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 601, 'de', 'funcionamento', 'Pousada: 24 Stunden. Restaurant: 10:30–14 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 602, 'de', 'descricao', 'Verschiedene geröstete Kaffees, Spezialitätenkaffee, Kuchen und die hauseigene besondere Bananensüßspeise. Besichtigung und Erlebnis des Herstellungsprozesses der Spezialitätenkaffees, die in 900 m Höhe geerntet werden. Der Besuch führt vom Feld bis zum Genuss, vorbei an den Maschinen, der Sortierung der Bohnen und der Trocknung, und endet mit einer köstlichen Verkostung. 2019 wurde der Kaffee zum zweitbesten Spezialitätenkaffee von Rio de Janeiro gewählt. Der Ort bietet außerdem einen Blick auf den Pico da Bandeira, den höchsten Punkt der Südostregion Brasiliens, sowie einen Angelteich mit der Möglichkeit, bei der Pflege von Bananen und Kaffee mitzuarbeiten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 602, 'de', 'funcionamento', '8–12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 603, 'de', 'descricao', 'Besichtigung der Produktion des Café Iranita, 100 % Arabica, ein Produkt der bäuerlichen Familienlandwirtschaft, angebaut auf nachhaltigen Plantagen in 400 bis 600 m Höhe. Der Betrieb entstand 1993 und trägt den Namen Sítio Iranita, aus den Namen Irany und Nita, den Eltern des Besitzers Olympio Matheus Ribeiro. Ab 2005, unter der Leitung von Ana Regina und Suhail, wurde in die Qualität des Kaffees investiert, von der Bewirtschaftung der Pflanzung bis zum verkaufsfertigen Kaffee. Heute verfügt der Betrieb über eine geeignete Infrastruktur für die Herstellung eines Kaffees von ausgezeichneter Qualität.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 603, 'de', 'funcionamento', 'Montag bis Freitag, 8–17 Uhr. Samstag, 8–12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 604, 'de', 'descricao', 'Ländliches Restaurant, Rundgang über den Hof, Kinderbereich, Vermietung für Feiern und Veranstaltungen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 604, 'de', 'funcionamento', 'Flexibel nach Vereinbarung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 605, 'de', 'descricao', 'Snackbar, Kinderbereich, Vermietung für Feiern und Veranstaltungen und Produkte vom Land.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 605, 'de', 'funcionamento', '16–24 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 606, 'de', 'descricao', 'Der Ort dient der Erholung und Ruhe und vermittelt das Leben auf dem Land. Unser Haus versetzt uns zurück zu Erinnerungen, die tief verborgen und fast vergessen sind. Es lädt uns ein, uns an die Kindheit zu erinnern, durch Spiele und Abenteuer. Umgeben von schönen Bäumen, die den vielen Vogelarten als Bühne für ihre Ständchen dienen, sind wir der Natur nahe und doch ganz in der Nähe der Stadt. Wir haben eine Veranda, die das ganze Haus umgibt, voller einladender Hängematten für ein Nickerchen nach dem Essen. Wenn wir an den Spruch denken: „Gestresst? Geh angeln!“, dann sind Sie hier genau richtig! Wir haben einen majestätischen See voller Leben, in dem man Catch-and-Release-Angeln betreiben kann.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 606, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 607, 'de', 'descricao', 'Besucher können aus nächster Nähe die Herstellung handgefertigter Lampen aus wiederverwertbaren Materialien wie Glasflaschen, Fahrradfelgen, Abbruchholz und anderem verfolgen. Unsere Produkte werden in alle Regionen des Landes verschickt, da der Verkauf hauptsächlich über das Internet erfolgt.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 607, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 608, 'de', 'descricao', 'Gesunde Ernährung mit ländlicher, herzlicher Küche.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 608, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 609, 'de', 'descricao', 'Besuch und Verkostung von Produkten.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 609, 'de', 'funcionamento', 'Täglich, 6–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 610, 'de', 'descricao', 'Ländliches Erlebnis mit Schwimmbecken, Waldflächen, ruhiger Lage, Naturnähe und leichter Erreichbarkeit.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 610, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 611, 'de', 'descricao', 'Vorstellung der Etappen der Cachaça-Herstellung (Mahlen, Gärung und Dekantieren), ein Kupferkessel zur Herstellung von Rapadura und Zuckerrohrsirup, ein Laden mit den vor Ort hergestellten Produkten und außerdem eine große Grünfläche für Fotos. Handwerkliche Cachaça-Herstellung in der Brennerei und Verkauf von abgefüllter Cachaça.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 611, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 612, 'de', 'descricao', 'Einblick in die Herstellung von Spezialitätenkaffee. Gut vorbereitete und qualifizierte Fachkräfte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 612, 'de', 'funcionamento', '7–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 613, 'de', 'descricao', 'Fischzucht, Anbau und Melken. Ein völlig originelles und vielfältiges ländliches Angebot.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 613, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 614, 'de', 'descricao', 'Bietet eine familiäre ländliche Umgebung, ideal für Ausritte und Fahrten mit dem Mikrotraktor, mit Wegen für Wanderungen ebenso wie für Motocross in der Serra Boa Vista, Angeln im örtlichen See und einem typischen Frühstück nach Art von Ubá für alle Besucher. Der Ort besitzt eine einzigartige Schönheit, lädt zum Baden und zum Betrachten eines Wasserfalls in der Regenzeit ein; interessierte Besucher können beim Melken der Kuh zusehen und/oder mitmachen. Er ist zudem ein herausragendes Gebiet unserer Gemeinde beim Schutz von Quellen und teilt natürliches Trinkwasser mit der gesamten interessierten Bevölkerung; außerdem werden Bäume zum Umweltschutz gepflanzt, wobei Umweltschutz und Umweltbewusstsein das wichtigste Merkmal sind.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 614, 'de', 'funcionamento', 'Samstag und Sonntag, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 615, 'de', 'descricao', 'Der Ort verfügt über eine einfache Küche. Kleine Platten zum Teilen, Mittagessen, Süßes und Getränke. Ein Ort, an dem der Kontakt zur Natur an erster Stelle steht. Sportangeln, exotische Vögel, Kinderbereich, Bar und kleines Restaurant in familiärer Atmosphäre. Der Ort ist inspirierend. Natur, Respekt, schmackhaftes Essen und kaltes Bier.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 615, 'de', 'funcionamento', 'Feiertage, Samstage und Sonntage, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 616, 'de', 'descricao', 'Erlebnis der Milchviehhaltung und ein hundertjähriges Haus im Kolonialstil.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 616, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 617, 'de', 'descricao', 'Kaffeeproduktion von der Bohne bis zur Tasse: Wir zeigen den gesamten Prozess von Anbau und Nachernte über den Boden bis zur Verkostung, und dazu viel Gespräch. Wir sind bäuerliche Familienbetriebe und erzeugen Spezialitätenkaffees zu 100 % handwerklich.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 617, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 618, 'de', 'descricao', 'Mal- und Handwerkskurse, Ausritte, Besuch der Kaffee- und Weinpflanzungen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 618, 'de', 'funcionamento', 'Nur nach Voranmeldung.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 619, 'de', 'descricao', 'Geführt von Dona Conceição Bendia, ist sie die urwüchsigste Kellerei unter den wichtigsten Jabuticaba-Weinproduzenten der Stadt und blickt auf mehr als 100 Jahre Tradition zurück. Der Alkoholgehalt des Weins stammt allein aus der Gärung der Frucht, getreu einer Familientradition, keine Konservierungsstoffe zu verwenden.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 619, 'de', 'funcionamento', '8–20 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 620, 'de', 'descricao', 'Verkostung und Kauf verschiedener auf dem Hof hergestellter Produkte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 620, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 621, 'de', 'descricao', 'Keine Angabe');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 621, 'de', 'funcionamento', 'Montag, 12–18 Uhr. Dienstag, 9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 622, 'de', 'descricao', 'Besichtigung der Kellerei und der Produktion, mit der Verarbeitung von Direktsaft und der Herstellung von Wein, Konfitüren und Likör, dazu Pflanzungen verschiedener Früchte wie Jabuticaba, Orange, Pocan (Mandarine), Sternfrucht und anderen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 622, 'de', 'funcionamento', '8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 623, 'de', 'descricao', 'Weine, Liköre, Kunsthandwerk aller Art, Süßes, Honig und Konfitüren. Besuch einer kleinen Kapelle und eines Kalvarienbergs. Verschiedene Haustiere vor Ort.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 623, 'de', 'funcionamento', 'Samstag und Sonntag, 8–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 624, 'de', 'descricao', 'Besichtigung der Herstellung und Zubereitung von Spezialitätenkaffees. Der Café Pelegrini wird von der Familie Pelegrini Menezes auf nachhaltigen Plantagen angebaut und erhielt 2020 den 1. Platz beim Rio Coffee Nation.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 624, 'de', 'funcionamento', '9–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 625, 'de', 'descricao', 'Besichtigung des Lagerkellers. Verkostung der Produkte von D''Chalet.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 625, 'de', 'funcionamento', 'Montag bis Samstag, 8–18 Uhr. Sonntag, 8–12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 626, 'de', 'descricao', 'Kontakt mit der Natur und mit der Herstellung handwerklicher Produkte.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 626, 'de', 'funcionamento', '8–18 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 627, 'de', 'descricao', 'Pizzeria mit Steinofen, Gourmet-Pizza und Produkten der Fazenda Dendê (Gourmet-, traditioneller und Spezialkaffee (gemahlen und als Bohnen), Maismehl aus der Wassermühle, Honig, Konfitüre, trockener Jabuticaba-Wein und Roséwein aus Niágara-Rosada-Trauben.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 627, 'de', 'funcionamento', 'Donnerstag bis Sonntag und an Feiertagen.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 628, 'de', 'descricao', 'Kaffee aus dem Nordwesten des Bundesstaates Rio de Janeiro, wo das tropische Höhenklima in Verbindung mit der sorgfältigen Nacherntebehandlung durch bäuerliche Familienbetriebe die Erzeugung von Spezialitätenkaffee begünstigt. Von der Bohne bis zur Tasse! Die Besucher lernen die familiäre Erzeugung von Spezialitätenkaffees kennen, die von der Familie Rodolphi angebaut und geröstet werden. Sie kümmert sich um jedes Detail der Produktion, damit der Kaffee mit der Qualität in die Tasse gelangt, die die Pflanze hervorgebracht hat. Zweifacher Meisterproduzent des ersten Spezialitätenkaffee-Wettbewerbs im Nordwesten von Rio de Janeiro (Noroeste Fluminense).');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 628, 'de', 'funcionamento', 'Montag bis Freitag, 8–17 Uhr, und samstags, 9–12 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 629, 'de', 'descricao', 'Besichtigung des Anwesens, Verkostung und Verkauf von Craft-Bier, Jabuticaba-Wein und verschiedenen Likören.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 629, 'de', 'funcionamento', '9–17 Uhr.');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 630, 'de', 'descricao', 'Obwohl die Gegend als ländlich gilt, liegt die Pousada nur 5 Autominuten vom Zentrum von Varre-Sai entfernt. Man kann auch zu Fuß hingehen. Der Gast genießt das Privileg, auf dem Land und zugleich in Varre-Sai zu sein, und kann außerdem eine wunderschöne Lavendelplantage besuchen');
INSERT INTO traducoes (entidade, entidade_id, idioma, campo, texto) VALUES ('atrativo', 630, 'de', 'funcionamento', '24 Stunden.');
